local P = LoreForeverPacks.Begin("LoreForever_Lang_roRO")
P.entries["quest:673"] = {n="Foul Magics",s="Tor'gan din Hammerfall este sigur ca un warlock puternic traieste intre zidurile Stromgarde si foloseste o relicva arcana pentru a invoca demoni in numar mare. In continuarea primei parti din Foul Magics, te trimite sa-l omori pe warlock si sa aduci relicva.",h="Tor'gan din Hammerfall este sigur ca un warlock puternic traieste intre zidurile Stromgarde si foloseste o...",kw={"arathi highlands","bloodstone","hammerfall","marez cowl","stromgarde","torgan","warlock"},sec={{t="Un Warlock in Stromgarde",b="Tor'gan este sigur ca in zidurile Stromgarde locuieste un warlock. Din cand in cand, warlock-ul foloseste o relicva arcana pentru a chema demoni cumpliti, in numar mare. Focul din sangele lui Tor'gan se inteteste pe zi ce trece. Vrea sa-l gasesti si sa-l ucizi pe warlock, apoi sa-i aduci orice obiect magic ar avea asupra lui, ca sa-l poata distruge si sa impiedice puterea acestuia sa pangareasca pamantul. Warlock-ul este Marez Cowl, iar obiectul este un Befouled Bloodstone Orb."},{t="Ce-si aminteste globul",b="Dupa distrugerea globului, Tor'gan spera ca noptile lui nelinistite se vor transforma in somn linistit. Ii aminteste de puterea ingrozitoare pe care demonii au avut-o candva asupra orcilor, inainte ca Hellscream sa-i elibereze de blestem."}},faq={{q="Cine te trimite sa vanezi Warlock-ul?",a="Tor'gan din Hammerfall te trimite in Stromgarde sa-l gasesti pe warlock si sa iei obiectul magic pe care-l poarta.",al={"cine ofera foul magics","cine da misiunea foul magics","misiunea lui torgan"}},{q="Unde se afla warlock-ul?",a="Marez Cowl se afla intre zidurile Stromgarde, in afara fortaretei si la vest de aceasta, ascunsa in spatele unei cladiri. O poti auzi canalizand o vraja.",al={"unde este Marez Cowl","locatia Warlock din Stromgarde","unde o gasesc pe Marez Cowl"}},{q="Ce relicva trebuie sa recuperezi?",a="Globul de piatra sangelui profanat al lui Marez Cowl, obiectul magic pe care Tor'gan vrea sa i-l aduci ca sa-l poata distruge.",al={"ce obiect doreste torgan","befouled bloodstone orb","obiect cu magie necurata"}},{q="De ce vrea Tor'gan sa-l opreasca pe warlock?",a="Warlock a invocat demoni cumpliti in numar mare. Tor'gan vrea ca sursa acelei puteri sa fie inlaturata si globul distrus, ca sa nu mai poata pangari pamantul.",al={"de ce sa distrugi globul","motivul lui torgan","de ce sa-l opresti pe warlock"}}},fp="11,250,23.445.0,20.205.1,34.107.0,29.149.0,36.107.0,42.167.0"}
P.entries["quest:674"] = {n="Raising Spirits",s="Raising Spirits este o misiune a Horde menita sa reaprinda vointa de lupta a lui Gor'mul, un razboinic frant, mistuit de deznadejde. Un emisar ii aduce o Raptor Talon Amulet, in speranta ca aceasta ii va trezi spiritul neinfricat de odinioara. Totusi, Gor'mul ramane plin de amaraciune si se intreaba daca un simplu talisman i-ar putea alina vreodata durerea sau reda gloria Horde.",h="Raising Spirits este o misiune a Horde menita sa reaprinda vointa de lupta a lui Gor'mul, un razboinic frant...",kw={"Gor'mul","Gormul","Hoarda","inviorarea spiritelor","amuleta de rapitor","amuleta din gheara rapitorului","Warrior"},ang={["class:Warrior"]="Aceasta sarcina urmareste sa reaprinda spiritul razboinic stins al unui orc paralizat de disperare si durerea provocata de o lovitura miseleasca.",["faction:Horde"]="Gor'mul deplange puterea cazuta a Horde, intrebandu-se daca un simplu talisman ar putea vreodata reda factiunii gloria pierduta."},sec={{t="O scanteie pentru o flacara stinsa",b="Raising Spirits presupune ducerea unui Raptor Talon Amulet la un orc pe nume Gor'mul. Aliatii sai spera ca puterea salbatica si ferocitatea raptoarelor, canalizate prin talisman, vor reaprinde flacara razboinicului care ardea odinioara cu putere in vinele lui."},{t="Amaraciune si disperare",b="Dupa ce primeste talismanul, Gor'mul nu-si arata decat durerea amara. Chinuit de amintirea celor mai puternici campioni doborati de maini lasoase, respinge simbolul, spunand ca nu-i decat un os lustruit, si se intreaba cum ar putea vreo maruntis sa redea Hordei gloria de odinioara."}},faq={{q="Ce inseamna Raising Spirits?",a="Raising Spirits este o misiune prin care trebuie sa livrezi un Raptor Talon Amulet unui razboinic abatut pe nume Gor'mul, in speranta ca-i vei reaprinde spiritul de luptator.",al={"ce este ridicarea spiritelor","misiunea Raising Spirits"}},{q="Cine este Gor'mul?",a="Gor'mul este un razboinic zdrobit sufleteste, care a cazut in deznadejde dupa ce a vazut cei mai puternici campioni rapusi de mana unui las. Desconsidera simbolurile si pune la indoiala viitorul Horde.",al={"cine este gormul","gor mul"}},{q="De ce este dus Amuleta Ghearei de Raptor la Gor'mul?",a="Amuleta Ghearei de Raptor este confectionata din os lustruit si gheare de raptor, oferita in speranta ca invocarea fortei si ferocitatii naturale a raptoarelor va trezi flacara interioara a lui Gor'mul.",al={"de ce sa aduc amuleta","la ce foloseste amuleta cu gheara de rapitor"}},{q="De ce este Gor'mul abatut?",a="Gor'mul si-a pierdut orice speranta dupa ce a vazut cei mai puternici razboinici ucisi de lasitate. Tragedia l-a convins ca onoarea si puterea pot fi lesne stinse, frangandu-i vointa de a lupta.",al={"de ce este Gormul trist","de ce este Gormul deprimat"}},{q="Cum reactioneaza Gor'mul la amuleta?",a="Gor'mul refuza darul si respinge cu amaraciune amuleta, considerand-o doar un os lustruit, incapabil sa refaca Horde sau sa indrepte tragedia pe care o deplange.",al={"ii place lui gormul amuleta","reactia lui gormul"}},{q="Ce spune Gor'mul despre Horde?",a="Gor'mul se indoieste deschis ca Horde ar putea vreodata sa-si recapete gloria de odinioara, vazand putina speranta cand tradarea josnica poate dobori chiar si cei mai mari eroi.",al={"poate Horde sa-si recapete gloria","gloria Horde pentru Gormul"}}},fp="15,352,26.256.0,22.267.1,24.153.0,15.193.0,50.187.0,26.191.0,37.149.0,38.155.0"}
P.entries["quest:675"] = {n="Raising Spirits",s="Raising Spirits este o misiune a Horde care abordeaza trauma emotionala persistenta a unui veteran orc in varsta. Cu indrumarea lui Tor'gan, un saman incearca sa ajunga la Gor'mul, macinat de amaraciune, folosind magia stramosilor pentru a-i reda mandria pierduta si vointa de a trai.",h="Raising Spirits este o misiune a Horde care abordeaza trauma emotionala persistenta a unui veteran orc in...",kw={"amuleta","Gor'mul","mila","Orc","invocarea spiritelor","Shaman","Tor'gan","veteran","warchief"},ang={["class:Shaman"]="Aceasta sarcina ilustreaza scopul vindecator si spiritual al samanismului modern al orcilor, folosind relicve inzestrate cu putere pentru a ajuta la vindecarea traumelor persistente ale veteranilor zdruncinati.",["faction:Horde"]="Sub conducerea lui Thrall, Horde cauta in mod activ sa reintegreze si sa ridice moralul veteranilor indarjiti, in loc sa-i lase prada disperarii.",["race:Orc"]="Gor'mul intruchipeaza profunda suferinta spirituala si dezonoarea resimtite de veteranii de odinioara, carora li s-a refuzat ceea ce considerau a fi o moarte onorabila, alaturi de fostul lor Warchief."},sec={{t="Un spirit frant",b="Dupa razboaiele din trecut, multi veterani orci se lupta cu povara supravietuirii si cu dezonoarea pe care cred ca au indurat-o. Gor'mul este unul dintre ei; traieste intr-o deznadejde amara, fiindca i s-a refuzat ceea ce el socoteste a fi o moarte onorabila, alaturi de Warchief cazut. Tor'gan, un saman empatic, cauta sa-i aline suferinta reamintindu-i de forta spirituala a poporului sau. Crezand ca energiile stramosilor pot vindeca ranile sufletesti, Tor'gan pregateste o amuleta vrajita, menita sa reaprinda mandria batranului luptator."},{t="Limitele amuletei",b="Cand talismanul ii este inmanat lui Gor'mul, acesta nu produce efectul dorit. Intr-un acces de resentimente, Gor'mul arunca amuleta in tarana si se intreaba de ce i-ar arata cineva mila, cand soarta i-a refuzat un sfarsit onorabil. Tor'gan accepta esecul cu calm, intelegand ca un singur talisman nu avea puterea necesara sa invinga ani intregi de durere adanc inradacinata. Chiar si asa, samanul ramane neclintit in misiunea sa, convins ca practica in plina dezvoltare a samanismului il va calauzi, in cele din urma, pe Gor'mul inapoi spre onoarea de odinioara."}},faq={{q="Cine este Gor'mul?",a="Gor'mul este un veteran orc plin de amaraciune, mistuit de durere si de vina supravietuitorului. Dupa ce a supravietuit conflictelor vechii Horde, in care a cazut Warchief-ul sau, el vede faptul ca a ramas in viata drept o cruda intorsatura a sortii si respinge compasiunea obisnuita.",al={"cine este gormul","trecutul lui gormul","ce nu-i in regula cu gormul"}},{q="Cine este Tor'gan si de ce il ajuta pe Gor'mul?",a="Tor'gan este un saman care incearca sa-l scoata pe Gor'mul din deznadejdea sa amara. Crezand ca reconectarea cu traditiile strabune poate repara sufletele frante, Tor'gan confectioneaza amulete infuzate cu magie, pentru a le aminti fostilor razboinici de renasterea spirituala a poporului lor.",al={"cine este Torgan","ce vrea Torgan","scopul lui Torgan"}},{q="Care era scopul amuletei?",a="Amuleta era un talisman fermecat pregatit de Tor'gan pentru a trezi din nou spiritul razboinic al lui Gor'mul prin energia samanica. Cand i-a fost oferita, Gor'mul a respins-o si a aruncat-o la pamant, socotind ca magia ei nu era de ajuns pentru a-i risipi amaraciunea profunda.",al={"ce este amuleta","de ce a aruncat gormul amuleta","a functionat amuleta"}},{q="Dupa care Warchief jeleste Gor'mul?",a="Desi Gor'mul blestema soarta pentru ca nu l-a lasat sa moara alaturi de Warchief-ul sau in lupta, nu-i rosteste numele. Cuvintele sale reflecta perspectiva tragica a ramasitelor infrante ale vechii Horde, care tanjeau dupa o moarte onorabila pe campul de lupta.",al={"care sef de razboi a murit","cine era seful de razboi al lui Gormul","cui ii slujea Gormul"}},{q="Ce planuieste Tor'gan sa faca dupa ce amuleta da gres?",a="Tor'gan ramane rabdator in ciuda esecului initial. Recunoaste ca amuleta nu a fost suficient de puternica de una singura, dar isi pastreaza increderea ca demonstrarea adevaratei puteri a samanismului va reaprinde, in cele din urma, mandria pierduta a lui Gor'mul.",al={"renunta Torgan","ce se intampla dupa Raising Spirits","isi va reveni Gormul"}},{q="De ce foloseste Tor'gan samanismul pentru a-l ajuta pe Gor'mul?",a="Efortul scoate in evidenta rolul esential al samanilor in noua Horde, ca vindecatori spirituali, care nu doar canalizeaza elementele pentru razboi, ci ingrijesc si mintile ranite si mandria poporului lor.",al={"ce arata asta despre saman","de ce se foloseste aici magia samanilor"}}},fp="15,250,15.528.0,24.526.1,15.228.0,45.242.0,35.254.0,34.238.0,52.232.0,47.200.0"}
P.entries["quest:676"] = {n="The Hammer May Fall",s="Trimisi de Tallow din Tarren Mill, campionii Horde sunt indrumati peste munti, in Arathi Highlands, pentru a veni in ajutorul asezarii asediate Hammerfall. Inainte de a se prezenta la Drum Fel, aventurierii trebuie sa-si dovedeasca pregatirea de lupta infruntand brutalii ogri Boulderfist care pandesc langa ruinele din Stromgarde.",h="Trimisi de Tallow din Tarren Mill, campionii Horde sunt indrumati peste munti, in Arathi Highlands, pentru a...",kw={"arathi highlands","boulderfist enforcer","capcaun boulderfist","drum fel","hammerfall","hillsbrad foothills","stromgarde","seu","tarren mill","the hammer may fall"},ang={["class:Warrior"]="Infruntarea gorilor masivi Boulderfist este o proba clasica pentru luptatorii din prima linie care vor sa castige respectul comandantilor orci veterani precum Drum Fel.",["faction:Horde"]="Aceasta sarcina marcheaza trecerea de la disputele locale din Hillsbrad la apararea mai ampla a Arathi Highlands, consolidand pozitia strategica vitala a Hammerfall in regiune.",["race:Orc"]="Hammerfall are o profunda valoare sentimentala si istorica pentru orci, fiind intemeiat acolo unde Warchief Orgrim Doomhammer si-a dat viata in timpul campaniilor de eliberare."},sec={{t="O chemare aspra",b="In Tarren Mill, Tallow nu are rabdare cu aventurierii fara experienta care ratacesc prin Foothills. Vazand recruti nedisciplinati stand degeaba in timp ce aliatii indepartati sangereaza, ii trimite pe luptatorii capabili spre est, dincolo de Thoradin's Wall, in Arathi Highlands. Avanpostul Horde-ului din Hammerfall este asediat din mai multe directii, dar Tallow refuza sa trimita carne de tun daca luptatorii nu si-au dovedit mai intai valoarea infruntand adversari redutabili."},{t="Proba Boulderfist",b="In loc sa-i lase pe recruti sa ajunga orbecaind la Hammerfall, Tallow cere o dovada de forta martiala la movila ogre din nord-estul Stromgarde. Tribul Boulderfist are o prezenta puternica in Arathi, iar ogrii lor masivi si fortele de ordine reprezinta o amenintare imediata pentru oricine strabate potecile inaltimilor. Uciderea acestor brute rareste randurile fortelor ostile care flancheaza drumul si se asigura ca numai razboinicii capabili ajung la avanpost."},{t="Raportarea la Hammerfall",b="Dupa ce tabara Boulderfist este curatata, drumul duce spre nord-est, catre Hammerfall, un avanpost numit in amintirea Warchief Orgrim Doomhammer. Acolo, comandantul Drum Fel ii primeste pe noii veniti cu un scepticism istovit. Fie ca Tallow a vrut sa intareasca garnizoana, fie doar sa trimita niste neghiobi la moarte, Drum Fel nu pierde vremea si ii trimite pe luptatorii incercati in incaierarile fara sfarsit care ameninta supravietuirea avanpostului."}},faq={{q="Unde incepe si unde se incheie aceasta misiune?",a="Misiunea este oferita de Tallow in Tarren Mill, situat in Hillsbrad Foothills. Dupa ce ucizi tintele cerute in Arathi Highlands, o predai lui Drum Fel, in avanpostul Horde din Hammerfall.",al={"unde incep misiunea Hammer May Fall","locul de predare a misiunii","cine da misiunea Hammer May Fall"}},{q="Unde se gasesc ogrii Boulderfist?",a="Ogrul Boulderfist locuiesc pe o movila de pamant proeminenta si in tabara din jurul acesteia, la nord-est de ruinele Stromgarde, in Arathi Highlands.",al={"locatia capcaunilor Boulderfist","unde sunt capcaunii din Arathi","movila Boulderfist"}},{q="Ce este avanpostul Hammerfall?",a="Hammerfall este o asezare fortificata a Horde din nord-estul Arathi Highlands. Poarta numele in onoarea fostului Warchief Orgrim Doomhammer, care a cazut in lupta in apropiere, in timpul eliberarii lagarelor de internare ale orcilor.",al={"ce este Hammerfall","istoria Hammerfall","cine a fondat Hammerfall"}},{q="De ce te pune Tallow sa te lupti cu ogrii inainte sa te intorci la Hammerfall?",a="Hammerfall este atacata neincetat si are nevoie disperata de luptatori priceputi. Tallow trimite recrutii impotriva capcaunilor Boulderfist pentru a-i pune la incercare cu asprime si a se asigura ca cei care vin sa intareasca Drum Fel stiu sa lupte, in loc sa devina o povara in plus.",al={"de ce sa omori capcaunii mai intai","motivul lui Tallow","de ce ma testeaza"}},{q="Cine este Drum Fel?",a="Drum Fel este un razboinic orc veteran si comandant stabilit la Hammerfall, in Arathi Highlands. Sarcina lui este sa organizeze apararea impotriva vietatilor salbatice ostile, a ogreilor, trollilor si ramasitelor Alliance.",al={"identitatea lui Drum Fel","comandantul din Hammerfall","cine este drum fel"}},{q="Ce urmeaza dupa aceasta misiune?",a="Prezentarea la Drum Fel duce direct la campania Call to Arms, o serie de operatiuni militare menite sa elimine amenintarile din imprejurimi, inclusiv triburile troll Witherbark care ameninta tinuturile inalte.",al={"urmatoarea misiune","continuarea lui Hammer May Fall","ce urmeaza"}}},fx={b3b0715a={q="Cine sunt ogrii Boulderfist impotriva carora esti trimis?",a="Tribul Boulderfist este un clan brutal de ogri care pretinde teritorii in Arathi Highlands, cu centrul in movila lor de la nord-est de ruinele din Stromgarde. Feroce, incapatanati si impunatori fizic, ei stapanesc dealurile stancoase ale tinutului si isi disputa teritoriile din jur. Tallow te trimite la movila lor ca sa vada daca poti supravietui in fata luptatorilor lor din prima linie, asigurandu-se ca ai forta necesara inainte sa te arunci in masina de tocat carne care este zona de razboi din Arathi.",al={"ogrii Boulderfist","cine sunt Boulderfist","ogrii din Arathi"}}},fp="19,317,15.441.0,20.463.0,23.415.1,36.207.0,40.143.0,34.212.0,68.259.0,16.198.0,29.206.0"}
P.entries["quest:677"] = {n="Call to Arms",s="Call to Arms este o initiativa militara Horde, coordonata de Drum Fel din avanpostul Hammerfall din Arathi Highlands. Amenintata de alianta dintre trolii padureni Witherbark din zona si capcaunii Boulderfist, Horde lanseaza o campanie preventiva impotriva celor din Witherbark pentru a-si asigura pozitia in regiune.",h="Call to Arms este o initiativa militara Horde, coordonata de Drum Fel din avanpostul Hammerfall din Arathi...",kw={"arathi highlands","aruncator de topoare","boulderfist","chemare la arme","drum fel","hammerfall","vanator de capete","vrajitor-doctor","witherbark"},ang={["faction:Horde"]="Hammerfall se afla izolat in Arathi Highlands, inconjurat de forte ostile; apararea avanpostului impotriva factiunilor bastinase agresive este esentiala pentru a asigura o pozitie permanenta a Horde pe taramurile dominate de oameni.",["race:Orc"]="Construit pe locul unui fost lagar de internare din Second War, Hammerfall este un simbol al eliberarii pentru orci, ceea ce face ca apararea noii lor asezari impotriva vecinilor ostili sa fie o chestiune profund personala.",["race:Troll"]="Pentru trollii Darkspear care slujesc in Horde a lui Thrall, lupta impotriva trollilor ostili din padurea Witherbark scoate in evidenta ruptura adanca dintre poporul lor si triburile care au respins noua Horde."},sec={{t="Apararea Hammerfall",b="Din adapostul fortificat Hammerfall, Drum Fel organizeaza o lovitura militara preventiva impotriva puterilor bastinase ostile din Arathi Highlands. Inconjurata de vechi ruine umane si factiuni locale agresive, asezarea Horde se confrunta cu o amenintare iminenta, nascuta din pactul dintre trolii de padure bastinasi Witherbark si ogrii brutali Boulderfist. In loc sa-si lase dusmanii sa dicteze conditiile supravietuirii, Drum Fel cheama campionii la atac."},{t="Amenintarea Witherbark",b="Ofensiva initiala se concentreaza la sud de Hammerfall, vizand inima teritoriului Witherbark. Witherbark au renuntat la orice tentativa de diplomatie si au ales sa comploteze cu capcaunii Boulderfist pentru a alunga Horde din tinuturile inalte. Nimicindu-le aruncatorii de securi specializati, vanatorii de capete si vracii, Hammerfall urmareste sa le zdrobeasca conducerea militara si sa arate ca Horde a venit ca sa ramana."}},faq={{q="Cine ofera misiunea Call to Arms?",a="Call to Arms este data de Drum Fel, un orc stationat la avanpostul Horde din Hammerfall, in nord-estul Arathi Highlands. El coordoneaza atacurile defensive si ofensive pentru a asigura supravietuirea taberei in fata amenintarilor din imprejurimi.",al={"cine ofera Call to Arms","unde este Drum Fel","cel care da misiunea Call to Arms"}},{q="De ce ii vizeaza Hammerfall pe trolii Witherbark?",a="Tribul Witherbark, alcatuit din trolli ai padurii, s-a aliat cu ogrii Boulderfist pentru a alunga Horde din Arathi Highlands. Dupa ce au respins convietuirea pasnica si au intors spatele Horde, atitudinea lor agresiva nu-i lasa lui Hammerfall alta optiune decat sa loveasca primul.",al={"de ce sa-i ucid pe Witherbark","de ce sa atac trolii din Arathi","ce au facut Witherbark"}},{q="Unde se gasesc trolii Witherbark?",a="Trollii Witherbark locuiesc in mai multe asezari si tabere aflate la sud de Hammerfall, in Arathi Highlands, inclusiv in adancul Witherbark Village, langa munti.",al={"unde sunt trollii Witherbark","locatia taberei Witherbark","unde gasesti aruncatorii de topoare din Arathi"}},{q="Ce rol joaca ogrii Boulderfist in acest conflict?",a="Ogrele Boulderfist sunt un clan brutal care locuieste in Arathi Highlands. Potrivit lui Drum Fel, au incheiat o alianta de conjunctura cu trolii Witherbark pentru a eradica prezenta Horde in tinuturile inalte.",al={"cine sunt Boulderfist","ogri in Arathi","alianta trolilor Boulderfist"}},{q="Ce este Hammerfall si de ce trebuie aparat?",a="Hammerfall este principalul avanpost al Hordei din Arathi Highlands, numit in amintirea Warchief Orgrim Doomhammer. Asezat pe locul unei vechi tabere de internare a Alliancei, este un refugiu castigat cu greu si o fortareata militara a Hordei in Eastern Kingdoms.",al={"ce este Hammerfall","istoria Hammerfall","de ce se afla Horde in Arathi"}},{q="Fac trolii Witherbark parte din Horde?",a="Nu. Desi jungle trolls din Darkspear tribe sunt membri ai Horde, Witherbark sunt forest trolls originari din Eastern Kingdoms. Ei nutresc o ostilitate adanca fata de straini si au respins cu violenta orice apropiere din partea Horde.",al={"sunt Witherbark in Hoarda","sunt Troll forestieri prietenosi cu Hoarda","Darkspear contra Witherbark"}}},fp="12,316,20.489.0,21.423.0,34.241.0,50.275.0,40.173.0,57.220.0,50.262.0,44.243.0"}
P.entries["quest:678"] = {n="Call to Arms",s="Call to Arms este o incercare martiala a Horde, incredintata de Drum Fel la avanpostul Hammerfall din Arathi Highlands. Dupa ce si-au dovedit pregatirea de baza pentru lupta, aventurierii primesc ordinul sa se indrepte spre sud-vest, catre podul piticilor, si sa-i infrunte pe capcaunii periculosi Boulderfist. Eliminarea atat a brutelor din prima linie, cat si a magilor care arunca vraji pune la incercare hotararea razboinicului, aparand totodata pozitia vulnerabila a Horde in Arathi.",h="Call to Arms este o incercare martiala a Horde, incredintata de Drum Fel la avanpostul Hammerfall din Arathi...",kw={"Arathi Highlands","Boulderfist","bruta Boulderfist","mag Boulderfist","chemare la arme","Drum Fel","Hammerfall","ogri","Thandol Span"},ang={["class:Mage"]="Infruntarea magilor Boulderfist le permite magilor sa contracareze vrajitorii care se bazeaza pe forta bruta si folosesc energiile arcane in scopuri primitive si distructive.",["class:Warrior"]="Cerintele lui Drum Fel de a da dovada de tenacitate impotriva fortei brute si a puterii arcane le ofera razboinicilor o proba directa de rezistenta in lupta si onoare martiala.",["faction:Horde"]="Asigurarea lui Hammerfall este vitala pentru pozitia Horde in Eastern Kingdoms, iar rarirea capcaunilor agresivi Boulderfist impiedica avanpostul sa fie coplesit.",["race:Orc"]="Hammerfall poarta numele Warchief Orgrim Doomhammer, ceea ce le ofera orcilor un motiv profund personal sa alunge orice brute rivale care ameninta aceasta fortareata memoriala."},sec={{t="O proba de curaj",b="La avanpostul Horde izolat din Hammerfall, supravietuirea cere o forta martiala de neclintit. Drum Fel, recunoscand abilitatile tot mai mari ale calatorilor care ajuta avanpostul, nu lasa pe nimeni sa se multumeasca cu victorii usoare. In loc sa infrunte simpli luptatori de gherila, razboinicii trebuie sa-si dovedeasca valoarea impotriva a ceea ce Fel considera o amenintare adevarata: ogrii masivi Boulderfist. Acesti brute au hartuit in repetate randuri expeditia Horde si au pus la incercare hotararea aparatorilor din Hammerfall. Fel pune conditii simple: razboinicii trebuie sa se intoarca invingatori, in carne si oase sau macar cu onoarea intacta, iar pentru tenacitatea lor in lupta li se promite lauda."},{t="Amenintarea Boulderfist",b="Clanul Boulderfist si-a intemeiat o vizuina bine fortificata la sud-vest de Hammerfall, extinzandu-si teritoriul spre marele pod pitic care leaga Arathi de Wetlands. Spre deosebire de fiarele nedisciplinate, ogrii stapanesc atat o forta fizica zdrobitoare, cat si arte mistice letale, trimitand in lupta brute rezistente si magi sireti. Prezenta lor agresiva ameninta direct liniile de aprovizionare ale Horde si suprematia regionala. Poruncind distrugerea a zece brute Boulderfist si a patru magi, Drum Fel urmareste sa le slabeasca puterea, facandu-i pe Boulderfists sa inteleaga ca razboinicii din Hammerfall nu vor ceda teren si nu vor tolera rivali in Arathi."}},faq={{q="Cine ofera misiunea Call to Arms?",a="Misiunea este oferita de Drum Fel, un ofiter stationat in avanpostul fortificat Horde din Hammerfall, in nord-estul regiunii Arathi Highlands. In cautarea unor campioni capabili sa apere pozitia fragila a fortaretei, Fel le cere luptatorilor incercati sa porneasca impotriva adversarilor periculosi din regiune, pentru a-si dovedi disciplina martiala si forta bruta.",al={"cine ofera call to arms","misiunea drum fel","cel care ofera misiunea call to arms"}},{q="Unde se afla vizuina Boulderfist?",a="Asezarea capcaunilor Boulderfist se afla la sud-vest de Hammerfall, de-a lungul drumului spre Thandol Span, marele pod al piticilor care duce in Wetlands. Capcaunii locuiesc in vizuini si movile de pamant din tinuturile inalte, unde se aduna in numar mare atat batausii lor, cat si vrajitorii.",al={"locatia Boulderfist","unde sunt ogrii","vizuina Boulderfist din Arathi"}},{q="Ce dusmani trebuie invinsi pentru aceasta sarcina?",a="Drum Fel le porunceste razboinicilor sa elimine zece bruti Boulderfist si patru magi Boulderfist inainte de a se intoarce la Hammerfall. Brutele se bazeaza pe atacuri grele in lupta corp la corp, in timp ce magii le ofera sprijin de la distanta cu vraji arcane, fiind astfel mult mai periculosi decat batausii obisnuiti de pe drumurile din Arathi.",al={"numarul de ucideri pentru Call to Arms","ce ogri trebuie ucisi","tinte pentru Call to Arms"}},{q="De ce sunt considerati ogrii Boulderfist o amenintare pentru Hammerfall?",a="Boulderfist-ii si-au consolidat o pozitie fortificata in Arathi si au provocat in repetate randuri garnizoana Horde de la Hammerfall. Apropierea lor de rutele-cheie de tranzit spre podul pitic din sud ameninta recunoasterea si liniile de aprovizionare ale Horde. Drum Fel ii considera o forta rivala autentica, care trebuie tinuta sub control prin atacuri martiale regulate.",al={"de ce sa ne luptam cu Boulderfist","sunt Boulderfist ostili Hoardei","amenintarea ogrelor in Arathi"}},{q="Ce vrea sa spuna Drum Fel prin a se intoarce in trup sau in spirit?",a="Remarca sumbra a lui Drum Fel reflecta spiritul razboinic neinduplecat al Horde din Arathi. Se asteapta ca luptatorii sai sa izbandeasca si sa se intoarca teferi, dar ii respecta pe cei care cad luptand vitejeste impotriva unor dusmani redutabili. In ochii lui, sa dai dovada de tenacitate si neinfricare in fata fortei coplesitoare a ogurilor aduce onoare, indiferent daca supravietuiesti sau nu intalnirii sangeroase.",al={"citatul Drum Fel","semnificatia intoarcerii in spirit","sa vii in trup sau in spirit"}},{q="Pot jucatorii din Alliance sa intreprinda aceasta misiune?",a="Nu, acest Call to Arms este strict o misiune a Horde, oferita de Drum Fel in Hammerfall. Fortele Alliance isi au baza la Refuge Pointe, spre vest, si ii considera dusmani ostili atat pe aparatorii din Hammerfall, cat si pe ogrii Boulderfist, rivali in lupta pentru dominatia asupra Arathi Highlands.",al={"misiunea call to arms este doar pentru horda","call to arms pentru alianta in arathi","poate alianta sa faca aceasta misiune"}},{q="De ce Drum Fel ii vizeaza atat pe batausi, cat si pe magi?",a="Tintirea ambelor tipuri de ogri neutralizeaza avantajul tactic al fortelor combinate ale Boulderfist. Matahalele formeaza linia intai, musculoasa, care absoarbe loviturile, in timp ce magii folosesc magie distructiva din spate. Infrangerea ambelor tipuri impiedica clanul sa lanseze o contraofensiva organizata impotriva Hammerfall.",al={"de ce sa ucid magii","importanta magilor Boulderfist","Boulderfist brute si magus"}}},fp="12,399,16.642.0,22.661.0,33.356.0,38.307.0,48.306.0,64.356.0,58.370.0,42.275.0,46.307.0"}
P.entries["quest:679"] = {n="Call to Arms"}
P.entries["quest:68"] = {n="The Legend of Stalvan",s="Aceasta investigatie dezgroapa un capitol uitat din povestea intunecata a lui Stalvan Mistmantle. O scrisoare prafuita, netrimisa, scoasa dintr-un cufar de calatorie uitat in Moonbrook, ofera dovada concreta a locului in care a stat inainte ca urma sa i se piarda, ducand inapoi la arhivele din Darkshire.",h="Aceasta investigatie dezgroapa un capitol uitat din povestea intunecata a lui Stalvan Mistmantle.",kw={"functionar daltry","blestemul lui Stalvan","Darkshire","Duskwood","scrisoare prafuita netrimisa","lada","Forlorn Spirit","Mistmantle","Moonbrook","Stalvan"},ang={["class:Mage"]="Umbra ostila care pazeste lada de calatorie manuieste unelte arcane inselatoare, precum polimorfia, alaturi de un blestem paralizant, sugerand fortele nefiresti impletite in urma lasata de Stalvan.",["class:Priest"]="Intruparea unui Forlorn Spirit legat de un simplu cufar cu amintiri vorbeste despre o povara emotionala chinuitoare, care nu si-a gasit odihna nici dupa moarte.",["faction:Alliance"]="Deslusirea misterului lui Stalvan Mistmantle ajuta orasul Darkshire, aflat sub asediu, sa identifice siluetele intunecate care au trecut granitele regiunii."},sec={{t="O urma uitata in Moonbrook",b="In timp ce cerceteaza trecutul lui Stalvan Mistmantle, un cufar vechi, uitat in Moonbrook, dezvaluie o piesa esentiala a puzzle-ului: o scrisoare prafuita, netrimisa. Moonbrook, odinioara o asezare agricola infloritoare, a ajuns o ruina, iar acum e plina de proscrisi si spectre nelinistite. Stalvan a stat aici prea putin pentru a ramane in amintirea oamenilor de rand, dar scrisoarea neglijata dovedeste fara tagada ca a fost in catun."},{t="O bantuire la lada",b="Scotocirea prin lucrurile lui Stalvan nu trece neobservata. Tulburarea cufarului trezeste din umbre un Forlorn Spirit, dornic sa pazeasca secretele ramase in urma. Spectrul ataca prin magie vrajita si blestemul debilitant Curse of Stalvan, sugerand ca, orice soarta ar fi avut omul, durerea si vrajitoria intunecata apasa greu asupra lucrurilor sale ramase."},{t="Actualizarea registrului orasului",b="Returnarea scrisorii peste granita, in Darkshire, ii ofera lui Clerk Daltry documentatia lipsa de care are nevoie. Desi Daltry considera ciudat faptul ca scrisoarea nu a fost niciodata trimisa, dovezile sunt de netagaduit. Odata verificata legatura cu Moonbrook, sirul documentelor birocratice poate, in sfarsit, sa indrume ancheta catre locul in care a fugit apoi Stalvan."}},faq={{q="Ce se afla in vechiul cufar din Moonbrook?",a="In lada de campanie se afla o scrisoare prafuita, Unsent Letter, scrisa in timpul sederii lui Stalvan Mistmantle in Moonbrook. Este o dovada materiala care confirma ca a locuit in oras inainte de a disparea.",al={"ce am gasit","continutul cufarului","scrisoarea lui Stalvan"}},{q="De ce ataca un spirit cand este deschis cufarul?",a="Un Forlorn Spirit bantuie in apropierea lucrurilor uitate ale lui Stalvan si se ridica sa atace pe oricine ii tulbura cufarul. Foloseste magie nelinistitoare, inclusiv efecte de teama, vraji de metamorfozare si blestemul persistent al lui Stalvan.",al={"forlorn spirit","de ce sunt atacat","fantoma din lada de voiaj"}},{q="De ce trebuie dusa scrisoarea la Clerk Daltry?",a="Clerk Daltry supravegheaza registrele orasului si arhiva din primaria Darkshire. Are nevoie de documente concrete care sa confirme unde s-a aflat Stalvan in trecut, inainte de a te putea ajuta sa-i dai de urma.",al={"cine este functionarul Daltry","de ce Daltry","primaria din Darkshire"}},{q="De ce este important faptul ca scrisoarea nu a fost trimisa niciodata?",a="Faptul ca scrisoarea a ramas ascunsa si abandonata intr-un cufar de voiaj abandonat sugereaza o plecare brusca sau o paranoia tot mai accentuata, intarind secretul tulburator care inconjoara miscarile lui Stalvan.",al={"misterul scrisorii netrimise","de ce nu a fost expediata"}},{q="Ce efect are blestemul lui Stalvan?",a="Blestemul lui Stalvan, provocat de Forlorn Spirit care pazeste lada de campanie, este un blestem debilitant care reduce toate atributele primare ale victimei timp de zece minute.",al={"blestemul lui Stalvan","blestemul spiritului"}},{q="Unde duce pista dupa ce ii dai scrisoarea lui Daltry?",a="Dupa ce Clerk Daltry actualizeaza registrul municipal cu aceasta dovada din Moonbrook, iti poate indruma cercetarile catre urmatoarea destinatie cunoscuta a lui Stalvan.",al={"ce urmeaza","unde merg dupa daltry","urmatorul indiciu"}}},fp="21,277,30.406.0,28.360.1,26.344.0,47.192.0,50.210.0,36.196.0,53.199.0,34.169.0,60.163.0"}
P.entries["quest:680"] = {n="The Real Threat",s="Dupa Call to Arms, Korin Fel iti spune ca sotul ei nu stie de ce Hammerfall este atacat si iti cere sa-l ucizi pe capcaunul Or'Kalar si sa-i aduci capul.",h="Dupa Call to Arms, Korin Fel iti spune ca sotul ei nu stie de ce Hammerfall este atacat si iti cere sa-l...",kw={"Arathi Highlands","hammerfall","korin fel","mug'thol","or'kalar","stromgarde","tower of arathor"},sec={{t="O ranchiuna impotriva sotului ei",b="Korin Fel spune ca ii esti de mare ajutor sotului ei, dar el habar n-are de ce este atacat Hammerfall. Vinovatul este Or'Kalar, marioneta lui Mug'thol in Stromgarde, care-l uraste pe sotul ei pentru ca l-a invins cu ani in urma si il vrea mort. Viziunile ei ii spun ca ogrele i-au intins o capcana."},{t="Ce ascunde Korin",b="Korin i-a ascuns sotului ei semnele prezentei ogrului, fiindca este convinsa ca el ar porni nechibzuit la drum daca ar sti unde se afla Or'Kalar. In schimb, iti cere tie ajutorul. Il vei gasi pe Or'Kalar langa Tower of Arathor, iar ea se asteapta ca moartea lui sa puna capat atacurilor asupra Hammerfall."}},faq={{q="Pe cine incearca Korin Fel sa protejeze?",a="Sotul ei. Prevestirile ei ii spun ca Or'Kalar i-a intins o capcana, iar capcaunul il vrea mort pentru ca l-a invins cu ani in urma.",al={"sotul lui korin","de ce are korin nevoie de ajutor"}},{q="De ce ataca Or'Kalar Hammerfall?",a="Korin Fel il numeste pe Or'Kalar pionul lui Mug'thol in Stromgarde, plin de ura fata de sotul ei, care l-a invins cu ani in urma. Ea spune ca moartea lui ar opri atacurile.",al={"de ce il uraste or'kalar pe sotul lui korin","cine este or'kalar","motivul lui or'kalar"}},{q="Unde se afla Or'Kalar?",a="Korin Fel spune ca se afla langa Tower of Arathor.",al={"locatia lui or'kalar","unde il gasesc pe or'kalar","gaseste-l pe or'kalar"}},{q="De ce pastreaza Korin secretul amenintarii fata de sotul ei?",a="Se teme ca el ar porni nechibzuit la drum daca ar afla unde se afla capcaunul, asa ca l-a impiedicat sa vada vreo urma a lui Or'Kalar.",al={"de ce sa pastrezi secretul","de ce sa ascunzi or'kalar","secretul lui korin"}}},fp="15,169,28.274.0,16.281.0,35.124.0,37.162.0,26.47.0,57.125.0"}
P.entries["quest:681"] = {n="Northfold Manor",s="Captain Nials, din Refuge Pointe, cere ajutor impotriva Syndicate, care ocupa Northfold Manor. Stapanirea lor asupra tinutului dintre aparatorii din Stromgarde si cei din Southshore ingreuneaza sosirea proviziilor.",h="Captain Nials, din Refuge Pointe, cere ajutor impotriva Syndicate, care ocupa Northfold Manor.",kw={"captain nials","talhar","mercenar","northfold manor","refuge pointe","southshore","stromgarde","syndicate"},sec={{t="O aparare dificila",b="Stromgarde a fost impartita intre ogre, Syndicate si Alliance, iar fiecare factiune se lupta cu celelalte pana la un impas sangeros. Fortele Alliance scad, in timp ce dusmanii lor se inmultesc. Apararea are nevoie de ajutor din Southshore, dar proviziile ajung cu intarziere."},{t="Syndicate la conac",b="Syndicate stapaneste teritoriul dintre aparatori si Southshore. Captain Nials vrea sa mergi la baza lor din Northfold Manor si sa-i dobori pe talharii de drumul mare si pe mercenarii lor, in speranta ca presiunea asupra trenurilor de aprovizionare va scadea si ca mai multe vor ajunge la destinatie."}},faq={{q="De ce vrea Captain Nials ca Syndicate sa fie atacati la Northfold Manor?",a="Ajutorul trebuie sa vina din Southshore, dar Syndicate controleaza tinutul dintre acel loc si aparatori. Nials spera ca uciderea lor in tabara de baza va reduce presiunea asupra convoaielor de provizii.",al={"de ce sa ataci Northfold Manor","obiectivul lui Nials","scopul misiunii Northfold Manor"}},{q="Care este situatia actuala in Stromgarde?",a="Ogres, Syndicate si Alliance au impartit intre ei orasul odinioara maret, iar fiecare factiune lupta cu celelalte pana la un impas sangeros. Fortele Alliance se imputineaza, in timp ce dusmanii sai cresc in numar.",al={"situatia razboiului din Stromgarde","cine controleaza Stromgarde","starea Stromgarde"}},{q="De unde vin proviziile Alliance?",a="Aparatorii cer ajutor orasului Southshore, dar controlul Syndicate asupra tinuturilor dintre ele face ca proviziile sa fie greu de primit.",al={"cine aprovizioneaza Refuge Pointe","provizii pentru Southshore","de unde provin transporturile"}},{q="Ce dusmani trebuie eliminati de la conac?",a="Zece Syndicate Highwaymen si sase Syndicate Mercenaries, aflati la Northfold Manor.",al={"pe cine sa omori la Northfold","tinte la Northfold","lista dusmanilor Syndicate"}}},fp="15,205,20.269.0,26.257.0,70.197.0,44.201.0,44.140.0,49.81.0"}
P.entries["quest:682"] = {n="Stromgarde Badges",s="In Stromgarde, Syndicate se lupta cu un contingent de militie, iar liderii sai platesc aur pentru fiecare insigna luata de la un militiaman cazut. La Refuge Pointe, Captain Nials vrea ca acele insigne sa fie recuperate.",h="In Stromgarde, Syndicate se lupta cu un contingent de militie, iar liderii sai platesc aur pentru fiecare...",kw={"arathi","insigne","captain nials","militie","refuge pointe","stromgarde","syndicate"},sec={{t="Recompensa pe capul soldatilor",b="In Stromgarde, Syndicate este in razboi cu un contingent de militieni. Pentru a-si impinge adeptii sa lupte impotriva soldatilor mai bine instruiti, liderii Syndicate platesc aur pentru fiecare insigna luata de la un militiaman ucis. Captain Nials ii numeste asasini si nu-i va lasa sa pastreze trofee de la cei cazuti cu vitejie, asa ca esti trimis in partea din Stromgarde controlata de Syndicate sa cauti insignele si sa le aduci inapoi la Refuge Pointe. Nials vrea ca Syndicate sa afle ca nu poate profita de pe urma mortilor."},{t="Dupa vanatoare",b="Nials promite ca rudelor celor cazuti li se va spune ca au murit in lupta. Vestea e sumbra, dar Nials considera ca e mai bine asa decat sa lasi o familie sa se intrebe ce s-a intamplat cu o ruda disparuta."}},faq={{q="De ce vrea Syndicate insignele din Stromgarde?",a="Liderii lor au pus o recompensa pe capul militiei: aur pentru fiecare insigna luata de la un militiaman cazut, menita sa-i impinga pe adeptii Syndicate sa lupte cu trupele mai bine antrenate.",al={"de ce insigne Syndicate","recompensa Syndicate din Stromgarde","de ce sa colectezi insigne"}},{q="Unde se gasesc insemnele?",a="Captain Nials te trimite in partea din Stromgarde controlata de Syndicate, sa-i vanezi pentru insemne.",al={"unde gasesti insigne","locatia insignei Stromgarde","unde cad insignele"}},{q="Cine ordona recuperarea insignelor?",a="Captain Nials, din Refuge Pointe, care nu vrea ca Syndicate sa pastreze trofee de la militia cazuta.",al={"cine da insignele Stromgarde","misiunea cu insigna Captain Nials","cel care ofera misiunea cu insigne Stromgarde"}}},fp="17,200,20.487.0,14.204.1,46.189.0,27.103.0,39.106.0"}
P.entries["quest:683"] = {n="Sara Balloo's Plea"}
P.entries["quest:684"] = {n="WANTED: Marez Cowl",s="WANTED: Marez Cowl este o misiune Alliance de punere a unei recompense pe capul unui agent de rang inalt al Syndicate, instalat in ruinele din Stromgarde. Fiind atat un consilier influent, cat si un warlock intunecat care face trafic cu demoni, Cowl reprezinta o amenintare grava pentru fortele Alliance care incearca sa securizeze Arathi Highlands.",h="WANTED: Marez Cowl este o misiune Alliance de punere a unei recompense pe capul unui agent de rang inalt al...",kw={"arathi highlands","rasplata","captain nials","marez cowl","refuge pointe","stromgarde","syndicate","warlock"},ang={["class:Paladin"]="Ca traficant pe fata de entitati demonice printre ruinele unui stravechi regat omenesc, Cowl sfideaza Holy Light si apararea Stromgarde.",["class:Warlock"]="Marez Cowl intruchipeaza aripa ocultista intunecata a Syndicate, demonstrand cat de usor recurg rebelii politici la invocari demonice pentru a-si extinde influenta.",["faction:Alliance"]="Garnizoana Alliance din Refuge Pointe, aflata sub comanda capitanului Nials, lupta cu disperare pentru a recuceri Stromgarde, ceea ce face din tinte Syndicate de rang inalt, precum Marez Cowl, o prioritate strategica."},sec={{t="Un pret pentru conducerea Syndicate",b="CAUTATA: Marez Cowl este tinta unui ordin de recompensa al Alliance, menit sa elimine una dintre figurile-cheie ale conducerii Syndicate din Arathi Highlands. Marez Cowl este consilier de rang inalt si agent de teren in cadrul organizatiei, orchestrandu-i activitatile in capitala ruinata Stromgarde. Oferind o recompensa pentru capul ei, comandantii Alliance din Refuge Pointe urmaresc sa decapiteze structura locala de comanda a Syndicate."},{t="Vrajitorul din Stromgarde",b="Spre deosebire de talharii obisnuiti sau nobilii fara pamant din randurile Syndicate, Marez Cowl practica vrajitoria intunecata. Este cunoscuta drept o vrajitoare iscusita, care se foloseste pe fata de puterile demonice pentru a-si impune vointa si a apara teritoriul Syndicate. Pentru a ajunge la ascunzatoarea ei din Stromgarde, trebuie sa infrunti nu doar asasini si conspiratori, ci si entitatile malefice pe care le stapaneste."}},faq={{q="Cine este Marez Cowl?",a="Marez Cowl este o agenta de rang inalt si sfatuitoare in cadrul Syndicate. Departe de a fi doar un soldat oarecare, ea exercita o influenta considerabila in organizatia criminala si este cunoscuta drept o warlock vicleana si periculoasa, care face negot cu forte demonice.",al={"cine este Marez Cowl","trecutul lui Marez Cowl","cine este ea"}},{q="Unde se afla Marez Cowl?",a="Marez Cowl locuieste in partea ruinata a orasului Stromgarde controlata de Syndicate, in regiunea Arathi Highlands. Oricine incearca s-o vaneze trebuie sa strabata teritorii impanzite de criminali pentru a-i gasi sanctuarul.",al={"unde il gasesc pe Marez Cowl","locatia lui Marez Cowl","unde se afla Marez"}},{q="Cine a pus recompensa pe capul lui Marez Cowl?",a="Recompensa este oferita in numele fortelor militare Alliance stationate in Arathi Highlands. De ea se ocupa capitanul Nials, care comanda fortareata Alliance din Refuge Pointe.",al={"cine a pus recompensa pe marez cowl","cine il vrea mort pe marez cowl","cine plateste recompensa"}},{q="De ce s-a pus o recompensa pe capul ei?",a="Este cautata din cauza rolului sau esential de conducere in Syndicate si a practicarii active a invocarii demonice in Stromgarde. Prezenta sa reprezinta o amenintare imediata pentru garnizoana Alliance, care se lupta sa recucereasca regatul ruinat.",al={"de ce este Marez Cowl cautat","de ce s-a pus o recompensa pe Marez Cowl","de ce sa-l ucid pe Marez Cowl"}},{q="Ce fel de magie foloseste Marez Cowl?",a="Marez nu este doar o conspiratoare politica; este si o Warlock iscusita, care invoca demoni si negociaza cu ei in mod activ. Vanatorii sunt avertizati explicit sa fie extrem de precauti cand o infrunta pe ea si pe slugile ei demonice.",al={"ce il face periculos pe marez cowl","puterile lui marez cowl","e marez cowl puternic"}},{q="Unde predai recompensa pentru Marez Cowl?",a="Dupa ce Marez Cowl este ucisa, capul ei trebuie dus direct la Captain Nials, in Refuge Pointe, principalul avanpost al Alliance din Arathi Highlands.",al={"unde predai recompensa pentru Marez Cowl","unde se afla capitanul Nials","predarea capului lui Marez"}}},fp="18,312,31.423.0,25.373.0,18.260.0,28.217.0,36.186.0,34.240.0,39.224.0,47.150.0"}
P.entries["quest:685"] = {n="WANTED: Otto and Falconcrest",s="O recompensa anuntata de Stromgarde Militia cere moartea lui Lord Falconcrest, conducatorul fortelor locale din Syndicate, si a bodyguardului sau ucigas, Otto. Eliminarea lor ar lovi puternic pozitiile organizatiei criminale din Arathi Highlands. Dovezile mortii lor trebuie duse capitanului Nials, la Refuge Pointe.",h="O recompensa anuntata de Stromgarde Militia cere moartea lui Lord Falconcrest, conducatorul fortelor locale...",kw={"arathi highlands","recompensa","captain nials","falconcrest","otto","refuge pointe","militia Stromgarde","syndicate"},ang={["faction:Alliance"]="Lord Falconcrest si agentii Syndicate ameninta ramasitele Stromgarde, ceea ce face ca aceasta recompensa sa fie esentiala pentru securizarea Refuge Pointe si recucerirea tinuturilor inalte.",["race:Human"]="Pentru aparatorii din Stromgarde, uciderea nobililor oameni tradatori din Syndicate este o lupta personala, menita sa razbune regatul cazut."},sec={{t="O recompensa pentru o misiune disperata",b="Militia din Stromgarde a emis o recompensa oficiala pentru doua personaje-cheie din Arathi Highlands: Lord Falconcrest si garzile sale de corp feroce, Otto. Avand baza la Refuge Pointe, aparatorii coplesiti ai Stromgarde incearca sa rupa stapanirea Syndicate asupra tinuturilor stramosesti. Vanatorii trebuie sa aduca capetele ambelor tinte capitanului Nials pentru a-si revendica recompensa."},{t="Comandant si executor",b="Lord Falconcrest este creierul din spatele incursiunii coordonate a Syndicate in Arathi Highlands. Moartea lui reprezinta o victorie strategica esentiala pentru Alliance, care ar trebui sa perturbe grav operatiunile retelei criminale din regiune. Alaturi de el se afla Otto, o garda de corp de o eficienta brutala, ale carei lame au doborat deja zeci de soldati din militia ramasa a Stromgarde."}},faq={{q="Cine este Lord Falconcrest?",a="Lord Falconcrest este un nobil si comandant care conduce operatiunile Syndicate in Arathi Highlands. Prezenta sa coordoneaza ocuparea oportunista a regatului ruinat Stromgarde, iar inlaturarea lui devine un obiectiv prioritar pentru militia locala de oameni.",al={"cine este Lord Falconcrest","povestea lui Falconcrest","cine este Falconcrest"}},{q="Cine este Otto?",a="Otto este garda de corp personala, letala, a lui Lord Falconcrest. Desi nu este un strateg precum stapanul sau, este un combatant feroce, raspunzator de uciderea a zeci de aparatori din Stromgarde in tinuturile inalte.",al={"cine este otto","garda de corp a lui falconcrest","otto sindicat"}},{q="De ce a pus Stromgarde Militia pret pe capul lor?",a="Militia din Stromgarde a pus recompense pe capetele lor pentru a decapita conducerea Syndicate in Arathi Highlands. Eliminarea lui Falconcrest le destrama structura regionala de comanda, iar uciderea lui Otto inlatura o amenintare letala, care a macelarit multi luptatori ai Alliance.",al={"de ce s-a pus recompensa pe Falconcrest","de ce sa-i omori pe Otto and Falconcrest","recompensa din Stromgarde"}},{q="Cine ofera recompensa pentru Otto and Falconcrest?",a="Recompensele pentru Lord Falconcrest si Otto sunt incasate de capitanul Nials, un ofiter al militiei din Stromgarde stationat la Refuge Pointe, in Arathi Highlands.",al={"unde predau misiunea pentru otto falconcrest","cine este captain nials","unde predau recompensa pentru falconcrest"}},{q="Ce face Syndicate in Arathi Highlands?",a="Syndicate este alcatuita din nobili Alteraci cazuti in dizgratie si elemente renegate, care urmaresc sa puna mana pe pamanturi si bogatii in mijlocul prabusirii nordului Lordaeron. In Arathi Highlands, au ocupat ruinele Stromgarde pentru a prelua controlul de la aparatorii sai supravietuitori.",al={"ce este Syndicate in Arathi","rolul Syndicate in Arathi"}},{q="Ce dovada este necesara pentru a revendica recompensa?",a="Pentru a revendica recompensa, vanatorii trebuie sa-i aduca lui Captain Nials, la Refuge Pointe, capetele taiate ale lui Lord Falconcrest si Otto, drept dovada incontestabila a mortii lor.",al={"unde sa duc capul lui Otto","dovada recompensei"}}},fp="28,329,18.373.0,22.393.0,24.255.0,12.206.0,55.267.0,47.168.0,52.255.0,43.171.0"}
P.entries["quest:686"] = {n="A King's Tribute"}
P.entries["quest:687"] = {n="Theldurin the Lost",s="Un membru al lui Twilight's Hammer iti cere sa-l gasesti pe Theldurin the Lost, care a facut candva parte din ordinul lor, si-a pierdut mintile si a fugit cu pergamentul lui Myzrael. Zvonurile spun ca se afla in Badlands.",h="Un membru al lui Twilight's Hammer iti cere sa-l gasesti pe Theldurin the Lost, care a facut candva parte din...",kw={"badlands","gerrig bonegrip","myzrael","scroll of myzrael","theldurin","theldurin the lost","twilight's hammer","zaruk"},sec={{t="Barbatul care a furat pergamentul",b="Theldurin a facut candva parte din Twilight's Hammer, pana cand si-a pierdut mintile si a intors spatele invataturilor ordinului. In timp ce fugea, a luat cu el scroll-ul lui Myzrael. Cei pe care i-a lasat in urma nu l-au putut prinde."},{t="Zvonuri despre Badlands",b="Ordinul a auzit ca Theldurin se ascunde in Badlands, delirand si innebunit. Pergamentul este necesar pentru intoarcerea lui Lady, iar ca sa-l obtii trebuie mai intai sa-l gasesti pe omul care l-a luat."}},faq={{q="Cine este Theldurin the Lost?",a="Un fost membru al Twilight's Hammer, care si-a pierdut mintile, a respins invataturile ordinului si a fugit cu pergamentul lui Myzrael.",al={"povestea lui theldurin","cine este theldurin","istoria lui theldurin"}},{q="De ce il cauta Twilight's Hammer?",a="A fugit cu scroll of Myzrael, pe care ordinul spune ca trebuie sa-l gaseasca pentru a o readuce pe Lady.",al={"de ce sa-l gasesti pe theldurin","de ce vor cultistii sa-l gaseasca pe theldurin"}},{q="Unde a fugit Theldurin dupa ce a parasit ordinul?",a="Ordinul nu are decat zvonuri, care il situeaza in Badlands.",al={"unde este theldurin","locatia si povestea lui theldurin"}},{q="Ce precede in mod direct aceasta cautare?",a="Urmeaza dupa Myzrael's Allies.",al={"misiunea anterioara theldurin","conditie prealabila pentru Theldurin the Lost"}}},fp="18,185,28.215.0,22.172.0,26.128.0,45.97.0,49.59.0,39.28.0"}
P.entries["quest:688"] = {n="Myzrael's Allies"}
P.entries["quest:689"] = {n="A King's Tribute"}
P.entries["quest:69"] = {n="The Legend of Stalvan",s="Aceasta misiune marcheaza o cotitura decisiva in cautarea lui Stalvan Mistmantle, greu de gasit, conducandu-i pe anchetatori din negura tinutului Duskwood inapoi spre inima regatului. O insemnare mazgalita in graba si apoi stearsa, descoperita in registrul orasului Darkshire, indica un loc de dincolo de rau: Goldshire. Urmarea pistei documentelor pana la animatul Lion's Pride Inn este urmatorul pas pentru a afla unde a disparut misteriosul tutore.",h="Aceasta misiune marcheaza o cotitura decisiva in cautarea lui Stalvan Mistmantle, greu de gasit, conducandu-i...",kw={"clerk daltry","darkshire","duskwood","elwynn forest","goldshire","innkeeper farley","lion's pride inn","stalvan"},ang={["faction:Alliance"]="Dezlegarea istoriilor locale si urmele reci din teritoriile sudice ale Alliance necesita calatorii intre avanposturi de frontiera precum Darkshire si catune centrale precum Goldshire.",["race:Human"]="Pe urmele lui Stalvan, vei strabate inima Kingdom of Stormwind, legand frontierele bantuite din Duskwood de confortul familiar din Elwynn Forest."},sec={{t="Un indiciu in registru",b="In timp ce revizuieste arhivele din Darkshire, Clerk Daltry descopera o omisiune in registrul orasului. Ascunsa sub o inregistrare mai veche despre Stalvan Mistmantle se afla o a doua destinatie, scrisa in graba si partial stearsa, de parca cineva s-ar fi razgandit sau ar fi vrut sa-si ascunda miscarile. Nota arata ca Stalvan intentiona sa calatoreasca spre nord-vest, catre Elwynn Forest, mai exact la Lion's Pride Inn."},{t="Trecerea in Elwynn",b="Parasirea crangurilor umbrite din Duskwood pentru drumurile insorite din Goldshire ofera un contrast izbitor, insa umbra trecutului lui Stalvan ajunge chiar si aici. Lion's Pride Inn este o rascruce plina de viata in Elwynn Forest, primind deopotriva calatori, negustori si soldati. Innkeeper Farley domneste peste sala de mese aglomerata, fiind persoana ideala pe care sa o intrebi despre un calator invatat care cauta adapost."}},faq={{q="De ce duce urma la Goldshire?",a="Clerk Daltry a descoperit o a doua adresa, stearsa partial, in registrul din Darkshire, sub prima inregistrare a lui Stalvan. Aceasta indica limpede ca se indrepta spre Lion's Pride Inn din Goldshire.",al={"de ce goldshire","de ce sa mergi la goldshire","stalvan in goldshire"}},{q="Cine este Clerk Daltry?",a="Clerk Daltry este pastratorul registrelor din primarie, in orasul Darkshire. El tine registrele locale si ajuta la descoperirea documentelor istorice despre fostii locuitori.",al={"daltry","cine este daltry"}},{q="Cu cine vorbesc la Lion's Pride Inn?",a="Trebuie sa vorbesti direct cu Innkeeper Farley, care administreaza Lion's Pride Inn si tine evidenta calatorilor si clientilor care trec prin Goldshire.",al={"cu cine sa vorbesti","persoana de contact de la Lion's Pride","hangiul din Goldshire"}},{q="De ce a fost taiata insemnarea din registru?",a="Inregistrarea din registru a fost stearsa doar partial, ceea ce sugereaza o incercare grabita sau deliberata de a ascunde traseul lui Stalvan spre Elwynn Forest, la plecarea sa din Duskwood.",al={"nota stearsa","de ce a fost stearsa"}},{q="Implica aceasta misiune vreo lupta?",a="Nu. Aceasta etapa a investigatiei tine exclusiv de calatorie si cercetare, purtandu-te in siguranta de la Town Hall din Darkshire pana la sala hanului din Goldshire.",al={"exista lupte","trebuie sa ma lupt cu ceva"}},{q="Ce este Lion's Pride Inn?",a="Lion's Pride Inn este locul central din Goldshire, in Elwynn Forest. Este un popas binecunoscut pentru calatorii care merg intre Stormwind City, Westfall si Duskwood.",al={"hanul Lion's Pride Inn","hanul din Goldshire"}}},fx={f40d5969={q="De ce vrea Clerk Daltry sa fie gasit Stalvan?",a="In calitate de functionar al orasului Darkshire, Daltry tine arhiva si registrul local. Dupa ce Madame Eva te-a trimis initial pe urmele siluetei misterioase cunoscute sub numele de Stalvan Mistmantle, Daltry a ajutat la cautari, scotocindu-si registrele. Gasind sub prima adresa o inregistrare trecuta cu vederea, stearsa partial, el te indruma sa cercetezi noul indiciu pentru a contribui la reconstituirea trecutului acestui om enigmatic.",al={"de ce ii pasa lui Daltry","motivul lui Daltry in povestea lui Stalvan","de ce sa-l urmaresti pe Stalvan"}},["136b3a3d"]={q="De ce te trimite Clerk Daltry la Goldshire in loc sa mearga el insusi?",a="Clerk Daltry este un functionar civil legat de primaria din Darkshire, responsabil cu pastrarea registrelor si deservirea localnicilor dintr-o asezare asediata de orori. Calatoria pana peste rau, in Elwynn Forest, pentru a interoga hangii nu tine de atributiile si indatoririle sale, asa ca un aventurier in putere este mult mai potrivit sa urmareasca pistele indepartate.",al={"de ce ma trimit","de ce nu pleaca Daltry","de ce are Daltry nevoie de un aventurier"}}},fp="21,405,20.410.0,20.404.0,37.199.0,20.172.0,42.150.0,48.160.0,35.150.0,29.176.0"}
P.entries["quest:690"] = {n="Malin's Request",s="In Stormwind, Malin cere ajutor pentru recuperarea relicvelor din Stromgarde, cazut in ruina. Archmage Malin trimite aventurieri veterani din Alliance spre nord, la Refuge Pointe din Arathi Highlands, unde o expeditie cauta relicvele magice ramase dupa caderea Stromgarde.",h="In Stormwind, Malin cere ajutor pentru recuperarea relicvelor din Stromgarde, cazut in ruina.",kw={"Arathi Highlands","Malin","Refuge Pointe","Skuerto","Stormwind","Stromgarde","Tower of Arathor","Trelane","Wizard's Sanctum"},ang={["class:Mage"]="Ca Mage care viziteaza Wizard's Sanctum, il poti ajuta pe Malin sa pastreze pretioase cercetari arcane si relicve legate de Mage din Arathor.",["faction:Alliance"]="Ca membru Alliance, poti contribui la intarirea Refuge Pointe, fragila baza pe care Alliance o mai pastreaza in Arathi.",["race:Human"]="Ca Human, poti ajuta la recuperarea comorilor din Stromgarde, leaganul civilizatiei Human, si la pastrarea mostenirii lui Arathor."},sec={{t="Bunurile pierdute ale unui maestru",b="Archmage Malin slujeste in Wizard's Sanctum din Stormwind si actioneaza in numele fostului sau mentor, Archmage Trelane. Cand Stromgarde a cazut in haos, Trelane a opus rezistenta intr-o batalie disperata la Tower of Arathor. Pe masura ce fortele ostile au cucerit orasul, a trebuit sa-si abandoneze postul si sa lase in urma bunuri fermecate puternice. Malin se teme ca relicvele ar putea ajunge in maini dusmane. Trimite mercenari capabili spre nord, ca sa-si intareasca agentii de pe teren si sa recupereze bunurile pierdute ale lui Trelane."},{t="Avanpostul tensionat din Refuge Pointe",b="Refuge Pointe se afla pe drumul catre relicvele lui Trelane, in centrul Arathi Highlands. Avanpostul este un refugiu greu incercat pentru loialistii din Stromgarde, iar principalul contact al lui Malin de acolo este Dwarf-ul Skuerto. Haiducii Syndicate, trolls Witherbark si ogrele Boulderfist preseaza avanpostul din toate partile. La sosirea ta, Skuerto si garnizoana sunt prea ocupati ca sa te primeasca bine fara ajutor imediat."}},faq={{q="Cine este Archmage Malin?",a="Archmage Malin este un vrajitor Human din Wizard's Sanctum din Stormwind. Odinioara ucenic al lui Archmage Trelane din Stromgarde, acum coordoneaza din Stormwind eforturile de recuperare a cercetarilor magice ale mentorului sau.",al={"archmage malin","cine este malin","malin stormwind"}},{q="De ce are Malin nevoie de ajutor in Arathi?",a="Stromgarde a fost asediat, fortandu-l pe Archmage Trelane sa fuga din Tower of Arathor. Agentii lui Malin incearca sa recupereze relicvele abandonate ale lui Trelane, dar sunt coplesiti si au nevoie de intariri.",al={"de ce sa mergi in Arathi","scopul misiunii lui Malin","de ce in Arathi Highlands"}},{q="Unde se afla Skuerto?",a="Skuerto este un cercetas dwarf stationat la Refuge Pointe, o tabara a Alliance de pe principalul drum comercial care strabate centrul Arathi Highlands.",al={"gaseste-l pe Skuerto","locatia lui Skuerto","unde este Refuge Pointe"}},{q="Ce s-a intamplat cu Tower of Arathor?",a="Tower of Arathor a fost o fortareata arcana din Stromgarde. In timp ce regatul se prabusea, Archmage Trelane a incercat sa o apere impotriva celor de tip Rogue din Syndicate si a ogre-lor Boulderfist, dar apararea a cazut, iar el a fost nevoit sa fuga.",al={"prabusirea Tower of Arathor","ce s-a intamplat cu Stromgarde","turnul Trelane"}},{q="Ce se intampla dupa ce-i raportezi lui Skuerto?",a="Skuerto este coplesit si dispretuitor cand sosesti. Te trimite la tovarasii sai din Refuge Pointe pentru a incepe recuperarea lucrurilor ratacite ale lui Trelane.",al={"continuare cererea lui Malin","urmatoarea misiune dupa Malin","urmatoarea misiune a lui Skuerto"}},{q="Cine este Archmage Trelane?",a="Archmage Trelane este un mage de seama din Stromgarde si mentorul lui Archmage Malin. A fost unul dintre aparatorii-cheie ai capitalei Arathi inainte de caderea regatului.",al={"arhimagul Trelane","cine este Trelane","Trelane din Stromgarde"}}},fx={["5671e9ba"]={q="De ce are nevoie Archmage Malin de un aventurier pentru aceasta sarcina?",a="Archmage Malin este legat de indatoririle sale de la Wizard's Sanctum din Stormwind, mult spre sud. Desi are deja agenti stationati la Refuge Pointe, in Arathi Highlands, acestia au raportat ca situatia din jurul orasului cazut Stromgarde este grava si necesita intariri. Un aventurier calator are libertatea de a se deplasa rapid spre nord si taria de caracter necesara pentru a patrunde in ruine ostile si disputate, unde emisarii oficiali nu pot ajunge cu usurinta.",al={"de ce trimit un aventurier","de ce eu, Malin","de ce nu pleaca Malin insusi"}}},fp="15,253,26.467.0,37.407.0,22.199.0,35.198.0,25.136.0,38.207.0,40.154.0,24.154.0"}
P.entries["quest:691"] = {n="Worth Its Weight in Gold",s="La Refuge Pointe, Apprentice Kryten cauta colti de la Witherbark, saculeti cu medicamente si un cutit de vanator de umbre, toate fiind reactivi pentru Archmage Malin, care i-a trimis pe el si pe Skuerto sa le stranga. Iti cere sa le cauti printre trollii Witherbark din sud-estul Arathi.",h="La Refuge Pointe, Apprentice Kryten cauta colti de la Witherbark, saculeti cu medicamente si un cutit de...",kw={"apprentice kryten","arathi highlands","archmage malin","saculet cu leacuri","refuge pointe","cutit de vanator de umbre","skuerto","witherbark","colt witherbark"},sec={{t="Reactivii lui Malin",b="Archmage Malin i-a trimis pe Kryten si Skuerto in Arathi dupa reagenti, iar Kryten habar n-avea cum sa-i adune pana la sosirea ta. Are nevoie de zece colti Witherbark, patru saculeti de leacuri si un cutit de shadow hunter. Trollii Witherbark isi au casa in sud-estul Arathi."},{t="Ce poarta Witherbark",b="Potrivit cercetarilor lui Kryten, orice troll Witherbark ar trebui sa aiba colti, iar doctorii vrajitori poarta saculetii cu medicamente. Cutitul le revine celor mai puternici vanatori de umbre, dupa ce isi incheie ritualurile de trecere. Numai lupta va arata care dintre ei il are."}},faq={{q="Pentru cine lucreaza Apprentice Kryten?",a="Archmage Malin i-a trimis pe Kryten si Skuerto in Arathi sa-i adune reactivi.",al={"cine l-a trimis pe Kryten","stapanul lui Kryten","de ce se afla Kryten in Arathi"}},{q="Unde se gasesc trolii Witherbark?",a="In sud-estul Arathi, unde isi au salasul trollii Witherbark.",al={"locatia witherbark","unde gasesti witherbark","locatia satului witherbark"}},{q="Ce trolli poarta pungile cu medicamente?",a="Cercetarile lui Kryten arata ca doctorii vrajitori Witherbark poarta saculeti cu leacuri, in timp ce orice troll Witherbark ar trebui sa aiba colti.",al={"sursa pungii cu medicamente","cine are pungi cu medicamente","punga cu medicamente Witherbark"}},{q="Cum gasesti cutitul shadow hunter?",a="Ar trebui sa-l aiba cei mai puternici shadow hunters Witherbark, o lama care le este inmanata dupa ritualurile de trecere. Numai lupta va dezvalui care dintre ei o poarta.",al={"locatia cutitului shadow hunter","cine lasa cutitul shadow hunter","cutitul rite of passage"}}},fp="24,263,16.278.0,25.264.0,37.77.0,40.72.0,40.131.0,40.159.0"}
P.entries["quest:692"] = {n="The Lost Fragments",s="Theldurin the Lost e cuprins de panica din cauza Scroll of Myzrael. Magia acestuia ar putea s-o aduca pe Myzrael la suprafata, dar daca ea e deja libera, pergamentul poate fi singura cale de a o lega din nou. Elementalii furiosi l-au sfasiat si se lupta pentru ramasite, iar tu esti trimis sa le aduni.",h="Theldurin the Lost e cuprins de panica din cauza Scroll of Myzrael.",kw={"badlands","fragment de pergament mototolit","elementali","myzrael","scroll of myzrael","fragment de pergament parjolit","theldurin the lost","fragment de pergament rupt"},sec={{t="Un pergament periculos",b="Theldurin the Lost se alarma la pomenirea Scroll of Myzrael, temandu-se ca magia lui ar putea-o atrage pe Myzrael la suprafata. Apoi se razgandeste: daca ea a scapat deja sau isi aduna fortele pentru a ataca, pergamentul este exact lucrul de care vei avea nevoie ca s-o prinzi din nou."},{t="Sfasiet de elemente",b="Pergamentul nu mai este intreg. Elementalii furiosi l-au luat, l-au sfasiat in bucati si acum se lupta pentru ramasite. Ai nevoie de trei bucati: una rupta, una mototolita si una parjolita, iar Theldurin intentioneaza sa incerce sa le repare. Hotii cutreiera dealurile din spatele lui Theldurin."}},faq={{q="Cine te trimite sa aduni fragmentele de pergament?",a="Theldurin the Lost iti cere sa aduci inapoi fragmentele pergamentului distrus.",al={"cel care da misiunea","cine incepe Lost Fragments","misiunea lui Theldurin"}},{q="Ce ar trebui sa faca Scroll of Myzrael?",a="Theldurin spune ca magia acesteia ar putea-o atrage pe Myzrael la suprafata. Theldurin mai crede ca, daca ea este deja libera, aceasta ar fi ceea ce ti-ar trebui ca s-o prinzi din nou.",al={"ce face pergamentul","povestea Scroll of Myzrael","de ce sa gasesti fragmentele pergamentului"}},{q="Unde se afla fragmentele de pergament?",a="Elementalii furiosi au luat pergamentul, l-au rupt in bucati si se lupta pentru ele. Se afla pe dealurile din spatele lui Theldurin.",al={"cine are fragmentele","unde gasesc fragmentele pergamentului","locatia fragmentului de pergament"}},{q="Ce misiune preceda aceasta?",a="Aceasta urmeaza tranzactiilor tale anterioare cu Theldurin the Lost.",al={"misiunea precedenta","conditie prealabila pentru Lost Fragments"}}},fp="18,284,21.279.0,20.262.0,46.77.0,45.159.0,31.122.0,29.57.0"}
P.entries["quest:6921"] = {n="Amongst the Ruins",s="Trimisi de Je'neu Sancrea de la Zoram'gar Outpost, aventurierii Horde patrund in templul inundat din Blackfathom Deeps pentru a recupera un fathom core. Earthen Ring cauta aceasta relicva pentru a descoperi planurile elementale intunecate ale cultului invadator Twilight's Hammer.",h="Trimisi de Je'neu Sancrea de la Zoram'gar Outpost, aventurierii Horde patrund in templul inundat din...",kw={"amongst the ruins","ashenvale","blackfathom deeps","cercul pamantului","nucleul fathom","piatra fathom","je'neu sancrea","moonshrine ruins","twilight's hammer","zoram'gar outpost"},ang={["class:Shaman"]="Recuperarea nucleului abisal slujeste direct misiunii Earthen Ring de a proteja spiritele apei si ale pamantului, impiedicand Twilight's Hammer sa le supuna vointei sale.",["faction:Horde"]="Eliminand amenintarile din Blackfathom Deeps, protejezi Zoram'gar Outpost si asiguri capul de pod disputat al Horde de pe coasta Ashenvale.",["race:Troll"]="Ajutorul oferit lui Je'neu Sancrea il sprijina pe un Darkspear care face legatura intre Horde si pazitorii elementali ai Earthen Ring."},sec={{t="O amenintare din adancuri",b="Vechiul templu al night elves din Blackfathom Deeps, odinioara sacru pentru Elune, a cazut sub stapanirea fortelor sinistre. In adancul pasajelor sale scufundate, cultistii Twilight's Hammer si-au intemeiat o fortareata. Aflat pe tarmul batut de vant din Zoram'gar Outpost, in Ashenvale, shamanul Darkspear Je'neu Sancrea observa cu tot mai multa alarma raspandirea intinarii, intelegand ca acest cult vrea sa supuna elementele tinutului si aparatorii sai."},{t="Piatra Adancurilor",b="Pentru a zadarnici planurile cultului, Je'neu le cere campionilor Hordei sa puna mana pe un nucleu abisal din piatra abisala subacvatica din Moonshrine Ruins. Descifrat cum se cuvine de samani priceputi, nucleul dezvaluie o cronica amanuntita a curentilor elementali si a tulburarilor. Cu acest artefact in maini, Earthen Ring spera sa patrunda dincolo de valul care ascunde operatiunile Twilight's Hammer si sa apere regiunea de o catastrofa elementala."}},faq={{q="Cine ofera misiunea Amongst the Ruins?",a="Misiunea este oferita de Je'neu Sancrea, un reprezentant troll al Earthen Ring, stationat la Zoram'gar Outpost, de-a lungul Zoram Strand, in vestul Ashenvale.",al={"cel care da misiunea","unde iei misiunea","cine incepe Amongst the Ruins"}},{q="Ce este un nucleu de stanjeni?",a="Un nucleu fathom este un artefact special adapostit intr-o piatra fathom scufundata, aflata printre ruine. Cand il citesc samanii, acesta le ofera o istorie cuprinzatoare a activitatii elementale, dezvaluind cum sunt constranse si manipulate elementele locale.",al={"ce este fathom core","scopul pietrei fathom","ce face nucleul"}},{q="De ce este Earthen Ring ingrijorat de Blackfathom Deeps?",a="Earthen Ring cauta echilibrul dintre elementele naturii. Cultistii Twilight's Hammer, care au pus stapanire pe ruinele scufundate, corup si constrang in mod activ elementele sa le slujeasca scopurilor intunecate, amenintand stabilitatea intregii regiuni.",al={"motivul Inelului Pamantului","de ce ii pasa Inelului Pamantului","cultistii din Blackfathom Deeps"}},{q="Unde se afla piatra adancurilor?",a="Piatra fathom se afla sub apa, in apele de la Moonshrine Ruins, in Blackfathom Deeps; exploratorii trebuie sa se scufunde ca sa recupereze miezul.",al={"unde este piatra","locatia nucleului abisal","nucleul abisal din Moonshrine Ruins"}},{q="Pot jucatorii din Alliance lua aceasta misiune?",a="Nu. Misiunea este rezervata Horde, intrucat Je'neu Sancrea isi desfasoara activitatea din avanpostul Horde din Zoram'gar si sprijina prezenta strategica a Horde in Ashenvale, pe langa indatoririle sale fata de Earthen Ring.",al={"este aceasta misiune doar pentru Horde","varianta Alliance","poate Alliance sa faca Amongst the Ruins"}},{q="Ce grup ocupa Blackfathom Deeps?",a="Complexul templului, vast ca o caverna, a fost ocupat de Twilight's Hammer, un cult apocaliptic dedicat slujirii entitatilor sinistre Old God si rasucirii elementelor spre un deznodamant catastrofal.",al={"cine se afla in blackfathom","dusmani in bfd","twilight's hammer blackfathom"}}},fx={["139b4a2b"]={q="De ce vrea Je'neu Sancrea sa fie recuperat Fathom Core?",a="Je'neu Sancrea se teme ca cultistii din Twilight's Hammer care ocupa Blackfathom Deeps vor sili elementele locale sa se intoarca impotriva regiunii si a Horde. Fara Fathom Core, Earthen Ring nu are cum sa vada ce ritualuri si tulburari elementale pune la cale cultul adanc sub ruine.",al={"motivele lui jeneu sancrea","de ce sa obtin fathom core","de ce in Amongst the Ruins"}}},fp="17,251,20.481.0,16.434.0,38.159.0,22.241.0,58.254.0,34.166.0,37.193.0,42.189.0"}
P.entries["quest:6922"] = {n="Baron Aquanis",s="Dupa ce il inving pe elementarului de apa Baron Aquanis in Blackfathom Deeps, aventurierii recupereaza un glob de apa ciudat, care contine un lichid alterat si fetid. Dus la Je'neu Sancrea din Earthen Ring, artefactul ofera dovezi esentiale ale coruperii elementale care se raspandeste sub Ashenvale. Je'neu crede ca acesta va dovedi ce l-a corupt pe baron si nu s-ar mira daca vinovatii ar fi cultistii Twilight's Hammer, ascunsi printre ruinele subacvatice.",h="Dupa ce il inving pe elementarului de apa Baron Aquanis in Blackfathom Deeps, aventurierii recupereaza un...",kw={"Ashenvale","Baron Aquanis","Blackfathom Deeps","cercul terestru","coruptie elementala","Je'neu Sancrea","glob de apa ciudat","Twilight's Hammer","Zoram Strand"},ang={["class:Shaman"]="Earthen Ring considera coruperea spiritelor elementale o incalcare grava a ordinii firesti. Cercetarea starii intinate a lui Baron Aquanis este esentiala pentru restabilirea echilibrului elemental.",["faction:Horde"]="Je'neu Sancrea se coordoneaza cu cercetasii Horde de la Zoram'gar Outpost si cauta campioni curajosi care sa curete apele corupte de sub coasta din Ashenvale."},sec={{t="O inima corupta",b="Baron Aquanis nu era un spirit al apei obisnuit, ci un elemental puternic, corupt de vrajitorie malefica in grote inundate din Blackfathom Deeps. Cand este distrus, elementalul lasa in urma un Strange Water Globe - un glob indestructibil care contine un lichid fetid, agitat, ce pare sa fi sustinut si deformat esenta naturala a creaturii. Obiectul nu poate fi deteriorat prin mijloace fizice si adaposteste energii care ii tulbura profund pe cei sensibili la echilibrul elementelor."},{t="Studiile Earthen Ring",b="Je'neu Sancrea, un saman din Earthen Ring aflat la Zoram Strand, recunoaste imediat artefactul drept dovada unei interventii nefiresti. El si ordinul sau banuiesc de mult timp ca Baron Aquanis a cazut prada fortelor intunecate si ii acuza direct pe cultistii Twilight's Hammer care ocupa templul scufundat. Studiind globul, Je'neu spera nu doar sa confirme vinovatia cultului, ci si sa descopere metodele intunecate exacte prin care acesta supune si perverteste spiritele elementare din Azeroth."}},faq={{q="Ce este Baron Aquanis?",a="Baron Aquanis este un elementar de apa puternic, care salasluieste in apele subterane din Blackfathom Deeps. In loc sa umble liber, Aquanis a fost corupt si legat de practicantii magiei intunecate care locuiesc in complexul templului ruinat.",al={"cine este Aquanis","seful Aquanis","povestea lui Baron Aquanis"}},{q="Ce este Strange Water Globe?",a="Strange Water Globe este o sfera indestructibila ramasa dupa infrangerea lui Baron Aquanis. In interior se balaceste un lichid infect si fetid, sursa energiei contaminate care a alimentat starea corupta a elementarului.",al={"glob de apa","glob de apa ciudat","obiect de misiune Aquanis"}},{q="De ce vrea Je'neu Sancrea globul?",a="Ca membru al Earthen Ring, Je'neu Sancrea supravegheaza tulburarile elementale din Ashenvale. El cerceteaza globul pentru a confirma daca Twilight's Hammer se afla in spatele coruptiei si pentru a descifra ritualurile folosite la pervertirea spiritelor.",al={"de ce sa duci la jeneu","scopul lui jeneu sancrea"}},{q="Cine se afla in spatele coruperii lui Baron Aquanis?",a="Principalii suspecti sunt cultistii din Twilight's Hammer, care isi au cuibul in adancurile Blackfathom Deeps. Prezenta lor in templu se inscrie intr-o campanie de profanare si comuniune intunecata cu fiinte nenaturale.",al={"cine l-a corupt pe aquanis","aquanis si twilight hammer","cultisti in blackfathom"}},{q="Unde se afla Je'neu Sancrea?",a="Je'neu Sancrea este un shaman din Earthen Ring, campat de-a lungul Zoram Strand, pe coasta nord-vestica a Ashenvale, in apropierea intrarii in sistemul de pesteri Blackfathom Deeps.",al={"unde este Jeneu","predarea misiunii Aquanis","unde predai globul de apa"}},{q="Ce urmeaza dupa predarea acestei misiuni?",a="Predarea globului duce direct la cercetari suplimentare asupra tulburarilor elementale din regiune si ii indeamna pe aventurieri sa continue sa ajute Earthen Ring in lupta impotriva pustiirii tot mai raspandite.",al={"misiunea urmatoare","primejdie elementala"}}},fp="13,454,17.461.0,27.500.1,22.235.0,32.221.0,39.238.0,46.203.0,32.170.0,39.192.0"}
P.entries["quest:693"] = {n="Wand over Fist",s="Skuerto, de la Refuge Pointe, a aflat unde a ajuns primul dintre obiectele lui Trelane. Kor'gresh are Wand of Invocation a lui Trelane in Boulderfist Hall, iar Skuerto vrea sa-l aduci inapoi.",h="Skuerto, de la Refuge Pointe, a aflat unde a ajuns primul dintre obiectele lui Trelane.",kw={"arathi highlands","boulderfist hall","korgresh","refuge pointe","skuerto","stromgarde","thandol span","trelane","bagheta invocarii","wand over fist"},sec={{t="Ogrele si bagheta",b="Dupa ce ai lucrat pentru Apprentice Kryten, Skuerto a aflat unde a ajuns primul obiect al lui Trelane. Kor'gresh il tine in Boulderfist Hall si a aruncat rafale de gheata asupra propriilor semeni ca sa-i tina in frau. Skuerto crede ca capcaunul trebuie sa fie aproape de a descoperi toate puterile baghetei. Boulderfist Hall se afla la sud de Refuge Pointe, apoi la est de Thandol Span."},{t="Lista lui Skuerto",b="La intoarcere, Skuerto bifeaza bagheta ca fiind rezolvata, iar mai sunt trei de gasit, potrivit listei sale. Celelalte trei sunt toate in Stromgarde."}},faq={{q="Cine ofera misiunea Wand over Fist?",a="Skuerto, la Refuge Pointe din Arathi Highlands.",al={"cel care da misiunea wand over fist","cine incepe wand over fist","de unde iei wand over fist"}},{q="Unde se afla Kor'gresh?",a="Kor'gresh se afla in Boulderfist Hall, la sud de Refuge Pointe si apoi la est de Thandol Span.",al={"unde este korgresh","locatia lui korgresh","gaseste-l pe korgresh"}},{q="Ce obiect trebuie recuperat?",a="Trelane's Wand of Invocation, primul dintre obiectele lui Trelane. Kor'gresh a aruncat cu el rafale de gheata asupra semenilor sai.",al={"ce obiect tine Kor'Gresh","ce bagheta","bagheta lui Trelane"}},{q="Ce conditii prealabile sunt necesare pentru aceasta misiune?",a="Urmeaza Worth Its Weight in Gold, munca pe care ai facut-o pentru Apprentice Kryten.",al={"cerinte preliminare pentru Wand over Fist","conditii necesare pentru Wand over Fist","misiune anterioara pentru Wand over Fist"}}},fp="14,183,21.359.0,14.140.1,35.50.0,27.98.0,32.121.0,45.76.0"}
P.entries["quest:694"] = {n="Trelane's Defenses",s="Cu bagheta in mana, Skuerto se ocupa de ogrele care inconjoara Tower of Arathor. Pentru a activa apararea turnului, are nevoie de o agata azurie de la Shaman-ul Boulderfist, pe care trebuie sa o duci la Apprentice Kryten din Refuge Pointe.",h="Cu bagheta in mana, Skuerto se ocupa de ogrele care inconjoara Tower of Arathor.",kw={"apprentice kryten","azure agate","saman boulderfist","refuge pointe","skuerto","stromgarde","tower of arathor","apararea lui trelane"},sec={{t="Apararea turnului",b="Ogres inconjoara Tower of Arathor din Stromgarde. Skuerto spune ca apararea turnului trebuie activata daca vrei sa ai o sansa impotriva lor si sa ajungi la obiecte in viata."},{t="O nestemata pentru o cheie",b="Anumite nestemate din turn au atras atentia shamanului Boulderfist, care le-a luat, desi Skuerto spune ca nu le va pastra mult timp. Du un agate azure la Apprentice Kryten, in Refuge Pointe; el stie vraja cu care sa-l incanteze, astfel incat sa functioneze ca o cheie."}},faq={{q="De ce este nevoie de o agata azurie?",a="Skuerto vrea sa activezi apararea turnului, ca sa poti infrunta ogrele din jurul Tower of Arathor si sa ajungi totusi la obiecte cu viata. Odata fermecata, nestemata va functiona ca o cheie.",al={"de ce azure agate","scopul apararilor lui trelane","de ce sa iei nestemata"}},{q="De unde provin agatele azurii?",a="Shaman-ul Boulderfist le-a luat din Tower of Arathor si s-a atasat de ele.",al={"cine a luat agatele","de unde provin nestematele","originea agatelor"}},{q="Cine poate vraji nestemata?",a="Apprentice Kryten de la Refuge Pointe cunoaste vraja care incanta nestemata, astfel incat sa functioneze ca o cheie.",al={"cine incanta agata","rolul lui kryten","cine o transforma in cheie"}}},fp="18,228,20.177.0,15.274.0,29.170.0,37.94.0,24.96.0"}
P.entries["quest:695"] = {n="An Apprentice's Enchantment",s="Apprentice Kryten a fermecat agata pe care i-ai adus-o de la Shaman-ul Boulderfist. Atingand-o de piedestalul de la baza turnului, vei trezi apararea acestuia. Inainte sa pleci, te trimite la Skuerto pentru restul.",h="Apprentice Kryten a fermecat agata pe care i-ai adus-o de la Shaman-ul Boulderfist.",kw={"apprentice kryten","arathi highlands","agat vrajit","skuerto","turn","trelane"},sec={{t="O cheie pentru turn",b="Kryten iti da nestemata fermecata. Iti explica faptul ca atingerea ei de un piedestal de la baza turnului va trezi apararea acestuia si ca ar trebui s-o folosesti cand esti gata sa intri dupa restul obiectelor lui Trelane. Te va astepta la intoarcere, in tabara. Mai intai, vorbeste cu Skuerto, care iti va da toate celelalte informatii de care ai nevoie."}},faq={{q="La ce foloseste agata fermecata?",a="Atingerea ei de un piedestal de la poalele turnului trezeste apararea acestuia. O folosesti cand esti gata sa intri dupa restul obiectelor lui Trelane.",al={"de ce am nevoie de agate","utilizarea agatei fermecate","ce face nestemata"}},{q="Cu cine trebuie sa vorbesti inainte sa parasesti tabara?",a="Skuerto. Kryten va spune sa vorbiti cu el inainte sa plecati, fiindca va va spune orice altceva trebuie sa stiti.",al={"cu cine vorbesc","incotro merg mai departe","cine este skuerto"}},{q="Unde va fi Kryten?",a="Te va astepta la intoarcere in tabara.",al={"unde este kryten","kryten asteapta"}}},fp="27,225,19.338.0,43.152.0,47.110.0,21.44.0"}
P.entries["quest:696"] = {n="Attack on the Tower",s="Cu apararea turnului trezita, Skuerto din Refuge Pointe te trimite in turnul stapanit de ogri dupa filacteria, globul si agata de jar ale lui Trelane. Ar trebui sa se afle in cuferele din interior, iar Skuerto spune ca Malin va fi foarte multumit daca le aduci inapoi.",h="Cu apararea turnului trezita, Skuerto din Refuge Pointe te trimite in turnul stapanit de ogri dupa...",kw={"arathi highlands","attack on the tower","malin","capcauni","refuge pointe","skuerto","trelane","trelane's ember agate","trelane's orb","trelane's phylactery"},sec={{t="In turn",b="Dupa vraja lui Kryten, Skuerto iti spune ce trebuie sa cauti: filacteria, globul si agata de jar ale lui Trelane. Cele trei ar trebui sa se afle in lazi din turn si nu vei avea nicio problema sa le deschizi singur, desi trebuie sa fii atent la ogres. Apararile turnului nu se vor ocupa de ei de la sine, iar daca ogres te prind furandu-le lucrurile, te vor snopi in bataie."},{t="Verdictul lui Skuerto",b="Cand returnezi cele trei obiecte, Skuerto spune ca Malin nu ar fi putut cere o persoana mai vrednica sa-i ajute aici. Malin va fi incantat sa afle cat de deplin le-a reusit expeditia."}},faq={{q="Cine incredinteaza aceasta sarcina?",a="Skuerto, la Refuge Pointe din Arathi Highlands, dupa ce Kryten vrajeste nestemata.",al={"cine ofera attack on the tower","cel care da misiunea attack on the tower","unde gasesc attack on the tower"}},{q="Ce obiecte trebuie sa recuperezi?",a="Filacteria lui Trelane, globul si agata de jar. Fiecare ar trebui sa fie intr-un cufar din turn.",al={"obiecte din Attack on the Tower","ce relicve sa iei","obiectele lui trelane"}},{q="Ce vor face ogrii?",a="Apararile turnului nu se vor ocupa de ei in locul tau. Daca ogrii afla ca le furi lucrurile, te vor snopi in bataie.",al={"sunt ogrii periculosi","ogrii din turn"}},{q="Ce urmeaza inaintea acestui lucru?",a="Urmeaza dupa An Apprentice's Enchantment, in care Kryten vrajeste nestemata si te trimite la Skuerto.",al={"conditie prealabila pentru Attack on the Tower","ce misiune trebuie facuta mai intai"}}},fp="19,246,14.384.0,17.189.1,22.85.0,36.86.0,23.137.0,23.98.0"}
P.entries["quest:6962"] = {n="Treats for Great-father Winter"}
P.entries["quest:697"] = {n="Malin's Request",s="Skuerto iti da o scrisoare sigilata pentru Archmage Malin, care se afla in Mage Quarter din Stormwind. Scrie ca Kryten si Skuerto se vor intoarce curand acasa, iar Skuerto e sigur ca Malin te va rasplati cum se cuvine pentru ca i-ai ajutat in Arathi.",h="Skuerto iti da o scrisoare sigilata pentru Archmage Malin, care se afla in Mage Quarter din Stormwind.",kw={"arathi highlands","archmage malin","kryten","mage quarter","malin's request","scrisoare sigilata","skuerto","stormwind"},sec={{t="O scrisoare pentru Archmage",b="Dupa treaba din Arathi, Skuerto iti da o scrisoare pe care s-o duci inapoi la Stormwind. Mesajul ei pentru Archmage Malin din Mage Quarter este ca Kryten si Skuerto vor ajunge curand acasa. Skuerto nu se indoieste ca Malin te va rasplati cum se cuvine pentru ca i-ai ajutat si te trimite la drum, urandu-ti calatorie placuta."},{t="Malin citeste scrisoarea",b="Cand Malin deschide scrisoarea, ochii i se maresc. Este incantat si spune ca Trelane va fi foarte multumit. Isi inchipuie ca si Kryten si Skuerto impartasesc entuziasmul sau, acum ca se intorc acasa, la Stormwind."}},faq={{q="Cine te trimite cu scrisoarea?",a="Skuerto o face. Scrisoarea ii spune lui Malin ca el si Kryten se vor intoarce curand acasa.",al={"cine da scrisoarea","cine incepe solicitarea lui malin","cine initiaza solicitarea lui malin"}},{q="Unde se afla Archmage Malin?",a="Archmage Malin se afla in Mage Quarter of Stormwind.",al={"unde se afla archmage malin","locatia lui archmage malin","unde predau acest obiect"}},{q="Cine este Kryten?",a="Kryten este insotitorul lui Skuerto in Arathi Highlands. Skuerto spune ca cei doi se vor intoarce curand acasa.",al={"cine este kryten","kryten arathi"}},{q="Ce urmeaza inaintea acestui pas?",a="Urmeaza dupa Attack on the Tower, treaba pe care ti-a incredintat-o Skuerto la turnul din Arathi.",al={"misiunea anterioara","conditie prealabila","ce duce la asta"}}},fp="15,230,25.296.0,22.199.1,30.74.0,32.51.0,14.102.0,28.85.0"}
P.entries["quest:698"] = {n="Lack of Surplus",s="Dar strange provizii pentru avanpostul de pe plaja din est, unde Tok'Kar abia are timp liber intre turele de paza si gatitul pentru soldati. Dar iti cere sa-i duci lui Tok'Kar o incarcatura de carne de sawtooth.",h="Dar strange provizii pentru avanpostul de pe plaja din est, unde Tok'Kar abia are timp liber intre turele de...",kw={"dar","flanc","carne","avanpost","sawtooth","swamp of sorrows","tok'kar"},sec={{t="Provizii pentru tarm",b="Dar strange provizii pentru avanpostul de pe plaja din est. Tok'Kar face tot ce poate acolo, dar turele de garda si gatitul pentru soldati lasa putin timp liber in timpul zilei. Soldatilor le place sa gateasca carne de sawtooth cand au ocazia, iar Dar nu a avut timp sa le trimita un alt transport."},{t="Alegerea carnii",b="Dar te avertizeaza sa-i lasi in pace pe sawtooth-ii tineri, fiindca cei batrani au gust mai bun. Cei tineri au nevoie de un an sau doi ca sa ajunga la maturitate. Sunt necesare opt pulpe de sawtooth crude, pe care trebuie sa le duci la Tok'Kar in Swamp of Sorrows."}},faq={{q="Cine cere carnea de sawtooth?",a="Dar, care aduna provizii pentru avanpostul de pe plaja din est.",al={"cine da Lack of Surplus","cine incepe Lack of Surplus","Dar din Swamp of Sorrows"}},{q="Unde este stationat Tok'Kar?",a="La avanpostul de langa plaja din est despre care vorbeste Dar. Carnea trebuie livrata acolo lui Tok'Kar, in Swamp of Sorrows.",al={"unde se afla tok'kar","locatia tokkar","avanpostul tok'kar"}},{q="De ce are Tok'Kar nevoie ca altii sa-i aduca carne?",a="Intre schimburile de garda si gatitul pentru soldati, Tok'Kar ii ramane putin timp liber in zi.",al={"de ce are nevoie tok'kar de carne","de ce trimite dar mancare"}},{q="Ce sawtooths trebuie vanati?",a="Cele mai batrane. Cele tinere sunt mai putin gustoase si au nevoie de un an sau doi pentru a ajunge la dimensiunea maxima.",al={"care sawtooths","ce sawtooths lasa carne","sursa de sawtooth flank"}},{q="Cate flancuri sunt necesare?",a="Opt flancuri de sawtooth nepreparate, aduse lui Tok'Kar.",al={"cate flancuri","numarul de flancuri sawtooth nepragatite"}},{q="Ce urmeaza in lantul de misiuni?",a="Urmeaza un al doilea pas cu acelasi nume.",al={"urmatoarea misiune dupa Lack of Surplus","continuarea lui Lack of Surplus"}}},fp="15,216,22.299.0,17.220.0,36.72.0,27.130.0,43.91.0,33.84.0,27.53.0,29.42.0"}
P.entries["quest:6981"] = {n="The Glowing Shard",s="Glowing Shard este o nestemata misterioasa, de culoarea smaraldului, scoasa din adancurile intunecate ale Wailing Caverns. Sub suprafata sa lustruita se roteste o esenta fumurie, iar aceasta relicva tulburatoare ii impinge pe aventurieri sa caute raspunsuri in Ratchet si dincolo de acesta.",h="Glowing Shard este o nestemata misterioasa, de culoarea smaraldului, scoasa din adancurile intunecate ale...",kw={"Barrens","druizi ai coltilor","Emerald Nightmare","Falla Sagewind","ciob stralucitor","Ratchet","Sputtervalve","Wailing Caverns"},ang={["class:Druid"]="Pentru druizi, stralucirea de smarald si miezul fumuriu al aschiei sunt dovezi sumbre ca Emerald Nightmare se infiltreaza in lumea celor treji prin confratii lor cazuti din Wailing Caverns.",["faction:Alliance"]="Chiar si departe de casa, in Kalimdor, exploratorii Alliance recunosc pericolul global reprezentat de orice putere intunecata care corupe natura sub Barrens.",["faction:Horde"]="Dezlegarea misterului fragmentului ajuta la protejarea rascrucilor si rutelor comerciale vitale din Barrens de amenintarile supranaturale care mocnesc in izvoarele subterane.",["race:Tauren"]="Echilibrul din Barrens este pretios pentru Shu'halo, iar ducerea acestei relicve nefiresti la Falla Sagewind ajuta la intelegerea coruptiei care le otraveste pamanturile ancestrale."},sec={{t="O descoperire tulburatoare",b="Scoasa din adancurile Wailing Caverns, aschia stralucitoare ii nelinisteste numaidecat pe cei care o tin in mana. De un verde stralucitor si aparent solida, ea ascunde umbre frematatoare, ca de ceata, sub fata cristalina. Cristalul exercita o atractie subtila, cerand atentie si emanand o aura profund tulburatoare, care sugereaza natura corupta a druidilor adormiti si a sanctuarului lor bantuit de cosmaruri."},{t="In cautarea raspunsurilor in Ratchet",b="Nestiind de unde provine piatra si ce natura are, aventurierii duc artefactul in portul goblin Ratchet. Acolo, inginerul local Sputtervalve cerceteaza obiectul neobisnuit si isi da seama ca originile lui nu tin de utilajele goblinilor sau de geologia obisnuita. In schimb, ii indruma pe cautatori spre crestele stancoase de deasupra pesterilor, unde mistica tauren Falla Sagewind vegheaza asupra spiritelor framantate din Barrens."}},faq={{q="Ce este Glowing Shard?",a="Este un cristal verde, luminos si corupt, descoperit in adancul Wailing Caverns. In interiorul invelisului sau sticlos se invart suluri de fum palide, tulburand pe oricine il cerceteaza indeaproape.",al={"fragment stralucitor","ce este aceasta piatra pretioasa verde","fragment din Wailing Caverns"}},{q="Cine poate examina aschia din Ratchet?",a="Sputtervalve, un inginer stationat langa maestrul de zbor din Ratchet, examineaza aschia. Desi este inginer, nu druid, ii recunoaste energia stranie si te indruma spre cineva cu cunostinte spirituale.",al={"cine din ratchet se ocupa de fragment","npc din ratchet pentru fragment","fragment sputtervalve"}},{q="Unde se afla Falla Sagewind?",a="Falla Sagewind isi ridica tabara pe culmile muntoase, chiar deasupra intrarii in Wailing Caverns, in centrul Barrens.",al={"locatia lui Falla Sagewind","unde este Falla","muntele de deasupra Wailing Caverns"}},{q="Are Sputtervalve un marcaj de misiune deasupra capului?",a="Nu. Sputtervalve nu are un simbol de misiune activa. Trebuie sa vorbesti direct cu el si sa alegi optiunea de dialog despre ciobul straniu, stralucitor, pentru a continua.",al={"sputtervalve fara semn de intrebare","nu pot preda la sputtervalve","sputtervalve bugged"}},{q="De ce pare ca ciobul contine fum?",a="Volbura fumurie din cristal reflecta coruptia omniprezenta care deformeaza Wailing Caverns, legata direct de Emerald Nightmare, ce patrunde in gandurile Druids of the Fang adormiti.",al={"de ce scoate fum fragmentul","fum verde in nestemata","coruptia din fragment"}},{q="Cine poate continua sirul misiunilor dupa Falla Sagewind?",a="Aventurierii din Horde si Alliance pot urma aceasta poveste. Descoperirile Falla Sagewind duc direct la misiunea 'In Nightmares', trimitand eroii sa ceara indrumare de la liderii si batranii factiunii lor.",al={"este aceasta misiune doar pentru Hoarda","fragmentul stralucitor al Aliantei","cine primeste In Nightmares"}}},fx={["8f9c92be"]={q="De ce trebuie sa investighezi Glowing Shard?",a="Ciobul stralucitor este profund tulburator. Solid, dar plin de adancimi verzi, fumurii si involburate, emana o prezenta nenaturala care cere o explicatie. Dupa ce l-ai recuperat din inima tulburata a Wailing Caverns, trebuie sa intelegi ce corupere poarta si ce amenintare ar putea reprezenta pentru Barrens.",al={"de ce sa investighezi fragmentul stralucitor","motivul fragmentului stralucitor","de ce sa duci fragmentul la ratchet"}}},fp="17,241,22.398.0,26.419.1,26.170.0,37.225.0,32.126.0,52.167.0,47.196.0,54.208.1"}
P.entries["quest:6984"] = {n="A Smokywood Pastures' Thank You!"}
P.entries["quest:699"] = {n="Lack of Surplus",s="Tok'Kar si soldatii de pe coasta sunt postati pentru a apara Stonard de murloci sau pentru a trimite avertismentul daca forta lor e prea mare. Tok'Kar vrea sase gheare de snapper cu dinti ca fierastraul si iti ofera una dintre armele avanpostului drept multumire.",h="Tok'Kar si soldatii de pe coasta sunt postati pentru a apara Stonard de murloci sau pentru a trimite...",kw={"gheare","murlocs","sawtooth snapper","stonard","swamp of sorrows","tok'kar"},sec={{t="Arme pentru coasta",b="Cum murlocii reprezinta o amenintare de-a lungul coastei, Tok'Kar si soldatii sunt stationati aici pentru a proteja Stonard sau pentru a-l avertiza daca forta inamica este prea mare. Astfel, ramane putin timp pentru odihna, iar Tok'Kar ar avea nevoie de mai mult ajutor. Ghearele snapperilor cu dinti de fier fac arme bune daca sunt pregatite cum se cuvine. Tok'Kar cere sase si ofera la schimb una dintre armele avanpostului, recunoscator pentru carne si companie."}},faq={{q="Cine cere ghearele?",a="Tok'Kar, care este stationat de-a lungul coastei pentru a proteja Stonard.",al={"cine da Lack of Surplus","cel care da misiunea","tokkar"}},{q="De ce are Tok'Kar nevoie de ghearele sawtooth snapper?",a="Ghearele lor devin arme excelente daca sunt pregatite cum trebuie, iar Tok'Kar vrea sase dintre ele.",al={"de ce gheare","scopul snapper sawtooth","ghearele armei"}},{q="Ce amenintare supravegheaza avanpostul de pe coasta?",a="Murloc de-a lungul coastei. Soldatii sunt acolo ca sa protejeze Stonard sau sa-l avertizeze daca forta este prea mare.",al={"pericole de pe coasta","atacul murlocilor asupra Stonard","ce supravegheaza Tok'Kar"}},{q="Unde duce mai departe?",a="Urmeaza dupa Threat From the Sea.",al={"ce urmeaza","misiunea urmatoare","dupa Lack of Surplus"}}},fp="15,225,21.392.0,23.61.0,45.84.0,45.108.0,26.28.0"}
P.entries["quest:7"] = {n="Kobold Camp Cleanup",s="La Northshire, Kobold Camp Cleanup le ofera noilor recruti prima incercare de a apara granitele din Stormwind. Marshal McBride trimite voluntari impotriva kobold din padurile nordice, unde numarul lor tot mai mare ameninta tinuturile manastirii.",h="La Northshire, Kobold Camp Cleanup le ofera noilor recruti prima incercare de a apara granitele din Stormwind.",kw={"echo ridge","elwynn forest","kobold","marshal mcbride","northshire","northshire abbey","daunatori"},ang={["faction:Alliance"]="Ca membru Alliance, poti vedea presiunea la care sunt supuse teritoriile de origine ale Stormwind, unde pana si invaziile necrofagilor necesita ajutor urgent din partea militiei de voluntari.",["race:Human"]="Ca Human din Northshire, alungarea verminei kobold este o indatorire civica ce ajuta la protejarea abatiei si a terenurilor agricole impotriva cotropirii."},sec={{t="O vale sub presiune",b="Northshire Valley oferea odinioara liniste pentru rugaciune, agricultura si pregatirea novicilor. In ultimii ani, fortele din Stormwind s-au imputinat. Cu regele disparut si garnizoanele regale imprastiate, creaturile salbatice si cei care profita de situatie imping spre marginea civilizatiei. Marshal McBride conduce apararea vaii din Northshire Abbey. Se bazeaza pe voluntari noi pentru a impiedica amenintarile sa tulbure abatia sau sa puna in pericol podgoriile din imprejurimi."},{t="Daunatorii din padure",b="Kobold sunt locuitori timizi ai pesterilor, foarte atasati de lumanari. De obicei scormonesc prin filoanele subterane, departe de lumina directa a soarelui. Acum, un clan intreg a ajuns la marginea nordica a padurii din Northshire. Daca nu sunt opriti, numarul lor poate transforma cautarea de hrana in raiduri deschise. McBride trimite recruti sa le reduca avangarda si sa-si puna la incercare hotararea de a apara tinutul."}},faq={{q="Cine da ordinul de a starpi tabara koboldilor?",a="Marshal McBride da ordinul. Din Northshire Abbey, el supravegheaza recrutarea si securitatea vaii pentru Stormwind.",al={"cine ofera aceasta misiune","cel care da misiunea","rolul lui Marshal McBride"}},{q="De ce sunt kobolzii in padurile din nord, nu intr-o mina?",a="Kobold traiesc de obicei in vizuini si mine, insa populatia tot mai mare din Northshire s-a raspandit in padurea deschisa. Si-au facut tabere primitive printre copacii din nord, aproape de marginea tinuturilor civilizate.",al={"de ce sunt kobold in afara","koboldii la suprafata","de ce prin paduri"}},{q="De ce sunt acesti koboldi considerati o amenintare pentru Stormwind?",a="Singure, scursurile kobold sunt timide si slabe. In haite, pot sa-i ia prin surprindere pe calatori, sa le prade proviziile si sa copleseasca avanposturile nepazite - o amenintare pe care Stormwind nu si-o poate permite, cu fortele deja intinse la maximum.",al={"sunt kobold periculosi","de ce sa omori daunatorii"}},{q="Unde duce aceasta misiune mai departe?",a="Dupa ce rarii kobold-ii de la suprafata, recrutilor li se cere sa cerceteze mai adanc in Echo Ridge Mine, unde se afla inima infestarii.",al={"care este urmatoarea misiune","pasul urmator","dupa curatarea taberei"}},{q="Primeste Northshire sprijin regulat din partea armatei regale?",a="Nu. Tensiunile politice si lipsa trupelor de dupa disparitia regelui Varian ii obliga pe comandanti precum McBride sa se bazeze pe voluntari civili, aventurieri si recruti in pregatire pentru apararea granitei.",al={"unde sunt garzile Stormwind","de ce voluntari"}},{q="De ce tin koboldii atat de mult la lumanarile lor?",a="Kobolds venereaza lumanarile, considerandu-le principala aparare impotriva intunericului sufocant al tunelurilor subterane. Flacarile le ofera siguranta, vedere si sentimentul ca acel loc le apartine.",al={"de ce lumanari","obsesia pentru lumanari"}}},fx={afae4267={q="De ce vrea Marshal McBride sa curete tabara kobolzilor?",a="Un clan de koboldi a inceput sa impanzeasca padurile de la nord de abatie, iar Marshal McBride vrea sa le reduca numarul inainte sa napadeasca valea. Stormwind este deja coplesit de amenintari din alte parti, asa ca Northshire trebuie sa se apere singur. Desi sunt lasi cand sunt singuri, koboldii prind curaj in haita. Starpirea lor acum mentine asezarea in siguranta si da startul eforturilor de a-i alunga cu totul din Northshire.",al={"de ce sa elimini kobolzii","motivul lui McBride in privinta kobolzilor","de ce sa cureti tabara kobolzilor"}},["35967b57"]={q="Ce sunt daunatorii kobold pe care esti trimis sa-i vanezi?",a="Kobold vermin sunt cercetasii si cautatorii de hrana ai unui clan care s-a strecurat in padurea nordica. Fiind umanoizi asemanatori sobolanilor, care traiesc in mod firesc sub pamant, sunt hoti lasi cand actioneaza singuri, dar s-au adunat in padurile din afara Northshire in numar alarmant. Daca nu sunt opriti, taberele lor care se extind ameninta calatorii, livezile si insasi abatia.",al={"ce sunt daunatorii kobold","tinta daunatorilor kobold"}},["921e514b"]={q="De ce te trimite Marshal McBride in locul garzilor din Stormwind?",a="Armata regala a Stormwindului si-a raspandit fortele in lupta impotriva crizelor din tot regatul, lasand in Northshire Valley doar o mana de garzi. McBride trebuie sa-si tina soldatii in jurul manastirii si al drumurilor principale, pentru a mentine perimetrele defensive. Neavand trupe de rezerva care sa patruleze prin salbaticie, se bazeaza pe recruti capabili si voluntari aflati in trecere pentru a starpi primejdiile nou-aparute.",al={"de ce nu trimit garzi","de ce are McBride nevoie de mine","de ce sa recrutezi aventurieri impotriva koboldilor"}}},fp="19,229,23.429.0,23.359.0,42.123.0,56.202.0,55.197.0,34.145.1,50.184.0,48.164.0"}
P.entries["quest:70"] = {n="The Legend of Stalvan",s="Aceasta etapa a investigatiei ii conduce pe cei care cauta la o scrisoare abandonata in hanul din Goldshire cu ani in urma. Urmand urmele lui Stalvan Mistmantle, drumul iese din Elwynn Forest si ajunge in Districtul Canalelor din Stormwind.",h="Aceasta etapa a investigatiei ii conduce pe cei care cauta la o scrisoare abandonata in hanul din Goldshire...",kw={"canale","Caretaker Folsom","Goldshire","Innkeeper Farley","Lion's Pride Inn","Mistmantle","Stalvan","Stormwind","scrisoare nelivrata"},ang={["faction:Alliance"]="Deslusirea misterului lui Stalvan presupune o calatorie prin tinuturile centrale ale Alliance, refacand un vechi traseu de la catunul linistit Goldshire pana la canalele grandioase ale capitalei.",["race:Human"]="Aceasta ancheta scoate la iveala fortele intunecate care mocnesc in Kingdom of Stormwind, aratand ca raul ce bantuie Duskwood isi are radacinile chiar la portile capitalei."},sec={{t="O teroare in miez de noapte",b="Cand Innkeeper Farley de la Lion's Pride Inn este intrebat despre Stalvan Mistmantle, isi aminteste de o noapte furtunoasa, cu multi ani in urma. Un curier aflat in trecere cautase adapost de ploaia torentiala, dar a coborat scarile in graba, pe la miezul noptii, cuprins de panica. Imbracat doar in hainele de dormit, curierul a iesit in fuga direct in furtuna intunecata si nu a mai fost vazut niciodata."},{t="Pachetul ramas",b="In zborul sau panicat, curierul si-a abandonat sacosa si cufarul personal in camera de la etaj. Printre lucrurile uitate se afla o scrisoare netrimisa, purtand numele Stalvan si adresata unei persoane care locuia in Canal District din Stormwind City. Cufarul a ramas neatins la capatul patului pana cand Farley a permis sa fie deschis."},{t="O primire geroasa",b="Scrisoarea, purtata dupa o lunga intarziere pana in Stormwind, ajunge la Caretaker Folsom, care supravegheaza proprietati de-a lungul canalelor din apropierea parcului. In loc sa-si arate recunostinta pentru livrarea restantei, simpla mentionare a numelui lui Stalvan si vederea scrisului sau starnesc imediat dezgust si ostilitate, sugerand scandaluri adanc inradacinate legate de expeditor."}},faq={{q="Unde este pastrata scrisoarea nelivrata?",a="Scrisoarea se afla intr-un cufar de depozitare, la etajul superior al Lion's Pride Inn din Goldshire. Urca scarile, fa dreapta si intra in dormitorul cu pat; cufarul este la picioarele cadrului patului.",al={"gaseste scrisoarea","locatia cufarului lui Stalvan","unde se afla cufarul"}},{q="De ce nu a fost livrata initial scrisoarea?",a="Cu ani in urma, curierul s-a adapostit de o ploaie torentiala la Lion's Pride Inn. Aproape de miezul noptii, ceva l-a ingrozit atat de tare, incat a fugit in furtuna imbracat doar in hainele de noapte, lasandu-si in urma lada si livrarile.",al={"de ce a fost abandonata scrisoarea","ce l-a speriat pe curier","de ce a fugit mesagerul"}},{q="Unde il gasesc pe Caretaker Folsom in Stormwind?",a="Caretaker Folsom sta de-a lungul canalelor din Stormwind City, aproape de marginea cartierului Park.",al={"locatia lui Folsom","unde este Caretaker Folsom","predarea misiunii in cartierul canalelor"}},{q="De ce este suparat Caretaker Folsom ca a primit scrisoarea?",a="Folsom recunoaste imediat scrisul si numele lui Stalvan si reactioneaza indignat. Stalvan Mistmantle a lasat in urma amintiri amare si furie in randul celor legati de trecutul sau din Stormwind.",al={"de ce e Folsom furios","reactia lui Folsom","ai ceva tupeu"}},{q="Cum se leaga acest lucru de necazurile din Duskwood?",a="Consiliul orasului Darkshire investigheaza un rau persistent, legat de numele lui Stalvan Mistmantle. Pentru a descoperi cine a fost Stalvan in viata, trebuie sa-i reconstitui calatoriile si relatiile de la inceput, prin Elwynn Forest si Stormwind.",al={"de ce este misiunea din Duskwood in Goldshire","ce legatura are asta cu Duskwood"}},{q="Ce se intampla dupa ce ii dai scrisoarea lui Caretaker Folsom?",a="Replica taioasa a lui Caretaker Folsom deschide capitolul Stormwind al anchetei, indemnandu-te sa descoperi unde lucrase Stalvan in trecut si evenimentele sumbre petrecute in sanul familiei nobile pe care o slujea.",al={"urmatorul pas","ce urmeaza dupa aceasta misiune"}}},fx={["1a6ccbd1"]={q="De ce vrea Innkeeper Farley sa fie livrata scrisoarea lui Stalvan?",a="Innkeeper Farley nu are niciun interes personal in treburile lui Stalvan sau in vechea scrisoare; doar te ajuta sa pui cap la cap misterul pe care il cercetezi. Cand intrebi de Stalvan Mistmantle, Farley isi aminteste de un curier ingrozit care a fugit din Lion's Pride Inn cu ani in urma, in timpul unei furtuni, lasandu-si lada cu corespondenta la etaj. Amintindu-si ca ramasese acolo o scrisoare nedusa la destinatie, trimisa de Stalvan si adresata cartierului Canal din Stormwind, Farley ti-o ofera ca sa-ti poti urmari pista evaziva.",al={"de ce ajuta Farley","motivul lui Innkeeper Farley","de ce sa livrez scrisoarea"}},b7fa74bd={q="Ce este scrisoarea nelivrata?",a="Scrisoarea este o veche corespondenta scrisa de Stalvan Mistmantle cu ani in urma, destinata unei adrese din Cartierul Canalelor din Stormwind. A fost lasata in urma la Lion's Pride Inn, cand un mesager a fugit in noapte ingrozit, lasandu-si lucrurile incuiate intr-un cufar de la etaj. In cadrul anchetei tale, scrisoarea este un indiciu material esential, care te trimite la Caretaker Folsom din Stormwind pentru a afla pe cine contacta Stalvan si ce s-a intamplat cu el.",al={"ce este o scrisoare nelivrata","scrisoarea nelivrata a lui Stalvan","ce scrie in scrisoare"}}},fp="21,218,17.344.0,19.334.0,16.348.1,37.203.0,46.226.0,46.99.0,57.200.0,49.228.0,57.204.1"}
P.entries["quest:700"] = {n="A King's Tribute"}
P.entries["quest:7003"] = {n="Zapped Giants",s="Pe Forgotten Coast din Feralas, langa docuri, Zorbin Fandazzle spune ca uriasii ii strica afacerea. Zorbin a construit o raza de micsorare dupa un proiect gnomish, imbunatatit cu pricepere goblin, si iti da Ultra-Shrinker sa-l incerci pe uriasii din Feralas.",h="Pe Forgotten Coast din Feralas, langa docuri, Zorbin Fandazzle spune ca uriasii ii strica afacerea.",kw={"cliff giant","feralas","forgotten coast","land walker","reziduuri de miniaturizare","ultra-shrinker","zapped giants","zorbin fandazzle"},sec={{t="O raza de micsorare pentru uriasi",b="Zorbin Fandazzle trebuie sa gaseasca o solutie pentru uriasii din Feralas, care nu sunt deloc buni pentru afaceri daca Zorbin vrea sa ramana pe-aici. Solutia este o varianta a razei de micsorare gnome, construita cu ceea ce Zorbin numeste cu mandrie inovatii goblin superioare. Ca sa evite neplaceri precum moartea, Zorbin prefera sa o testezi tu. Trebuie sa folosesti Ultra-Shrinker asupra unor uriasi precum Cliff Giants, Deep Striders, Wave Striders, Shore Striders sau Land Walkers si sa aduni reziduurile de miniaturizare ramase pe ei dupa micsorare, apoi sa le aduci inapoi la docuri."},{t="De ce vrea Zorbin reziduurile",b="Zorbin spune ca reziduurile de miniaturizare sunt o marfa pretioasa in inginerie, fiindca ajuta la prevenirea unei situatii atat de dezamagitoare precum explozia pistolului cu descarcator asupra celui care il foloseste. Apoi, Zorbin adauga ca asta se aplica doar altor pistoale cu descarcator, nu celui pe care-l tii in mana."},{t="Inapoi la docuri",b="La intoarcere, Zorbin este incantat sa vada reziduul si ca inca ai toate membrele importante. Apoi Zorbin insista ca Ultra-Shrinker nu a fost niciodata periculos si te numeste prietenul goblinilor de pretutindeni."}},faq={{q="Cine se afla in spatele lui Ultra-Shrinker?",a="Zorbin Fandazzle, aflat langa docurile de pe Forgotten Coast, in Feralas.",al={"cine ofera zapped giants","cel care da misiunea zorbin fandazzle","unde incep zapped giants"}},{q="De ce vrea Zorbin sa micsoreze uriasii?",a="Zorbin spune ca uriasii nu sunt deloc buni pentru afaceri daca ramane aici, iar un urias micsorat este mult mai usor de stapanit.",al={"de ce sa electrocutezi uriasii","de ce sa micsorezi uriasii din feralas","motivul lui zorbin fandazzle"}},{q="Ce uriasi pot fi micsorati?",a="Va fi bun orice fel de urias din Feralas. Pe langa Forgotten Coast se numara Cliff Giants, Deep Striders, Wave Striders, Shore Striders si Land Walkers.",al={"ce uriasi pot electrocuta","care uriasi se pun la socoteala","tinte pentru Zapped Giants"}},{q="Ce sunt reziduurile de miniaturizare?",a="Se gaseste pe un gigant dupa ce acesta a fost micsorat. Zorbin o numeste o marfa pretioasa in inginerie si spune ca ajuta la prevenirea exploziei aparatului de electrocutare in mainile celui care il foloseste.",al={"de ce reziduu de miniaturizare","la ce foloseste reziduul","scopul reziduului lui zorbin"}}},fp="13,258,30.547.0,28.261.0,17.213.1,33.71.0,39.129.0,27.154.0,32.170.0"}
P.entries["quest:701"] = {n="Guile of the Raptor",s="Guile of the Raptor este o misiune in care Tor'gan cauta sa trezeasca spiritul razboinic adormit din Gor'mul. Culegand inimile vanatorilor de carne din tinuturile inalte, Tor'gan planuieste sa faureasca un obiect fermecat, inzestrat cu viclenia si puterea pradatoare a rapitorului.",h="Guile of the Raptor este o misiune in care Tor'gan cauta sa trezeasca spiritul razboinic adormit din Gor'mul.",kw={"razboinic adormit","gor'mul","viclenia rapitorului","vanatori de carne din munti","inimi de rapitor","tor'gan","razboinic"},ang={["class:Warrior"]="Tor'gan cauta sa reaprinda spiritul razboinic adormit din Gor'mul, folosind viclenia si ferocitatea rapitoarelor pentru a-i reaminti de puterea martiala.",["faction:Horde"]="Acest ritual reflecta traditiile Horde de a apela la bestii primordiale si spirite ale naturii pentru a-i reda scopul unui tovaras apatic sau tulburat."},sec={{t="Trezirea razboinicului adormit",b="Tor'gan incearca sa-si readuca in fire un compatriot apatic, pe nume Gor'mul, al carui spirit razboinic a adormit. In loc sa se bazeze pe simple vorbe, Tor'gan recurge la magia primordiala pentru a-l zgudui pe Gor'mul si a-l readuce la actiune. Creand un talisman impregnat cu esenta pradatorilor salbatici, spera sa-i redea lui Gor'mul hotararea de a lupta si sa-i arate puterea noii lor forte."},{t="Inima pradatorului",b="Pentru a canaliza instinctele de pradator ale salbaticiei, Tor'gan are nevoie de inimile Highland Fleshstalkers. In traditiile samanice si primordiale, inima unui vanator viclean ii poarta ferocitatea si siretenia. Tor'gan impleteste din aceste trofee atat un talisman fizic, cat si o vraja, urmarind sa-l inzestreze direct pe Gor'mul cu siretenia pradatorului, pentru ca acesta sa-si redescopere adevarata menire."}},faq={{q="Cine este Tor'gan?",a="Tor'gan este o figura spirituala sau samanica ce cauta sa-l ajute pe Gor'mul. Crezand ca Gor'mul si-a pierdut legatura cu puterea interioara, Tor'gan aduna ingrediente pentru a fauri un obiect impregnat cu magia fiarelor, care sa-l trezeasca din nou.",al={"cine este Tor'gan","Torgan","cel care ofera misiunea"}},{q="Cine este Gor'mul?",a="Gor'mul si-a pierdut spiritul de luptator si a lasat razboinicul din el sa adoarma. Tor'gan vrea sa-i insufle esenta primordiala a unui pradator, pentru ca acesta sa vada o noua putere si sa se ridice din nou la lupta.",al={"cine este gormul","de ce il ajuta pe gormul","razboinic adormit"}},{q="De ce are nevoie Tor'gan de inimi de rapitor?",a="Tor'gan are nevoie de douasprezece inimi de raptoare pentru a fauri atat un talisman material, cat si vraja necesara pentru a-l incarca pe Gor'mul. Magia primordiala foloseste adesea inimile pradatorilor pentru a canaliza instinctele, siretenia si puterea lor de vanatoare.",al={"de ce inimi de raptor","la ce folosesc inimile","magia raptorilor"}},{q="De unde provin inimile de raptoare?",a="Inimile necesare sunt luate de la Highland Fleshstalkers, rapitoare pradatoare cunoscute pentru maiestria lor neobosita la vanatoare si viclenie. Tor'gan le considera suficient de puternice pentru a alimenta vraja de trezire.",al={"unde gasesc inimi","care raptoare","urmaritorii de carne din tinuturile inalte"}},{q="Ce semnifica siretenia rapitorului?",a="Viclenia rapitorului intruchipeaza siretenia, reflexele rapide si instinctul letal al pradatorului. Tor'gan crede ca insusirea acestei naturi anume va pune capat letargiei lui Gor'mul si ii va readuce instinctele de lupta.",al={"ce este viclenia rapitorului","ce putere","ce inseamna viclenia rapitorului"}},{q="Care este scopul final al ritualului?",a="Tor'gan faureste obiectul si impleteste vraja folosind inimile adunate, pentru a-i demonstra lui Gor'mul o putere noua si a-i trezi identitatea latenta de razboinic, astfel incat acesta sa-si poata relua calea.",al={"s-a vindecat gormul","ce se intampla dupa ritual","functioneaza oare"}}},fp="19,260,29.372.0,25.370.0,15.214.0,15.212.0,36.231.0,37.206.0,42.218.0,40.182.0"}
P.entries["quest:702"] = {n="Guile of the Raptor",s="Dupa Guile of the Raptor de mai devreme, Tor'gan iti da un glob si te trimite la Gor'mul din Hammerfall. Energia lui poarta esenta raptorului, menita sa insufleteasca spiritul lui Gor'mul si sa-i dea un nou rost.",h="Dupa Guile of the Raptor de mai devreme, Tor'gan iti da un glob si te trimite la Gor'mul din Hammerfall.",kw={"arathi highlands","gor'mul","hammerfall","esenta de raptor","tor'gan","orbul lui torgan"},sec={{t="Sfera lui Tor'gan",b="Tor'gan iti da un glob a carui energie ar trebui sa-l umple pe Gor'mul cu esenta raptorului. El spera ca aceasta ii va trezi spiritul razboinic si il va indrepta spre un nou drum in viata. Odata ce Gor'mul isi revine, Tor'gan intentioneaza sa-i explice situatia actuala a Horde si sa-i castige ajutorul unui mare Warrior in luptele neintrerupte."},{t="Amaraciunea lui Gor'mul",b="Gor'mul te intampina cu amaraciune la intoarcere, spunand ca nu vrea nimic altceva decat si mai multa mila din partea lui Tor'gan si batandu-si joc de tine cu vorbe despre o sfoara viu colorata."},{t="O putere ciudata",b="Totusi, globul este mult mai interesant decat se astepta Gor'mul, iar el remarca energia stranie pe care o emana."},{t="Raptorul launtric",b="Cand Gor'mul ia globul, sangele ii fierbe, iar viclenia raptorului il cuprinde. Se intreaba cu voce tare daca aceasta este shamanismul despre care i-a vorbit Tor'gan, apoi declara ca s-a reinnoit si ca puterea ii revine."}},faq={{q="Cine este Gor'mul?",a="Gor'mul este un razboinic abatut din Hammerfall. Tor'gan vrea sa-i ridice moralul si sa-l indrume pe un drum nou, pentru ca Horde sa se poata bucura de ajutorul unui mare razboinic.",al={"cine este gormul","povestea lui gormul","ce problema are gormul"}},{q="La ce foloseste orb-ul lui Tor'gan?",a="Energia lui trebuie sa-l umple pe Gor'mul cu esenta raptorului, trezindu-i spiritul si oferindu-i un nou scop.",al={"ce face globul","scopul globului lui torgan","globul guile"}},{q="Ce a fost inainte de acest pas?",a="Mai intai vine o misiune anterioara Guile of the Raptor, iar acest pas se bazeaza pe ea.",al={"misiune precedenta","prereq"}}},fp="19,206,13.324.0,20.152.0,15.122.1,17.207.1,15.160.0,37.111.0,27.71.0"}
P.entries["quest:7025"] = {n="Treats for Greatfather Winter"}
P.entries["quest:703"] = {n="Barbecued Buzzard Wings",s="Rigglefuzz jura pe aripile de bucard la gratar, cu sos bogat peste carne acrisoara. Are toate ingredientele pentru o portie, in afara de aripile propriu-zise. Adu-i destule si poate se va desparti de reteta.",h="Rigglefuzz jura pe aripile de bucard la gratar, cu sos bogat peste carne acrisoara.",kw={"badlands","gratar","buzzard","gatit","reteta","rigglefuzz","aripi"},ang={["profession:Cooking"]="Atentie, bucatari: reteta preparatului este disponibila."},sec={{t="Un favorit local",b="Rigglefuzz este mandru de aripile de vultur-gulerat la gratar. Sosul este bogat, carnea are un gust acrisor, iar aroma ajunge departe, pana la cei infometati. Are deja toate ingredientele pentru o portie, mai putin aripile. Adu patru aripi de vultur-gulerat, iar Rigglefuzz s-ar putea sa-ti impartaseasca reteta."}},faq={{q="Cine cere aripile de buzzard?",a="Rigglefuzz vrea aripi de buzzard ca sa gateasca o portie de aripi de buzzard la gratar.",al={"cine ofera barbecued buzzard wings","cine este rigglefuzz","cel care ofera misiunea"}},{q="Ce ofera Rigglefuzz la schimb pentru aripi?",a="Rigglefuzz sugereaza ca iti va impartasi reteta daca aduci destule aripi.",al={"care este recompensa","ce primesc","recompensa pentru reteta"}},{q="De ce are Rigglefuzz nevoie de aripi de buzzard?",a="Rigglefuzz are toate celelalte ingrediente necesare pentru o portie de aripi de buzzard la gratar; lipsesc doar aripile.",al={"de ce vulturii","motivul lui Rigglefuzz","de ce vrea Rigglefuzz aripi"}},{q="De cate aripi are nevoie Rigglefuzz?",a="Patru aripi de vultur de stepa.",al={"cate aripi de buzzard","numarul de aripi de buzzard"}}},fp="23,198,16.268.0,31.74.0,51.65.0,39.109.0,36.19.0"}
P.entries["quest:705"] = {n="Pearl Diving",s="Rigglefuzz, un goblin, gaseste Badlands plin de pradatori feroce si necrofagi indrazneti si supravietuieste fiind viclean: bombele orbitoare alunga vietatile salbatice. Rezervele de praf de perle albastre zdrobite sunt pe terminate, asa ca esti trimis la Vile Reef din Stranglethorn, sa aduci mai mult.",h="Rigglefuzz, un goblin, gaseste Badlands plin de pradatori feroce si necrofagi indrazneti si supravietuieste...",kw={"badlands","blue pearl","flash bomb","pearl diving","rigglefuzz","stranglethorn vale","vile reef"},ang={["profession:Engineering"]="Inginerii au motive intemeiate sa se intereseze de bombele luminoase ale lui Rigglefuzz."},sec={{t="Un Goblin sireat",b="Badlands sunt aspre, iar Rigglefuzz recunoaste ca ii este frica fiind un goblin mic si scund, inconjurat de pradatori si necrofagi. Rigglefuzz stie reteta bombelor orbitoare si le foloseste pentru a speria fauna salbatica. Un ingredient e pe terminate: pulbere de perle albastre zdrobite."},{t="Perle din recif",b="Perlele albastre provin din scoicile de la Vile Reef din Stranglethorn. Rigglefuzz glumeste ca ar fi bine sa porti cizme bune, apoi te asteapta in Badlands pentru noua dintre ele, promitand ca iti va rasplati efortul."}},faq={{q="De ce are Rigglefuzz nevoie de perle albastre?",a="Rigglefuzz foloseste pulbere de perla albastra zdrobita pentru a face bombe orbitoare, iar proviziile sunt pe terminate.",al={"perlele lui rigglefuzz","de ce Pearl Diving","de ce perle albastre"}},{q="Unde se gasesc perlele albastre?",a="Se gasesc in scoici la Vile Reef, in Stranglethorn.",al={"unde se gasesc perlele albastre","locatia perlei albastre","perle din Vile Reef"}},{q="De ce foloseste Rigglefuzz bombe orbitoare?",a="Badlands sunt pline de pradatori feroce si necrofagi indrazneti, iar bombele orbitoare alunga vietatile salbatice.",al={"de ce bombe orbitoare","apararea lui Rigglefuzz"}},{q="Cate perle albastre vrea Rigglefuzz?",a="Noua perle albastre, aduse inapoi la Rigglefuzz in Badlands.",al={"numar de perle albastre","cate perle"}}},fp="12,269,22.261.0,20.207.0,37.93.0,32.58.0,36.104.0,42.61.0"}
P.entries["quest:706"] = {n="Fiery Blaze Enchantments",s="Sigrun Ironhew, care asteapta vesti din Ironforge, se afla in Badlands si cunoaste o tehnica de infuzare a armelor cu foc. Are nevoie de sange din inima inca batatoare a unui pui rar de dragon negru, iar puii din Lethlor Ravine sunt locul unde vei gasi unul.",h="Sigrun Ironhew, care asteapta vesti din Ironforge, se afla in Badlands si cunoaste o tehnica de infuzare a...",kw={"badlands","inima de black drake","feranor steeltoe","flacara arzatoare","ironforge","lethlor ravine","pui de dragon dogoritor","paznic parjolit","sigrun ironhew"},ang={["faction:Alliance"]="Sigrun Ironhew asteapta vesti din Ironforge, iar aceasta sarcina este pentru Alliance."},sec={{t="Meseria unui ucenic",b="Sigrun Ironhew a invatat o metoda speciala de a impregna armele cu vraji de foc pe cand era ucenica lui Feranor Steeltoe, despre care s-a auzit ultima oara printre fierarii unei cete de vanatoare din Lordaeron. Sigrun asteapta vesti din Ironforge si nu prea are altceva de facut."},{t="Puii din Lethlor Ravine",b="Sigrun nu va dezvalui prea multe despre proces; spune doar ca este nevoie de sange din inima inca batatoare a unui pui rar de drake negru. Du-i lui Sigrun o inima de la puii din acea ravena si iti va arata mestesugul. Scalding Whelps si Scorched Guardians de acolo sunt sursa inimilor."}},faq={{q="Cine a invatat-o pe Sigrun Ironhew aceasta tehnica de vrajire?",a="Sigrun a invatat meseria ca ucenica a lui Feranor Steeltoe, despre care s-a auzit ultima data in Lordaeron, la o fierarie a unei expeditii de vanatoare.",al={"profesorul lui sigrun","cine l-a instruit pe sigrun","feranor steeltoe"}},{q="De ce componenta este nevoie pentru a pune foc pe o lama?",a="Sange extras din inima unui pui rar de dragon negru, a carui inima inca bate.",al={"de ce are nevoie Sigrun","cerinta pentru inima de drake negru","materialele pentru Fiery Blaze"}},{q="Unde pot fi gasiti puii de dragon negru?",a="In Lethlor Ravine, in partea de est a Badlands.",al={"unde gasesc black drakes","pui de dragon din Lethlor Ravine","locatia inimii unui black drake"}},{q="De ce zaboveste Sigrun Ironhew in Badlands?",a="Sigrun asteapta vesti din Ironforge, iar intre timp nimic altceva nu o tine ocupata.",al={"de ce este sigrun in badlands","scopul lui sigrun ironhew"}},{q="Ce creaturi lasa in urma inima necesara?",a="Puii de dragon oparesti si Gardienii parjoliti din Lethlor Ravine.",al={"ce lasa black drakes heart","care pui au inimi"}}},fp="24,242,21.245.0,28.303.0,53.114.0,52.77.0,39.43.0,48.106.0,39.61.0"}
P.entries["quest:708"] = {n="The Black Box",s="O cutie neagra metalica a aparut in stomacul unui condor urias din Badlands, cu suprafata plina de gropite, ca si cum ar fi stat in acid. Pe partea de dedesubt, sub un simbol, este stampilat un semn: Engine #19 - Ironforge Siege Brigade.",h="O cutie neagra metalica a aparut in stomacul unui condor urias din Badlands, cu suprafata plina de gropite...",kw={"badlands","cutie neagra","cutie neagra corodata","condor urias","sala armelor","ironforge siege brigade","pilot longbeard"},ang={["faction:Alliance"]="Pe cutie se afla insemnele Ironforge, iar urma ei duce la Ironforge."},sec={{t="Smuls dintr-un condor",b="Coroziunea sugereaza ca acea cutie a stat in interiorul condorului vreme indelungata, in timp ce acidul ataca metalul. Intoarce-o si vei vedea un simbol imprimat pe fund, iar dedesubt scrie Engine #19 - Ironforge Siege Brigade. Trebuie sa o duci la Hall of Arms din Ironforge, la Pilot Longbeard."}},faq={{q="De unde provine cutia neagra corodata?",a="Se afla in stomacul unui condor urias din Badlands si pare sa fi zacut acolo de foarte mult timp.",al={"de unde provine cutia","cum a ajuns cutia aici","originea cutiei negre"}},{q="Ce insemne sunt imprimate pe cutie?",a="Pe fund este imprimat un simbol, iar dedesubt scrie Engine #19 - Ironforge Siege Brigade.",al={"ce scrie pe cutie","inscriptiile de pe cutia neagra","inscriptia de pe cutie"}},{q="Cine ar trebui sa primeasca cutia?",a="Pilot Longbeard, la Hall of Arms din Ironforge.",al={"cine primeste cutia","unde ajunge cutia neagra","cui trebuie sa-i duc cutia"}}},fp="13,226,20.271.0,43.104.0,37.98.0,35.50.0"}
P.entries["quest:71"] = {n="Report to Thomas"}
P.entries["quest:710"] = {n="Study of the Elements: Rock",s="Lotwil Veriatus s-a oprit in Badlands ca sa lucreze la catuse de legare a elementalilor. Pentru a testa cateva vraji ofensive si niste dispozitive asamblate din bucati, Lotwil are nevoie de fragmente mici de piatra de la elementalii inferiori ai pietrei din apropiere.",h="Lotwil Veriatus s-a oprit in Badlands ca sa lucreze la catuse de legare a elementalilor.",kw={"badlands","elementali inferiori ai rocii","lotwil veriatus","catuse de legare elementala","aschii mici de piatra","study of the elements: rock"},ang={["class:Mage"]="Mages sunt cei pe care sunt menite sa-i slujeasca lanturile lui Lotwil."},sec={{t="Catuse elementale",b="Aici, in Badlands, Lotwil Veriatus lucreaza la un proiect: catuse pentru legarea elementala. Odata incheiate, acestea le-ar permite magilor sa invoce elementali si mai puternici, pentru scopuri si mai insemnate. Pentru inceput, Lotwil vrea zece aschii mici de piatra, usor de luat de la elementalii inferiori de piatra din dealurile aflate chiar la vest."}},faq={{q="Cine cere fragmentele de piatra?",a="Lotwil Veriatus, care s-a oprit in Badlands pentru a lucra la un proiect.",al={"cine da aceasta misiune","cel care ofera misiunea","lotwil veriatus"}},{q="La ce lucreaza Lotwil Veriatus?",a="Catuse pentru legarea elementala, menite sa le permita magilor sa invoce elementali si mai puternici.",al={"proiectul lui lotwil","catusele legarii elementale","ce construieste lotwil"}},{q="De ce are Lotwil nevoie de fragmente mici de piatra?",a="Sunt pentru testarea unor vraji ofensive noi ale lui Lotwil si a catorva dispozitive asamblate din piese.",al={"de ce fragmente de piatra","scopul fragmentelor","la ce folosesc fragmentele"}},{q="Unde se gasesc fragmentele de piatra?",a="De la elementalii de piatra inferiori din dealurile aflate imediat la vest de Lotwil.",al={"unde gasesti fragmente","locatia lesser rock elementals","sursa fragmentelor de piatra"}}},fp="27,221,18.314.0,35.70.0,35.87.0,40.95.0,33.72.0"}
P.entries["quest:711"] = {n="Study of the Elements: Rock",s="Lotwil Veriatus te lauda, spunand ca esti mai priceput decat toti ucenicii lui Lotwil laolalta, si doreste sa treci la urmatoarea etapa a probelor. De data aceasta sunt necesare trei lespezi mari de piatra, bucati care se gasesc cel mai bine la elementalii de piatra.",h="Lotwil Veriatus te lauda, spunand ca esti mai priceput decat toti ucenicii lui Lotwil laolalta, si doreste sa...",kw={"badlands","placi mari de piatra","lotwil veriatus","rock elementals","placi de piatra","study of the elements: rock"},sec={{t="Bucati mai mari",b="Urmatoarele parti ale lucrarii lui Lotwil Veriatus necesita materiale mai solide. Elementalii de piatra au trupuri mai mari si mai rezistente, deci e mai probabil sa poarte bucati suficient de mari pentru teste. Lotwil te indruma mai departe spre vest sau spre sud-est, de-a lungul marginilor muntilor, si iti cere sa aduni trei lespezi mari de piatra. Lotwil are nevoie de ceva timp ca sa testeze piesele mai mici pe care le-ai adus mai devreme."},{t="Sperantele lui Lotwil",b="Vra jile lui Lotwil au actionat asupra bucatilor mai mici exact cum prevazuse. Daca urmatorul experiment reuseste la fel de bine cum anticipeaza, elementalii aflati sub controlul lui Lotwil vor face de rusine orice a fost chemat inainte."}},faq={{q="Cine te trimite dupa lespezile mari?",a="Lotwil Veriatus, care lucreaza in Badlands.",al={"cine ofera aceasta misiune","misiunea lui Lotwil","cine ofera Studiul elementelor"}},{q="Ce a precedat aceasta cerere?",a="Misiunea anterioara Study of the Elements: Rock, in care i-ai adus lui Lotwil mici fragmente de piatra.",al={"misiunea anterioara","etapa precedenta","ce am facut inainte"}},{q="Unde spune Lotwil ca se gasesc elementalii de piatra?",a="Mai la vest de Lotwil sau spre sud-est, de-a lungul marginilor muntilor.",al={"unde sunt elementalii","locatiile elementalilor","unde gasesti lespezile"}},{q="De ce are Lotwil nevoie de placi mari de piatra?",a="Lotwil are nevoie de bucati mai mari pentru urmatoarele teste. Elementalii de piatra au corpuri mai mari si mai puternice, asa ca bucatile lor sunt suficient de mari.",al={"de ce placi mari","scopul placilor","obiectivul cercetarii lui Lotwil"}}},fp="27,202,13.360.0,14.194.0,36.48.0,30.88.0,50.70.0,40.126.0"}
P.entries["quest:712"] = {n="Study of the Elements: Rock",s="Lotwil Veriatus mai are nevoie de o piesa de la elementalii din Badlands: bratari de legare a pietrei, luate de la elementalii superiori ai pietrei. Dupa socotelile lui Lotwil, acestea sunt suficiente pentru a masura puterea propriilor sale catuse.",h="Lotwil Veriatus mai are nevoie de o piesa de la elementalii din Badlands: bratari de legare a pietrei, luate...",kw={"badlands","bratari de legare a stancii","elementali superiori ai stancii","kharanos","lotwil veriatus","lucien","ogri","servo"},sec={{t="Evaluarea catusei",b="Dupa dalele de piatra, Lotwil Veriatus iti cere o ultima piesa de la elementalii din Badlands. Bratari de legare a stancii, luate de la elementalii de piatra superiori, ar trebui sa-i permita lui Lotwil sa evalueze rezistenta catuselor aflate in lucru. Clarviziunea lui Lotwil a aratat un grup de elementali la sud-vest, langa niste ogri, daca isi aminteste bine. Se doresc cinci bratari, ca sa ramana si unele de rezerva, fiindca Servo e vestit pentru ca rataceste reactivi si materiale de cercetare."}},faq={{q="De ce are nevoie Lotwil de aparatori pentru brate?",a="Potrivit calculelor lui Lotwil, bratarile de legare a stancii sunt suficiente pentru a masura puterea propriilor catuse ale lui Lotwil.",al={"de ce bracers of rock binding","la ce folosesc bratarile","bratarile de legare ale lui lotwil"}},{q="De ce cere Lotwil cinci bratari?",a="Ca sa aiba cateva in plus, fiindca Servo e cunoscut pentru ca rataceste reactivii si cercetarile lui Lotwil.",al={"de ce cinci bracers","cate bracers","de ce mai multe"}},{q="Unde se gasesc elementalii superiori ai pietrei?",a="Potrivit viziunilor lui Lotwil, un grup se afla la sud-vest de el, langa niste ogre. Dealurile din jurul Camp Cagg sunt salasul lor.",al={"unde se afla rock elementals","locatia lui greater rock elemental","unde gasesti bracers"}},{q="Ce se intampla cu lespezile de piatra colectate mai devreme?",a="Lucien va duce placile suplimentare inapoi la Kharanos dupa ce se incheie treaba de aici, deoarece s-ar putea dovedi din nou utile.",al={"ce s-a intamplat cu lespezile de piatra","lespezile de piatra ale lui lucien","lespezile din kharanos"}}},fp="27,219,20.431.0,33.112.0,37.89.0,46.134.0,50.114.0"}
P.entries["quest:713"] = {n="Coolant Heads Prevail",s="Lotwil Veriatus vrea o fiola de Frost Oil pentru a intari catusele menite sa tina in frau un prieten invocat. Bro'kin, un prieten goblin al lui Lotwil din Alterac, te poate invata cum sa-l prepari.",h="Lotwil Veriatus vrea o fiola de Frost Oil pentru a intari catusele menite sa tina in frau un prieten invocat.",kw={"badlands","bro'kin","coolant heads prevail","ulei de inghet","lotwil veriatus","ruinele din alterac","catuse"},sec={{t="Un lichid de racire esential",b="Lotwil Veriatus jura ca nimic nu impiedica un motor sau angrenajele sa se supraincalzeasca la fel de bine ca Frost Oil si ca valoarea acestuia ca lubrifiant este de neegalat. De asemenea, ajuta obiectele magice sa-si pastreze vrajile. O fiola ar spori capacitatea magica a catuselelor lui Lotwil, facandu-le destul de puternice pentru a-l opri pe prietenul invocat sa-i omoare pe toti."},{t="Bro'kin din Alterac",b="Bro'kin, un prieten goblin al lui Lotwil, te poate invata sa faci uleiul. Bro'kin se afla in Ruins of Alterac si vinde marfa dintr-un loc aflat sus, pe zidul vechiului oras."},{t="Cand soseste petrolul",b="Cand soseste uleiul, Lotwil spune ca este lichidul de racire perfect pentru noile bracere. Lotwil jura ca, daca vrajile nu tin un secol, toate bunurile lui vor reveni lui Servo. Lotwil se asteapta si ca mage-ii din Assembly sa ramana uimiti cand lucrarea va fi gata."}},faq={{q="De ce are Lotwil Veriatus nevoie de Frost Oil?",a="O fiola ar spori capacitatea magica a catuselor lui Lotwil, facandu-le suficient de puternice pentru a impiedica prietenul invocat sa-i omoare pe toti.",al={"de ce ulei de gheata","la ce foloseste uleiul de gheata","uleiul lui lotwil"}},{q="Cine stie sa prepare Frost Oil?",a="Bro'kin, un prieten Goblin al lui Lotwil, te poate invata sa-l confectionezi. Se afla in Ruins of Alterac, sus, pe un zid al vechiului oras.",al={"cine te invata Frost Oil","unde poti invata Frost Oil","reteta lui brokin"}},{q="Ce este special la Frost Oil?",a="Lotwil spune ca nimic nu impiedica mai bine supraincalzirea unui motor sau a unor roti dintate, ca este un lubrifiant fara egal si ca ajuta obiectele magice sa-si pastreze incantatiile.",al={"proprietatile uleiului de ger","la ce e bun uleiul de ger"}}},fp="21,185,15.338.0,18.158.0,20.268.1,40.141.0,32.124.0,32.171.0"}
P.entries["quest:714"] = {n="Gyro... What?",s="Dupa ce i-ai adus lui Lotwil Veriatus Frost Oil de la Coolant Heads Prevail, il gasesti tot absorbit de un mecanism in Badlands. Lipseste o singura piesa mica, dar cruciala: un gyrochronatom.",h="Dupa ce i-ai adus lui Lotwil Veriatus Frost Oil de la Coolant Heads Prevail, il gasesti tot absorbit de un...",kw={"badlands","dispozitiv","coolant heads prevail","gyrochronatom","kharanos","lotwil veriatus"},ang={["profession:Engineering"]="Engineers pot confectiona singuri un gyrochronatom."},sec={{t="O piesa esentiala",b="Lotwil Veriatus, absorbit de munca, spune ca te-ai descurcat cu mult peste toate asteptarile si iti spune sa vii sa ceri de lucru daca va mai intalniti vreodata in Kharanos. Apoi se grabeste sa prinda ceva din zbor si iti spune ce vrea de fapt: un gyrochronatom. Recunoaste ca e o piesa mica, dar cruciala. Adu una, iar proiectul ar trebui sa fie gata de finalizare."},{t="Predarea obiectului",b="Cand ii dai gyrochronatomul, Lotwil il smulge cu un strigat si spune ca lucrarea este aproape gata, intr-adevar, si ca proiectul are acum prioritate absoluta. Promisiunea ca va termina curand continua sa se clatine, de la doar cateva minute pana la cine stie cat."}},faq={{q="Cine cere gyrochronatom?",a="Lotwil Veriatus, care lucreaza la un mecanism in Badlands.",al={"cine ofera Gyro What","cine da misiunea Gyro What","Lotwil Veriatus din Badlands"}},{q="La ce ii trebuie gyrochronatomul lui Lotwil Veriatus?",a="Este o piesa mica, dar destul de importanta, iar cu ea Lotwil ar trebui sa poata termina proiectul.",al={"de ce gyrochronatom","ce construieste Lotwil"}},{q="Care este oferta legata de Kharanos?",a="Absorbit de munca, Lotwil spune ca, daca va intalniti vreodata in Kharanos, poti veni oricand sa ceri de lucru.",al={"lotwil kharanos","oferta de munca din Kharanos"}},{q="Unde poate fi gasit un gyrochronatom?",a="Inginerii le fabrica, dar pot fi cumparate si de la furnizorii de inginerie.",al={"cum obtii gyrochronatom","sursa gyrochronatom","de unde cumperi gyrochronatom"}}},fp="13,193,14.370.0,15.250.1,36.65.0,53.98.0,33.111.0,35.76.0"}
P.entries["quest:716"] = {n="Stone Is Better than Cloth",s="Lucien Tosselwrench stie cat de zgarcit poate fi Lotwil si se ofera sa-ti faca ceva drept rasplata: bratari fermecate facute din pietrele in plus pe care le-ai strans. Lui Lucien ii lipsesc niste bratari de bronz cu model, facute de un fierar.",h="Lucien Tosselwrench stie cat de zgarcit poate fi Lotwil si se ofera sa-ti faca ceva drept rasplata: bratari...",kw={"badlands","roca elementala","bratari fermecate","lotwil veriatus","lucien tosselwrench","bratari din bronz cu model"},ang={["profession:Blacksmithing"]="Bratarile de bronz pe care le vrea Lucien sunt faurite de un fierar."},sec={{t="Un multumesc pentru osteneala",b="Dupa probele din Study of the Elements: Rock, Lucien Tosselwrench recunoaste cat de zgarcit poate fi Lotwil si vrea sa se revanseze fata de tine. Lucien a fost ocupat cu pietrele in plus pe care le-ai adunat si poate fauri bratari fermecate de calitate. S-ar putea chiar sa te apere de ceea ce Lucien numeste atrocitatea ce va veni, cea mai noua inventie a lui Lotwil."},{t="De ce are nevoie Lucien",b="Ca sa termine bratarile, Lucien are nevoie de bratari din bronz cu model, de felul celor facute de un fierar. Lucien te avertizeaza ca e intelept sa nu astepti mult, fiindca nimeni nu stie ce urmeaza."}},faq={{q="Cine se ofera sa confectioneze bratarile?",a="Lucien Tosselwrench, din Badlands, se ofera sa faca bratari vrajite din pietrele in plus pe care le-ai adunat.",al={"cine ofera stone is better than cloth","cel care da misiunea","lucien tosselwrench"}},{q="De ce iti confectioneaza Lucien aceasta armura?",a="Lucien stie cat de zgarcit poate fi Lotwil si vrea sa-ti faca ceva drept multumire pentru tot efortul. Ar putea, de asemenea, sa te ajute sa te aperi de cea mai noua inventie a lui Lotwil.",al={"de ce sa faci aparatori","motivul lui lucien","lotwil ieftin"}},{q="De ce are nevoie Lucien pentru a termina de faurit aparatorile de incheietura?",a="Bratari de bronz cu model, de genul celor faurite de un fierar.",al={"de ce obiect am nevoie","obiectele necesare","sunt necesare bratari din bronz cu model"}},{q="Ce misiune preceda aceasta?",a="Urmeaza dupa a treia cerere Study of the Elements: Rock a lui Lotwil.",al={"misiunea anterioara","cerinta prealabila pentru Stone Is Better than Cloth"}}},fp="26,220,28.326.0,17.175.0,32.107.0,40.148.0,53.54.0,29.62.0"}
P.entries["quest:7162"] = {n="Proving Grounds"}
P.entries["quest:717"] = {n="Tremors of the Earth",s="Garek a ajuns la concluzia ca Blacklash si Hematus nu pot fi lasati singuri in inchisoarea lor din Lethlor. Acolo s-au instalat dragoni negri, iar ogrele au furat Sign of the Earth, asa ca Garek te trimite sa eliberezi dragonii si sa-i ucizi.",h="Garek a ajuns la concluzia ca Blacklash si Hematus nu pot fi lasati singuri in inchisoarea lor din Lethlor.",kw={"blacklash","garek","hematus","kirin tor","krasus","lethlor ravine","pietre runice","sigiliul pamantului","semnul pamantului","cutremurele pamantului"},ang={["faction:Alliance"]="Cererea lui Garek este una pentru Alliance."},sec={{t="O inchisoare pe cale sa cedeze",b="Garek nu mai poate fi sigur ca Blacklash si Hematus vor ramane inchisi. Dragonii negri salasluiesc acum in Lethlor, iar ogrele au furat Sign of the Earth. Garek considera ca e nevoie de masuri mai dure, iar dragonii trebuie sa moara."},{t="Ruperea sigiliului",b="Trei pietre runice tin drakes inchisi, iar numai Sign of the Earth ii poate atrage. Folosesti Sign pe Pillars of Amethyst, Opal si Diamond, apoi asezi pietrele runice in Seal of the Earth. Asta ii elibereaza pe cei doi, iar tu ii ucizi. Garek vrea inapoi Bindings ale lui Blacklash, Chains ale lui Hematus si Sign of the Earth."},{t="Dupa fapta",b="Dupa ce drakes sunt morti, Garek declara ca Kirin Tor nu mai trebuie sa-si faca griji pentru prizonierii lui Lethlor. Garek intentioneaza sa-i raporteze succesul unui maestru, Krasus, care va fi cu siguranta multumit."}},faq={{q="Cine sunt Blacklash si Hematus?",a="Drakes tinuti prizonieri in Lethlor, dincolo de un sigiliu.",al={"blacklash and hematus","cine sunt drake-ii","ce este inchis in lethlor"}},{q="De ce trebuie ucisi drakes, in loc sa fie tinuti inchisi?",a="Garek nu mai poate fi sigur ca vor ramane intemnitati. Black dragons traiesc acum in Lethlor, iar ogres au luat Sign of the Earth.",al={"de ce sa-l ucizi pe blacklash","de ce sa distrugi inchisoarea","de ce sa-l ucizi pe hematus"}},{q="Cum este desigilata inchisoarea?",a="Trei pietre runice sunt luate de pe stalpii cu Semnul Pamantului, apoi asezate in Sigiliul Pamantului.",al={"cum deschid Seal of the Earth","cum il invoc pe Blacklash","cum eliberez drakes"}},{q="Ce trebuie adus inapoi la Garek?",a="Trei lucruri trebuie duse inapoi la Garek: Blacklash's Bindings, Chains of Hematus si Sign of the Earth.",al={"ce sa-i returnez lui garek","legaturile lui blacklash","lanturile lui hematus"}},{q="Ce misiune preceda aceasta?",a="Urmeaza dupa Tremors of the Earth.",al={"misiunea anterioara","conditia prealabila pentru Tremors of the Earth"}}},fp="20,225,16.231.0,17.335.0,14.182.1,30.47.0,58.127.0,27.109.0,35.101.0,29.44.0"}
P.entries["quest:718"] = {n="Mirages",s="Grabindu-se sa plece de la locul sapaturilor din Uldaman, grupul lui Sigrun Ironhew a lasat in urma carute si lazi. Ogres din Camp Kosh au luat caruta care continea toate armele lor, iar de atunci grupul nu mai are hrana.",h="Grabindu-se sa plece de la locul sapaturilor din Uldaman, grupul lui Sigrun Ironhew a lasat in urma carute si...",kw={"badlands","camp kosh","sapatura","mirages","ogres","sigrun ironhew","lada cu provizii","uldaman"},ang={["faction:Alliance"]="Sigrun Ironhew cauta ajutorul Alliance."},sec={{t="Flamand in Badlands",b="In graba de a parasi situl de excavare din Uldaman, Sigrun Ironhew si grupul ei au lasat in urma multe carute si lazi cu provizii. Ogres din Camp Kosh scormonesc printre resturi ca niste vulturi. Au luat caruta in care se aflau toate armele grupului, iar de atunci membrii lui au ramas fara mancare. Sigrun recunoaste ca e stanjenitor si iti cere sa recuperezi lada cu provizii."},{t="La intoarcerea ta",b="Cand te intorci, Sigrun marturiseste ca a inghitit o gura de nisip cat ai fost plecat. Sigrun trece repede peste asta si spune ca grupul va iesi in seara aceasta sa gaseasca de mancare si va manca regeste."}},faq={{q="Cine este Sigrun Ironhew?",a="Sigrun Ironhew face parte dintr-un grup care a parasit in graba situl de excavare din Uldaman si a ramas acum fara hrana in Badlands.",al={"sigrun ironhew","cine da mirages","cine este sigrun"}},{q="De ce este grupul lui Sigrun infometat?",a="Ogrilor le-a cazut cu tronc caruta care le transporta toate armele si celelalte lucruri, iar de atunci nu au mai putut obtine hrana.",al={"de ce le este foame","de ce nu au mancare","problema lui sigrun cu mancarea"}},{q="Cine a luat proviziile abandonate?",a="Ogres din zona Camp Kosh, care au umblat peste tot printre echipamentele ramase in urma.",al={"cine a furat lada","ogrii din Camp Kosh","cine a luat armele"}},{q="Ce spera Sigrun sa recupereze?",a="Lada cu provizii, lasata in urma in graba de a parasi locul excavarii.",al={"lada cu provizii","ce trebuie recuperat pentru sigrun"}}},fp="7,205,22.364.0,14.192.1,22.123.0,31.114.0,32.81.0,34.71.0"}
P.entries["quest:719"] = {n="A Dwarf and His Tools",s="Prospector Ryedol te avertizeaza ca Dark Iron dwarves, care seamana cu clanul Shadowforge, sunt peste tot. Tocmai au atacat santierul de excavare unde lucra Ryedol, iar acesta vrea inapoi tarnacopul norocos.",h="Prospector Ryedol te avertizeaza ca Dark Iron dwarves, care seamana cu clanul Shadowforge, sunt peste tot.",kw={"badlands","dark iron","excavatie","hammertoe","tarnacop norocos","ryedol","shadowforge"},sec={{t="Jefuitori la sapaturi",b="Dupa spusele lui Prospector Ryedol, Dark Iron din clanul Shadowforge au atacat locul de excavare unde lucra Ryedol. I-au ucis aproape pe toti, inclusiv pe seful lui Ryedol, Hammertoe, iar Ryedol abia a scapat cu viata. Situl se afla la nord de locul unde e Ryedol."},{t="O alegere norocoasa",b="Ryedol incearca sa gaseasca o cale de a recupera o parte din proviziile pierdute, mai ales tarnacopul sau norocos. Unul dintre Dark Iron trebuie sa-l aiba, desi ar putea fi oricare dintre ei. Ryedol spera ca-l vei ajuta si te asteapta la sud de Hammertoe's Dig Site."}},faq={{q="Cine este Prospector Ryedol?",a="Ryedol lucra la un sit de excavare atacat de dwarves Dark Iron. Abia a scapat, iar acum asteapta la sud de Hammertoe's Dig Site.",al={"cine este ryedol","prospector ryedol","cine da a dwarf and his tools"}},{q="Cine a atacat tabara de excavare?",a="Dwarves Dark Iron despre care se credea ca apartineau clanului Shadowforge.",al={"cine a atacat excavarea","cine l-a atacat pe Hammertoe","ce a atacat tabara"}},{q="Ce i s-a intamplat lui Hammertoe?",a="Hammertoe era seful lui Ryedol si s-a numarat printre cei ucisi in atac.",al={"cine este Hammertoe","Hammertoe mai traieste","ce s-a intamplat cu boss Hammertoe"}},{q="Unde se afla tarnacopul norocos?",a="Ryedol crede ca unul dintre Dark Iron il are, desi ar putea fi oricare dintre ei.",al={"unde este tarnacopul norocos al lui ryedol","cum gasesc tarnacopul","cine are tarnacopul lui ryedol"}}},fp="21,189,18.287.0,12.233.0,25.131.0,33.59.0,27.70.0,32.76.0"}
P.entries["quest:72"] = {n="The Legend of Stalvan",s="Aceasta etapa a investigatiei ii trimite pe cercetatori la Canalele din Stormwind City, unde Caretaker Folsom supravegheaza bunurile ramase ale familiei Flintridge, ruinata. In cautarea unor raspunsuri despre misteriosul Stalvan Mistmantle, aventurierii trebuie sa scotoceasca printre bunurile familiei puse in lazi, confruntandu-se totodata cu spiritele nelinistite legate de un masacru din trecut.",h="Aceasta etapa a investigatiei ii trimite pe cercetatori la Canalele din Stormwind City, unde Caretaker Folsom...",kw={"canale","caretaker folsom","duskwood","flintridge","forlorn spirit","legend of stalvan","masacru","ladaie sigilata","stormwind","tilloa"},ang={["class:Priest"]="Confruntarea cu Forlorn Spirit, care plange prin canalele orasului, dezvaluie chinul persistent al sufletelor nevinovate ucise inainte de vreme, care cer odihna de la Light.",["faction:Alliance"]="Tragedia tacuta a familiei Flintridge se desfasoara chiar in capitala regatului, dezvaluind cum pana si cele mai protejate familii nobile din Stormwind pot fi nimicite cu violenta."},sec={{t="Ecourile unui masacru",b="Urmarirea miscarilor lui Stalvan duce din crangurile umbrite din Duskwood pana in inima orasului Stormwind. Langa canalele orasului, Caretaker Folsom are grija de ce a mai ramas din gospodaria Flintridge. Potrivit lui Folsom, tatal sau slujise pe mosie inaintea lui si avusese sarcina macabra de a spala sangele ramas dupa un masacru ingrozitor in casa - o tragedie legata, intr-un fel, de numele Stalvan."},{t="Licitarea unei case ruinate",b="Cu fondurile fiduciare ale familiei Flintridge cu totul epuizate si cu vulturii lacomi ai fiscului regal dand tarcoale, mostenirile si bunurile impachetate ramase ale familiei urmeaza sa fie scoase la licitatie. Amintirile si documentele care au supravietuit varsarii de sange zac gramada in lazile de transport de-a lungul malului canalului. Pentru a descoperi urmele lui Stalvan, trebuie deschise aceste lazi sigilate inainte ca ultimele bunuri lumesti ale domeniului sa fie imprastiate printre colectionarii din regat."},{t="O umbra nelinistita",b="Tulburarea lazilor celor raposati nu trece neobservata. Trauma crimelor inca se agata de aceste bunuri recuperate si se manifesta sub forma unui Forlorn Spirit razbunator, care ii ataca pe toti cei ce scotocesc printre lucrurile familiei. Aceasta aparitie plangatoare, despre care se crede ca este fantoma tinerei Tilloa Flintridge, ramane legata cu indarjire de ramasitele fizice ale vietii ei curmate brusc."}},faq={{q="Unde il pot gasi pe Caretaker Folsom?",a="Caretaker Folsom este stationat de-a lungul Canals din Stormwind City, langa o gramada de lazi de transport aruncate si de bunuri de uz casnic, pe malul canalului.",al={"locatia lui Caretaker Folsom","unde este Folsom","unde se afla Caretaker Folsom in Stormwind"}},{q="Ce s-a intamplat cu familia Flintridge?",a="Familia Flintridge era o gospodarie instarita, destramata de un masacru brusc si nemilos. Dupa cum dezvaluie povestea ingrijitorului, varsarea de sange a fost atat de ampla, incat tatal lui Folsom a trebuit sa curete toata mosia. Nu se stie inca cine a fost vinovat.",al={"masacrul din flintridge","ce a fost masacrul","cine a ucis familia flintridge"}},{q="De ce sunt lucrurile familiei impachetate in lazi de-a lungul canalului?",a="Fondul trustului familiei Flintridge s-a epuizat complet dupa tragedie. Sub presiunea perceptorilor de taxe ai regatului, bunurile ramase ale domeniului au fost puse in lazi si asezate langa canale, pentru a fi vandute la licitatie.",al={"de ce sa licitezi obiectele flintridge","de ce sunt lazile in canale","averea familiei flintridge"}},{q="De ce ataca un spirit cand este deschisa lada?",a="Trauma violenta a masacrului a legat sufletele victimelor de bunurile pe care le avusesera. Se crede ca Forlorn Spirit care se iveste pentru a apara lazile este stafia lui Tilloa Flintridge, unul dintre copiii ucisi.",al={"Forlorn Spirit Stormwind","cine este spiritul indurerat","de ce e o fantoma in canalele din Stormwind"}},{q="Cum se leaga asta inapoi de Duskwood?",a="Ancheta a inceput in Darkshire, ca o investigatie privind disparitia lui Stalvan Mistmantle. Urmarirea trecutului sau a dus inapoi la perioada in care era tutorele familiei Flintridge, in Elwynn si Stormwind.",al={"legatura lui stalvan cu duskwood","de ce suntem in stormwind pentru o misiune din duskwood","legenda lui stalvan legatura cu orasul"}},{q="Ce gasesti in lada sigilata?",a="Scotocirea prin mobilierul indesat si obiectele personale scoate la iveala mosteniri prafuite si, aproape de fund, o pagina rupta din jurnalul lui Stalvan, care devine urmatorul indiciu.",al={"ce se afla in lada","indiciu despre lada sigilata","continutul lazii Flintridge"}}},fx={d6eccd2d={q="De ce te lasa Caretaker Folsom sa cauti prin lazile cu marfa?",a="Caretaker Folsom, personal, nu mai are aproape nimic de care sa se ingrijeasca. Fondurile familiei Flintridge s-au epuizat cu totul, lasand mosia ramasa in ruina si ultimele lor bunuri pregatite pentru casa de licitatii, ca sa fie platiti colectorii de taxe. Desi familia sa a slujit mosia vreme de generatii - tatal sau curatase sangele dupa masacrul ingrozitor -, Folsom nu are niciun motiv sa ascunda adevarul sumbru si pur si simplu iti permite sa cotrobai prin ceea ce a mai ramas.",al={"motivul lui Caretaker Folsom","de ce ajuta Folsom","de ce ma lasa sa caut prin lazi"}}},fp="21,349,20.405.0,29.431.0,16.377.1,34.153.0,39.231.0,66.215.0,50.234.0,39.192.0,41.163.0"}
P.entries["quest:720"] = {n="A Sign of Hope",s="O harta mototolita poarta cateva cuvinte scrise cu creta: o rugaminte adresata lui Ryedol din partea lui Hammertoe, care spune ca il duc pe Hammertoe la Uldaman si cere ajutor. Prospector Ryedol trebuie sa afle ca Hammertoe Grez este in viata.",h="O harta mototolita poarta cateva cuvinte scrise cu creta: o rugaminte adresata lui Ryedol din partea lui...",kw={"A Sign of Hope","Badlands","bilet cu creta","harta mototolita","Hammertoe Grez","Prospector Ryedol","Uldaman"},sec={{t="Cuvinte scrise cu creta",b="Schitat in graba cu creta pe harta mototolita se afla un scurt mesaj semnat de Hammertoe. Este adresat lui Ryedol si spune doar ca il duc pe Hammertoe la Uldaman si ca este nevoie de ajutor. Mesajul care trebuie transmis lui Prospector Ryedol este ca Hammertoe Grez traieste."}},faq={{q="Ce scrie pe harta mototolita?",a="Un bilet scris cu creta, adresat lui Ryedol si semnat Hammertoe. Spune ca il duc pe Hammertoe la Uldaman si cere ajutor.",al={"ce spune biletul","mesajul cu creta de pe harta","textul de pe harta mototolita"}},{q="Cine este Prospector Ryedol?",a="Cel caruia ii este destinat biletul. Trebuie sa-l cauti pe Prospector Ryedol si sa-i spui ca Hammertoe Grez este in viata.",al={"cine este Ryedol","unde sa duci harta mototolita"}},{q="Unde spune mesajul ca este dus Hammertoe Grez?",a="Catre Uldaman.",al={"unde este dus hammertoe","unde este dus grez"}}},fp="14,206,14.259.0,36.122.0,25.108.0,57.11.0"}
P.entries["quest:723"] = {n="Prospect of Faith",s="Hammertoe Grez, ranit, te trimite cu amuleta la Prospector Ryedol din Badlands. Ryedol stie ce cauta Hammertoe si ce nu trebuie lasat clanul Shadowforge sa gaseasca.",h="Hammertoe Grez, ranit, te trimite cu amuleta la Prospector Ryedol din Badlands.",kw={"A Sign of Hope","Badlands","Hammertoe Grez","amuleta lui Hammertoe","origini","Prospector Ryedol","Shadowforge"},sec={{t="O amuleta pentru Ryedol",b="Hammertoe Grez, tinandu-se de rani, se opreste sa-si recapete suflul, apoi iti cere sa-l gasesti pe Ryedol si sa-i dai amuleta. Hammertoe este sigur ca Ryedol va sti ce sa faca. Ryedol stie ca Hammertoe cauta originile poporului lor si ca voia totodata sa zadarniceasca planurile clanului Shadowforge, care nu trebuie lasat sa puna mana pe pergamente."},{t="In mainile lui Ryedol",b="Dupa ce primeste amuleta lui Hammertoe, Ryedol spune ca moralul era mai ridicat cand credeau ca Hammertoe murise, fiindca certitudinea nu face decat sa sporeasca durerea. Ryedol numeste amuleta opera vietii lui Hammertoe si jura ca moartea lui nu va fi in zadar."}},faq={{q="Cine este Prospector Ryedol?",a="Prospector Ryedol este cel caruia trebuie sa-i duci amuleta lui Hammertoe, in Badlands. Ryedol stie ce cauta Hammertoe.",al={"prospector ryedol","cine este ryedol","unde se afla ryedol"}},{q="Ce incearca Hammertoe Grez sa opreasca?",a="Hammertoe voia sa zadarniceasca planurile clanului Shadowforge, care nu trebuie lasat sa puna mana pe pergamente.",al={"scopul lui hammertoe","suluri Shadowforge","de ce sa oprim Shadowforge"}},{q="Ce cauta Hammertoe Grez?",a="Originile poporului lor, potrivit lui Hammertoe.",al={"originea lui hammertoe","ce cauta hammertoe"}},{q="Din ce lant face parte acest pas?",a="Aceasta face parte din lantul inceput cu A Sign of Hope.",al={"Prospect of Faith, lantul de misiuni","lantul A Sign of Hope"}}},fp="17,195,20.348.0,17.246.1,25.126.0,38.100.0,32.52.0,33.57.0"}
P.entries["quest:724"] = {n="Prospect of Faith",s="Prospector Ryedol te trimite la Ironforge cu amuleta lui Hammertoe. Historian Karnik si Hammertoe lucrau impreuna pentru a gasi artefactele pierdute din Uldaman, iar Ryedol banuieste ca Shadowforge au aflat ca cei doi stiau mai mult decat lasau sa se inteleaga.",h="Prospector Ryedol te trimite la Ironforge cu amuleta lui Hammertoe.",kw={"badlands","hammertoe","hammertoes amulet","historian karnik","ironforge","prospect of faith","prospector ryedol","shadowforge","uldaman"},sec={{t="Un mesaj pentru Ironforge",b="Ryedol se gandeste cine ar putea sti ce trebuie facut mai departe si se hotaraste asupra lui Historian Karnik, care se afla in Ironforge. Trebuie sa-i spui lui Karnik ce i s-a intamplat lui Hammertoe si sa-i incredintezi amuleta. De acolo, Karnik iti va spune ce trebuie facut."},{t="Bun venit din partea lui Karnik",b="Karnik te intampina ca pe inca un calator care-i cere timp, iar el nu are de pierdut, pana cand ii arati amuleta. Atunci Karnik ia lucrurile in serios, lasa doliul pentru Hammertoe pe mai tarziu si iti arata cat de valoroasa este amuleta, chemind spiritul lui Hammertoe."}},faq={{q="Cine incepe aceasta misiune?",a="Prospector Ryedol din Badlands te trimite mai departe la Ironforge cu amuleta lui Hammertoe.",al={"cine da prospect of faith","cel care ofera misiunea prospect of faith","unde incepe prospect of faith"}},{q="Unde se afla Historian Karnik?",a="Historian Karnik se afla in Ironforge.",al={"unde se afla karnik","locatia lui Historian Karnik","karnik in Ironforge"}},{q="De ce a fost ales Historian Karnik?",a="Karnik si Hammertoe lucrau impreuna pentru a gasi artefactele pierdute din Uldaman, asa ca Ryedol are incredere ca Karnik va sti ce sa faca.",al={"de ce sa trimiti amuleta la karnik","legatura cu karnik"}},{q="Ce urmeaza dupa aceasta misiune?",a="Partea lui Karnik din poveste continua cu Passing Word of a Threat.",al={"urmatoarea misiune dupa Prospect of Faith","ce urmeaza dupa Prospect of Faith"}}},fp="17,239,23.251.0,16.273.1,22.84.0,34.33.0,32.125.0,28.68.0"}
P.entries["quest:725"] = {n="Passing Word of a Threat",s="Historian Karnik iti da un bilet sigilat pentru Advisor Belgrum. Trebuie sa-i spui lui Belgrum ce ai vazut si sa-l intrebi cum vrea sa procedeze, in timp ce Karnik se intoarce catre spiritul lui Hammertoe, in legatura cu Shadowforge din Badlands.",h="Historian Karnik iti da un bilet sigilat pentru Advisor Belgrum.",kw={"advisor belgrum","badlands","hammertoe","historian karnik","ironforge","passing word of a threat","shadowforge"},sec={{t="Un mesaj pentru Advisor Belgrum",b="Karnik vrea sa-l gasesti repede pe Advisor Belgrum, sa-i spui ce ai vazut si sa-l intrebi cum vrea Belgrum sa procedeze. Nota ofera mai multe detalii. Intre timp, Karnik va vorbi cu spiritul lui Hammertoe, in speranta ca Hammertoe stie ceva ce ar putea pune capat faptelor celor din Shadowforge in Badlands, si nu-i ramane decat sa se roage ca asa sa fie."}},faq={{q="Cine te trimite la Advisor Belgrum?",a="Historian Karnik iti da un bilet sigilat si iti cere sa-l gasesti pe Advisor Belgrum cat mai repede.",al={"cine incepe Passing Word of a Threat","cine da Passing Word of a Threat","misiunea Karnik"}},{q="Ce vrea Karnik de la Advisor Belgrum?",a="Karnik vrea sa-i spui lui Belgrum ce ai vazut si sa-l intrebi cum vrea sa procedeze. Biletul explica mai multe.",al={"de ce sa-l vizitezi pe belgrum","scopul biletului pentru belgrum","de ce sa trimiti biletul"}},{q="Ce face Historian Karnik in timp ce duci biletul?",a="Karnik isi face timp sa vorbeasca cu spiritul lui Hammertoe, sperand sa afle ceva care sa ajute la oprirea celor din Shadowforge, in Badlands.",al={"ce face karnik","planul lui karnik","historian karnik badlands"}},{q="Ce misiune preceda Passing Word of a Threat?",a="Urmeaza dupa Prospect of Faith, etapa in care duci amuleta lui Hammertoe la Karnik, in Ironforge.",al={"cerinte pentru Passing Word","misiunea dinainte de Passing Word of a Threat","misiunea anterioara"}}},fp="24,227,24.321.0,33.97.0,43.113.0,58.130.0,49.100.0"}
P.entries["quest:726"] = {n="Passing Word of a Threat",s="Advisor Belgrum a citit biletul lui Historian Karnik si te trimite inapoi la Karnik cu un mesaj rostit in numele regelui: actioneaza repede si hotarat pe baza informatiilor cunoscute si pune capat actiunilor lui Shadowforge in Badlands.",h="Advisor Belgrum a citit biletul lui Historian Karnik si te trimite inapoi la Karnik cu un mesaj rostit in...",kw={"angor fortress","badlands","belgrum","karnik","shadowforge","uldaman"},sec={{t="Raspunsul lui Belgrum",b="Belgrum citeste biletul pana la capat, cu ochii tot mai mari, si spune ca vestea este ingrozitoare. Trebuie sa te intorci la Karnik si sa-i transmiti, din partea regelui, ca informatia trebuie urmata rapid si hotarat de actiune. Activitatile celor din Shadowforge in Badlands trebuie sa inceteze."},{t="Replica lui Karnik",b="Karnik ia situatia urgenta foarte in serios si are deja un plan: Shadowforge din Uldaman poate fi incetinit printr-o lovitura data asupra Angor Fortress, de unde isi conduc operatiunile."}},faq={{q="Cine te trimite inapoi la Karnik?",a="Advisor Belgrum, dupa ce a citit biletul lui Karnik. Porti un mesaj dat in numele regelui, prin care ti se cere sa actionezi rapid si hotarat.",al={"cine da ordinul","ordinele lui belgrum","autoritatea regala din badlands"}},{q="Ce vrea Belgrum sa se faca in privinta lui Shadowforge?",a="Belgrum vrea ca Karnik sa actioneze rapid si hotarat si sa puna capat lucrurilor pe care le fac Shadowforge in Badlands.",al={"ce vrea Belgrum","comanda Shadowforge din Badlands"}},{q="Ce a fost inainte de asta?",a="I-ai dus biletul sigilat al lui Karnik lui Advisor Belgrum in cadrul misiunii anterioare Passing Word of a Threat, care a urmat pasilor din Prospect of Faith.",al={"pasul anterior","misiunea dinainte de passing word of a threat","pista care duce la badlands"}}},fp="24,221,16.268.0,14.177.1,29.120.0,50.116.0,22.136.0"}
P.entries["quest:727"] = {n="To Ironforge for Yagyin's Digest",s="Theldurin the Lost te trimite la Ironforge cu un sigiliu. Intr-un magazin din Forlorn Cavern, Gerrig Bonegrip trebuie sa te ia drept unul dintre oamenii de care a fugit Theldurin, iar tu trebuie sa-i ceri lui Gerrig Yagyin's Digest.",h="Theldurin the Lost te trimite la Ironforge cu un sigiliu.",kw={"badlands","forlorn cavern","gerrig bonegrip","ironforge","sigil of the hammer","theldurin the lost","yagyin's digest"},sec={{t="O carte scrisa demult",b="Tableta ii dezvaluie multe lui Theldurin, dar nici pe departe destule. Cu veacuri in urma, Yagyin a scris un rezumat, iar oamenii de care a fugit Theldurin pastreaza copii in multe locuri, unde cei mai invatati le studiaza. Theldurin crede ca acesta contine vaste cunostinte care pot oferi protectie si vrea sa i-l aduci inapoi."},{t="Pravalia din Forlorn Cavern",b="Gerrig Bonegrip are un magazin in Forlorn Cavern din Ironforge. Theldurin iti da Sigil of the Hammer ca sa i-l arati lui Gerrig si sa te ia drept unul dintre oamenii lui; trebuie sa-i ceri Yagyin's Digest."},{t="Salutul lui Gerrig",b="Gerrig te avertizeaza sa fii atent la ce atingi in magazin, fiindca stiinta poate fi fatala. Cand ii arati sigiliul, Gerrig te saluta ca pe un frate sau o sora si le aduce laude celor care salasluiesc dedesubt."}},faq={{q="De ce vrea Theldurin Yagyin's Digest?",a="Tableta ii dezvaluie multe lui Theldurin, dar nu indeajuns. Compendiul, scris de Yagyin in vremuri de demult, cuprinde vaste cunostinte care pot oferi protectie, iar Theldurin vrea sa i-l aduci inapoi.",al={"de ce este nevoie de yagyins digest","ce este yagyins digest","scopul lui yagyin digest"}},{q="Unde se afla Gerrig Bonegrip?",a="Gerrig Bonegrip se gaseste intr-un magazin din Forlorn Cavern din Ironforge.",al={"unde este gerrig bonegrip","locatia lui gerrig bonegrip","cine este gerrig"}},{q="La ce foloseste Sigil of the Hammer?",a="Theldurin ti-o da ca sa i-o arati lui Gerrig Bonegrip, astfel incat Gerrig sa creada ca faci parte dintre oamenii de care Theldurin a fugit.",al={"ce face sigil","la ce foloseste sigil of the hammer","de ce sa folosesti sigil"}},{q="Unde se incadreaza acest pas in lant?",a="Aceasta vine dupa Solution to Doom, impreuna cu Theldurin the Lost, si continua in urmatorul pas al lantului.",al={"ce urmeaza inainte de to ironforge for yagyins digest","ordinea lantului yagyin"}}},fp="32,204,23.283.0,30.207.0,17.189.1,40.176.0,25.65.0,41.114.0,33.103.0"}
P.entries["quest:728"] = {n="To the Undercity for Yagyin's Digest",s="Theldurin the Lost te trimite in Undercity of Lordaeron cu un sigiliu. Keeper Bel'dugur trebuie sa te ia drept unul dintre oamenii de care a fugit Theldurin, iar tu trebuie sa-i ceri pastratorului Yagyin's Digest.",h="Theldurin the Lost te trimite in Undercity of Lordaeron cu un sigiliu.",kw={"badlands","Bel'Dugur","digestie","ciocan","sigiliu","Theldurin","Undercity","Yagyin"},sec={{t="O carte scrisa demult",b="Tavita ii dezvaluie multe lui Theldurin, dar nici pe departe destule. Yagyin a scris un rezumat cu veacuri in urma, iar oamenii de care Theldurin a fugit pastreaza copii in multe locuri, unde cei mai invatati le studiaza. Theldurin crede ca ascunde cunostinte vaste, care ii pot proteja, si vrea sa fie adus inapoi."},{t="Paznicul din Undercity",b="Keeper Bel'dugur se afla in Undercity of Lordaeron. Theldurin iti da Sigil of the Hammer ca sa i-l arati pazitorului, astfel incat sa creada ca esti de-al lor, iar tu trebuie sa ceri digestul."},{t="Un cuvant de precautie",b="Bel'dugur te intampina ca pe un cautator nerabdator sa descopere colectia si te avertizeaza ca intelepciunea le da putere celor puternici, dar ii innebuneste pe cei slabi. Dupa ce vede sigiliul, Bel'dugur te indeamna sa pastrezi discretia in privinta unor asemenea semne. Unii nu cred in dreptatea juramantului, iar altii ar vrea sa-l vada incalcandu-se daca ar afla de el. Cei care impartasesc juramantul trebuie sa fie mereu prudenti, vigilenti si rabdatori."}},faq={{q="Cine te trimite la Undercity?",a="Theldurin the Lost te trimite, cu Sigil of the Hammer, sa-l gasesti pe Keeper Bel'dugur.",al={"cine incepe aceasta misiune","cine da To the Undercity for Yagyin's Digest","cel care da misiunea"}},{q="La ce foloseste Sigil of the Hammer?",a="Theldurin ti-l da ca sa i-l arati lui Keeper Bel'dugur, astfel incat acesta sa creada ca esti unul dintre oamenii de care a fugit Theldurin.",al={"la ce foloseste sigil of the hammer","de ce am nevoie de sigil","ce face sigilul"}},{q="Ce este Yagyin's Digest?",a="Este o carte scrisa de Yagyin in vremuri stravechi. Theldurin spune ca adaposteste cunostinte vaste si este studiata de cei mai invatati dintre oamenii de care Theldurin a fugit.",al={"ce este digestia lui yagyin","cine este yagyin","cartea lui yagyin"}},{q="Unde se afla Keeper Bel'dugur?",a="Keeper Bel'dugur ramane in Undercity of Lordaeron, unde il gasesti pe Keeper.",al={"locatia lui Keeper Bel'dugur","unde gasesc Keeper Bel'dugur","Bel'dugur in Undercity"}},{q="Ce a fost inainte de asta?",a="Urmeaza dupa Solutia catre pieire.",al={"misiunea anterioara","ce vine inainte de asta","solutia pentru doom connection"}}},fp="36,193,23.279.0,27.192.0,17.394.1,31.85.0,36.119.0,24.143.0,26.80.0,22.28.0"}
P.entries["quest:729"] = {n="The Absent Minded Prospector"}
P.entries["quest:730"] = {n="Trouble in Darkshore?"}
P.entries["quest:731"] = {n="The Absent Minded Prospector"}
P.entries["quest:732"] = {n="Tremors of the Earth",s="Garek a aflat de la Sigrun cat de mult ai ajutat si iti cere, la randul sau, ajutorul. Stapanul lui Garek, Krasus of the Kirin Tor, l-a trimis sa opreasca ceea ce se pune la cale in Lethlor Ravine, iar mai intai trebuie gasit un Sign of the Earth furat.",h="Garek a aflat de la Sigrun cat de mult ai ajutat si iti cere, la randul sau, ajutorul.",kw={"angor fortress","camp boff","dark iron","deathwing","garek","kirin tor","krasus","lethlor ravine","semnul pamantului"},sec={{t="Un secret bine pastrat",b="Garek a fost trimis in Badlands de Krasus of the Kirin Tor, maestrul sau, ca sa opreasca necazurile care se pregatesc in Lethlor Ravine. Nu poate dezvalui misiunea exacta, ci doar ca este de mare insemnatate. O ceata de ogres ratacitori, vazuta din cand in cand prin preajma Camp Boff, a furat Sign of the Earth, iar Garek are nevoie de el. Adu-l inapoi si vei afla mai multe."},{t="Ogrele ratacitoare",b="Ogrele se muta dintr-o tabara in alta prin Badlands, iar caldura in crestere si vanturile involburate le fac urma greu de urmarit. Garek a auzit ca trec uneori prin Camp Boff, un loc bun de cercetat daca le pierzi urma."},{t="Garek explica",b="Cand te intorci cu Sign, Garek iti spune ca Dwarves Dark Iron din Angor Fortress l-au creat pentru a-i lega pe locotenentii gemeni ai lui Deathwing, nemilosii Blacklash si Hematus."}},faq={{q="Pentru cine lucreaza Garek?",a="Stapanul lui Garek este Krasus of the Kirin Tor, care l-a trimis pe Garek in Badlands ca sa opreasca necazurile care se pregatesc in Lethlor Ravine.",al={"cine l-a trimis pe garek","stapanul lui garek","krasus badlands"}},{q="Ce este Semnul Pamantului?",a="Ogres ratacitori au furat-o, iar Garek are nevoie sa o recupereze. Garek iti va da mai multe detalii dupa ce i-o aduci.",al={"semnul pamantului","ce este semnul pamantului","povestea semnului pamantului"}},{q="Unde pot fi gasiti ogrii ratacitori?",a="Cutreiera tinuturile dintre taberele lor din Badlands, iar Garek a auzit ca uneori trec prin Camp Boff.",al={"unde sunt ogrii","tabara de ogri Boff","unde se afla semnul pamantului"}},{q="De ce pastreaza Garek misiunea secreta?",a="Garek nu spune care este misiunea sau ce presupune aceasta, ci doar ca este de o importanta vitala.",al={"de ce secret","misiunea secreta a lui Garek"}}},fp="20,236,19.356.0,19.224.0,14.178.1,25.120.0,30.88.0,39.109.0,42.103.0"}
P.entries["quest:7321"] = {n="Soothing Turtle Bisque",s="Soothing Turtle Bisque este o sarcina culinara oferita de Christoph Jeffcoat in Tarren Mill. Bucatarul Forsaken vrea sa infirme ideea ca strigoii nu au talent culinar, pregatind o supa consistenta din carne locala de snapjaw. Jucatorii trebuie sa vaneze testoase de apa dulce prin canalele din Hillsbrad Foothills si pe malurile lacului Lordamere Lake pentru a-i stapani reteta de pret.",h="Soothing Turtle Bisque este o sarcina culinara oferita de Christoph Jeffcoat in Tarren Mill.",kw={"christoph jeffcoat","gatit","hillsbrad foothills","lordamere lake","snapjaw","soothing turtle bisque","tarren mill","carne de testoasa"},ang={["faction:Horde"]="Sprijinirea garnizoanei din Tarren Mill inseamna mai mult decat apararea granitelor; mentinerea proviziilor si a moralului la cote ridicate ajuta la consolidarea pozitiei Horde in Hillsbrad, un tinut disputat.",["profession:Cooking"]="Aceasta sarcina le permite bucatarilor sa invete sa prepare Soothing Turtle Bisque, transformand reptilele agresive din Lordamere Lake si raurile din Hillsbrad intr-o masa hranitoare.",["race:Undead"]="Christoph Jeffcoat intruchipeaza latura mai senina si mai mestesugareasca a celor din Forsaken, sustinand ca moartea nu i-a tocit pasiunea culinara."},sec={{t="Gastronomia Forsaken",b="Se presupune indeobste ca Forsaken au renuntat cu totul la placerile vietii, inclusiv la arta gastronomiei fine. Christoph Jeffcoat, aflat la Tarren Mill, respinge cu tarie aceasta presupunere. Laudandu-se ca supa sa bogata si catifelata de broasca testoasa este destul de buna incat sa ademeneasca sufletele inapoi de dincolo de mormant, Jeffcoat vrea sa dovedeasca faptul ca si mainile celor strigoi pot crea lucruri delicate si reconfortante, chiar si intr-un tinut patat de molima si razboi."},{t="Vanatoarea de Snapjaws",b="In mod obisnuit, Jeffcoat isi procura singur ingredientele din cursurile de apa din Hillsbrad Foothills si de pe tarmurile estice ale Lordamere Lake, in Alterac, aflat in vecinatate. Insa indatoririle din Tarren Mill si prezenta tot mai apasatoare a fortelor Alliance l-au tinut pe loc. Se bazeaza pe bucatarii din Horde aflati in trecere, care sa vaneze snapjaws, sa le recolteze carnea si sa o aduca inapoi, pentru ca traditia culinara sa dainuie."}},faq={{q="De ce ii pasa unui bucatar Forsaken sa faca supa crema fierbinte?",a="Desi Forsaken nu au nevoie de hrana in acelasi fel ca muritorii vii, indivizi precum Christoph Jeffcoat sunt foarte mandri de meseria lor. Jeffcoat vrea sa infirme prejudecata ca strigoii nu au pricepere rafinata, glumind ca supa lui speciala este atat de buna, incat ii poate readuce pe cei morti la viata.",al={"gatit pentru strigoi","de ce sa faci bisque","strigoii mananca"}},{q="Unde se gaseste carne de testoasa pentru aceasta reteta?",a="Carnea de testoasa este recoltata de la testoasele agresive Snapjaw care traiesc de-a lungul raurilor ce strabat Hillsbrad Foothills si Alterac, precum si pe tarmurile lacului Lordamere Lake.",al={"unde sunt testoasele","locatiile testoaselor","locatiile testoaselor snapjaw"}},{q="De ce nu-si poate aduna Christoph Jeffcoat singur ingredientele?",a="Jeffcoat sustine ca responsabilitatile il tin ocupat in Tarren Mill. Isi exprima, de asemenea, iritarea fata de fortele Alliance care se apropie prin apropiere si care fac iesirile personale la vanatoare mult mai periculoase.",al={"de ce nu pleaca Christoph","Jeffcoat e blocat in oras"}},{q="Este necesara cunoasterea gatitului pentru a accepta aceasta misiune?",a="Da. Christoph Jeffcoat isi impartaseste mestesugul si reteta doar cu alti practicanti ai bucatariei, desi nu este nevoie de vreo maiestrie avansata pentru a incepe.",al={"am nevoie de cooking","cerinta pentru profesia cooking"}},{q="Ce importanta are Tarren Mill pentru Horde in Hillsbrad?",a="Tarren Mill este principala fortareata Horde din Hillsbrad Foothills. Odinioara un sat al oamenilor, acum functioneaza ca baza fortificata pentru Forsaken si aliatii lor, confruntandu-se frecvent cu Southshore si cu prezenta Alliance in regiune.",al={"ce este Tarren Mill","povestea din Tarren Mill"}},{q="Este bisque-ul de testoasa specific Horde?",a="Bucatarii din Alliance pot obtine reteta de la bucatarii Human locali din Southshore, care folosesc si ei testoasele din zona, insa misiunea personala si perspectiva lui Christoph Jeffcoat le sunt rezervate membrilor Horde.",al={"varianta Alliance","poate Alliance sa obtina supa de testoasa"}}},fx={["7509a6d7"]={q="La ce foloseste carnea de testoasa?",a="Christoph Jeffcoat are nevoie de carnea de testoasa pentru a-si prepara supa de testoasa calmanta, specialitatea casei. Desi strigoii poate ca nu simt frigul sau foamea precum cei vii, Jeffcoat este foarte mandru de arta sa culinara. Sustine ca reteta sa secreta este atat de buna, incat oamenii s-ar intoarce din morti doar ca sa guste un bol fierbinte.",al={"la ce foloseste carnea de testoasa","de ce carne de testoasa","pentru ce se foloseste carnea de testoasa"}},["5469f6c5"]={q="Ce sunt snapjaw-ii pe care ii vanezi pentru aceasta supa?",a="Snapjaw sunt testoase de apa dulce feroce, cu carapace tare, originare din cursurile de apa din Lordaeron, deosebit de raspandite pe tarmurile Lake Lordamere si de-a lungul malurilor raurilor din regiune. Desi salbatice si periculoase pentru calatorii neatenti, carnea lor tare ofera carnea bogata si hranitoare de care are nevoie Christoph pentru bisque-ul sau.",al={"snapjaws din Hillsbrad","snapjaws din Lake Lordamere","pe cine trebuie sa vanez"}}},fp="22,366,19.433.0,20.388.0,54.306.0,47.175.0,56.200.0,49.170.0,59.255.0,37.208.0"}
P.entries["quest:733"] = {n="Scrounging",s="Sigrun Ironhew are nevoie de materiale pentru a construi aparari si alte lucruri necesare taberei si a observat ca ogres din apropiere poarta mult fier vechi. Sigrun vrea sapte bucati.",h="Sigrun Ironhew are nevoie de materiale pentru a construi aparari si alte lucruri necesare taberei si a...",kw={"badlands","dustbelch grotto","explorers' league","ironforge","ogres","fier vechi","cautare de resturi","sigrun ironhew"},sec={{t="O tabara cu lipsuri de provizii",b="Sigrun se descurca greu fara materiale pentru aparare si alte lucruri necesare, iar Prospector-ul si-a facut griji pentru starea micii tabere. Sigrun vrea sa se apuce curand de treaba si are nevoie de fier vechi."},{t="Fier vechi de la ogre",b="Ogrele din zona par sa aiba multe deseuri metalice, ceea ce o face pe Sigrun sa creada ca zvonurile despre masinile de asediu din Badlands ar putea fi adevarate. Tabara lor principala este Dustbelch Grotto, la mare distanta spre vest de tabara lui Sigrun."}},faq={{q="Cine cere fier vechi?",a="Sigrun Ironhew, care vrea sa foloseasca obiectul pentru a construi aparari si alte lucruri necesare pentru tabara.",al={"cel care ofera misiunea","cine ofera Scrounging","sigrun"}},{q="De ce are tabara nevoie de fier vechi?",a="Sigrun nu are materialele necesare pentru a construi aparari si alte lucruri esentiale, iar Prospectorul este ingrijorat de starea taberei.",al={"de ce este nevoie de fier vechi","scopul fierului vechi","aparari"}},{q="Unde poate fi gasit fierul vechi?",a="Ogrele din zona o poarta. Tabara lor principala este Dustbelch Grotto, la o lunga calatorie spre vest de tabara lui Sigrun.",al={"locatia fierului vechi","unde gasesc fier vechi","tabara capcaunilor"}},{q="Ce urmeaza inaintea acestui lucru?",a="Urmeaza dupa Mirages.",al={"misiune precedenta","conditia prealabila pentru Scrounging"}}},fp="10,179,25.219.0,16.227.0,34.82.0,35.133.0,35.103.0,23.19.0"}
P.entries["quest:734"] = {n="This Is Going to Be Hard",s="Lotwil Veriatus, ocupat cu un set de catuse, te trimite sa vorbesti cu Lucien Tosselwrench in Badlands. Lotwil are nevoie de o roata dintata #5 si vrea sa i-o aduci inapoi.",h="Lotwil Veriatus, ocupat cu un set de catuse, te trimite sa vorbesti cu Lucien Tosselwrench in Badlands.",kw={"badlands","cog #5","lotwil veriatus","lucien tosselwrench","catuse"},sec={{t="Angrenajul numarul cinci",b="Lotwil ridica privirea spre tine pentru o clipa, apoi se apleaca din nou asupra catuselor. Trebuie sa mergi sa vorbesti cu Lucien Tosselwrench, fiindca Lotwil are nevoie de o roata dintata #5 si te roaga sa i-o aduci."},{t="Verdictul lui Lucien",b="La auzul mentiunii despre pinionul #5, Lucien Tosselwrench nu pare sa spere ca lucrurile vor merge bine."}},faq={{q="Cine ofera aceasta misiune?",a="Lotwil Veriatus, care lucreaza la un set de catuse in Badlands.",al={"cine incepe aceasta misiune","misiunea lui Lotwil Veriatus","cel care da misiunea"}},{q="De ce are nevoie Lotwil?",a="O roata dintata #5, pe care Lotwil iti cere sa o aduci inapoi dupa ce vorbesti cu Lucien Tosselwrench.",al={"ce vrea Lotwil","care roata dintata","roata dintata 5"}},{q="Cu cine trebuie sa vorbesc despre roata dintata?",a="Lotwil te trimite la Lucien Tosselwrench, in Badlands.",al={"unde gasesc cog 5","cine este Lucien","Lucien Tosselwrench"}}},fp="24,155,15.173.0,16.86.1,21.69.0,22.86.0,32.56.0"}
P.entries["quest:735"] = {n="The Star, the Hand and the Heart",s="Gerrig Bonegrip din Ironforge are un exemplar de rezerva din Digestul lui Yagyin si ti-l va ceda in schimbul a trei obiecte de putere. Gerrig nu le va rosti numele cu voce tare, ci le noteaza pe un bilet.",h="Gerrig Bonegrip din Ironforge are un exemplar de rezerva din Digestul lui Yagyin si ti-l va ceda in schimbul...",kw={"nota lui bonegrip","gerrig bonegrip","mana lui dagun","ironforge","inima mostenirii","steaua lui xil'yeh","rezumatul lui yagyin"},sec={{t="Un schimb in soapta",b="Gerrig te aude cerand Yagyin's Digest si se intreaba daca incepi un nou capitol al ordinului lor undeva, apoi decide ca nu e treaba lui Gerrig sa intrebe. Gerrig are un exemplar in plus si crede ca cei din ordin trebuie sa se ajute unii pe altii. In schimb, trebuie aduse trei obiecte de putere. Numele lor raman nespuse, fiindca s-ar putea sa asculte cineva, iar Gerrig le noteaza."},{t="Cele trei obiecte",b="Biletul mentioneaza Star of Xil'yeh, Hand of Dagun si Legacy Heart. Acestea sunt obiectele pe care le vrea Gerrig inainte sa-ti dea digestul."},{t="Verdictul lui Gerrig",b="Dupa ce are relicvele in mana, Gerrig te numeste descurcaret si crede ca, daca ti-a fost intr-adevar incredintata sarcina de a intemeia un nou capitol al ordinului, il vei conduce bine."}},faq={{q="Cine cere cele trei obiecte?",a="Gerrig Bonegrip din Ironforge, care are un exemplar in plus din Yagyin's Digest pe care ti-l poate da in schimb.",al={"cel care ofera misiunea","cine incepe The Star, the Hand and the Heart","misiunea lui Gerrig Bonegrip"}},{q="Ce trei obiecte vrea Gerrig Bonegrip?",a="Biletul lui Gerrig Bonegrip cere trei lucruri: Steaua lui Xil'yeh, Mana lui Dagun si Inima Mostenirii.",al={"obiecte necesare","de ce relicve are nevoie","obiectele notate de bonegrips"}},{q="De ce noteaza Gerrig obiectele in loc sa le spuna?",a="Gerrig nu le va rosti numele, pentru ca cineva s-ar putea sa asculte.",al={"de ce sa le notezi","de ce biletul secret","soaptele lui bonegrip"}},{q="Ce a precedat aceasta in lantul de misiuni?",a="Urmeaza dupa To Ironforge for Yagyin's Digest, unde Theldurin the Lost te-a trimis la Gerrig.",al={"misiune prealabila","misiune anterioara"}}},fp="32,193,30.378.0,15.134.0,16.163.1,29.89.0,43.106.0,60.67.0,35.89.0"}
P.entries["quest:736"] = {n="The Star, the Hand and the Heart",s="Star, the Hand and the Heart este o misiune din Undercity, in care Keeper Bel'dugur pune la incercare un aspirant la conducere care vrea sa infiinteze o noua filiala a ordinului sau. Pentru a obtine indispensabilul Yagyin's Digest, candidatul trebuie sa gaseasca trei obiecte de putere ale caror nume Bel'dugur nu indrazneste sa le rosteasca cu voce tare.",h="Star, the Hand and the Heart este o misiune din Undercity, in care Keeper Bel'dugur pune la incercare un...",kw={"bel'dugur's note","keeper bel'dugur","ordin","steaua, mana si inima","trei obiecte de putere","undercity","yagyin's digest"},ang={["class:Warlock"]="Obtinerea lucrarii Yagyin's Digest pentru a intemeia un nou coven reprezinta un pas decisiv in extinderea influentei si a maiestriei oculte a ordinului tau intunecat.",["race:Undead"]="Activand din Undercity, Keeper Bel'dugur ii indruma pe practicantii Forsaken care cauta sa aprofundeze ritualurile interzise, sub turlele umbrite ale orasului."},sec={{t="O incercare a fraternitatii",b="In coridoarele intunecate ale Undercity, practicantii ambitiosi care vor sa-si conduca propriul cerc apeleaza la Keeper Bel'dugur. Pentru a intemeia un nou grup si a deschide un capitol al ordinului lor, un conducator aspirant are nevoie de Yagyin's Digest, un text de referinta despre traditiile ritualice, pazit de keeper. Bel'dugur este gata sa-si sprijine fratele, dar cere dovezi de vrednicie inainte de a-i incredinta o asemenea autoritate."},{t="Relicvele nedezvaluite",b="Keeper Bel'dugur nu va ceda usor Yagyin's Digest. Ca sa-si respecte partea din schimb, cere trei obiecte de putere diferite. Aceste relicve au o insemnatate atat de primejdioasa sau sacra, incat numele lor nu pot fi rostite nici macar cu voce tare; in schimb, Bel'dugur le noteaza pe un bilet privat. Doar un practicant capabil sa gaseasca si sa recupereze toate cele trei artefacte nenumite merita sa-si intemeieze propriul cerc."}},faq={{q="Cine este Keeper Bel'dugur?",a="Keeper Bel'dugur este o figura oculta care locuieste in Undercity si ii ajuta pe membrii fratiei sale intunecate. El pazeste cunostinte puternice si le cere candidatilor sa-si dovedeasca priceperea inainte de a le incredinta texte sacre.",al={"cine este Keeper Bel'dugur","rolul lui Bel'dugur","Bel'dugur din Undercity"}},{q="Ce este Yagyin's Digest?",a="Yagyin's Digest este un text de indrumare specializat, necesar pentru a intemeia si conduce un nou capitol sau pentru a strange un nou grup intr-un ordin ocult secret.",al={"ce este digestul lui Yagyin","scopul digestului lui Yagyin","cartea Digestul lui Yagyin"}},{q="Ce obiecte cere Keeper Bel'dugur?",a="Bel'dugur are nevoie de trei obiecte de putere anume. Pentru ca numele lor sunt prea interzise sau periculoase ca sa fie rostite cu voce tare, le noteaza in liniste intr-un mesaj scris, pentru ca solicitantul sa le recupereze.",al={"de ce obiecte are nevoie Bel'dugur","obiectele din biletul lui Bel'dugur","trei obiecte de putere"}},{q="De ce nu sunt rostite cu voce tare numele obiectelor cerute?",a="Keeper Bel'dugur precizeaza ca nu poate rosti cu voce tare numele acestor trei relicve, semn ca ele au o putere intunecata, sacra sau instabila, ce impune discretie.",al={"de ce nu poate bel'dugur sa rosteasca numele obiectelor","incapabil sa rosteasca numele","numele nespuse ale obiectelor"}},{q="Ce inseamna sa aduni inca un stol?",a="Adunarea unei turme inseamna recrutarea adeptilor si intemeierea unei filiale independente si functionale a fratiei lor, dovedind ca esti pregatit sa-i indrumi pe alti practicanti ai mestesugului.",al={"ce inseamna adunarea unui stol","deschiderea unui capitol","capitolul ordinului nostru"}},{q="Unde se desfasoara aceasta misiune?",a="Misiunea se invarte in jurul lui Keeper Bel'dugur, stationat in capitala subterana a Forsaken, Undercity.",al={"unde se desfasoara aceasta misiune","locatia lui bel'dugur","locatia predarii misiunii"}}},fp="32,291,21.413.0,19.424.0,24.221.0,24.160.0,41.190.0,58.174.0,42.188.0,29.118.0"}
P.entries["quest:737"] = {n="Forbidden Knowledge",s="Yagyin's Digest este predat cu avertismentul ca trebuie ferit de maini dusmanoase. Trebuie dus la Theldurin the Lost.",h="Yagyin's Digest este predat cu avertismentul ca trebuie ferit de maini dusmanoase.",kw={"badlands","cunoastere interzisa","the star the hand and the heart","theldurin the lost","yagyin's digest"},sec={{t="O carte care arde",b="Gerrig Bonegrip din Ironforge sau Keeper Bel'dugur din Undercity iti da compendiul. Ti se spune sa-l pazesti bine si sa nu-l lasi pe maini dusmanoase, fiindca poarta multe adevaruri, iar adevarul are obiceiul sa arda. Du-l la Theldurin the Lost."},{t="Speranta lui Theldurin",b="Theldurin striga ca se intrevede speranta si spune ca eforturile tale i-ar putea salva pe toti, aducandu-ti un monument, un altar si laude rostite de generatii intregi. Toate acestea vor fi posibile doar daca EI nu sunt eliberati sa se ridice la suprafata; altfel, spune Theldurin, toti vor ajunge hrana viermilor."}},faq={{q="Ce obiect trebuie livrat?",a="Yagyin's Digest, o carte care cuprinde multe adevaruri. Trebuie pazita cu strasnicie si tinuta departe de maini dusmanoase.",al={"ce carte este aceasta","ce este Yagyin's Digest","ce trebuie sa aduc"}},{q="Cine primeste rezumatul?",a="Rezumatul este destinat lui Theldurin the Lost.",al={"cine primeste cartea","cui trebuie sa predau asta","unde trebuie dus rezumatul"}},{q="Ce a fost inainte de asta?",a="Urmeaza dupa etapa in care au fost aduse trei obiecte in schimbul digestului.",al={"misiunea anterioara","ce duce la aceasta","ce misiune preceda Forbidden Knowledge"}}},fp="19,131,17.255.0,16.285.1,32.106.0,24.43.0,22.81.0"}
P.entries["quest:738"] = {n="Find Agmond",s="Prospector Ironband nu a mai primit vesti de la Prospector Agmond de cateva saptamani. Agmond raspundea de siturile de excavare din Badlands, iar Ironband vrea sa-l gasesti ca sa poata strange raportul.",h="Prospector Ironband nu a mai primit vesti de la Prospector Agmond de cateva saptamani.",kw={"agmond","angor fortress","badlands","ironforge","prospector ironband"},sec={{t="Un prospector tacut",b="Agmond conducea sapaturile din Badlands, spre sud-vest. Ironband spune \"conducea\" intentionat, fiindca nu s-a mai auzit nimic de la Agmond de saptamani intregi. Ironband vrea sa fie gasit Agmond, impreuna cu raportul. Ultima veste despre Agmond il plasa la sapatura cea mai sudica din Badlands, o mica echipa aflata dincolo de Angor Fortress, iar de acolo ar trebui sa inceapa cautarile."},{t="Unde se termina pista",b="La capatul cautarii gasesti un schelet, care trebuie sa fie ramasitele lui Agmond. Trupul este rupt si zdrobit, iar oasele au fost curatate de carne."}},faq={{q="Cine este Prospector Agmond?",a="Agmond conducea sapaturile din Badlands, la sud-vest de Prospector Ironband.",al={"cine este agmond","povestea lui agmond"}},{q="De ce il cauta Prospector Ironband pe Agmond?",a="Ironband nu a mai primit vesti de la Agmond de cateva saptamani si vrea sa obtina raportul lui Agmond.",al={"de ce sa-l gasesti pe agmond","ironband il cauta pe agmond"}},{q="Unde se stia ultima data ca se afla Prospector Agmond?",a="La sapatura cea mai sudica din Badlands, un mic grup aflat dincolo de Angor Fortress.",al={"locatia lui agmond","unde este situl sapaturilor lui agmond","unde a fost agmond"}},{q="Ce urmeaza inainte de aceasta parte a lantului?",a="Urmeaza dupa Ironband Wants You!",al={"misiune anterioara","cerinta preliminara pentru find agmond"}}},fp="11,192,19.345.0,20.154.1,25.77.0,46.77.0,45.80.0,36.30.0"}
P.entries["quest:739"] = {n="Murdaloc",s="Ramasitele zdrobite ale lui Agmond se afla in Badlands, iar langa mana sa moarta este mazgalit un nume in gresie: Murdaloc. Ucigasul lui Agmond trebuie omorat, iar vestea trebuie dusa inapoi la Prospector Ironband in Loch Modan.",h="Ramasitele zdrobite ale lui Agmond se afla in Badlands, iar langa mana sa moarta este mazgalit un nume in...",kw={"agmond","badlands","loch modan","murdaloc","prospector ironband","stonevault bonesnapper","trogg"},sec={{t="Un nume in gresie",b="Urma lui Agmond vine dinspre vest, iar sangele manjit pe piatra si nisip arata cat de departe s-a tarat dwarf-ul inainte sa moara aici. Langa mana fara viata, zgariat in gresia din Badlands, se afla un singur cuvant: Murdaloc. Ucigasul lui Agmond trebuie omorat, impreuna cu mai multi Stonevault Bonesnappers, iar vestea trebuie dusa la Prospector Ironband, in Loch Modan."},{t="Raspunsul lui Ironband",b="Ironband primeste vestea cu sobrietate, amintindu-si ca Agmond era puternic la brat, feroce cu ciocanul si tare de cap. Ironband spune ca Agmond a fost ucis de trogguri blestemate si e sigur ca a doborat multi dintre ei pana atunci."}},faq={{q="Cine a fost Agmond?",a="Agmond era un Dwarf care se ocupa de siturile de excavare din Badlands pentru Prospector Ironband. Cautarea ta dupa Agmond s-a incheiat in fata unui schelet.",al={"cine este agmond","lore despre agmond"}},{q="Cine este Murdaloc?",a="Murdaloc este numele mazgalit in gresia de langa mana moarta a lui Agmond. Trebuie sa-l ucizi pe ucigasul lui Agmond, Murdaloc.",al={"ce este murdaloc","povestea lui murdaloc"}},{q="Unde trebuie dus raportul?",a="Lui Prospector Ironband, in Loch Modan.",al={"cui ii spun despre murdaloc","unde se afla ironband"}}},fp="8,214,23.361.0,16.226.1,15.137.0,16.116.0,33.37.0"}
P.entries["quest:74"] = {n="The Legend of Stalvan",s="Aceasta etapa a anchetei duce la o lada veche cu mosteniri de familie Flintridge, lasata langa canalele din Stormwind City. Cercetarea relicvelor prafuite scoate la iveala o pagina rupta dintr-un jurnal, care ofera un indiciu esential, scris de mana, despre viata de altadata a lui Stalvan Mistmantle si duce la Marshal Haggard din Elwynn Forest.",h="Aceasta etapa a anchetei duce la o lada veche cu mosteniri de familie Flintridge, lasata langa canalele din...",kw={"Duskwood","Elwynn Forest","Forlorn Spirit","Marshal Haggard","Mistmantle","lada sigilata","Stalvan","pagina rupta din jurnal"},ang={["faction:Alliance"]="Investigarea cazurilor vechi nerezolvate din inima Elwynn dezvaluie cat de usor pot trece orori profund personale pe langa marshal-ii din Stormwind.",["race:Human"]="Marshal Haggard reprezinta generatia imbatranita a veteranilor din Stormwind, pastrand amintiri esentiale despre regat, de dinainte ca First War si Second War sa destrame familii."},sec={{t="Dezgroparea trecutului",b="In timp ce scotocesc intr-o lada sigilata, plina cu mosteniri prafuite, trofee de vanatoare vechi si portrete de familie, anchetatorii descopera o singura pagina rupta de jurnal, ascunsa sub o vaza de ceramica. Scrisa chiar de mana lui Stalvan Mistmantle, aceasta ramasita ofera o privire intima in mintea unui savant retras, inainte ca tragedia sa loveasca."},{t="Vederea unui maresal se stinge",b="Marshal Haggard, acum in varsta si chinuit de vederea tot mai slaba, se straduieste sa citeasca scrisul de pe pergamentul zdrentuit. Chiar si asa, caligrafia distinctiva ii trezeste o amintire tulburatoare, aducandu-i in minte documente si intamplari de acum multi ani, dinainte ca intunericul sa-i rapeasca vederea."}},faq={{q="Unde se afla lada sigilata?",a="Lada sigilata se afla langa Canals din Stormwind City, chiar in spatele lui Caretaker Folsom, printre bunurile impachetate ale familiei Flintridge. Pagina gasita acolo este dusa apoi la Marshal Haggard, in sud-estul Elwynn Forest.",al={"locatia lazii","unde este lada","lada ponosita"}},{q="Ce se afla in lada sigilata?",a="Lada contine amintiri de familie pline de praf, un portret de familie, carti vechi, trofee de vanatoare si o vaza ceramica; sub aceasta se afla o pagina rupta din jurnalul lui Stalvan.",al={"continutul lazii","ce se afla in lada","lada cu pagina rupta"}},{q="Cine este Marshal Haggard?",a="Marshal Haggard este un ofiter in varsta, retras din Stormwind, care locuieste singur in sudul Elwynn Forest. In ciuda vederii slabe si a fragilitatii sale, amintirile despre vechile arhive si calatori il fac un martor esential al evenimentelor din trecut.",al={"cine este haggard","marshal haggard poveste","vechiul maresal elwynn"}},{q="De ce este importanta aceasta pagina de jurnal?",a="Pagina rupta din jurnal este o dovada directa scrisa chiar de Stalvan Mistmantle. Scrisul sau distinctiv si gandurile care dainuie ajuta la legarea marturiilor disparate din Duskwood si Elwynn de propria sa decadere.",al={"de ce conteaza pagina rupta","indiciul de pe pagina jurnalului","jurnalul lui Stalvan"}},{q="Ce se intampla cand lada este deschisa?",a="Tulburarea ramasitelor trecutului lui Stalvan starneste mortii nelinistiti, facand ca un Forlorn Spirit razbunator sa se arate si sa-i atace pe cei care incearca sa dezlege tragedia.",al={"aparitia forlorn spirit","fantoma de dupa lada","de ce m-a atacat o fantoma"}},{q="Unde duce investigatia mai departe?",a="Dupa ce ii prezinti pagina rupta lui Marshal Haggard, amintirea scrisului de mana il ajuta sa indrume investigatia spre alte fragmente supravietuitoare din istoria lui Stalvan.",al={"pasul urmator","dupa pagina rupta","incotro merg acum"}}},fp="21,309,19.331.0,24.276.1,34.227.0,32.158.0,23.226.0,35.215.0,38.163.0,39.173.0"}
P.entries["quest:741"] = {n="The Absent Minded Prospector"}
P.entries["quest:742"] = {n="The Ashenvale Hunt",s="Ashenvale Hunt este o chemare trimisa tinerilor campioni ai Horde care viziteaza Thunder Bluff, indemnandu-i sa se indrepte spre nord, prin desisul din Ashenvale. Transmisa de crainicii orasului, chemarea le cere calatorilor sa se prezinte la Senani Thunderheart, in Splintertree Post, pentru a lua parte la o vanatoare de initiere.",h="Ashenvale Hunt este o chemare trimisa tinerilor campioni ai Horde care viziteaza Thunder Bluff, indemnandu-i...",kw={"Ashenvale","vanatoare","Senani","Splintertree","Thunder Bluff","Thunderheart","Windstrider","Zoram Strand"},ang={["class:Hunter"]="Pradatorii neimblanziti din Ashenvale le ofera vanatorilor ocazia de a-si insusi urmarirea prazii prin paduri dese, cu totul altfel decat in savanele sudice, uscate si deschise.",["faction:Horde"]="Splintertree Post si Zoram Strand sunt puncte vitale de organizare pentru liniile nordice de aprovizionare ale Horde, care se bazeaza pe recruti proaspeti pentru a tine la distanta fiarele salbatice si bastinasii ostili.",["race:Tauren"]="Pentru taureni care si-au petrecut incercarile pe campiile intinse din Mulgore, bolta deasa si umbrita din Ashenvale reprezinta o provocare sacra si necunoscuta, sub privirile atente ale celor din neamul lor, precum Senani."},sec={{t="O convocare din High Rise",b="In inaltimile linistite din Thunder Bluff, curierii tin Horde in plina dezvoltare la curent cu oportunitatile de dincolo de hotarele Mulgore. Bluff Runner Windstrider poarta o invitatie deschisa, adresata aventurierilor incercati, aflati in cautarea unor provocari mai mari. Pe masura ce Horde isi intemeiaza avanposturi in adancul padurii stravechi de la nord de Barrens, tinerii razboinici sunt chemati sa consolideze aceste avanposturi si sa-si puna la incercare aptitudinile de supravietuire intr-un mediu mult mai aspru."},{t="Frontiera nordica",b="Ashenvale inseamna pentru Horde atat resurse bogate, cat si primejdii grave. Doua tabere importante sustin prezenta factiunii pe acest teritoriu: Splintertree Post, de-a lungul drumului principal, si un avanpost izolat, cocotat pe coasta vestica, la Zoram Strand. Odata ajunsi la Splintertree Post, noii recruti intra direct sub aripa lui Senani Thunderheart, o veterana a salbaticiei care organizeaza o vanatoare de proportii, menita sa imblanzeasca tinuturile salbatice si sa aduca glorie pentru Horde."}},faq={{q="Cine ofera aceasta misiune in Thunder Bluff?",a="Bluff Runner Windstrider le ofera aceasta sarcina aventurierilor care trec prin Thunder Bluff. Datoria sa este sa-i instiinteze pe luptatorii capabili despre eforturile de expansiune ale Horde si sa-i indrume spre avanposturile indepartate care au nevoie de ajutor.",al={"cine incepe vanatoarea din ashenvale","cel care ofera misiunea ashenvale hunt","bluff runner windstrider"}},{q="Unde se afla Splintertree Post?",a="Splintertree Post este o asezare fortificata a Horde din estul Ashenvale. Pentru a ajunge acolo, mergi drept spre nord, trecand granita Barrens si intrand in Ashenvale, apoi urmeaza cararea din padurea estica, ce duce tot mai adanc printre copaci.",al={"locatia Splintertree Post","cum ajungi la Splintertree Post","unde se afla Splintertree"}},{q="Cine este Senani Thunderheart?",a="Senani Thunderheart este o cercetasa tauren cu multa experienta, stationata la Splintertree Post. Ea coordoneaza vanatorile din Ashenvale si pune la incercare forta si rabdarea recrutilor Horde in fata pradatorilor locali.",al={"Senani Thunderheart","cine este Senani","NPC-ul Thunderheart"}},{q="De ce vaneaza Horde in Ashenvale?",a="Horde isi continua expansiunea in Ashenvale pentru a aduna lemn si a-si asigura un teritoriu strategic. Vanatoarea propriu-zisa ajuta la imputinarea fiarelor salbatice primejdioase care le ameninta taberele, oferindu-le totodata tinerilor aventurieri ocazia de a-si dovedi vitejia pe un teritoriu necunoscut.",al={"de ce sa vanezi in ashenvale","scopul vanatorii in ashenvale","obiectivele hoardei in ashenvale"}},{q="Ce este Zoram Strand mentionat in informare?",a="Zoram Strand este tabara de coasta a Horde, aflata pe tarmul indepartat din vestul Ashenvale, cu fata spre mare. Este un al doilea punct de sprijin naval si o fortareata impotriva naga si a locuitorilor ostili ai padurii.",al={"ce este Zoram Strand","avanpostul Zoram Strand","avanpostul Zoram"}},{q="Ce se intampla dupa ce te raportezi la Senani?",a="Dupa ce te prezinti lui Senani Thunderheart, ea te intampina in avanpost si te initiaza imediat in sarcinile mai ample de vanatoare, indrumandu-te sa pandesti si sa invingi cele mai feroce bestii din Ashenvale.",al={"ce urmeaza dupa vanatoarea din Ashenvale","urmatoarea misiune dupa Senani","continuarea vanatorii"}}},fx={af70e220={q="De ce vrea Bluff Runner Windstrider sa mergi la Ashenvale?",a="Bluff Runner Windstrider este crainicul Horde si ii indruma pe tinerii campioni capabili spre locurile unde este cea mai mare nevoie de ei. Horde isi securizeaza cu hotarare avanposturile de frontiera din padurile neimblanzite de la nord de Barrens, iar vanatori precum Senani Thunderheart au nevoie de recruti proaspeti care sa le intareasca prezenta si sa dobandeasca glorie in salbaticie.",al={"de ce sa te trimita in ashenvale","motivul lui bluff runner windstrider","de ce doreste windstrider acest lucru"}}},fp="18,291,28.451.0,21.468.0,39.213.0,35.220.0,27.211.0,38.261.0,51.196.0,39.197.0"}
P.entries["quest:743"] = {n="Dangers of the Windfury",s="Dangers of the Windfury este un ritual de pregatire martiala oferit de Ruul Eagletalon in Bloodhoof Village. Tinerii Tauren si aventurierii Horde trebuie sa lupte cu harpiile salbatice Windfury care isi fac cuiburile pe stancile din sud-estul Mulgore. Vanarea acestor pradatori feroci este o incercare esentiala de indemanare si supravietuire, inainte de a calatori dincolo de tinuturile tribului.",h="Dangers of the Windfury este un ritual de pregatire martiala oferit de Ruul Eagletalon in Bloodhoof Village.",kw={"Bloodhoof Village","Dangers of the Windfury","harpii","Mulgore","Ruul Eagletalon","proba Tauren","Windfury","gheare Windfury"},ang={["class:Warrior"]="Incercarea lui Ruul Eagletalon are o semnificatie aparte pentru razboinicii aspiranti, care trebuie sa invete sa pareze loviturile rapide din picaj si sa-i invinga printr-o disciplina bine ancorata pe pradatorii feroce care ii ataca din aer.",["faction:Horde"]="Aliatii taurenilor care se supun incercarii lui Ruul isi dovedesc devotamentul fata de apararea tinutului de bastina al Horde si castiga respectul de durata al celor din Bloodhoof Village.",["race:Tauren"]="Pentru tinerii tauren, curatarea cuiburilor Windfury este atat un act de aparare a campiilor, cat si o trecere sacra la varsta adulta recunoscuta, sub privirile atente ale batranilor satului."},sec={{t="Evaluarea profesorului",b="In Bloodhoof Village, razboinicul veteran Ruul Eagletalon ii urmareste pe toti calatorii care trec prin inima regiunii Mulgore. Celor care ajung la maturitate sau vor sa dovedeasca faptul ca sunt pregatiti pentru aventuri mai ample, Ruul le cere dovezi concrete ale instinctelor de lupta. Supravietuirea dincolo de vaile ocrotite din Mulgore cere stapanire de sine in fata unor dusmani agresivi si vicleni, iar Ruul foloseste cei mai feroce pradatori bastinasi ai tinutului pentru a masura curajul tinerilor."},{t="Ameninarea Windfury",b="Harpile Windfury isi au cuiburile pe marginea muntoasa din sud-estul Mulgore, departe de potecile batatorite, dar amenintand in permanenta fauna ratacitoare si calatorii izolati. Feroce si mereu flamande dupa carne proaspata, aceste napaste inaripate se bazeaza pe atacuri in picaj rapide si gheare ascutite ca briciul. Infrangerea lor si luarea ghearelor dovedesc nu doar puterea de a invinge o amenintare bine inradacinata, ci si viteza necesara pentru a contracara jefuitorii aerieni."}},faq={{q="Cine este Ruul Eagletalon?",a="Ruul Eagletalon este un razboinic tauren si profesor cu multa experienta, care locuieste in Bloodhoof Village. Ii indruma pe tinerii aventurieri si le pune la incercare forta, reflexele si rezistenta, pentru a se asigura ca sunt pregatiti inainte de a porni spre zonele mai indepartate si mai primejdioase din Kalimdor.",al={"ruul eagletalon","cine da Dangers of the Windfury","ruul"}},{q="Unde se gasesc harpiile Windfury in Mulgore?",a="Harpile Windfury isi au cuiburile de-a lungul muntilor din sud-estul Mulgore. Isi fac cuiburi rudimentare sus, printre stanci si pe versantii de la poalele muntilor, departe de drumul principal care strabate valea.",al={"locatia harpiilor Windfury","unde sunt harpiile Windfury","locatia cuibului Windfury"}},{q="De ce sunt harpiile Windfury considerate dusmani firesti ai taurenilor?",a="Harpile sunt necrofage cunoscute pentru agresivitatea si teritorialitatea lor, atacand pe oricine se apropie de cuiburile lor. In Mulgore, stolul Windfury este renumit pentru pofta nesatioasa de carne proaspata si agresivitatea neobosita fata de calatori si animale la pascut, fiind o amenintare permanenta pentru campii.",al={"de ce se lupta taureni cu harpiile","amenintarea harpiilor din Mulgore","povestea Windfury"}},{q="Ce dovada cere Ruul Eagletalon in urma vanatorii?",a="Ruul le cere aventurierilor sa recupereze opt gheare Windfury direct de la harpiile ucise. Taierea si aducerea acestor gheare dovedeste ca ai invins principala arma naturala a harpiilor.",al={"dovada pentru Dangers of the Windfury","ce sa adun pentru Ruul","obiectivul misiunii Windfury"}},{q="De ce trebuie aventurierii sa treaca prin aceasta incercare inainte de a parasi Mulgore?",a="Ruul considera harpiile Windfury feroce drept un reper ideal pentru pregatirea martiala. Daca un aventurier nu poate face fata vitezei, ferocitatii si ghearelor unei harpii, are putine sanse impotriva pericolelor si mai letale care se aduna dincolo de povarnisurile de aparare ale Mulgore.",al={"scopul incercarii","de ce sa faci Dangers of the Windfury","incercarea lui Ruul"}},{q="Unde se afla Bloodhoof Village?",a="Bloodhoof Village se afla in centrul regiunii Mulgore, langa Stonebull Lake, la sud de Great Gate si Thunder Bluff. Este principalul centru de cultura, comert si instruire pentru calatorii tauren care strabat campiile.",al={"bloodhoof village locatie","unde este bloodhoof","ruul locatie"}}},fx={d8522cbd={q="De ce vrea Ruul Eagletalon sa fie vanate harpiile Windfury?",a="Ruul Eagletalon este un razboinic si mentor insarcinat sa-i pregateasca pe tinerii aventurieri inainte ca acestia sa se aventureze dincolo de hotarele sigure din Mulgore. El considera harpiile feroce Windfury o incercare fireasca - o masura reala a iscusintei tale martiale si a pregatirii de a infrunta primejdiile mai aspre ale lumii intinse.",al={"de ce sa vanam harpiile","motivul lui Ruul","motivul lui Ruul Eagletalon"}},["1789ad72"]={q="Cine sunt harpiile Windfury?",a="Harpile Windfury sunt necrofagi avieni salbatici, care-si fac cuibul pe cornisele muntilor, la sud-est de Bloodhoof Village. Vicioase si sirete, de multa vreme ii vaneaza pe calatori si animalele salbatice din Mulgore, impinse de o foame nestavilita de carne proaspata si de dusmania fireasca fata de tauren.",al={"harpiile Windfury","cine sunt Windfury","harpiile Windfury din Mulgore"}},["29c303b8"]={q="De ce nu vaneaza Ruul Eagletalon harpiile insusi?",a="Ruul este un invatator, iar datoria sa in Bloodhoof Village este sa formeze urmatoarea generatie de aparatori, nu sa lupte in locul lor. Aceasta sarcina este in mod explicit un ritual de trecere: trebuie sa-ti dovedesti singur puterea impotriva pradatorilor din Mulgore inainte de a fi considerat vrednic sa calatoresti dincolo de campii.",al={"de ce eu","de ce sa ma trimita","de ce nu se ocupa Ruul de asta"}}},fp="23,364,22.435.0,19.451.0,23.275.0,48.204.0,70.299.0,53.188.0,63.257.0,35.220.0"}
P.entries["quest:744"] = {n="Preparation for Ceremony",s="Preparation for Ceremony este o traditie tauren care consta in confectionarea unei tiare ceremoniale pentru cel care urmeaza sa se infatiseze in fata Sefului Cairne Bloodhoof. Pentru a desavarsi tinuta traditionala, trebuie culese pene viu colorate de la harpiile primejdioase care cuibaresc dincolo de Thunder Bluff, in timp ce sunt pregatite benzile de piele.",h="Preparation for Ceremony este o traditie tauren care consta in confectionarea unei tiare ceremoniale pentru...",kw={"cairne bloodhoof","ceremonie","pene","harpy","podoaba","mulgore","preparation for ceremony","tauren","thunder bluff"},ang={["faction:Horde"]="Ajutorul oferit unui alt membru al Horde in indatoririle sale ceremoniale traditionale onoreaza obiceiurile aliatilor tauren de pe platourile din Thunder Bluff.",["race:Tauren"]="Coifurile faurite din materiale naturale sunt strans legate de onoarea tauren si de riturile de trecere care preced intalnirea cu marele capetenie. Ajutorul dat la confectionarea acestor vesminte de ceremonie exprima spiritul comunitar si mandria triburilor din Mulgore."},sec={{t="Cinstirea capeteniei",b="In cultura tauren, a sta in fata sefului Cairne Bloodhoof este un prilej de mare mandrie si veneratie. Asemenea momente de referinta cer tinuta ceremoniala potrivita, indeosebi o coafura traditionala, lucrata cu grija din piele tratata si pene simbolice. Crearea acestei tinute este considerata o onoare de catre membrii familiei, care au grija ca fiecare componenta sa exprime demnitate si respect in fata conducatorului triburilor unite."},{t="Penele stancilor",b="Confectionarea unei podoabe ceremoniale pentru cap cere atat indemanare, cat si materiale anume. In timp ce curelele din piele moale sunt tabacite pentru a forma banda de baza, pene lungi si impecabile trebuie gasite pentru a impodobi coroana. Harpiile inaripate care isi au cuiburile pe dealurile stancoase din nordul si nord-vestul Thunder Bluff ofera penele de dimensiunea si culoarea exact necesare, astfel ca drumetii sunt nevoiti sa se aventureze in cuiburi ostile pentru a le recupera."}},faq={{q="Pentru ce ceremonie se fac pregatiri?",a="Ceremonia marcheaza infatisarea unui tauren inaintea capeteniei Cairne Bloodhoof. Pentru a cinsti aceasta ocazie onorabila, fratele sau sora sa faureste o podoaba ceremoniala pentru cap, din piele tabacita si pene viu colorate.",al={"ce ceremonie este aceasta","ce este ceremonia","cine sta inaintea lui bloodhoof"}},{q="Cine este Chief Bloodhoof?",a="Capetenia Cairne Bloodhoof este venerabilul mare capetenie si conducatorul triburilor tauren unite, domnind de pe platourile inalte din Thunder Bluff. A te afla in fata lui este o onoare aparte pentru orice tauren.",al={"cine este chief bloodhoof","cairne bloodhoof","cine este bloodhoof"}},{q="De ce sunt necesare penele de harpie pentru podoaba de cap?",a="Podoaba ceremoniala pentru cap are nevoie de pene de o anumita marime, cu un penaj deosebit - mai exact, azurii si de culoarea bronzului - pentru a desavarsi modelul traditional, in timp ce curelele de piele sunt tabacite.",al={"de ce avem nevoie de pene de harpie","de ce pene de harpie","de ce pene"}},{q="Unde se gasesc harpiile?",a="Harpiile de la care provin aceste pene traiesc in tinuturile accidentate, mult spre nord si nord-vest de Thunder Bluff, in Mulgore.",al={"unde traiesc harpiile","unde gasesc harpii","unde sunt penele azurii si de bronz"}},{q="Ce rol au harpiile in Mulgore?",a="Harpiile sunt creaturi feroce, jumatate pasari, jumatate humanoide, care isi fac cuibul in stancariile din jurul Mulgore. Pe langa faptul ca reprezinta o amenintare pentru calatori si triburi, penajul lor mare si colorat le face o sursa ideala de ornamente ceremoniale.",al={"de ce sunt vanate harpiile","ce sunt harpiile"}},{q="Cine confectioneaza coiful ceremonial?",a="Eyahn Eagletalon tabaceste curelele de piele si confectioneaza coiful pentru a-si onora fratele, in timp ce se pregateste sa se infatiseze inaintea conducatorului de clan.",al={"cine face podoaba de cap","cine confectioneaza podoaba de cap"}}},fp="24,307,22.430.0,21.430.0,36.217.0,23.195.0,48.194.0,30.131.0,37.226.0,41.150.0"}
P.entries["quest:745"] = {n="Sharing the Land",s="Incredintata de Baine Bloodhoof in Bloodhoof Village, aceasta sarcina ii trimite pe tinerii aventurieri ai Horde sa puna capat braconajului distrugator al gnollilor Palemane din tinut. Prin starpirea tabacarilor, jupuitorilor si braconierilor lor, protejati fauna din Mulgore si invatati filosofia tauren despre traiul in echilibru cu Earth Mother.",h="Incredintata de Baine Bloodhoof in Bloodhoof Village, aceasta sarcina ii trimite pe tinerii aventurieri ai...",kw={"baine bloodhoof","bloodhoof village","gnoll","mulgore","palemane","braconieri","impartirea pamantului","jupuitori","tabacari"},ang={["class:Druid"]="Druizii stiu ca braconajul necontrolat tulbura spiritul campiilor, asa ca trebuie sa intervina imediat pentru a restabili armonia pamantului.",["class:Hunter"]="Jupuitorii si braconierii Palemane sunt opusul vanatorului adevarat: macelaresc cu cruzime si risipa creaturile salbatice, in loc sa le respecte.",["faction:Horde"]="Ajutorul oferit lui Baine Bloodhoof intareste legatura dintre noii aventurieri Horde si conducerea tinerei natiuni Tauren.",["race:Tauren"]="Pentru tinerii tauren, a raspunde chemarii lui Baine este un pas esential in invatarea indatoririi sacre de a apara Mulgore si de a onora echilibrul lui Earth Mother."},sec={{t="Un tinut dezechilibrat",b="Tauren venereaza natura, luand din ea doar cat le este necesar pentru a supravietui si cinstind-o pe Earth Mother in toate. Gnollii Palemane, asezati la sud de Bloodhoof Village si intr-o pestera din vest, nu au un asemenea respect. In loc sa vaneze cu masura, ei macelaresc cu salbaticie vietuitoarele de pe campii, lasand in urma lesuri jupuite si ecosisteme devastate. Pentru un popor care incearca sa cladeasca o patrie pasnica in Mulgore, acest macel nechibzuit nu poate fi tolerat."},{t="Cand cuvintele nu ajung",b="La inceput, Baine Bloodhoof spera sa rezolve problema pe cale pasnica si a incercat sa deschida un dialog cu gnollii care inaintau. Palemane au respins orice tentativa de apropiere, raspunzand diplomatiei cu ostilitate si continuand sa devasteze tinutul. Vazand ca negocierile sunt zadarnice, Baine recurge la forta. Tineri razboinici sunt trimisi direct in taberele de vanatoare pentru a-i infrunta pe braconieri, tabacari si jupuitori, inainte ca pajistile sa sufere daune ireversibile."},{t="Cercul vietii si al mortii",b="Aceasta misiune este o proba de maturitate si o lectie morala pentru campionii aflati in formare. La intoarcerea din vanatoarea de control, Baine ii aminteste aventurierului ca viata nu trebuie luata niciodata din rautate, ci din necesitate, pentru a pastra echilibrul. Viata si moartea fac parte dintr-un cerc interconectat, in care niciuna nu poate dainui fara cealalta - un adevar fundamental pe care fiecare paznic din Mulgore trebuie sa-l duca mai departe."}},faq={{q="Cine ofera aceasta misiune?",a="Baine Bloodhoof, fiul marelui sef de trib Cairne Bloodhoof, ofera aceasta sarcina in Bloodhoof Village, in centrul Mulgore.",al={"cel care da misiunea","cine incepe Sharing the Land","misiunea lui Baine"}},{q="De ce ii vizeaza taurenii pe gnolii Palemane?",a="Gnollii Palemane vaneaza fara chibzuinta fauna din Mulgore, imputinand turmele fara sa respecte echilibrul naturii. Au refuzat, de asemenea, toate incercarile tauren de a purta tratative pasnice.",al={"de ce sa ucidem gnolli","problema Palemane","ce au facut gnollii"}},{q="Unde se afla gnollii acestia?",a="Palemane isi mentin taberele la sud de Bloodhoof Village si locuiesc in sistemul de pesteri Palemane Rock, aflat la vest.",al={"locatii de gnolli","tabara Palemane","unde se gasesc cei din Palemane"}},{q="Au incercat taurenii mai intai sa faca pace?",a="Da. Baine spune ca taurenii au incercat de mai multe ori sa comunice si sa imparta pamantul, dar gnolii le-au dispretuit si respins toate propunerile pasnice.",al={"au vorbit taurenii cu gnolii","diplomatia Palemane"}},{q="Ce lectie incearca Baine sa predea aici?",a="Baine vrea ca tinerii aparatori sa inteleaga ca viata si moartea exista intr-un cerc de nefrant. Desi uneori este necesar sa iei o viata pentru a apara echilibrul, acest lucru trebuie facut intotdeauna cu un respect profund fata de Earth Mother.",al={"lectia lui baine","sensul impartirii pamantului"}},{q="Cine sunt gnolii Palemane?",a="Sunt un trib primitiv, asemanator hienelor, originar din Mulgore, cunoscut pentru blana deschisa la culoare, agresivitatea teritoriala si dispretul total fata de armonia campiilor.",al={"cine sunt palemanes","tribul palemane"}}},fx={["901e0c5d"]={q="Impotriva cui esti trimis in Sharing the Land?",a="Baine te trimite impotriva gnollilor Palemane, care au patruns in campiile de la sud de Bloodhoof Village si s-au adapostit intr-o pestera din vest. Acesti braconieri, jupuitori si tabacari macelaresc fara chibzuinta vietuitoarele din Mulgore, fara sa respecte echilibrul sau Earth Mother. Fiindca au respins cu violenta toate incercarile pasnice ale taurenilor de a-i convinge, forta este singura cale ramasa pentru a le opri braconajul.",al={"tinte pentru Sharing the Land","pe cine trebuie sa ucid pentru Sharing the Land","gnoll-ii Palemane din Sharing the Land"}}},fp="16,309,21.523.0,15.429.0,28.396.0,21.114.0,49.178.0,31.122.0,39.155.0,42.222.0,28.160.0"}
P.entries["quest:746"] = {n="Dwarven Digging",s="Dwarven Digging este o misiune din Mulgore oferita de Baine Bloodhoof in Bloodhoof Village. Temandu-se ca excavatiile piticilor vor infuria fiarele locului si vor pangari pamantul sacru, Baine le cere tinerilor aparatori Horde sa le saboteze eforturile, confiscandu-le si zdrobindu-le tarnacoapele.",h="Dwarven Digging este o misiune din Mulgore oferita de Baine Bloodhoof in Bloodhoof Village.",kw={"Baine Bloodhoof","Bloodhoof Village","Dwarf","forja","kodo","Mulgore","tarnacoape","prospector"},ang={["class:Shaman"]="Shamanii inteleg ca tulburarea rocii de baza prin excavari neglijente dezechilibreaza elementele si starneste neliniste printre spiritele si fapturile tinutului.",["faction:Horde"]="Patrunderea dwarves Alliance-aligned in inima teritoriilor Horde submineaza pacea fragila stabilita dupa Third War si arata un dispret flagrant fata de granitele tribale.",["profession:Mining"]="In timp ce minerii venereaza bogatiile ascunse in piatra, metodele de exploatare ale Dwarf din Mulgore ignora respectul si armonia, alegand distrugerea nechibzuita.",["race:Tauren"]="Trupul Earth Mother este sacru, iar sa vezi intrusi straini sfredelind stepele unduitoare din Mulgore este o ofensa care cere un raspuns imediat si ferm."},sec={{t="Intrusi in dealuri",b="La nord-vest de Bloodhoof Village, prospectori pitici au inceput sa-si delimiteze un sit de excavare pe dealurile domoale din Mulgore. Explorer's League si echipele sale de excavare cauta relicve ale titanilor si secrete ale pamantului prin Kalimdor, dar rareori tin seama de pamanturile sau obiceiurile bastinasilor. Pentru tauren, pamantul este o mama vie, care trebuie venerata, nu jefuita si scobita dupa pietre si metal."},{t="Apararea pamantului sacru",b="Baine Bloodhoof isi da seama ca utilajele dwarfilor si exploziile neintrerupte ameninta armonia fragila a campiilor. Dincolo de distrugerile fizice, zarva agita fauna locala si starneste in furie kodo-ii din campii. Distrugandu-le uneltele prospectorilor chiar in propriile forje, taurenii spera sa transmita un mesaj direct si sa opreasca inaintarea inainte ca pagubele sa devina de durata."}},faq={{q="De ce sapa dwarves in Mulgore?",a="Prospectorii pitici cred ca secrete si artefacte ascunse zac in adancurile pamantului din centrul Kalimdorului. Insa dispretul lor fata de teritoriile tribale si metodele violente de minerit i-au adus in conflict direct cu taurenii.",al={"pitici in mulgore","de ce sunt cautatorii aici","excavatie piticeasca in mulgore"}},{q="Cine da misiunea Dwarven Digging?",a="Misiunea este oferita de Baine Bloodhoof, tanarul fiu al Inaltului Capetenie Cairne Bloodhoof, aflat in Bloodhoof Village, in centrul Mulgore.",al={"cel care ofera misiunea dwarven digging","cine incepe dwarven digging"}},{q="De ce vrea Baine ca uneltele lor sa fie distruse, in loc sa fie doar furate?",a="Baine vrea sa faca echipamentul complet inutil, pentru a opri imediat excavarea. Distrugerea uneltelor din forje transmite un mesaj clar, atat simbolic, cat si practic: pamantul nu-si va dezvalui secretele prin forta bruta si profanare.",al={"de ce sa rupi tarnacoapele","zdrobirea uneltelor piticilor"}},{q="Cum afecteaza sapaturile fauna salbatica din Mulgore?",a="Sapaturile zgomotoase si brazdele adanci sapate in pamant agita puternic creaturile bastinase, in special masivii kodo care cutreiera dealurile, facand turmele pasnice irascibile si agresive.",al={"kodo furiosi","de ce sunt fiarele furioase"}},{q="Unde pot fi sparte tarnacoapele?",a="Tarnacoapele pot fi transformate prin batere in fier vechi la orice forja functionala. Jucatorii pot folosi forja din tabara de excavare a piticilor sau le pot duce la fierarii din Thunder Bluff.",al={"unde este forja","zdrobeste tarnacoapele prospectorilor la forja"}},{q="Are aceasta misiune legatura cu prezenta mai ampla a Explorer's League in Kalimdor?",a="Da. Expeditii de pitici plecate din Ironforge au infiintat avanposturi in tot Kalimdorul, inclusiv in Mulgore, Barrens si sudul Kalimdorului, starnind adesea incaierari cu rasele Horde din cauza suveranitatii teritoriale si a locurilor sacre.",al={"Liga Exploratorilor in Mulgore","Ironforge in Kalimdor"}}},fx={["755e231a"]={q="La ce folosesc Broken Tools?",a="Broken Tools sunt dovezi palpabile ca ai pus capat operatiunilor Dwarf-ilor. In loc sa-i alunge pur si simplu pe prospectori sau sa le ia echipamentul, Baine Bloodhoof vrea ca tarnacoapele lor sa fie sfaramate la o forja si aduse la el, pentru a se asigura ca munca lor s-a oprit si ca mesajul impotriva profanarii pamantului sacru este clar.",al={"unelte stricate","de ce unelte stricate","scopul uneltelor stricate"}},["95107d94"]={q="Cine sunt Dwarf care sapa in Mulgore?",a="Sunt prospectori pitici care si-au ridicat o tabara de excavare in dealurile din nord-vestul Mulgore. Manati de zvonurile ca secrete stravechi zac ingropate sub campii, cauta relicve istorice si cunostinte despre titani, fara sa le pese de profanarea spirituala pe care carierele lor o aduc pamantului si vietuitoarelor sale.",al={"Dwarves din Mulgore","cine sunt excavatorii Dwarf","prospectorii din Mulgore"}}},fp="15,289,24.392.0,26.388.0,35.232.0,36.137.0,63.245.0,52.187.0,31.201.0,75.232.0"}
P.entries["quest:747"] = {n="The Hunt Begins",s="Hunt Begins este un ritual initiatic fundamental pentru tinerii aventurieri din Camp Narache, pe Red Cloud Mesa. La porunca lui Grull Hawkwind, initiatii sunt trimisi sa vaneze plainstriders din apropiere, pentru a aduce satului carne si pene. Indeplinirea acestei sarcini este primul pas spre castigarea respectului lui Chief Hawkwind si, in cele din urma, spre primirea in Thunder Bluff.",h="Hunt Begins este un ritual initiatic fundamental pentru tinerii aventurieri din Camp Narache, pe Red Cloud...",kw={"Camp Narache","Chief Hawkwind","pene","Grull Hawkwind","Hunt Begins","Mulgore","alergator de campie","Red Cloud Mesa"},ang={["class:Hunter"]="Vanatoarea stridersilor rapizi de pe Red Cloud Mesa este primul exercitiu practic de tir, urmarire si cinstire a fiarelor care te sustin.",["race:Tauren"]="Pentru tinerii shu'halo, doborarea primilor vostri alergatori de campie de pe mesa este un rit de trecere esential, care va confirma legatura cu pamantul si datoria de a asigura hrana pentru Camp Narache."},sec={{t="Hrana unui trib",b="Pe inaltimile din Red Cloud Mesa, supravietuirea si traditia se impletesc. Taurenii vaneaza de nevoie, pentru a-si hrani si imbraca poporul, dar vad si panda si goana drept o proba esentiala de disciplina si o indeletnicire placuta. Cand proviziile din Camp Narache se imputineaza, comunitatea le cere tinerilor promitatori sa adune carne proaspata de plainstrider pentru gatit si pene trainice pentru vesmintele tribale."},{t="Castigarea recunoasterii",b="Niciun erou aspirant nu paraseste pur si simplu Red Cloud Mesa pentru intinderile mai largi din Mulgore fara sa-si dovedeasca valoarea. Grull Hawkwind este unul dintre principalii judecatori ai caracterului nou-venitilor si insista ca fiecare sa-si dovedeasca priceperea inainte de a se infatisa in fata tatalui sau, Chief Hawkwind. O vanatoare reusita demonstreaza nu doar independenta, ci si devotamentul fata de sprijinirea tribului."}},faq={{q="Cine ofera aceasta misiune?",a="Grull Hawkwind ofera aceasta sarcina in Camp Narache. Este fiul conducatorului satului, Chief Hawkwind, si le este un prim mentor tinerilor vanatori si aventurieri din Red Cloud Mesa.",al={"cel care da misiunea","cine incepe Hunt Begins","Grull Hawkwind"}},{q="De ce sunt vanati alergatorii de campie in locul altor fiare?",a="Alergatorii de campie sunt raspanditi pe platou si ofera atat carne hranitoare, care reface rezervele de hrana pe sfarsite, cat si pene rezistente, folosite la imbracamintea si podoabele traditionale tauren.",al={"de ce plainstriders","carnea si penele de plainstrider","vanarea plainstriders"}},{q="De ce trebuie sa-mi dovedesc valoarea inainte de a-l vedea pe Chief Hawkwind?",a="Societatea tauren pune mare pret pe contributiile concrete si pe priceperea la vanatoare. Grull Hawkwind le cere initiatilor sa-si dovedeasca abilitatile de baza de supravietuire si loialitatea fata de sat, inainte de a fi primiti la capetenie si de a primi raspunderi mai mari.",al={"de ce sa-i dovedesc lui Chief Hawkwind","aprobarea lui Chief Hawkwind","de ce sa vanez mai intai"}},{q="Care este scopul general al acestor incercari de pe Red Cloud Mesa?",a="Platoul serveste drept teren de incercare. Dupa ce un tanar Tauren isi dovedeste priceperea in fata lui Chief Hawkwind si a batranilor din Camp Narache, este considerat pregatit sa coboare in campiile intinse din Mulgore si sa intre in capitala Thunder Bluff.",al={"scopul incercarilor de pe mesa","de ce sunt pe Red Cloud Mesa","plecarea de pe Red Cloud Mesa"}},{q="Ce urmeaza dupa aceasta vanatoare?",a="Intoarcerea cu carnea si penele ii castiga aprobarea lui Grull si duce direct la 'The Hunt Continues', in care initiatii urmaresc vanat mai mare si mai greu de prins prin toata mesa.",al={"urmatoarea misiune","continuare","ce urmeaza dupa Hunt Begins"}},{q="Vaneaza Tauren doar pentru a supravietui?",a="Desi hrana si resurse precum pielea, oasele si penele sunt esentiale, tauren practica vanatoarea si ca sport si comuniune spirituala, ascutindu-si instinctele care le mentin triburile vigilente si puternice.",al={"filosofia de vanatoare a taurenilor","vanatoarea ca sport","de ce vaneaza taurenii"}}},fx={["395288c5"]={q="De ce vrea Grull Hawkwind ca acest lucru sa fie facut?",a="Grull Hawkwind vede un mare potential in tine si vrea sa-ti dovedesti valoarea fata de trib si de tatal sau, Chief Hawkwind. Proviziile de carne din Camp Narache sunt pe sfarsite, iar tabara are nevoie de pene proaspete. Trimitandu-te sa le aduni, iti pune instinctele de vanator la incercare si reface proviziile esentiale ale satului.",al={"de ce vrea Grull sa fie vanati Plainstrider","motivul lui Grull Hawkwind","de ce sa vanezi Plainstrider pentru Grull"}},f26a5c4f={q="La ce foloseste Plainstrider Meat?",a="Carnea este stransa pentru a reface proviziile tot mai scazute ale Camp Narache. Supravietuirea in Red Cloud Mesa impune hrana sigura, iar vanatoarea de plainstrideri ofera carnea proaspata necesara pentru a-i hrani pe tinerii vanatori si pe batranii din tabara.",al={"la ce se foloseste carnea de plainstrider","de ce sa aduni carne de plainstrider","utilizarea carnii de plainstrider"}},fb1052a7={q="La ce foloseste Plainstrider Feather?",a="Tauren din Camp Narache folosesc penele de plainstrider pentru a confectiona haine si podoabe. Tribul foloseste fiecare parte a animalelor pe care le vaneaza, transformand penajul rezistent in vesminte practice si podoabe potrivite pentru viata pe platou.",al={"la ce folosesc penele de plainstrider","de ce sa aduni pene de plainstrider","utilizarea penelor de plainstrider"}}},fp="15,361,20.383.0,19.382.0,21.181.0,53.182.0,59.252.0,59.239.0,27.181.0,33.203.0"}
P.entries["quest:748"] = {n="Poison Water",s="Poison Water da startul eforturilor tauren de a inlatura poluarea din fantanile sacre ale Mulgore. La insarcinarea lui Mull Thunderhorn din Bloodhoof Village, tinerii aparatori ai Horde aduna ingrediente naturale de pe campii pentru a crea un totem ritualic cu puteri tamaduitoare.",h="Poison Water da startul eforturilor tauren de a inlatura poluarea din fantanile sacre ale Mulgore.",kw={"bloodhoof village","totem de purificare","mulgore","mull thunderhorn","plainstrider","poison water","lup de prerie","winterhoof water well"},ang={["class:Druid"]="Otravirea izvoarelor cu apa proaspata de catre goblini este un atac direct asupra echilibrului natural, care impune o reactie imediata pentru a pastra flora si fauna fragile din Mulgore.",["class:Shaman"]="Restabilirea apelor poluate prin totemuri intarite de puterea fiarelor ilustreaza principiile samanismului tauren: colaborarea cu fauna locala pentru a vindeca tulburarile elementale.",["race:Tauren"]="Pangarirea apei potabile loveste in esenta darurilor lui Earth Mother, transformand ritualul de purificare intr-o datorie fundamentala pentru orice tauren care ajunge la maturitate in Mulgore."},sec={{t="Un tinut pangarit",b="Campiile inierbate din Mulgore sunt pamant sacru pentru tauren, dar forte perfide au inceput sa le ameninte sursa vitala de viata. Mull Thunderhorn, un batran aflat in Bloodhoof Village, descopera ca intrusii goblini si lacheii lor au otravit fantanile pretioase care sustin triburile si vietuitoarele locale. Poluarea loveste direct in inima spirituala a poporului nomad care s-a asezat de curand aici."},{t="Adunarea esentei naturii",b="Pentru a contracara contaminantii industriali, Mull se bazeaza pe samanismul traditional tauren, nu pe leacuri primitive. Curatarea Winterhoof Water Well cere crearea unui totem ritualic puternic, impregnat cu vitalitatea pradatorilor bastinasi din Mulgore. El trimite vanatori sa urmareasca lupi de preerie pentru labele lor si plainstrideri maturi pentru ghearele lor, prin campiile din sud-vest, folosind puterea pamantului pentru a-i vindeca propriile rani."}},faq={{q="Cine a otravit fantanile cu apa din Mulgore?",a="Goblinilor invadatori si angajatilor lor le revine vina pentru pangarirea adapatorilor sacre din Mulgore. Operatiunile lor industriale distructive si nepasarea fata de echilibrul natural ameninta atat triburile tauren, cat si fauna locala.",al={"cine a otravit fantanile","cine a otravit Mulgore","cine a poluat apa"}},{q="De ce are Mull Thunderhorn nevoie de labele lupilor si de ghearele plainstriderilor?",a="Mull confectioneaza totemuri traditionale de purificare din parti luate de la vietuitoarele native din Mulgore. Folosind spiritele si forta innascute ale pradatorilor campiilor, el creeaza un focar suficient de puternic pentru a indeplini un ritual de purificare a apei.",al={"de ce labe de lup","de ce gheare de alergator de campie","materiale pentru totem"}},{q="Care fantana urmeaza sa fie purificata in aceasta misiune?",a="Aceasta sarcina strange materiale anume pentru confectionarea totemului purificator al fantanii Winterhoof Water Well, prima dintr-un sir de fantani poluate care au nevoie de purificare ritualica.",al={"pentru ce fantana este asta","care fantana cu apa"}},{q="Unde se afla Mull Thunderhorn?",a="Mull Thunderhorn locuieste in Bloodhoof Village, principala asezare Tauren, situata in centrul regiunii Mulgore, in jurul apelor lacului Stonebull Lake.",al={"locatia lui Mull Thunderhorn","unde este Mull","unde predau Poison Water"}},{q="Unde pot fi gasiti lupii si striderii de campie necesari?",a="Lupii de preerie si plainstriderii adulti ratacesc prin campiile domoale de la sud-vest de Bloodhoof Village.",al={"unde gasesc lupi de preerie","locatia plainstrider","terenuri de vanatoare"}},{q="Ce se intampla dupa ce Mull primeste labele si ghearele?",a="Mull leaga componentele adunate intr-un Winterhoof Cleansing Totem si iti cere sa-l duci direct la Winterhoof Water Well pentru a indeplini ritualul de purificare.",al={"urmatoarea misiune dupa Poison Water","ce fac mai departe"}}},fx={["50414ce1"]={q="De ce vrea Mull Thunderhorn ca acest lucru sa fie facut?",a="Goblin si oamenii lor tocmiti au corupt fantanile sacre din Mulgore, lovind chiar in seva patriei taurenilor. Pentru Mull Thunderhorn si locuitorii din Bloodhoof Village, a lasa fantanile contaminate inseamna a chema boala si a pangari echilibrul sacru al pamantului. Purificarea lor este o datorie urgenta, atat spirituala, cat si practica.",al={"motivul lui mull thunderhorn","de ce sa purifici fantanile cu apa","de ce misiunea Poison Water"}}},fp="12,238,17.428.0,26.435.0,40.234.0,65.236.0,46.172.0,34.141.0,58.96.0,53.172.0"}
P.entries["quest:749"] = {n="The Ravaged Caravan",s="Morin Cloudstalker ii indeamna pe calatori sa cerceteze ramasitele unei caravane Venture Company atacate in apropierea malului nordic al Stonebull Lake. Taurenii au incendiat convoiul ca razbunare pentru camarazii pierduti, dar goblinii recuperatori s-au intors sa salveze marfa neatinsa. Cercetarea lazilor de provizii ramase dezvaluie adevarata amploare industriala a operatiunilor Venture Company din Mulgore.",h="Morin Cloudstalker ii indeamna pe calatori sa cerceteze ramasitele unei caravane Venture Company atacate in...",kw={"morin cloudstalker","mulgore","caravana jefuita","stonebull lake","lada cu provizii","venture co","venture company"},ang={["faction:Horde"]="Extinderea corporatista necontrolata in Mulgore ameninta stabilitatea Thunder Bluff, asa ca cercetasii Horde trebuie sa perturbe logistica Venture Company.",["profession:Mining"]="Lazile trainice si notitele logistice dovedesc amploarea operatiunilor agresive de prospectare si extractie a mineralelor pe care Venture Company le desfasoara in Mulgore.",["race:Tauren"]="Pangarirea campiilor de catre masinariile Venture Company si defrisarile lor loveste direct in patria stramoseasca, asa ca recuperarea si distrugerea proviziilor lor sunt vitale pentru apararea tinutului Mulgore."},sec={{t="Razbunare langa lac",b="Ramasitele carbonizate de-a lungul malului nordic de la Stonebull Lake sunt urmarea unui atac rapid al razboinicilor Tauren. Indurerati de pierderea a doi tovarasi ucisi intr-o incaierare anterioara, Morin Cloudstalker si razboinicii sai au atacat prin surprindere un convoi de aprovizionare inarmat al Venture Company. Hotarati sa nimiceasca eforturile intrusilor, razboinicii Tauren au dat foc carelor si au lasat in urma ruinele fumegande, presupunand ca focul va mistui tot ce incercau goblinii sa transporte."},{t="Treburi neterminate",b="Tauren au observat curand ca recuperatorii din Venture Company scotoceau printre resturile innegrite, semn ca focul lor nu distrusese cea mai importanta incarcatura. In loc sa riste alte vieti orbeste, Morin trimite cercetasi sa inspecteze epava. Printre ramasitele patate de funingine zac lazi intacte, marcate cu insemnele Venture Company Mining Division, ambalate si destinate instalatiilor centrale de procesare."}},faq={{q="De ce a fost distrusa caravana?",a="Morin Cloudstalker si razboinicii sai tauren au prins caravana intr-o ambuscada si i-au dat foc, razbunandu-se dupa ce pierdusera doi cercetasi intr-o confruntare anterioara cu Venture Company.",al={"cine a distrus caravana","de ce a fost arsa caravana","atacul asupra caravanei"}},{q="Unde se afla Ravaged Caravan?",a="Carutele arse se afla pe tarmul nordic al Stonebull Lake, la est de Bloodhoof Village, in Mulgore.",al={"locatia caravanei","unde se afla caravana","locul caravanei devastate"}},{q="De ce se intorc goblinii la epava?",a="Venture Company a trimis recuperatori fiindca focul nu le-a distrus intreaga incarcatura. Acestia incearca sa recupereze lazile rezistente de provizii, inscriptionate pentru a fi trimise la unitatile lor centrale de procesare.",al={"de ce sunt aici recuperatorii","recuperatorii Venture Co","ce vor goblinii"}},{q="Ce se afla in lazile cu provizii?",a="Lazile poarta insemnele Venture Company Mining Division si contin resurse minerale marcate pentru rafinare si prelucrare in principalele lor uzine industriale.",al={"continutul lazii","ce se afla in lada","lada sigilata cu provizii"}},{q="Cine este Morin Cloudstalker?",a="Morin Cloudstalker este cercetas si urmaritor tauren, stationat la est de Bloodhoof Village. Sarcina lui este sa supravegheze incursiunile ostile din centrul Mulgoreului, in special pe cele ale Venture Company.",al={"cine este Morin","rolul lui Morin Cloudstalker"}},{q="Ce dezvaluie aceasta caravana despre Venture Company?",a="Acest lucru arata ca prezenta Venture Company in Mulgore nu se rezuma la o echipa de explorare, ci reprezinta o operatiune organizata de extractie industriala, cu linii de aprovizionare inarmate si retele centralizate de prelucrare.",al={"prezenta Venture Co in Mulgore","de ce sunt goblinii in Mulgore"}}},fx={["89fc7cfd"]={q="De ce vrea Morin Cloudstalker sa fie examinate lazile caravanei?",a="Morin si razboinicii sai au atacat prin surprindere caravana Venture Company de langa Stonebull Lake pentru a razbuna camarazii cazuti, au ars carele si au presupus ca focul va distruge tot ce era folositor. Vazand goblini cautatori de vechituri scormonind printre ramasite, si-a dat seama ca ceva valoros sau periculos supravietuise flacarilor. Are nevoie sa inspectezi lazile pentru a afla ce transporta Venture Company prin Mulgore si de ce se grabesc atat de mult sa recupereze marfa.",al={"de ce sa cercetez caravana","motivul lui morin cloudstalker","de ce sa caut lazile cu provizii"}}},fp="19,390,23.438.0,19.408.0,30.169.0,37.102.0,46.197.0,33.171.0,26.190.0,56.201.0"}
P.entries["quest:7493"] = {n="The Journey Has Just Begun"}
P.entries["quest:7497"] = {n="The Journey Has Just Begun",s="In Stormwind, Major Mattingly il recunoaste pe mestesugarul care a doborat-o pe Onyxia. El il invata mestesugul necesar pentru a confectiona o mantie din solzii ei.",h="In Stormwind, Major Mattingly il recunoaste pe mestesugarul care a doborat-o pe Onyxia.",kw={"black dragonflight","blackrock","pielarie","major mattingly","nefarian","onyxia","onyxia scale cloak","stormwind"},ang={["faction:Alliance"]="Ca erou din Alliance, duci victoria Stormwindului asupra lui Onyxia in ofensiva ce urmeaza impotriva fratelui ei, Nefarian, la Blackrock Mountain."},sec={{t="O maiestrie rara",b="Putini dintre cei care au contribuit la doborarea lui Onyxia pot prelucra si pielea ei. Cand un artizan cu maiestrie in prelucrarea pielii se prezinta la Major Mattingly in Stormwind, ofiterul intelege cat de importante vor fi aceste aptitudini in bataliile ce urmeaza."},{t="Protectie impotriva Black Dragonflight",b="Moartea lui Onyxia nu inlatura amenintarea aripii dragonilor negri. Major Mattingly il invata pe mestesugar sa prelucreze si sa coasa solzii ei intr-o capa din solzi de Onyxia. Haina protejeaza impotriva suflului de foc al fratelui ei, Nefarian, Lord of Blackrock."}},faq={{q="Cine ofera misiunea The Journey Has Just Begun?",a="Major Mattingly din Stormwind City le ofera acest lucru eroilor Alliance care au luptat in campania impotriva lui Onyxia si au atins maiestria in pielarie.",al={"cine ofera journey has just begun","de unde obtin journey has just begun","personajul care ofera misiunea journey has just begun"}},{q="Ce te invata aceasta misiune?",a="Major Mattingly ii invata pe tabacarii cu experienta sa confectioneze o mantie din solzi de Onyxia, folosind solzii lui Onyxia.",al={"ce reteta primesc","reteta pelerinei onyxia","recompensa pentru Marea calatorie abia a inceput"}},{q="De ce este necesara pelerina din solzi de Onyxia?",a="Pelerina este tratata pentru a-si feri purtatorul de suflul inflacarat al lui Nefarian, Lord of Blackrock.",al={"de ce am nevoie de pelerina Onyxia","la ce foloseste pelerina din solzi de Onyxia","protectie impotriva flacarii umbrelor"}},{q="Cine este Lord of Blackrock, mentionat de Major Mattingly?",a="Lord of Blackrock este Nefarian, un dragon negru puternic si fratele lui Onyxia. El domneste peste Blackrock Spire si continua planurile black dragonflight.",al={"cine este Lord of Blackrock","cine este Nefarian","avertismentul dragonului Mattingly"}},{q="De ce trebuie ca eroul sa fie tabacar pentru a primi aceste cunostinte?",a="Prelucrarea solzilor de dragon fara a le distruge protectia magica necesita priceperea avansata a unui maestru tabacar.",al={"de ce doar pielarit","poate oricine primi aceasta misiune","cerinta de pielar"}},{q="Moartea lui Onyxia rezolva amenintarea dragonilor negri din Stormwind?",a="Nu. Onyxia este moarta, dar fratele ei Nefarian inca stapaneste Blackrock Mountain si unelteste impotriva Alliance si a raselor muritoare.",al={"Stormwind este in siguranta acum","Onyxia a murit, ce urmeaza","ce se intampla cu zborul dragonilor negri dupa Onyxia"}}},fx={b42a6800={q="De ce iti ofera Major Mattingly aceste cunostinte?",a="Major Mattingly stie ca uciderea lui Onyxia a fost doar lovitura de inceput. Mama puilor a murit, dar neamul ei continua sa ameninte Azeroth din inaltimile lui Blackrock Mountain. Pentru a nimici haita dragonica neagra ramasa, campionii trebuie sa supravietuiasca flacarilor mistuitoare ale lui Nefarian insusi. Mattingly le impartaseste aceasta tehnica specializata, pentru ca eroii Alliance sa poata confectiona mantii de protectie din solzii lui Onyxia si sa duca razboiul la bun sfarsit.",al={"de ce te invata Mattingly","motivul lui Major Mattingly","motivul lui Mattingly"}}},fp="26,138,14.214.0,41.241.1,48.138.0,27.101.0,40.99.0,58.153.0,63.118.0,65.131.1"}
P.entries["quest:75"] = {n="The Legend of Stalvan",s="Investigatia asupra lui Stalvan Mistmantle te poarta din Duskwood pana la o casa izolata din sud-estul zonei Elwynn Forest. Marshal Haggard, un veteran in varsta, a carui vedere s-a inrautatit, te indruma spre un cufar de la etaj, in care se afla un teanc vechi de hartii, lasat in urma cand s-a mutat acolo.",h="Investigatia asupra lui Stalvan Mistmantle te poarta din Duskwood pana la o casa izolata din sud-estul zonei...",kw={"duskwood","elwynn forest","pagina de jurnal decolorata","forlorn spirit","marshal haggard","stalvan"},ang={["faction:Alliance"]="Dezvaluirea trecutului lui Stalvan scoate la iveala capitole intunecate, ascunse cu grija in tinuturile pastorale altminteri linistite din Elwynn.",["race:Human"]="Drumul lui Stalvan trece prin asezari umane obisnuite si slujeste drept poveste de avertizare despre izolare si rautate ascunse la vedere."},sec={{t="Podul unui veteran",b="Marshal Haggard locuieste departe de oras, la marginea sud-estica a Elwynn Forest, aproape de granitele Duskwood si Redridge. Cand s-a mutat in casa sa izolata, a gasit un cufar ascuns la etaj, plin cu pergamente vechi. Pe masura ce vederea i se inrautateste, ochii i se incetoseaza, iar el renunta sa mai incerce sa le citeasca, lasand documentele neatinse pana cand un anchetator vine sa intrebe despre Stalvan."},{t="Umbre persistente",b="Hartile lasate in cufarul de la etaj nu sunt simple lucruri de prin casa. Rascolirea lucrurilor lui Stalvan starneste in mod regulat magia nelinistita, care scoate la iveala un Forlorn Spirit legat de trecutul lui Mistmantle. Pagina de jurnal ascunsa inauntru consemneaza direct scrierile personale ale lui Stalvan si ofera dovezi concrete ca retrasul invatat si-a lasat amprenta in Elwynn inainte sa dispara."}},faq={{q="Cine este Marshal Haggard?",a="Marshal Haggard este un veteran in varsta, aproape orb, care traieste linistit intr-o cabana izolata din sud-estul lui Elwynn Forest. Pastreaza documente de mult uitate, descoperite in casa sa, care i-au apartinut lui Stalvan Mistmantle.",al={"marshal haggard","haggard elwynn","cine este haggard"}},{q="De ce ducea urma inapoi in Elwynn Forest?",a="Indiciile adunate in Darkshire si Moonbrook urmaresc ratacirile lui Stalvan prin tinuturile sudice ale Stormwind. Gospodaria lui Haggard adapostea hartii vechi lasate in urma de Stalvan.",al={"de ce Elwynn Forest","Stalvan in Elwynn","de ce sa mergi la Haggard"}},{q="Ce se afla in cufarul de la etaj?",a="Lada contine o pagina de jurnal decolorata, scrisa de Stalvan Mistmantle si pastrata intr-un teanc de pergamente pe care Haggard nu a reusit niciodata sa-l cerceteze cum se cuvine.",al={"cufar de la etaj","pagina de jurnal decolorata","ce se afla in cufar"}},{q="De ce ataca un spirit cand este deschis cufarul?",a="Un Forlorn Spirit bantuie relicvele vietii de odinioara a lui Stalvan si se manifesta cu violenta atunci cand un strain ii tulbura scrierile si amintirile personale.",al={"Forlorn Spirit","de ce ataca fantoma","fantoma din casa Haggard"}},{q="Cum ajuta aceasta la ancheta despre Stalvan?",a="Pagina decolorata ofera o dovada directa, scrisa chiar de Stalvan, care ajuta la reconstituirea povestii trecutului sau.",al={"misterul lui Stalvan","ce dezvaluie pagina","etapa din sirul de misiuni Stalvan"}},{q="De ce nu a putut Marshal Haggard sa citeasca singur documentele?",a="Vederea lui Haggard a devenit incetosata si slaba odata cu varsta, impiedicandu-l sa descifreze scrisul marunt sau sters de pe documentele decolorate.",al={"Haggard orb","de ce are Haggard nevoie de ajutor"}}},fx={["7284e072"]={q="De ce vrea Marshal Haggard ca acest lucru sa fie facut?",a="Marshal Haggard este un soldat batran, retras in liniste, dar inca pastreaza instinctele unui ofiter al tinutului. Cand vii sa afli adevarul despre Stalvan Mistmantle, el isi aminteste pergamentele aruncate in lada atunci cand a preluat casa. Desi nu are nimic de castigat personal din acest mister intunecat, vrea sa-ti ajute ancheta cum poate - chiar daca vederea lui slabita il impiedica sa examineze singur documentele.",al={"de ce sa-l ajut pe Haggard","motivul lui Marshal Haggard","de ce vrea Haggard jurnalul"}}},fp="21,280,17.391.0,17.382.1,23.216.0,45.162.0,34.157.0,50.144.0,48.111.1,53.140.0"}
P.entries["quest:750"] = {n="The Hunt Continues",s="Hunt Continues este un ritual de trecere timpuriu, incredintat de Grull Hawkwind in Camp Narache. Vanatorii aspiranti trebuie sa adune piei de puma de munte de pe colinele sudice, pentru a imbraca odraslele tribului si a-si repara corturile.",h="Hunt Continues este un ritual de trecere timpuriu, incredintat de Grull Hawkwind in Camp Narache.",kw={"camp narache","chief hawkwind","grull hawkwind","blanuri de puma de munte","red cloud mesa","vanatoare tauren","the hunt continues"},ang={["class:Hunter"]="Aceasta sarcina intareste principiile de baza ale vanatorii in campie: sa pandesti fiarele cu un scop, sa iei doar ceea ce iti trebuie si sa nu privesti niciodata animalele ca pe un simplu divertisment sau ca pe niste trofee.",["race:Tauren"]="Pentru tinerii tauren care ajung la maturitate in Red Cloud Mesa, sa invete ca fiecare parte a unei bestii trebuie sa slujeasca tribul - de la hrana la imbracaminte si adapost - este un ritual esential de trecere."},sec={{t="Scopul vanatorii",b="In Camp Narache, tinerii vanatori invata ca vanarea unei bestii nu este niciodata o simpla distractie sau o cautare de trofee. Grull Hawkwind le cere aventurierilor incepatori sa patrunda in dealurile sudice din Red Cloud Mesa pentru a urmari pumele de munte. In loc sa le puna la incercare doar priceperea in lupta, sarcina subliniaza responsabilitatea fata de comunitate si arata ca adevaratii vanatori trebuie sa le asigure provizii esentiale celor din poporul lor."},{t="Adapost pentru trib",b="Viata pe platou cere materiale rezistente, capabile sa infrunte intemperiile. Grull explica faptul ca pieile de puma sunt neaparat necesare pentru a coase hainele copiilor tribului si pentru a repara corturile uzate din piele din tot Camp Narache. Cel care dovedeste ca poate procura aceste piei pretioase castiga recunostinta batranilor, iar Grull promite sa-i duca personal tatalui sau, Chief Hawkwind, vestea despre contributiile dezinteresate ale vanatorului."}},faq={{q="De ce are tribul nevoie de blanuri de puma de munte?",a="Blanurile pumelelor de munte sunt resurse practice esentiale pentru Camp Narache. Grull Hawkwind explica faptul ca pieile sunt necesare pentru confectionarea hainelor calduroase pentru copiii tribului, precum si pentru repararea si intarirea corturilor satului.",al={"de ce sa vanam pume","la ce folosesc blanurile de puma","utilizarea blanurilor de puma de munte"}},{q="Cine ofera aceasta misiune?",a="Grull Hawkwind, un vanator de vaza din Camp Narache si fiul lui Chief Hawkwind, iti incredinteaza vanatoarea. El ii indruma pe aventurierii incepatori sa invete indatoririle esentiale pentru sprijinirea asezarii.",al={"cine ofera Hunt Continues","cel care da misiunea in Camp Narache"}},{q="Unde se gasesc pumele de munte?",a="Pumele de munte cutreiera crestele stancoase si dealurile domoale aflate chiar la sud de Camp Narache, pe Red Cloud Mesa.",al={"unde sunt pumele","locatia pumelor de munte","unde gasesti o puma de munte"}},{q="Ce legatura exista intre Grull Hawkwind si Chief Hawkwind?",a="Grull Hawkwind este fiul lui Chief Hawkwind, conducatorul tribal din Camp Narache. Grull promite sa vorbeasca in favoarea ta cu tatal sau si sa-i povesteasca despre faptele tale generoase, daca ii aduci blanurile necesare.",al={"cum sa-l impresionezi pe Chief Hawkwind","fiul lui Chief Hawkwind"}},{q="Ce invata aceasta vanatoare despre traditia taurenilor?",a="Pentru tauren, vanatoarea nu este niciodata privita ca un sport sau ca o ocazie de a obtine trofee. Fiecare fiara luata de pe pamant trebuie sa sustina comunitatea, cinstind campiile prin folosirea pielii, a carnii si a oaselor pentru a asigura supravietuirea tribului.",al={"filozofia vanatorii tauren","de ce se vaneaza in mulgore"}},{q="De ce sunt blanurile de puma de munte atat de pretioase?",a="Blanurile pumelelor sunt groase, rezistente si foarte potrivite pentru a infrunta intemperiile campiilor batute de vant. Fiindca le tin de cald copiilor mici si sunt suficient de trainice pentru a carpi locuintele, sunt foarte pretuite de batranii satului.",al={"sunt valoroase blanurile de puma","de ce sunt apreciate blanurile de puma"}}},fp="18,230,23.420.0,21.427.0,46.228.0,22.197.0,37.124.0,54.202.0,49.220.0,55.228.0"}
P.entries["quest:751"] = {n="The Ravaged Caravan",s="Investigarea unui vehicul de transport avariat din Mulgore dezvaluie ca industriasii goblini si-au stabilit ilegal un punct de sprijin pe teritoriul taurenilor. Recuperand documente dintr-o lada sigilata, cercetasii confirma ca Venture Company jefuieste sistematic bogatiile minerale ale tinutului. Descoperirea ii mobilizeaza pe Bloodhoof Outrunners sa-si apere activ campiile stramosesti.",h="Investigarea unui vehicul de transport avariat din Mulgore dezvaluie ca industriasii goblini si-au stabilit...",kw={"bloodhoof village","morin cloudstalker","mulgore","outrunners","caravana jefuita","ladaie cu provizii","venture co","documentele venture co"},ang={["class:Druid"]="Druizii considera sacru echilibrul pamantului, asa ca exploatarea miniera distructiva a Venture Company, care lasa in urma fum si devastare, este o profanare ce trebuie curatata.",["faction:Horde"]="Horde se bazeaza pe loialitatea si stabilitatea din Mulgore; a lasa cartelurile de negustori straini sa-i devasteze dealurile ar ameninta insasi siguranta Thunder Bluff.",["profession:Mining"]="Minereurile de calitate superioara ingramadite in lada dovedesc ca dealurile estice din Mulgore ascund filoane subterane bogate, pe care strainii se grabesc sa le exploateze.",["race:Tauren"]="Pentru tauren, sa vada utilaje industriale grosolane sfasiind campiile ancestrale din Mulgore este o insulta la adresa Earth Mother si un act de razboi impotriva pacii abia dobandite."},sec={{t="Dovezi de exploatare",b="Epava unei caravane devastate, la est de Bloodhoof Village, spune o poveste tulburatoare. Intr-o lada de provizii sigilata se afla un depozit consistent de minereu si minerale extrase, alaturi de un teanc legat de documente ale Venture Company. Actele dovedesc fara putinta de tagada ca lacoma Venture Company a inceput o exploatare miniera neautorizata, adanc in vaile linistite din Mulgore."},{t="Veghea Outrunners",b="Morin Cloudstalker si ceilalti Outrunners ai sai au vegheat cu prudenta asupra hotarelor din Mulgore, fiind atenti la factiunile din afara care ar putea exploata patria lor pasnica. Documentele recuperate confirma cele mai mari temeri ale lui Morin: fumul care se ridica deasupra poalelor estice anunta o invazie comerciala in plina escaladare. Taurenii nu au de ales si trebuie sa-i respinga pe profanatori inainte ca dealurile lor sa fie secatuite cu totul."}},faq={{q="Ce se afla in lada cu provizii sigilata?",a="Deschiderea lazilor dezvaluie o multime de minereu extras, minerale brute si un teanc de documente ale Venture Company care descriu operatiunile acesteia.",al={"prada din lada","ce contine lada","continutul lazii"}},{q="Cine este Morin Cloudstalker?",a="Morin Cloudstalker este un tauren Outrunner aflat pe drumul de la est de Bloodhoof Village spre granita cu Barrens, insarcinat sa patruleze Mulgore si sa urmareasca amenintarile straine.",al={"cine este Morin","rolul lui Morin Cloudstalker","Morin, iscoada"}},{q="De ce se afla Venture Company in Mulgore?",a="Venture Company urmareste sa exploateze cu cruzime bogatele resurse naturale si filoanele de minereu din Mulgore, sapand in dealuri fara sa tina seama de pamant sau de locuitorii sai nativi.",al={"de ce sunt goblinii aici","scopul Venture Co in Mulgore","ce vor goblinii"}},{q="De unde a venit caravana?",a="Caravana apartinea Venture Company si transporta minereu extras si documente operationale din exploatarile lor de la poalele muntilor, inainte sa fie distrusa pe drum.",al={"a cui era caravana","originea caravanei","cine a atacat caravana"}},{q="Incotro duce aceasta investigatie?",a="Inarmat cu documentele, Morin Cloudstalker ii indruma pe razboinici sa infrunte direct conducerea Venture Company si sa-i demonteze operatiunea miniera de la poalele muntilor din est.",al={"ce urmeaza","urmatoarea misiune dupa Ravaged Caravan","continuarea aventurii caravanei"}},{q="De ce ii ameninta asta pe tauren?",a="Tauren considera pamantul sacru si o venereaza pe Earth Mother. Exploatarea miniera iresponsabila si poluarea industriala provocate de Venture Company pangaresc in mod direct peisajul nealterat din Mulgore.",al={"de ce le pasa taurenilor","amenintarea Venture Co","amenintare pentru Mulgore"}}},fp="19,373,24.371.0,21.434.0,39.146.0,26.176.0,38.180.0,32.169.0,40.178.1,34.178.0"}
P.entries["quest:752"] = {n="A Humble Task",s="A Humble Task este un ritual timpuriu al datoriei, incredintat de Chief Hawkwind in Camp Narache. In timp ce seful tribului se ocupa de chestiuni presante ale clanului pe Red Cloud Mesa, ii cere unui tanar aventurier sa mearga spre sud-est si sa-si viziteze mama in varsta la fantana locala. Cererea subliniaza responsabilitatea fata de comunitate, respectul fata de batrani si armonia cotidiana, esentiale pentru modul de viata tauren.",h="A Humble Task este un ritual timpuriu al datoriei, incredintat de Chief Hawkwind in Camp Narache.",kw={"o sarcina modesta","camp narache","chief hawkwind","greatmother hawkwind","mulgore","red cloud mesa","fantana cu apa"},ang={["faction:Horde"]="Firea linistita si pastorala a sarcinilor din Narache scoate in evidenta contrastul dintre filosofia comunitara pasnica a taurenilor si duritatea aspra, de supravietuitor, intalnita in restul Horde abia nascute.",["race:Tauren"]="Pentru tinerii viteji tauren, raspunsul la chemarea Chieftainului demonstreaza principiile de baza ale invataturilor Earth Mother: respectul fata de cei in varsta si devotamentul neclintit fata de binele comun al tribului."},sec={{t="Armonie si datorie comunitara",b="La umbra lui Camp Narache, se asteapta ca fiecare membru al tribului sa-si faca partea si sa contribuie la armonia vietii. Pentru tinerii tauren care ajung la maturitate, datoria fata de trib nu se masoara doar in priceperea de a lupta cu quilboar sau pradatori; ea incepe cu responsabilitati sociale elementare. Chief Hawkwind le da chiar el acest exemplu: tinut la post de indatoririle administrative si de conducerea apararii, isi pune increderea in aventurierii incepatori, carora le incredinteaza ocrotirea batranilor vulnerabili din comunitate."},{t="Fantana de la sud-est de Narache",b="Red Cloud Mesa din Mulgore se bazeaza pe fantanile naturale de apa, esentiale, imprastiate dincolo de perimetrul taberei. Dis-de-dimineata, Greatmother Hawkwind a parasit satul nepazit pentru a aduce apa proaspata de la izvorul din sud-est. Intr-un tinut pandit de vietati teritoriale si de quilboarii Bristleback care inainteaza, absenta vreme de ore a unei batrane starneste o ingrijorare tacuta, iar Hawkwind trimite ajutoare pentru a se asigura ca nu a patit nimic."}},faq={{q="Cine ofera aceasta misiune si unde il gasesc?",a="Chief Hawkwind, conducatorul taberei Camp Narache de pe Red Cloud Mesa, in Mulgore, ofera misiunea. El se afla in pavilionul central al taberei, de unde supravegheaza treburile locale.",al={"cine ofera A Humble Task","unde preiau misiunea","locatia lui chief hawkwind"}},{q="Unde se afla Greatmother Hawkwind?",a="Greatmother Hawkwind se afla chiar la sud-est de Camp Narache, avand grija de fantana de apa aflata in partea mai joasa a platoului.",al={"locatia lui Greatmother Hawkwind","unde este mama","locatia fantanii cu apa"}},{q="De ce nu isi viziteaza Chief Hawkwind mama personal?",a="Chief Hawkwind trebuie sa ramana la Camp Narache pentru a se ocupa de problemele urgente ale tribului si a-i indruma pe tinerii viteji. In calitate de sef de trib, se bazeaza pe responsabilitatea colectiva a tribului si are incredere ca aventurierii promitatori se vor ocupa de treburile satului in locul sau.",al={"de ce nu poate pleca seful","de ce nu verifica hawkwind","chief hawkwind are treaba"}},{q="Este Greatmother Hawkwind in pericol la fantana?",a="Desi campiile din jur sunt pline de pume de munte si strideri agresivi, Greatmother Hawkwind este in siguranta langa fantana, placut surprinsa ca cineva si-a facut timp sa verifice ce mai face o persoana in varsta.",al={"este in siguranta","a fost atacata strabunica","pericol la fantana cu apa"}},{q="Ce semnificatie culturala are aceasta misiune pentru Tauren?",a="Cultura tauren pune mare pret pe familie, coeziunea comunitatii si respectul fata de batrani. Misiunea ii invata pe tinerii eroi ca adevarata putere isi are radacinile in slujirea cu smerenie si in ocrotirea familiei, nu in goana dupa gloria personala.",al={"sarcina umila din cultura tauren","de ce este aceasta o sarcina umila","batranii tauren"}},{q="Ce se intampla dupa ce o gasesti pe Greatmother Hawkwind?",a="Dupa ce vorbesti cu Greatmother Hawkwind, ea incheie sarcina si iti cere sa o ajuti in continuare, ducand ulciorul plin cu apa inapoi in tabara.",al={"misiunea urmatoare","continuarea pentru a humble task","ce fac dupa ce o gasesc pe mama"}}},fx={b1d313d3={q="De ce vrea Chief Hawkwind sa verifici ce face mama lui?",a="Mama lui, in varsta, a plecat dis-de-dimineata din Camp Narache sa aduca apa din fantana aflata la sud-est si lipseste de foarte multa vreme. Viata taurenilor se bazeaza pe responsabilitate colectiva si grija reciproca, asa ca, desi Hawkwind se teme pentru siguranta ei, indatoririle de sef de trib il tin legat de tabara.",al={"de ce vrea hawkwind sa fac asta","motivul lui chief hawkwind","de ce sa-l verific pe greatmother hawkwind"}}},fp="13,384,25.486.0,29.432.0,47.166.0,38.125.0,55.242.0,46.215.0,64.231.0,48.151.0"}
P.entries["quest:753"] = {n="A Humble Task",s="A Humble Task este un ritual de initiere in slujba comunitatii, in Red Cloud Mesa, unde un batran pune la incercare umilinta si sarguinta unui aventurier aflat la inceput de drum. Ducand apa proaspata de la fantana peste campii, pana la conducatorul din Camp Narache, tinerii tauren invata ca slujirea poporului lor incepe cu cele mai simple indatoriri.",h="A Humble Task este un ritual de initiere in slujba comunitatii, in Red Cloud Mesa, unde un batran pune la...",kw={"camp narache","chief hawkwind","greatmother hawkwind","sarcina umila","mulgore","red cloud mesa","ritualurile Mamei Pamant","ulcior cu apa"},ang={["faction:Horde"]="Lectiile familiei Hawkwind arata cum taurenii isi pastreaza solidaritatea si supravietuiesc in Mulgore, alcatuind o piatra de temelie pasnica, dar neclintita, a Hordei lui Thrall.",["race:Tauren"]="Aducerea apei pentru batranii tai intruchipeaza virtutea fundamentala a taurenilor, grija fata de comunitate, si arata ca esti pregatit sa urmezi calea Earthmother."},sec={{t="Vitalitatea tinerilor",b="Greatmother Hawkwind a strabatut multe carari de-a lungul vietii sale indelungate si, desi spiritul ii ramane neclintit, picioarele nu o mai poarta peste campii cu viteza din tinerete. Aflata langa fantana din tinuturile sudice ale Red Cloud Mesa, isi indeplineste indatoririle cu rabdare si hotarare. Cand ii ies in cale aspiranti la rangul de aparatori ai tribului, le indreapta energia tineretii spre nevoile practice ale comunitatii, oferindu-le ocazia sa-si dovedeasca valoarea prin slujire, nu prin violenta."},{t="Slujire pentru trib",b="Sarcina ii cere novicei sa duca un ulcior plin cu apa inapoi, spre nord-vest, la Camp Narache, si sa i-l prezinte direct conducatorului asezarii, Chief Hawkwind, care se intampla sa fie fiul Marii Mame. In societatea tauren, supravietuirea pe campiile aride din Mulgore depinde de munca in comun si de rezerve sigure de apa proaspata. Sa-ti arati respectul fata de batranii comunitatii purtandu-le poverile este considerat piatra de temelie pentru a deveni un adevarat protector al tribului."},{t="Un drum spre Thunder Bluff",b="Chief Hawkwind vede mai mult decat o simpla corvoada indeplinita atunci cand un tanar pribeag vine cu apa de la mama sa. Potrivit obiceiurilor tauren, pregatirea fiecaruia de a-si apara poporul in tinuturi indepartate incepe cu umilinta si dorinta nesilita de a ajuta. Dovedind aceasta disciplina tacuta, initiatul ii atrage atentia capeteniei si primeste o recomandare pentru stravechile Rites of the Earthmother, adevaratele incercari spirituale care deschid portile spre Thunder Bluff."}},faq={{q="Cine este Greatmother Hawkwind?",a="Greatmother Hawkwind este o batrana a familiei Hawkwind, stationata la fantana din Red Cloud Mesa. Este mama conducatorului din Camp Narache, Chief Hawkwind, si ii invata pe tinerii tauren smerenia si valorile tribale.",al={"Greatmother Hawkwind","cine da A Humble Task","batrana Hawkwind"}},{q="Unde se afla fantana?",a="Fantana se afla la sud-est de Camp Narache, pe campiile inierbate din Red Cloud Mesa. Alaturi sunt ulcioare cu apa proaspata de fantana, pe care calatorii si ingrijitorii taberei le pot duce inapoi.",al={"locatia fantanii cu apa","unde este fantana","gaseste ulciorul cu apa"}},{q="Cine este Chief Hawkwind?",a="Chief Hawkwind este capetenia care conduce Camp Narache, pe Red Cloud Mesa. El indruma antrenamentul si ritualurile spirituale ale tinerilor tauren, pregatindu-i sa plece si sa slujeasca intregul trib din Mulgore.",al={"Chief Hawkwind","cine este seful","conducatorul Camp Narache"}},{q="De ce este aceasta corvoada tratata ca o proba importanta?",a="Cultura tauren pune mare pret pe umilinta, sprijinul comunitar si respectul fata de batrani. Indeplinirea sarcinilor obisnuite, deloc spectaculoase, dovedeste ca un aventurier isi pasa de bunastarea poporului sau, nu doar de gloria personala in lupta.",al={"de ce sa cari apa","de ce o sarcina umila","este aceasta misiune importanta"}},{q="Ce urmeaza dupa finalizarea misiunii A Humble Task?",a="Indeplinirea acestei sarcini ii dovedeste disciplina ta lui Chief Hawkwind, care apoi te indruma sa treci prin Rites of the Earthmother - o serie de incercari traditionale pe care trebuie sa le indeplineasca toti taurenii ajunsi la maturitate.",al={"ce urmeaza","urmatoarea misiune","dupa o sarcina umila"}},{q="Unde duce in cele din urma acest drum?",a="Castigarea respectului batranilor din Camp Narache te pregateste sa lasi in urma mesa izolata si sa calatoresti prin campiile intinse ale tinutului Mulgore, indreptandu-te in cele din urma spre platourile inalte ale capitalei, Thunder Bluff.",al={"destinatia viitoare","incotro mergem","scopul Thunder Bluff"}}},fx={["57bce500"]={q="De ce vrea Greatmother Hawkwind ca acest lucru sa fie facut?",a="Greatmother Hawkwind recunoaste ca picioarele ei imbatranite nu mai au vigoarea de odinioara, iar treburile zilnice din Red Cloud Mesa au devenit lente si istovitoare. Mai presus de toate, ea vede in aceasta insarcinare obisnuita o lectie morala esentiala pentru tine. Sa-i duci apa potabila fiului ei, Chief Hawkwind, este o prima incercare care arata daca ai umilinta, rabdarea si spiritul comunitar asteptate de la un adevarat slujitor al tribului.",al={"motivul lui Greatmother Hawkwind","de ce sa-i duci apa lui Chief Hawkwind","de ce o sarcina umila"}},b511fd77={q="La ce foloseste Water Pitcher?",a="Water Pitcher este un vas simplu de lut, umplut cu apa proaspata din fantana de pe Red Cloud Mesa pentru a asigura apa curata taberei Camp Narache. Transportarea lui iti pune la incercare devotamentul fata de treburile comunitatii, asigurandu-te ca pana si aventurierii incepatori invata cat de important este sa-si sustina neamul inainte de a cauta gloria martiala.",al={"scopul urciorului cu apa","de ce un urcior cu apa","ce este urciorul"}},["19ad5d96"]={q="De ce te roaga Greatmother Hawkwind pe tine in loc sa se ocupe chiar ea?",a="Greatmother Hawkwind este batrana si recunoaste ca picioarele nu-i mai au puterea de odinioara, asa ca ii ia mult mai mult sa care urcioare grele. Cand se apropie un novice in putere, precum tine, profita de ocazie atat pentru a-si usura povara, cat si pentru a-ti pune la incercare dorinta de a face munca de zi cu zi, lipsita de stralucire, pentru tabara.",al={"de ce nu Marea Bunica","de ce imi ceri apa","de ce nu poate Hawkwind sa ia apa"}}},fp="13,288,21.500.0,20.469.0,27.468.0,28.220.0,32.178.0,22.203.0,47.236.0,42.202.0,37.209.0"}
P.entries["quest:754"] = {n="Winterhoof Cleansing",s="Winterhoof Cleansing este un ritual incredintat aventurierilor Horde de catre Mull Thunderhorn, in Bloodhoof Village. Dupa ce operatiunile goblinilor au poluat izvoarele locale, un totem consacrat trebuie dus pe teritoriul Venture Company pentru a purifica Winterhoof Water Well. Refacerea acestui izvor este un prim pas esential in vindecarea apelor otravite din centrul Mulgore.",h="Winterhoof Cleansing este un ritual incredintat aventurierilor Horde de catre Mull Thunderhorn, in Bloodhoof...",kw={"bloodhoof village","purificare","mulgore","mull thunderhorn","otravire","totem","venture company","fantana de apa","winterhoof"},ang={["class:Druid"]="Faptul ca fauna insetata se intoarce imediat la izvorul purificat dovedeste cat este de important sa vindeci natura oriunde civilizatia risca s-o distruga.",["class:Shaman"]="Canalizarea spiritelor prin totemuri pentru a inversa pangarirea industriala nenaturala reprezinta scopul fundamental al legaturii unui saman cu apele elementale.",["faction:Horde"]="Asigurarea aprovizionarii cu apa proaspata a Mulgore stabilizeaza tinuturile centrale ale taurenilor recent stabiliti si intareste pilonul sudic al tinerei Horde.",["race:Tauren"]="Fantanile din Mulgore sunt datatoare de viata si sacre, daruri ale Earth Mother; apararea lor impotriva lacomiei goblinilor este atat o datorie civica, cat si o obligatie sfanta pentru fiecare tauren."},sec={{t="Un tinut pustiit",b="Campiile inverzite din Mulgore depind de o retea delicata de fantani ancestrale pentru a sustine atat vanatul salbatic, cat si triburile tauren raspandite prin tinut. Recent, mercenarii industriali nemilosi ai Venture Company s-au mutat pe dealurile domoale de la sud-est de Bloodhoof Village. Operatiunile lor au contaminat panzele freatice locale, lasand Winterhoof Water Well poluata si toxica. Fiarele salbatice evita apa otravita, iar taberele din apropiere se confrunta cu o criza iminenta daca miasma se raspandeste si mai mult prin pamant."},{t="Ritualul apelor purificatoare",b="Pentru a combate mizeria industriala, Mull Thunderhorn sculpteaza si vrajeste un totem ritualic de purificare, incarcat cu binecuvantarile lui Earth Mother. Insa aducerea acestui leac cere infruntarea gorilelor inarmate ale Venture Company, care si-au insusit izvorul. Asezand totemul chiar la gura fantanii, un aventurier alunga scurgerile toxice, ingaduind apei curate, datatoare de viata, sa tasneasca din nou din adancurile pamantului."}},faq={{q="Unde se afla Winterhoof Water Well?",a="Fantana Winterhoof Water Well se afla in dealurile de la sud-est de Bloodhoof Village, in Mulgore. Este puternic pazita de muncitori goblini si mercenari care lucreaza pentru Venture Company.",al={"locatia izvorului winterhoof","unde se afla winterhoof well","cum gasesti winterhoof well"}},{q="De ce a fost otravita fantana?",a="Venture Company si-a infiintat in apropiere operatiunile miniere si de excavare, facand ca deseurile si reziduurile industriale toxice sa se infiltreze direct in acvifer si sa faca izvorul natural de nebaut pentru fauna locala si Tauren.",al={"cine a otravit apa","de ce este murdara fantana","fantana Venture Company"}},{q="Cine este Mull Thunderhorn?",a="Mull Thunderhorn este un batran spiritual aflat in Bloodhoof Village. Fiind profund conectat la sanatatea pamantului, el creeaza totemuri ceremoniale pentru a anula devastarea mediului provocata de invadatorii din afara.",al={"cine este Mull","rolul lui Mull Thunderhorn"}},{q="Ce se intampla dupa purificarea fantanii?",a="Dupa ce apa din fantana Winterhoof Water Well devine limpede si animalele salbatice incep sa o bea din nou fara pericol, Mull Thunderhorn iti atrage atentia asupra altor fantani contaminate din Mulgore, incepand cu Thunderhorn Totem.",al={"ce urmeaza","dupa Winterhoof Cleansing","ce face Mull in continuare"}},{q="Cine sunt paznicii de la fantana?",a="Fantana este ocupata de muncitori si angajati ai Venture Company, un sindicat lipsit de scrupule, condus de goblini, care exploateaza resursele naturale ale tinuturilor fara sa tina seama de ecosistemul local.",al={"cine pazeste Winterhoof Well","ce dusmani sunt la fantana"}},{q="Cum functioneaza totemul purificarii?",a="Sculptat cu rituri sacre tauren si ritualuri de protectie, totemul se foloseste de spiritele naturii si de binecuvantarile Earth Mother pentru a curata de poluantii chimici nenaturali izvorul de la care provine apa.",al={"poveste despre totemul purificarii","cum functioneaza totemul lui mull"}}},fx={["16ee77f0"]={q="De ce vrea Mull Thunderhorn ca Winterhoof Water Well sa fie purificata?",a="Winterhoof Water Well este vitala pentru echilibrul si supravietuirea Mulgore. Apa ei a fost contaminata, punand in pericol atat vietuitoarele locale, cat si triburile care depind de ea. Mull Thunderhorn a pregatit un totem consacrat pentru purificare, dar puterea lui trebuie adusa chiar la fata locului, pentru a vindeca apele si a restabili armonia pamantului.",al={"de ce sa purifici fantana winterhoof","motivul lui mull thunderhorn","de ce sa purifici apa din winterhoof"}}},fp="20,358,16.505.0,30.432.0,43.191.0,32.227.0,24.205.0,40.212.1,31.195.0,34.192.0"}
P.entries["quest:7541"] = {n="Service to the Horde",s="Pandantivul cu nestemate se afla acum la Zor Lonetree, in Orgrimmar, dus acolo dupa Report to Zor, iar Zor mai are un lucru sa-ti spuna.",h="Pandantivul cu nestemate se afla acum la Zor Lonetree, in Orgrimmar, dus acolo dupa Report to Zor, iar Zor...",kw={"dustwallow marsh","pandantiv","report to zor","slujba pentru Horde","zor lonetree"},sec={{t="Zor Lonetree din Orgrimmar",b="Ai dus pandantivul cu nestemate la Zor Lonetree, in Orgrimmar, iar acum se afla la Zor. Intoarce-te la Zor Lonetree si vei mai afla despre ce ai facut pentru Horde."},{t="Ultimul cuvant al lui Zor",b="Zor spune ca savantii vor avea nevoie de timp pentru a studia pandantivul. Pentru serviciile tale aduse lui Horde, Zor iti ofera un mic dar si spune ca faptele tale iti aduc onoare tie si lui Horde."}},faq={{q="Cine are acum pandantivul?",a="Zor Lonetree din Orgrimmar, dupa ce ai dus obiectul acolo de la Nazeer Bloodpike din Brackenwall Village.",al={"cine ia pandantivul","cine ofera aceasta misiune","rolul lui zor lonetree"}},{q="Ce misiune preceda aceasta?",a="Urmeaza Report to Zor, in care ai dus pandantivul cu bijuterii la Zor Lonetree.",al={"ce misiune a fost inainte","conditie prealabila pentru service to the horde","misiunea precedenta"}}},fp="20,126,25.185.0,15.186.1,24.99.0,29.77.0"}
P.entries["quest:755"] = {n="Rites of the Earthmother",s="Rites of the Earthmother marcheaza inceputul calatoriei spirituale a unui initiat pe Red Cloud Mesa. Indrumati de Chief Hawkwind, calatorii il cauta pe Seer Graytongue in dealurile din sudul Camp Narache. Indeplinirea acestor ceremonii venerabile este considerata o incercare esentiala de initiere pentru taurenii care ajung la maturitate.",h="Rites of the Earthmother marcheaza inceputul calatoriei spirituale a unui initiat pe Red Cloud Mesa.",kw={"camp narache","chief hawkwind","earthmother","red cloud mesa","ritualurile earthmother","seer graytongue","tauren"},ang={["class:Druid"]="Candidatii la druidism isi incep calea armoniei cu natura respectand indrumarea sacra a batranilor tribului si a clarvazatorilor.",["class:Shaman"]="Pentru viitorii shamani, indeplinirea ritualurilor binecuvantate de vizionarii tribului este un prim pas esential catre comuniunea cu elementele si spiritele din Mulgore.",["faction:Horde"]="Intelegerea acestor incercari sacre ofera o perspectiva asupra inimii spirituale a aliatilor tauren care s-au alaturat de curand Horde.",["race:Tauren"]="Rites of the Earthmother reprezinta calatoria spirituala fundamentala pentru tinerii tauren, punandu-le la incercare pregatirea de a-si sluji tribul si de a o venera pe Earthmother."},sec={{t="Pragul incercarilor",b="Pe Red Cloud Mesa, Chief Hawkwind ii indruma catre Seer Graytongue pe tinerii tauren care cauta sa se dovedeasca. Locuind in colinele linistite aflate chiar la sud de Camp Narache, Graytongue vegheaza asupra inceputurilor spirituale ale tinerilor. Aceasta calatorie simpla marcheaza pragul oficial dintre viata obisnuita din tabara si angajamentele serioase impuse de traditia tribala."},{t="Imbratisarea Mamei-Pamant",b="Earthmother este esentiala pentru credintele despre creatie si viata de zi cu zi a taurenilor. Ritualurile ei sunt incercari sacre de maturitate, rezilienta si profunzime spirituala. Asa cum ii avertizeaza Seer Graytongue pe toti cei care ajung la sanctuarul sau, pornirea pe calea Rites of the Earthmother nu este o treaba usoara si cere devotament deplin fata de traditiile platoului."}},faq={{q="Cine ofera misiunea Rites of the Earthmother?",a="Misiunea este oferita de Chief Hawkwind in Camp Narache, care ii indruma pe tinerii aventurieri sa-l caute pe Seer Graytongue in dealurile din apropiere.",al={"cine incepe Rites of the Earthmother","cel care ofera misiunea"}},{q="Unde il pot gasi pe Seer Graytongue?",a="Seer Graytongue locuieste in dealurile aflate chiar la sud de Camp Narache, in Red Cloud Mesa din Mulgore.",al={"unde se afla Seer Graytongue","locatia lui Graytongue","gaseste-l pe Graytongue"}},{q="Ce sunt Rites of the Earthmother?",a="Rites of the Earthmother sunt incercari sacre traditionale de trecere, pe care tinerii tauren le parcurg pentru a-si dovedi intelepciunea, puterea si devotamentul fata de poporul si credintele lor.",al={"ce sunt ritualurile Earthmother","povestea incercarilor Earthmother"}},{q="Cine este Seer Graytongue?",a="Seer Graytongue este un batran spiritual respectat, care locuieste la sud de Camp Narache si supravegheaza initiatii, calauzindu-i prin incercarile sacre ale Earth Mother.",al={"cine este Seer Graytongue","rolul lui Graytongue"}},{q="Cine este Chief Hawkwind?",a="Chief Hawkwind este conducatorul tribal al Camp Narache, aflat pe Red Cloud Mesa, si are sarcina de a-i pregati pe tinerii tauren inainte de a-i trimite la vizionari.",al={"cine este Chief Hawkwind","rolul lui Hawkwind"}},{q="Ce este necesar pentru a indeplini aceasta sarcina?",a="Trebuie doar sa calatoresti spre sud din Camp Narache, in dealuri, si sa vorbesti cu Seer Graytongue pentru a-ti anunta ca esti gata de probe.",al={"ce trebuie sa fac","cum sa termin misiunea"}}},fp="24,304,27.356.0,25.352.0,45.141.0,33.108.0,38.172.0,23.157.0,22.155.0,39.135.0"}
P.entries["quest:756"] = {n="Thunderhorn Totem",s="Thunderhorn Totem este o sarcina primita de la Mull Thunderhorn, in Bloodhoof Village, pentru a confectiona un totem sacru de purificare. Pentru a combate poluarea raspandita in fantanile de apa din Mulgore de goblini, tinerii campioni Horde trebuie sa adune gheare naturale de la pradatorii campiilor si sa lege puterea primordiala a pamantului de lemnul ritualic.",h="Thunderhorn Totem este o sarcina primita de la Mull Thunderhorn, in Bloodhoof Village, pentru a confectiona...",kw={"bloodhoof village","purificare","gheare de cougar","cougar de campie","mulgore","mull thunderhorn","vanator de preerie","gheare de vanator","thunderhorn totem","fantana"},ang={["class:Hunter"]="Pentru a strange ghearele, trebuie sa intelegi comportamentul fiarelor de prada autohtone ale campiilor si sa cinstesti vanatul, pastrand astfel echilibrul ecosistemului.",["class:Shaman"]="Restaurarea totemica se bazeaza pe invocarea spiritelor vii ale pamantului pentru a curata apa corupta de activitati artificiale si necugetate.",["race:Tauren"]="Apararea acviferelor din Mulgore impotriva exploatarii de catre straini este o datorie tribala sacra, care reflecta porunca Earth Mother de a trai in echilibru, nu de a prada."},sec={{t="Vanatoarea pradatorilor campiilor",b="Pe masura ce exploatarea industriala a Venture Company otraveste pretioasele surse de apa din Mulgore, Mull Thunderhorn se grabeste sa pregateasca leacuri. Pentru a crea Thunderhorn Cleansing Totem sunt necesare esentele naturale ale celor mai iscusiti vanatori ai campiilor: pradatorii stepelor si pumele de ses. Luand ghearele acestor pradatori care cutreiera la est si la vest de Bloodhoof Village, ritualul canalizeaza in totem vigoarea pradatoare pura si neintinata a vietuitoarelor."},{t="Natura vanatorii",b="Traditia Tauren face o deosebire profunda intre vanatoarea pentru hrana sau echilibrul spiritual si jefuirea fara masura practicata de goblini. Mull subliniaza ca puritatea cu care vaneaza pradatorii bastinasi este esentiala pentru purificarea pamantului corupt. In timp ce masinariile goblinilor pangaresc izvoarele cu petrol si deseuri industriale, puterea naturala a fiarelor care se lupta cu tinutul ofera catalizatorul spiritual necesar pentru a reface Thunderhorn Water Well."}},faq={{q="De ce are Mull Thunderhorn nevoie de gheare de pradator?",a="Mull foloseste ghearele de prairie stalker si de pume de campie pentru a canaliza spiritul pur, primordial si pradator al campiilor intr-un totem purificator. El crede ca spiritul pur al vanatorilor naturali contracareaza coruptia artificiala, industriala.",al={"de ce gheare","scopul ghearelor de stalker","la ce folosesc ghearele de puma"}},{q="Cine corupe apa din Mulgore?",a="Goblinii din Venture Company care opereaza in Mulgore polueaza pamantul si apa. Extractia iresponsabila a resurselor si instalatiile lor miniere deverseaza mal toxic in acviferele care alimenteaza fantanile tribale.",al={"cine a contaminat fantana","de ce este fantana otravita","ce a otravit Mulgore"}},{q="Unde pot fi gasiti vanatorii de preerie si pumelor de campie?",a="Ambele fiare cutreiera campiile deschise din centrul Mulgore, raspandindu-se mai ales prin savanele ondulate aflate chiar la est si la vest de Bloodhoof Village.",al={"locatia lui Stalker","unde gasesti pumele","locatiile ghearelor de puma"}},{q="Ce se intampla dupa confectionarea Thunderhorn Totem?",a="Dupa ce Mull sculpteaza si incanta totemul folosind ghearele, te trimite direct la Thunderhorn Water Well, contaminata, pentru a indeplini ritualul de purificare si a alunga otrava.",al={"ce urmeaza","dupa Thunderhorn Totem","continuarea totemului"}},{q="Ce legatura are aceasta cu purificarea anterioara de la Winterhoof Well?",a="Aceasta face parte dintr-un efort tribal de durata pentru a ocroti apele sacre din Mulgore. Mai intai a fost purificata fantana Winterhoof Water Well, iar acum contaminarea ameninta fantana Thunderhorn, mai la nord.",al={"legatura cu Winterhoof","misiunea anterioara a totemului"}},{q="De ce nu folosesc taureni leacuri din plante in locul ghearelor de animale?",a="Arta ritualica tauren foloseste aspectele elementale si fizice distincte ale naturii. Puritatea taietoare a pradatorilor de varf ofera forta spirituala activa si combativa, necesara in mod special pentru a razbate prin otrava industriala agresiva a goblinilor.",al={"de ce nu merg ierburile","materiale pentru totemuri samanice"}}},fx={cb047e40={q="De ce vrea Mull Thunderhorn ca acest lucru sa fie facut?",a="Thunderhorn Water Well este tot mai contaminata de la o ora la alta, otravita de operatiunile nechibzuite ale goblinilor din apropiere. Mull Thunderhorn trebuie sa faureasca un totem sacru de purificare, pentru a curata fantana inainte ca intinarea sa se raspandeasca mai departe prin pamant si sa-i vatame poporul.",al={"de ce vrea Mull asta","motivul lui Mull Thunderhorn","de ce sa confectionezi Thunderhorn Totem"}},["43953f1d"]={q="Impotriva cui esti trimis pentru a obtine ghearele?",a="Esti trimis sa vanezi pradatorii salbatici care cutreiera campiile din Mulgore: vanatorii de preerie si pumele de campie. Aceste bestii umbla in mod firesc prin tinuturile de la est si vest de Bloodhoof Village, traind si vanand ca parte a echilibrului natural al pamantului.",al={"ce trebuie sa vanez","care sunt tintele","prada pentru Thunderhorn Totem"}}},fp="17,307,28.469.0,22.465.0,46.237.0,39.200.0,58.146.0,50.174.1,66.195.0,72.236.0"}
P.entries["quest:757"] = {n="Rite of Strength",s="Rite of Strength este prima incercare din traditionalele Rites of the Earthmother, parcurse de tinerii tauren din Camp Narache. Pentru a-si dovedi curajul si capacitatea de a-si apara tribul, initiatii trebuie sa starpeasca quilboarii Bristleback care inainteaza prin Brambleblade Ravine si sa-i inmaneze centurile lui Chief Hawkwind.",h="Rite of Strength este prima incercare din traditionalele Rites of the Earthmother, parcurse de tinerii tauren...",kw={"brambleblade ravine","bristleback","camp narache","chief hawkwind","earthmother","mulgore","quilboar","rite of strength","seer graytongue"},ang={["faction:Horde"]="Apararea platoului asigura unul dintre principalele centre de recrutare ale Horde, permitand tinerilor razboinici si samani sa se maturizeze in siguranta si sa sprijine noua uniune.",["race:Tauren"]="Fiecare tanar tauren isi incepe calatoria parcurgand aceste rituri stravechi, dovedind ca este pregatit sa-si apere poporul de amenintarea quilboar inainte de a parasi Red Cloud Mesa."},sec={{t="Prima incercare",b="Pentru un tanar tauren care cauta recunoasterea batranilor tribului si, in cele din urma, primirea in Thunder Bluff, indeplinirea Rites of the Earthmother este o datorie esentiala. Daruit de Seer Graytongue, Rite of Strength este prima incercare. Aceasta cere curaj fizic si actiune hotarata pentru apararea Red Cloud Mesa, punand la incercare capacitatea unui initiat de a-si infrunta fara sa clipeasca dusmanii de moarte ai tribului."},{t="Amenintarea Bristleback",b="Locul ales pentru aceasta incercare este Brambleblade Ravine, o crapatura plina de spini la est de Camp Narache, ocupata de quilboari Bristleback. Acesti intrusi agresivi incalca necontenit pamanturile stramosesti, atacand grupurile de vanatoare si jefuind proviziile taberei sub acoperirea intunericului. Uciderea lor si luarea centurilor servesc atat drept dovada de vitejie, cat si ca masura necesara pentru a mentine asezarea in siguranta."}},faq={{q="Care este scopul Rite of Strength?",a="Este prima etapa fundamentala a Rites of the Earthmother, menita sa puna la incercare curajul in lupta al unui tanar tauren. Eliminand amenintarile ostile pentru tabara, novicul dobandeste dreptul de a-si castiga, in cele din urma, respectul in Thunder Bluff.",al={"de ce sa faci Rite of Strength","povestea Rite of Strength","scopul Rite of Strength"}},{q="Cine incredinteaza aceasta incercare si cine o judeca?",a="Seer Graytongue ii incredinteaza sarcina initiatului si ii explica cerintele spirituale si practice ale incercarii. Dupa ce strange doisprezece brauri Bristleback, initiatul trebuie sa-i prezinte direct dovada vitejiei lui Chief Hawkwind, in Camp Narache.",al={"cine da Rite of Strength","cine primeste inapoi Rite of Strength"}},{q="Unde se afla Brambleblade Ravine?",a="Brambleblade Ravine se afla chiar la est de Camp Narache, pe Red Cloud Mesa. Este un canion plin de maracini, impanzit de quilboari Bristleback ostili.",al={"unde este Brambleblade Ravine","locatia Brambleblade"}},{q="De ce sunt vizati Bristlebacks?",a="Bristlebacks patrund pe terenurile de vanatoare ancestrale ale tribului. Ii ataca in repetate randuri prin ambuscade pe vanatorii tauren si fura pe intuneric provizii din Camp Narache, fiind dusmani directi ai tribului.",al={"de ce sa ucizi Bristlebacks","ce au facut quilboar"}},{q="De ce sa aduni curele in locul altor trofee?",a="Centurile sunt dovezi palpabile ale razboinicilor invinsi, demonstrand ca initiatul s-a luptat de aproape cu quilboarii si a doborat adulti, in loc sa scormoneasca doar de la distanta.",al={"de ce curele bristleback","de ce curele"}},{q="Ce urmeaza dupa finalizarea Rite of Strength?",a="Trecerea Rite of Strength dovedeste vitejia cuiva si il califica pe initiat pentru probele urmatoare ale Mamei Pamant, continuand calea oficiala spre maturitate si statutul spiritual in cadrul tribului.",al={"ce urmeaza dupa rite of strength","urmatorul rit earthmother"}}},fx={f38315d5={q="De ce te trimite Seer Graytongue la Bristlebacks?",a="Seer Graytongue ii calauzeste pe tinerii din Camp Narache prin sacrele Rites of the Earthmother. In prima ta proba, el trebuie sa-ti puna la incercare hotararea in lupta, confruntandu-te cu o amenintare reala si presanta pentru trib. Quilboarii Bristleback au patruns tot mai mult pe pamanturile taurenilor, atacand vanatorii prin surprindere si furand sub ocrotirea intunericului. Trimitandu-te sa-i infrunti, Graytongue se asigura ca-ti aperi poporul, iti dovedesti puterea si castigi respectul tribului.",al={"de ce vrea Graytongue acest lucru","motivul lui Seer Graytongue","de ce Rite of Strength"}},e0dd8e68={q="De ce esti trimis sa treci aceasta proba de unul singur?",a="Rite of Strength este un ritual personal de trecere la maturitate, nu o simpla indatorire de garnizoana. In timp ce razboinicii taberei pazesc perimetrul, fiecare tanar tauren trebuie sa-si dovedeasca singur vitejia si priceperea martiala inainte de a fi recunoscut ca adult in Thunder Bluff. Incercarea iti cere sa infrunti tu insuti dusmanii poporului tau, pentru ca batranii sa stie ca poti apara tribul atunci cand ti se va cere.",al={"de ce eu pentru Rite of Strength","de ce nu trimit gardieni impotriva Bristlebacks","de ce trebuie sa ma lupt cu Bristlebacks"}}},fp="16,303,15.399.0,22.404.0,44.234.0,34.237.0,37.150.0,40.223.0,44.196.0,49.201.0"}
P.entries["quest:758"] = {n="Thunderhorn Cleansing",s="Thunderhorn Cleansing este un ritual spiritual esential in Mulgore, care le cere calatorilor sa purifice Thunderhorn Water Well, ajuns corupt. Inarmati cu un totem ritualic pregatit de Mull Thunderhorn, aventurierii redau izvorului contaminat rolul vital pentru tribul local. Purificarea reusita le castiga aprobarea sincera a stramosilor Thunderhorn.",h="Thunderhorn Cleansing este un ritual spiritual esential in Mulgore, care le cere calatorilor sa purifice...",kw={"spirite stramosesti","bloodhoof village","totem de purificare","earth mother","mulgore","mull thunderhorn","thunderhorn cleansing","thunderhorn water well"},ang={["class:Druid"]="Purificarea apelor otravite opreste raspandirea coruptiei in ecosistemul din Mulgore, pastrand armonia naturala a campiilor.",["class:Shaman"]="Canalizarea energiei stramosilor prin totemuri pentru a vindeca izvoarele naturale corupte este insasi temelia chemarii samanice.",["faction:Horde"]="Ajutorul oferit taurenilor pentru ingrijirea izvoarelor sacre intareste legatura dintre tanara Horde si mandrii sai aliati Shu'halo.",["race:Tauren"]="Restaurarea izvoarelor sacre o onoreaza pe Earth Mother si iti protejeaza rudele, in timp ce isi cladesc o casa permanenta si pasnica in Mulgore."},sec={{t="O sursa de ajutor corupta",b="Fantanile de pe intinsele campii din Mulgore sunt surse vitale de apa pentru triburile nomade tauren care s-au stabilit recent pe pajisti. Cand otrava spurca aceste izvoare subterane, atat fauna salbatica, cat si asezarile din apropiere se confrunta cu urmari devastatoare. Thunderhorn Water Well, situata la nord de Bloodhoof Village si cazuta victima contaminarii, are nevoie de interventie spirituala deliberata pentru a vindeca tinutul napastuit."},{t="Purificarea stramoseasca",b="Pentru a contracara coruperea, Mull Thunderhorn faureste un Totem al Purificarii consacrat, incarcat cu putere spirituala. Ducerea directa a acestei relicve la apele otravite le permite aventurierilor sa canalizeze puterea strabunilor in izvor, risipind toxinele si restabilind echilibrul natural neintinat. Mull primeste confirmarea directa a reusitei cand spiritele stramosilor din Thunderhorn il viziteaza in vis, pentru a-si exprima recunostinta neclintita."}},faq={{q="Unde se afla Thunderhorn Water Well?",a="Thunderhorn Water Well se afla in campiile de la nord de Bloodhoof Village, in Mulgore. Este una dintre cateva surse vitale de apa care aprovizioneaza clanurile tauren locale.",al={"locatia fantanii Thunderhorn","unde se afla fantana","unde folosesc totemul"}},{q="Cine initiaza acest ritual de purificare?",a="Mull Thunderhorn initiaza ritualul. Il poti gasi in Bloodhoof Village, unde lucreaza la faurirea unor totemuri speciale pentru a vindeca mediul afectat din Mulgore.",al={"cine ofera misiunea","locatia lui Mull Thunderhorn","cel care ofera misiunea"}},{q="De ce trebuie curatate puturile cu apa din Mulgore?",a="Fantanile din Mulgore au fost afectate de otravire si coruptie nenaturale, care ameninta echilibrul delicat al campiilor si supravietuirea triburilor tauren dependente de apa curata.",al={"de ce sa cureti fantanile","ce s-a intamplat cu apa","de ce este fantana otravita"}},{q="Cum stie Mull ca ritualul a reusit?",a="Dupa incheierea ritualului de la fantana, spiritele stramosilor clanului Thunderhorn i se arata lui Mull in vis, laudand faptele aventurierului si oferindu-i multumiri din partea stramosilor.",al={"visul stramosului","cum stie Mull","rezultatul purificarii fantanii"}},{q="Ce urmeaza dupa purificarea fantanii Thunderhorn?",a="Purificarea fantanii Thunderhorn face parte dintr-un efort mai amplu de a proteja izvoarele din Mulgore. Apoi, Mull ii trimite pe calatori mai departe, sa ajute o alta regiune aflata la ananghie, construind Wildmane Totem.",al={"ce urmeaza","urmatoarea misiune dupa Thunderhorn","ce urmeaza dupa Wildmane Totem"}},{q="Ce este Thunderhorn Cleansing Totem?",a="Thunderhorn Cleansing Totem este un obiect spiritual sculptat in cadrul unui ritual, pregatit de Mull Thunderhorn special pentru a purifica apele corupte ale fantanii ancestrale a clanului sau.",al={"purificarea totemului","care este obiectul totem","totemul lui Mull"}}},fx={da3030fe={q="De ce are nevoie Mull Thunderhorn sa curete fantana?",a="Mull Thunderhorn a faurit focarul ritualic, dar curatarea unui loc sacru este un act de slujire si onoare pentru campionii tauren si aliatii lor care se afirma. Ducand personal Thunderhorn Cleansing Totem la fantana intinata, iti dovedesti devotamentul fata de Earthmother si spiritele stramosilor clanului sau, castigand bunavointa si indrumarea stramosilor care vegheaza asupra apelor.",al={"de ce eu, Mull Thunderhorn","de ce te trimite Mull","de ce sa indeplinesti ritualul de purificare"}}},fp="21,345,18.422.0,19.447.0,44.167.0,36.161.0,48.196.0,45.184.0,51.191.0,40.180.0"}
P.entries["quest:759"] = {n="Wildmane Totem",s="Wildmane Totem reprezinta a treia si ultima etapa a eforturilor lui Mull Thunderhorn de a crea totemuri purificatoare pentru fantanile otravite din Mulgore. Pentru a restaura Wildmane Well, ritualul cere ofrande luate de la cei mai feroce pradatori naturali ai tinutului: lupii de preerie alfa.",h="Wildmane Totem reprezinta a treia si ultima etapa a eforturilor lui Mull Thunderhorn de a crea totemuri...",kw={"bloodhoof village","mulgore","mull thunderhorn","alfa lupilor de preerie","thunder bluff","totem","fantana cu apa","wildmane"},ang={["class:Hunter"]="Urmarirea lupilor alfa sireti din preajma inaltimilor stancoase pune la incercare respectul unui vanator pentru salbaticie si cei mai feroce pradatori ai ei.",["class:Shaman"]="Shamanii apreciaza ritualurile delicate prin care totemurile de pradator sunt armonizate cu apa elementala pentru a curata molimele toxice.",["race:Tauren"]="Curatarea fantanilor stramosesti subliniaza obligatia taurenilor de a restabili echilibrul mediului si de a onora sacrificiile cerute de Earth Mother."},sec={{t="Ultima fantana",b="Dupa ce ai obtinut materialele necesare consacrarii totemurilor pentru fantanile Winterhoof si Thunderhorn, nu mai ramane decat o singura sursa afectata in centrul Mulgore: Wildmane Well. Apa otravita de pe campii ameninta atat fauna migratoare, cat si asezarile, iar restabilirea echilibrului natural al pamantului necesita ingrediente primordiale puternice."},{t="Puterea pradatorului",b="Pentru a contracara coruptia puternica ramasa in apele nordice, Mull Thunderhorn cere un tribut de ferocitate. Alfa lupilor de prerie pandesc prin pajisti, mai ales in jurul falezelor inalte de sub Thunder Bluff. Recoltarea dintilor lor concentreaza direct in fabricarea totemului purificator perseverenta neinfranata si rezistenta celor mai de temut vanatori din Mulgore."},{t="Sacrificiu si echilibru",b="In traditia spirituala tauren, folosirea vietuitoarelor pamantului are o insemnatate emotionala si elementala. Mull nu priveste strangerea coltilor de conducatori drept o cucerire, ci ca pe o necesitate grava, in care sacrificarea pradatorilor din Mulgore ajuta la vindecarea apelor bolnave ale Earth Mother."}},faq={{q="La ce foloseste Wildmane Totem?",a="Totemul este faurit de Mull Thunderhorn pentru a purifica Wildmane Well, ultima sursa de apa contaminata care pune in pericol locuitorii Tauren din Mulgore.",al={"de ce sa faci Wildmane Totem","scopul lui Wildmane Totem"}},{q="De ce sunt necesari in mod special dintii de lup de prerie alfa?",a="Purificarea contaminarii profunde din Wildmane Well necesita canalizarea fortei neinduplecate si salbatice a unui pradator de varf. Coltii conducatorilor haitei ofera puterea primordiala necesara.",al={"de ce dinti de lup","scopul dintilor de prairie alpha"}},{q="Unde se gasesc lupii alfa de prerie in Mulgore?",a="Alfa lupilor de preerie cutreiera campiile nordice din Mulgore si isi dau adesea tarcoale pe pajistile din jurul bazei Thunder Bluff.",al={"locatia masculului alfa al lupilor de preerie","unde gasesc masculii alfa de preerie"}},{q="Cine faureste totemul?",a="Mull Thunderhorn, un batran spiritual aflat in Bloodhoof Village, faureste fiecare totem de purificare dupa ce un initiat aduna ofrandele necesare.",al={"cine face totemul","cel care ofera misiunea totemului"}},{q="Ce urmeaza dupa crearea totemului Wildmane Totem?",a="Dupa ce Mull Thunderhorn asambleaza totemul din coltii alfa, esti trimis spre nord cu el pentru a indeplini purificarea propriu-zisa la Wildmane Well.",al={"ce urmeaza","urmatoarea misiune dupa Wildmane Totem"}},{q="Cum reflecta acest ritual credintele tauren?",a="Taurenii privesc luarea vietii unui animal ca pe un schimb solemn cu natura. Mull recunoaste sacrificiul lupilor, simtind atat tristete pentru moartea lor, cat si mandrie pentru rolul lor in vindecarea pamantului.",al={"filozofia totemului la tauren","credintele lui mull thunderhorn"}}},fx={["054e923c"]={q="De ce vrea Mull Thunderhorn ca Wildmane Totem sa fie confectionat?",a="A mai ramas un singur put de apa corupt de purificat in Mulgore - cel al clanului Wildmane. Mull Thunderhorn s-a dedicat curatarii fantanilor sacre ale Mamei-Pamant, iar crearea acestui ultim totem purificator, folosind spiritul pradator al tinutului, este esentiala pentru incheierea ritualului sacru si redarea apei curate tribului.",al={"de ce vrea mull wildmane totem","motivul lui mull thunderhorn","de ce sa creezi wildmane totem"}},["2aa23a29"]={q="La ce foloseste Prairie Alpha Tooth?",a="Coltii lupului de prerie alfa simbolizeaza sacrificiul si vitalitatea feroce a pradatorilor de varf din Mulgore. Mull Thunderhorn prinde opt dintre acesti colti in Wildmane Totem, pentru ca spiritul acestuia sa impace ordinea naturala si sa dea putere ritualului menit sa curete intinarea din fantana de apa Wildmane.",al={"folosire prairie alpha tooth","la ce folosesc prairie alpha teeth","dinti pentru wildmane totem"}},eb5f4bd0={q="De ce vanezi lupi de preerie alfa?",a="Ti se cere sa vanezi lupii de prerie alfa, conducatorii dominanti ai haitelor care cutreiera campiile din jurul bazei Thunder Bluff. Forta si ferocitatea lor intruchipeaza echilibrul firesc al campiilor, oferind esenta puternica de care Mull Thunderhorn are nevoie pentru ritualul final de purificare a apei.",al={"de ce sa ucizi lupii de preerie alfa","tinta lupilor de preerie alfa","pe cine esti trimis sa vanezi"}}},fp="14,272,14.339.0,23.367.0,21.277.0,38.141.0,55.192.0,47.130.0,21.146.0,48.147.0,44.199.0"}
P.entries["quest:76"] = {n="The Jasperlode Mine",s="Koboldii au napadit Jasperlode Mine, in estul Elwynn. Marshal Dughan trimite cercetasi sa afle cat de departe s-a raspandit infestarea.",h="Koboldii au napadit Jasperlode Mine, in estul Elwynn.",kw={"azora","dughan","elwynn","fargodeep","goldshire","jasperlode","kobold","mina","cercetas"},ang={["faction:Alliance"]="Ca membru al Alliance, vezi cat de vulnerabile au devenit teritoriile natale din Stormwind in lipsa sprijinului regal centralizat, dupa pierderea atat a Fargodeep, cat si a Jasperlode.",["profession:Mining"]="Ca miner, vezi zacaminte valoroase in tunelurile Jasperlode, dar koboldii teritoriali iti stau intre tine si minereu.",["race:Human"]="Ca Human, vezi cum infrastructura rurala din Elwynn se clatina, pe masura ce resursele de la granita se apropie de epuizare, chiar langa capitala."},sec={{t="O a doua incursiune",b="Dupa ce Kobold au napadit tunelurile Fargodeep, la sud de Goldshire, Marshal Dughan s-a temut ca au ajuns si in alte mine. Jasperlode se afla la poalele stancoase ale muntilor, la nord-est de Tower of Azora, si furnizeaza piatra bruta si metal regatului. Dughan nu-si poate lipsi patrulele orasului de garzile Stormwind, asa ca trimite aventurieri independenti spre est sa vada daca Kobold au ocupat si aceasta mina."},{t="Aparari suprasolicitate",b="Cercetasii care ajung in galeriile din Jasperlode descopera ca kobolds i-au alungat pe minerii Human si au fortificat pasajele intunecate. Marshal Dughan se confrunta cu inca o lovitura, pe masura ce criza se agraveaza. King Varian Wrynn este disparut, iar trupele regale nu sunt trimise in teritoriile indepartate. Garnizoana locala are prea putini soldati ca sa curete minele, lasand inima regatului fara minereuri si inconjurata de amenintari."}},faq={{q="Unde se afla Jasperlode Mine?",a="Jasperlode Mine se afla la poalele nordice ale partii estice din Elwynn Forest. Calatoreste spre est din Goldshire de-a lungul drumului principal, treci de Tower of Azora, apoi indreapta-te spre nord, spre dealuri.",al={"unde este Jasperlode","locatia minei Jasperlode","cum gasesc Jasperlode"}},{q="De ce are nevoie Marshal Dughan de un cercetas in loc sa trimita garzi?",a="Marshal Dughan are prea putine garzi pentru a putea trimite pe cineva in alta parte. Regele Varian Wrynn a disparut, iar blocajul politic din capitala a lasat fortele locale suprasolicitate, in timp ce apara fermele si orasele de banditi si gnolli, asa ca Dughan se bazeaza pe cercetasi civili.",al={"de ce trimit aventurieri","de ce nu trimit o garda din Stormwind","unde sunt garzile"}},{q="De ce ocupa kobolzii minele din Elwynn?",a="Kobold sapa tuneluri spre filoanele minerale si pesterile umede. Pe masura ce prezenta militara a Stormwind s-a redus, au prins curaj si au patruns in minele Human precum Fargodeep si Jasperlode, ca sa puna mana pe aur, minereu si teritoriu.",al={"de ce sunt koboldi in Jasperlode","ce vor koboldii","motivul invaziei koboldilor"}},{q="Ce se intampla dupa cercetarea minei Jasperlode Mine?",a="Dupa ce raportezi caderea lui Jasperlode, Marshal Dughan se confrunta cu pierderea minelor din est si cu amenintari de pe mai multe fronturi. Isi indreapta atentia spre vestul Elwynn, unde gnollii Riverpaw pun presiune mare asupra Westbrook Garrison.",al={"ce urmeaza dupa Jasperlode","continuarea dupa Jasperlode"}},{q="De ce este importanta pierderea Jasperlode Mine pentru Stormwind?",a="Minele din Elwynn furnizeaza minereul si piatra de care Stormwind are nevoie pentru economie si pentru faurirea armelor si armurilor. Pierderea Fargodeep si Jasperlode opreste extractia mineralelor si slabeste redresarea regatului.",al={"de ce conteaza Jasperlode","importanta Jasperlode"}},{q="Cine detine in apropiere Tower of Azora?",a="Tower of Azora este un mic turn pentru mage, aflat de-a lungul drumului estic din Elwynn Forest. Theocritus, Archmage of Azora, isi are resedinta acolo, iar servitorii lui Azora se ocupa de turn. Calatorii il folosesc ca reper in drumul spre poalele muntilor din est.",al={"ce este Tower of Azora","cine locuieste in turnul Azora"}}},fx={a973508b={q="De ce vrea Marshal Dughan sa cercetezi Jasperlode Mine?",a="Dupa ce a confirmat deja ca kobolzii au napadit Fargodeep Mine, Marshal Dughan se teme ca infestarea nu este un incident izolat. Trebuie sa afle daca amenintarea s-a extins si spre est, pana la Jasperlode Mine. Asigurarea resurselor din Elwynn si intelegerea amplorii depline a pericolului care se apropie sunt esentiale pentru apararea oraselului Goldshire si protejarea rutelor comerciale vitale din Stormwind.",al={"motivul lui dughan jasperlode","de ce sa cercetez jasperlode","de ce are nevoie dughan sa fie cercetat jasperlode"}}},fp="19,132,18.387.0,21.391.0,37.177.0,63.237.0,43.203.0,48.235.0,60.196.0,35.231.0"}
P.entries["quest:760"] = {n="Wildmane Cleansing"}
P.entries["quest:761"] = {n="Swoop Hunting",s="Swoop Hunting este un ritual de urmarire a prazii si tragere la tinta, oferit de Harken Windtotem in Bloodhoof Village. Pentru a-si dovedi istetimea si rabdarea, vanatorii si calatorii sunt provocati sa urmareasca pasarile greu de prins de-a lungul campiilor intinse din Mulgore. Intoarcerea cu penele impecabile drept trofeu demonstreaza atat devotamentul fata de vanatoare, cat si respectul pentru incercarile naturale ale lui Earth Mother.",h="Swoop Hunting este un ritual de urmarire a prazii si tragere la tinta, oferit de Harken Windtotem in...",kw={"bloodhoof village","harken windtotem","mulgore","swoop","swoop hunting","tauren trial","trofeu, pana de swoop"},ang={["class:Druid"]="Urmarirea swoopilor pe platourile inalte batute de vant ii apropie pe druizi de pasarile de prada care mentin echilibrul cerului din Mulgore.",["class:Hunter"]="Vanatoarea ofera o lectie introductiva de maiestrie in conducerea urmaririi prazii aeriene, evaluarea tiparelor de comportament si executarea unor atacuri precise impotriva pradatorilor vigilenti.",["race:Tauren"]="Pentru tinerii tauren si calatori, vanarea swoopurilor rapide din Mulgore este un stravechi ritual de initiere, care le ascute instinctul de urmarire si pastreaza traditiile stramosesti ale vanatorii."},sec={{t="O proba pentru ochi ageri",b="Stepele inverzite din Mulgore abunda in fiare, dar putine pun instinctele urmaritorului la fel de mult la incercare ca pasarile swoop native. Aceste pasari de prada mari se contopesc cu cerul si campiile, planand deasupra sau zburand razant peste iarba inalta. Spre deosebire de uriasele plainstrider sau de kodo care pasc, pasarile swoop cer o concentrare ascutita si picioare iuti pentru a fi ajunse din urma, astfel ca urmarirea lor este o proba traditionala pentru tinerii vanatori care vor sa-si castige un loc in triburi."},{t="Insemnele vanatorii",b="Pentru Harken Windtotem, strangerea penelor de trofeu tine mai putin de starpirea faunei si mai mult de cultivarea disciplinei. In cultura taurenilor, purtarea unor insemne obtinute dupa o vanatoare dificila dovedeste istetime si perseverenta. Inmanarea acestor pene fara cusur batranilor din Bloodhoof Village arata ca un aventurier este in stare sa sustina si sa apere comunitatea, dovedind ca are copite sprintene si simturi ascutite, numai bune pentru a stapani lumea larga."}},faq={{q="Care este scopul vanarii swoop-urilor pentru Harken Windtotem?",a="Harken Windtotem le cere vanatorilor sa urmareasca swoop-uri prin Mulgore, punandu-le la incercare ingeniozitatea, viteza si devotamentul. Aducerea inapoi a penelor-trofeu intregi este o dovada recunoscuta a priceperii unui vanator si ii aduce onoare printre tauren-ii din Bloodhoof Village.",al={"de ce sa vanam swoops","scopul misiunii lui harken windtotem","scopul swoop hunting"}},{q="Unde sunt intalniti de obicei swoopii?",a="Swoopii pot fi gasiti imprastiati pe campiile largi din Mulgore, zburand deasupra preriei sau cautand prada prin iarba, in afara asezarilor precum Bloodhoof Village.",al={"unde se gasesc swoops","locatiile swoops din mulgore","gaseste swoops"}},{q="De ce sunt swoopii considerati greu de vanat?",a="Spre deosebire de animalele de turma care strabat campiile impreuna, swoop-urile sunt rapitoare iuti si vigilente, intalnite pretutindeni si mereu atente. Pentru a le urmari, ai nevoie de o privire agera ca sa le observi traiectoriile si de pasi repezi ca sa le dobori inainte sa scape.",al={"de ce sunt greu de prins swoop-urile","comportamentul swoop-urilor"}},{q="Ce semnifica penele trofeu pentru tauren?",a="In traditiile taurenilor, penele de swoop, pastrate ca trofee, simbolizeaza rabdarea, vederea agera si o urmarire incununata de succes. Expunerea lor arata ca un vanator are instinctele necesare pentru a hrani si a proteja tribul.",al={"semnificatia penelor de swoop trofeu","importanta penelor"}},{q="Cine este Harken Windtotem?",a="Harken Windtotem este un locuitor tauren respectat din Bloodhoof Village, care ii observa pe nou-veniti si pe vanatorii aspiranti, evaluandu-le ingeniozitatea prin incercari traditionale desfasurate pe campii.",al={"cine ofera swoop hunting","povestea lui harken windtotem"}},{q="Afecteaza aceasta vanatoare echilibrul naturii in Mulgore?",a="Taurenii privesc vanatoarea ca pe un dialog sacru cu Earth Mother, nu ca pe un macel lipsit de sens. Culegerea spinilor este o proba cumpatata de disciplina, care cinsteste istetimea prazii si mentine echilibrul tribului.",al={"este Swoop Hunting vanatoare excesiva","echilibrul swoopilor in Mulgore"}}},fx={["0d785fcd"]={q="De ce trimite Harken Windtotem un strain in loc sa vaneze el insusi swoop-ii?",a="Harken Windtotem nu te trimite la vanatoare fiindca nu este in stare s-o faca el, ci pentru a-ti pune valoarea la incercare. Pentru Tauren, urmarirea swoopului viclean prin campii cere privire agera, rabdare si copite sprintene. Incredintandu-ti sarcina de a le aduce penele, Harken iti da prilejul sa-ti dovedesti priceperea si hotararea fata de Bloodhoof Village si sa arati ca esti un Hunter cu adevarat merituos.",al={"de ce sa ma trimiti la Swoop Hunting","de ce are Harken nevoie de mine","de ce nu poate Harken sa vaneze swoopii"}}},fp="13,385,19.466.0,18.451.0,59.252.0,39.172.0,41.246.0,48.215.0,24.192.0,55.222.0"}
P.entries["quest:762"] = {n="An Ambassador of Evil",s="Historian Karnik vrea ca Ambassador Infernus din Angor Fortress sa fie ucis. Trebuie sa te intorci in Badlands si sa duci dovada uciderii la Advisor Belgrum din Ironforge.",h="Historian Karnik vrea ca Ambassador Infernus din Angor Fortress sa fie ucis.",kw={"advisor belgrum","ambassador infernus","angor fortress","badlands","historian karnik","ironforge","ragnaros","shadowforge","uldaman"},sec={{t="Ambasadorul din Angor Fortress",b="Ragnaros insusi l-a trimis pe Ambassador Infernus la Angor Fortress ca sa supravegheze Shadowforge in timp ce cauta artefacte pierdute in Uldaman. Pierderile in randul Dwarves sunt deja mari si continua sa creasca. Karnik nu indrazneste sa ghiceasca cate artefacte ar putea gasi Shadowforge si folosi impotriva lui Ironforge. Trebuie sa te intorci in Badlands, sa-l distrugi pe Infernus si sa-i aduci lui Belgrum dovada victoriei tale. Timpul preseaza, fiindca Ragnaros nu va astepta sa se pregateasca."},{t="Multumirile lui Belgrum",b="Belgrum iti lauda devotamentul fata de Ironforge si fata de poporul dwarven si va trimite vestea reusitei tale lui Karnik. Va fi trimis ajutor si in Badlands pentru recucerirea sitului de excavare. Belgrum mai are un lucru sa-ti ceara, in numele regelui Bronzebeard."}},faq={{q="Cine este Ambassador Infernus?",a="Ragnaros insusi l-a trimis pe Infernus la Angor Fortress pentru a supraveghea Shadowforge in timp ce cauta artefacte pierdute in Uldaman.",al={"cine este infernus","povestea lui infernus","trecutul lui Ambassador Infernus"}},{q="Unde se afla Ambassador Infernus?",a="In Angor Fortress, in Badlands.",al={"unde il gasesti pe ambassador infernus","locatia lui ambassador infernus","unde este infernus"}},{q="De ce vrea Karnik ca Ambassador Infernus sa fie distrus?",a="Cautarile Shadowforge in Uldaman au costat deja multe vieti de dwarven, iar Karnik se teme ca artefactele gasite ar putea fi folosite impotriva lui Ironforge.",al={"de ce sa-l omori pe Ambassador Infernus","ce cauta Infernus in Uldaman","amenintare pentru Ironforge in Badlands"}},{q="Cine ofera si incheie aceasta misiune?",a="Historian Karnik din Ironforge ti-o da, iar tu ii duci dovada victoriei lui Advisor Belgrum, tot in Ironforge.",al={"cine incepe an ambassador of evil","cine preda ambassador of evil","cel care da misiunea ambassador of evil"}},{q="Ce dovada se cere?",a="Bracer-ul lui Ambassador Infernus, aratat lui Advisor Belgrum drept dovada a victoriei tale.",al={"de ce am nevoie de la infernus","dovada pentru ambassador infernus","bratara lui infernus"}}},fp="21,169,32.452.0,16.254.1,27.119.0,29.35.0,51.146.0,30.103.0,21.79.0"}
P.entries["quest:763"] = {n="Rites of the Earthmother",s="Rites of the Earthmother marcheaza trecerea unui taur tineresc din izolata Red Cloud Mesa spre intinsele campii din Mulgore. Dupa ce ti-ai dovedit vrednicia in Camp Narache, Chief Hawkwind te trimite spre nord, la Bloodhoof Village, cu un totem sculptat, pentru a continua vechile incercari sub indrumarea lui Baine Bloodhoof.",h="Rites of the Earthmother marcheaza trecerea unui taur tineresc din izolata Red Cloud Mesa spre intinsele...",kw={"Baine Bloodhoof","Bloodhoof Village","Cairne Bloodhoof","Camp Narache","Chief Hawkwind","Mulgore","ritualurile Mamei Pamant","Totem of Hawkwind"},ang={["faction:Horde"]="Riturile traditionale intaresc unitatea tribala din Mulgore, asigurand ca noii aparatori ai Horde au atat iscusinta razboinica, cat si radacini spirituale profunde.",["race:Tauren"]="Fiecare tanar tauren trebuie sa urmeze calea Earthmother pentru a-si dovedi valoarea in fata batranilor si a-si gasi locul printre triburile unite."},sec={{t="Parasirea platoului",b="De generatii, tinerii tauren isi pun puterea la incercare in adapostul ocrotitor al taberei Camp Narache, pe Red Cloud Mesa. Incheierea probelor initiale dovedeste ca cineva are disciplina si hotararea necesare pentru a supravietui, insa sacrele Rites of the Earthmother cer mult mai mult decat supravietuirea in fata faunei locale. Chief Hawkwind isi da seama cand un initiat a depasit terenurile de vanatoare ocrotite ale platoului si trebuie sa-si gaseasca locul in comunitatea mai larga."},{t="Un dar pentru Baine",b="Pentru a inlesni calatoria dintre Narache si asezarile din centru, Chief Hawkwind iti da un totem sculptat manual, drept semn de recunoastere. Purtand emblema pe cararea intortocheata spre Bloodhoof Village, te prezinti lui Baine Bloodhoof, tanarul conducator al satului si fiul marelui sef Cairne Bloodhoof. Totemul dovedeste ca esti pregatit pentru ritualurile spiritului si intelepciunii care te asteapta."}},faq={{q="Care este scopul acestei misiuni?",a="Este ritul de trecere care te indruma sa parasesti zona de inceput din Camp Narache si sa pornesti spre Bloodhoof Village, legandu-te de urmatoarea etapa a probelor ceremoniale tauren.",al={"de ce sa faci ritualurile Earthmother","ce face aceasta misiune","scopul misiunii"}},{q="Cine este Baine Bloodhoof?",a="Baine Bloodhoof este fiul Marelui sef de trib Cairne Bloodhoof. El conduce Bloodhoof Village, fiind un sef local respectat care supravegheaza probele spirituale si martiale la care sunt supusi tinerii tauren.",al={"cine este baine","povestea lui baine","fiul lui cairne"}},{q="Ce este Totem of Hawkwind?",a="Este un totem de lemn, sculptat manual de Chief Hawkwind din Camp Narache. Serveste drept acreditare oficiala si sigiliu de aprobare, dovedindu-i lui Baine Bloodhoof ca ai primit binecuvantarea lui Hawkwind pentru a urma ritualuri suplimentare.",al={"totem of hawkwind","totemul lui hawkwind","totem sculptat"}},{q="Ce ritualuri urmeaza?",a="Dupa ce ajungi in Bloodhoof Village si te intalnesti cu Baine, primesti sarcina de a indeplini Rite of Vision, care iti pune la incercare legatura spirituala prin viziuni sacre ale stramosilor.",al={"urmatoarele rituri","ce urmeaza","urmatoarea misiune"}},{q="Unde se afla Bloodhoof Village?",a="Bloodhoof Village se afla la nord de Camp Narache, pe malul Stonebull Lake, in centrul Mulgore. Calatorii nu trebuie decat sa urmeze drumul principal care coboara de pe podis si sa se indrepte spre nord.",al={"unde se afla Bloodhoof Village","cum gasesc Bloodhoof Village","drumul spre bloodhoof"}},{q="De ce trebuie indeplinite ritualurile Earthmother?",a="Rites of the Earthmother sunt traditii profund sacre pentru tauren. Trecerea tuturor etapelor ritualurilor dovedeste tarie fizica, legatura spirituala si intelepciune, castigandu-i initiatului recunoasterea adevarata a batranilor din Thunder Bluff.",al={"de ce ritualurile Earthmother","scopul incercarilor Tauren","povestea ritualurilor Earthmother"}}},fx={["4a33bb81"]={q="De ce te trimite Chief Hawkwind la Bloodhoof Village?",a="Chief Hawkwind te-a calauzit prin incercarile introductive de la Red Cloud Mesa, dar Camp Narache nu te mai poate invata nimic. Pentru a indeplini sacrele Rites of the Earthmother si a castiga acceptarea batranilor din Thunder Bluff, trebuie sa-ti imbogatesti experienta pe campiile intinse din Mulgore. Trimitandu-te la Baine Bloodhoof cu totemul sau sculptat, Hawkwind ii incredinteaza unui conducator capabil sa-ti puna la incercare pregatirea pentru adevarata maturitate responsabilitatea pentru dezvoltarea ta spirituala si fizica.",al={"de ce sa-l trimiti la Bloodhoof","motivul lui Chief Hawkwind","de ce sa faci Rites of the Earthmother"}},["9c980781"]={q="De ce trebuie sa duci tu insuti totemul?",a="Calatoria nu este o simpla sarcina de curier, ci o parte integranta a ritului tau de trecere. Iesirea din adapostul oferit de Red Cloud Mesa si urmarea drumului deschis spre Mulgore dovedesc independenta si rezistenta ta. Ducand Totem of Hawkwind cu propriile maini, ii dai lui Baine Bloodhoof ocazia sa te priveasca, sa recunoasca recomandarea personala a lui Hawkwind, sculptata in lemn, si sa-ti judece caracterul pe viu.",al={"de ce iau eu totemul","de ce nu poate hawkwind sa trimita un mesager","de ce eu pentru riturile Mamei Pamant"}}},fp="24,305,16.421.0,17.420.0,34.199.0,23.201.0,30.219.0,27.170.0,35.185.0,44.246.0"}
P.entries["quest:764"] = {n="The Venture Co.",s="Investigarea unei caravane Venture Company devastate in Mulgore scoate la iveala o concentrare agresiva de goblini Venture Company care sapa in dealurile estice. Dupa ce cererile oficiale de permise miniere le-au fost respinse categoric, compania a ales totusi sa exploateze pamantul lui Earth Mother, determinandu-l pe Morin Cloudstalker sa comande o riposta letala.",h="Investigarea unei caravane Venture Company devastate in Mulgore scoate la iveala o concentrare agresiva de...",kw={"goblin","drepturi miniere","Morin Cloudstalker","Mulgore","caravana devastata","Venture Co","mina Venture Co","Venture Company"},ang={["faction:Horde"]="Apararea Mulgore impotriva exploatarii comerciale iti confirma devotamentul fata de protejarea poporului lui Cairne Bloodhoof, care se straduieste sa-si consolideze noua patrie.",["profession:Mining"]="Venture Company se bazeaza exclusiv pe extractie prin forta bruta, facand rabat de la reguli si destabilizand pamantul fara sa tina seama de echilibrul natural sau de practicile miniere sigure.",["race:Tauren"]="Pentru tauren, Earth Mother este sacra. Exploatarea miniera in cariera deschisa a celor din Venture Company nu este doar o incalcare de teritoriu, ci o profanare violenta a caminului lor stramosesc, care justifica o expulzare imediata si ferma."},sec={{t="Intruziune industriala",b="Tauren din Mulgore venereaza pamantul ca pe o prelungire a lui Earth Mother, pretuindu-i campiile neatinse si fauna echilibrata. Cand Venture Company a cerut triburilor dreptul de a folosi explozibili si de a excava dealurile domoale in cautare de minereu brut, cererile i-au fost respinse categoric. Fara sa se lase descurajata de decretele tribale sau de suveranitatea teritoriala, cartelul neobosit a introdus pe furis utilaje grele, muncitori si supraveghetori chiar pe crestele estice din Mulgore, pentru a exploata ilegal minereul."},{t="Un mesaj inconfundabil",b="Cercetasi tauren precum Morin Cloudstalker inteleg ca nu poti negocia cu lacomia corporatiilor prin apeluri diplomatice, odata ce tarnacoapele au lovit piatra. Dupa ce documentele recuperate dintr-o caravana devastata a Venture Co. confirma operatiunea miniera a companiei, Morin trimite campioni ai Horde sa-i doboare atat pe supraveghetorii care pocnesc din bice, cat si pe muncitorii care manevreaza forezele. Aceasta razbunare sangeroasa ar trebui sa se asigure ca Venture Company intelege ca pretul incursiunii este mult prea mare."}},faq={{q="De ce se afla Venture Company in Mulgore?",a="Venture Company a infiintat un avanpost si o mina ilegale pe dealurile estice din Mulgore, pentru a extrage minereuri si resurse naturale. Dupa ce taureni le-au refuzat in mod oficial drepturile miniere, cartelul a ignorat autoritatea tribala si si-a inceput totusi operatiunile.",al={"de ce sunt goblini in Mulgore","motivul Venture Co in Mulgore","ce vrea Venture Co"}},{q="Cine a dat ordinul de a-i ataca pe mineri?",a="Morin Cloudstalker, un tauren care sta de straja langa Bloodhoof Village, da ordinul. El considera ca refuzul cartelului de a accepta refuzul tribului este o incalcare directa, care cere folosirea fortei, nu alte discutii.",al={"cine da aceasta misiune","rolul lui morin cloudstalker","cel care da misiunea"}},{q="Unde se afla mina Venture Company?",a="Mina principala Venture Company se afla in poalele dealurilor, la est de Ravaged Caravan si Bloodhoof Village. Un grup mai mic de angajati ai companiei poate fi intalnit si la un avanpost ascuns printre stancile de la nord-est de lifturile nordice din Thunder Bluff.",al={"locatia minei Venture Co","unde sunt supraveghetorii","unde gasesti Venture Co"}},{q="Au incercat vreodata taurenii sa negocieze cu goblinii?",a="Da. Venture Company le-a cerut taurenilor drepturi oficiale de exploatare miniera in Mulgore. Conducatorii tribali au refuzat sa-i lase sa exploateze pana la epuizare pamanturile stramosesti, dar goblinii au ales pur si simplu sa sape oricum, fara permisiune.",al={"au permis taurenii mineritul","drepturi de minerit in Mulgore","au cerut goblinii permisiunea"}},{q="Fac acesti goblini parte din Steamwheedle Cartel?",a="Nu. Venture Company este un cartel industrial independent si cunoscut pentru pradaciunile sale, distinct de grupurile comerciale neutre, precum Steamwheedle Cartel. Oriunde exploateaza resurse, intretine relatii ostile cu populatiile locale.",al={"sunt acestia goblini din Ratchet","este Venture Co prietenoasa","factiunea Venture Company"}},{q="Ce legatura are aceasta cu caravanele devastate?",a="Caravana devastata era un convoi al Venture Company distrus de tauren. Lazile si documentele diviziei miniere, recuperate dintre ramasitele sale, au dezvaluit operatiunile companiei din Mulgore, determinand acest atac asupra minei lor.",al={"legatura caravanei","a atacat venture co caravanele","legatura cu caravana devastata"}}},fx={f6df914e={q="De ce vrea Morin Cloudstalker sa fie atacata Venture Co.?",a="Venture Company nu a primit oficial drepturi de minerit in Mulgore, dar a ignorat refuzul si a inceput oricum sa-si aduca echipamentele si muncitorii. Morin Cloudstalker nu le poate ingadui sa pustiiasca pamantul si sa-i jefuiasca resursele naturale fara sa fie opriti. Diplomatia si refuzurile categorice nu le-au potolit lacomia, asa ca el crede ca taureni trebuie sa le transmita un mesaj limpede si ferm: incalcarea teritoriului si furtul nu vor fi tolerate.",al={"motivul lui Morin Cloudstalker","de ce sa atac Venture Co","de ce vrea Morin sa-i omoare pe cei din Venture Co"}},eda5096c={q="Cu cine esti trimis sa te lupti in mina?",a="Esti trimis impotriva supraveghetorilor si muncitorilor Venture Co. stationati la exploatarea miniera din estul Mulgore. Goblinii si muncitorii angajati de ei sapa adanc in dealurile sacre pentru a extrage minerale fara permisiunea tribului, condusi de maistri lacomi de profit, care impun extinderea agresiva si ilegala a companiei.",al={"tinte pentru misiunea venture co","cine sunt lucratorii venture co","cu cine ma lupt in mina"}}},fp="15,339,20.472.0,23.485.0,38.269.0,40.215.0,42.253.0,54.219.0,50.237.0,46.224.0"}
P.entries["quest:765"] = {n="Supervisor Fizsprocket",s="Supervisor Fizsprocket este un supraveghetor de rang inalt al Venture Company, stationat in galeriile miniere din Mulgore. La cererea lui Morin Cloudstalker de a pune capat jafurilor calculate ale intreprinderii goblinilor, aventurierii Horde patrund in mina pentru a-l elimina si a-i recupera clipboardul detaliat.",h="Supervisor Fizsprocket este un supraveghetor de rang inalt al Venture Company, stationat in galeriile miniere...",kw={"clipboard","Fizsprocket","mina","Morin Cloudstalker","Mulgore","supraveghetor","Venture Co"},ang={["faction:Horde"]="Ajutorul dat tauren impotriva jefuitorilor corporatisti intareste protectia Horde asupra tinuturilor natale recent revendicate din Kalimdor.",["race:Tauren"]="Planul deschis al Venture Company de a-ti alunga tribul si a jefui pamantul sacru face din uciderea lui Fizsprocket un act esential de aparare a teritoriului."},sec={{t="Un complot impotriva campiilor",b="Documentele recuperate dintr-o caravana Venture Company distrusa au dezvaluit ca Venture Company nu doar sapa dupa minereu - punea la cale in mod deliberat planuri pentru a-i alunga cu totul pe tauren din Mulgore. Indepartandu-i pe localnici, corporatia hrapareata urmarea sa obtina mana libera pentru a jefui dealurile unduitoare si filoanele subterane adanci de toate resursele naturale."},{t="Atacul asupra maistrului",b="Manios din cauza atrocitatilor corporatiste puse la cale impotriva poporului sau, Morin Cloudstalker trimite campioni in mina Venture Company, situata chiar la est de carele comerciale devastate. Adanc, in galeriile din dreapta, inconjurat de muncitori si de sefi de rang inferior, Supervisor Fizsprocket coordoneaza operatiunile. Daca-l dobori pe Fizsprocket si-i iei clipboardul, vei distruge coordonarea locala si vei obtine informatii esentiale despre planurile de viitor ale companiei."}},faq={{q="Cine este Supervisor Fizsprocket?",a="Supervisor Fizsprocket este un sef al Venture Company care coordoneaza operatiunile din galeriile miniere din estul regiunii Mulgore. El supravegheaza muncitorii care sapa in pamant si pune in aplicare strategii corporatiste menite sa extinda operatiunile in intreaga regiune.",al={"fizsprocket","cine este fizsprocket","lore despre fizsprocket"}},{q="De ce vrea Morin Cloudstalker ca Fizsprocket sa fie mort?",a="Morin a descoperit documente intr-o caravana jefuita, care dovedeau ca Venture Company complota sa-i alunge pe taurenii de pe pamanturile lor strabune pentru profit. Fizsprocket este supraveghetorul direct care pune in aplicare aceste planuri de exploatare bine calculate.",al={"de ce sa-l ucizi pe Fizsprocket","motivul lui Morin Cloudstalker"}},{q="Unde se afla Supervisor Fizsprocket?",a="Se afla in mina Venture Company, chiar la est de Ravaged Caravan, in Mulgore. In mina, urmeaza tunelul din extrema dreapta pana la o incapere unde sta inconjurat de muncitori si supraveghetori.",al={"unde se afla Fizsprocket","locatia minei Fizsprocket","harta Fizsprocket"}},{q="Ce dovada cere Morin ca Fizsprocket a fost invins?",a="Morin Cloudstalker are nevoie de clipboardul personal al lui Fizsprocket, care contine registre si documente ce ar putea dezvalui si alte ambitii ale Venture Company in Mulgore.",al={"dovada mortii","clipboard-ul lui fizsprocket"}},{q="De ce se afla Venture Company in Mulgore?",a="Venture Company este un cartel comercial lipsit de scrupule, hotarat sa jefuiasca teritoriile virgine de lemn, minerale si bogatii subterane valoroase, nesocotind cu totul populatiile bastinase si echilibrul mediului.",al={"venture co mulgore","de ce sunt goblini in mulgore"}},{q="Indeparteaza complet Venture Company uciderea lui Fizsprocket?",a="Nu. Desi moartea lui Fizsprocket le da peste cap conducerea locala si ii ofera lui Morin Cloudstalker notite esentiale despre planurile lor, Venture Company ramane o amenintare constanta, inradacinata in dealurile din Mulgore.",al={"a disparut Venture Co","dupa moartea lui Fizzsprocket"}}},fp="22,298,25.371.0,21.456.1,30.251.0,50.232.0,40.207.0,54.160.0,38.219.0,67.204.0"}
P.entries["quest:766"] = {n="Mazzranache",s="Maur Raincaller din Bloodhoof Village a fost muscat de Mazzranache, un strider de campie legendar care l-a terorizat pe bunicul sau cu o generatie in urma. Chinuit de febra si cosmaruri delirante, taurenul are nevoie de un leac puternic, preparat din fauna salbatica din Mulgore, inainte ca infectia sa-i curme viata.",h="Maur Raincaller din Bloodhoof Village a fost muscat de Mazzranache, un strider de campie legendar care l-a...",kw={"bloodhoof village","puma de campie","maur raincaller","mazzranache","mulgore","plainstrider","lup de preerie","swoop"},ang={["class:Hunter"]="Urmarirea lupilor de prerie, a pumelor, a alergatorilor de campie si a swoopurilor prin Mulgore ofera o lectie practica despre citirea campiilor si intelegerea faunei specifice savanei.",["faction:Horde"]="Apararea Bloodhoof Village de primejdiile cumplite din Mulgore este esentiala pentru instaurarea pacii si stabilitatii in patria taurenilor.",["race:Tauren"]="Leacul preparat de Maur reflecta vechea practica tauren de a obtine remedii direct din flora si fauna lui Earth Mother."},sec={{t="O mostenire a campiilor",b="Ani la rand, Maur Raincaller a considerat ca Mazzranache nu era decat o poveste de familie inspaimantatoare, transmisa de bunicul sau. Batranul tauren povestea despre un plainstrider neobisnuit de feroce, cu ochi rosii stralucitori, gheare ascutite ca briciul si o muscatura otravita, cu totul potrivita naturii pasnice a majoritatii vietuitoarelor din Mulgore. Cand Maur s-a intalnit cu fiara pe pajistea deschisa, legenda s-a dovedit cat se poate de reala, lasandu-l grav ranit si luptandu-se sa ajunga inapoi in siguranta."},{t="Intrecere cu infectia",b="Veninul creaturii isi face repede efectul, provocand febre mari si deliruri de cosmar. Pentru a-l curata inainte sa devina fatal, medicina traditionala tauren se bazeaza pe vitalitatea fiarelor din tinut. Maur are nevoie de o inima de lup de prerie, un femur de puma de campie, o solza de plainstrider si o pipota de swoop. Combinand esentele acestor vanatori si necrofagi feluriti, poate prepara o licoare capabila sa opreasca raspandirea necrotica si sa-l readuca la sanatate."}},faq={{q="Ce este Mazzranache?",a="Mazzranache este un strider de campie vestit si temut, care cutreiera pajistile din Mulgore. Spre deosebire de striderii obisnuiti, are un penaj viu colorat, ochi rosii demonici, gheare fioroase si o muscatura neobisnuit de veninoasa. A terorizat calatorii de-a lungul mai multor generatii.",al={"cine este Mazzranache","ce fel de bestie este Mazzranache","povestea lui Mazzranache"}},{q="Cine este Maur Raincaller?",a="Maur Raincaller este un tauren din Bloodhoof Village. In timp ce traversa Mulgore, a fost atacat pe neasteptate si muscat de umar de Mazzranache, ramanand tintuit la pat din cauza unei infectii veninoase, care-i pune viata in pericol.",al={"maur raincaller","cine mi-a dat aceasta misiune","cine este taurenul bolnav"}},{q="De ce are Maur nevoie de parti de la patru bestii diferite?",a="Leacurile traditionale ale taurenilor folosesc puterile naturale si esentele spirituale ale animalelor din campie pentru a neutraliza toxine puternice. Inima unui lup, maduva densa a unui femur de puma, un solz de plainstrider si pipota unei pasari swoop alcatuiesc impreuna un antidot suficient de puternic pentru a contracara veninul lui Mazzranache.",al={"de ce inima de lup si femur de puma","de ce ingrediente de origine animala","ingredientele remediului lui Mazzranache"}},{q="L-a ucis bunicul lui Maur pe Mazzranache?",a="Nu. Bunicul lui Maur s-a luptat cu temutul plainstrider cu ani in urma, dar n-a reusit sa-l invinga. A supravietuit doar pentru a le lasa urmasilor povesti de avertizare despre culorile sale vii si atacurile salbatice.",al={"l-a invins bunicul pe Mazzranache","Maur, bunicul lui Mazzranache","cine s-a luptat cu Mazzranache inainte"}},{q="Imi cere aceasta misiune sa-l vanez chiar pe Mazzranache?",a="Nu. Prioritatea imediata a lui Maur este sa supravietuiasca febrei. Sarcina se concentreaza exclusiv pe adunarea ingredientelor necesare pentru a-i prepara leacul, nu pe vanarea pasarii legendare.",al={"il omor pe mazzranache","unde se afla mazzranache","vanatoarea lui mazzranache"}},{q="Unde se afla Bloodhoof Village?",a="Bloodhoof Village se afla in centrul Mulgore, la sud de Thunder Bluff si chiar la est de Stonebull Lake. Este principala asezare a tinerilor viteji tauren care pornesc spre campiile intinse.",al={"unde se afla Bloodhoof Village","locatia Bloodhoof Village"}}},fx={["3b88d77e"]={q="De ce vrea Maur Raincaller ca acest lucru sa fie facut?",a="Viata lui Maur este in joc. In timp ce strabatea campiile din Mulgore, s-a intalnit cu Mazzranache, un strider de campie legendar care l-a terorizat candva pe bunicul sau. Creatura l-a muscat cu salbaticie de umar, injectandu-i venin. L-a cuprins o febra debilitanta, care ii provoaca cosmaruri delirante si se raspandeste necontenit prin trup. Fara ingredientele de origine animala necesare pentru a prepara un leac, infectia cumplita il va ucide in curand.",al={"motivul lui Maur Raincaller","de ce sa-l ajut pe Maur Raincaller","ce i s-a intamplat lui Maur"}},ce37bf7e={q="De ce are nevoie Maur de un strain in loc sa se vindece singur?",a="Maur este prea grav ranit si febril ca sa vaneze singur fiarele din Mulgore. Muscatura veninoasa a lui Mazzranache l-a rapus, lasandu-l cu delir si epuizare, tintuit in Bloodhoof Village. Cum timpul se scurge si infectia il poate ucide, trebuie sa se bazeze pe calatorii aflati in trecere, care sa urmareasca pumele sprintene, swoopii, lupii si plainstriderii necesari pentru leacul sau.",al={"de ce nu poate maur sa obtina piesele","de ce are maur nevoie de tine","de ce eu mazzranache"}}},fp="11,313,22.471.0,20.462.0,20.251.0,23.208.0,52.303.0,40.198.0,55.180.0,35.193.0"}
P.entries["quest:767"] = {n="Rite of Vision",s="Rite of Vision este o incercare esentiala de maturizare in cadrul Rites of the Earthmother, care pune la incercare maturitatea spirituala a unui tanar aventurier. Initiata de Baine Bloodhoof, misiunea ii indruma pe aspiranti sa ceara sfatul vazatorului satului, Zarlman Two-Moons. Parcurgerea acestei calatorii este esentiala pentru oricine cauta binecuvantarea si respectul batranilor de pe inaltimile din Thunder Bluff.",h="Rite of Vision este o incercare esentiala de maturizare in cadrul Rites of the Earthmother, care pune la...",kw={"baine bloodhoof","bloodhoof village","mulgore","rite of vision","ritualurile Earth Mother","incercare tauren","thunder bluff","zarlman two-moons"},ang={["class:Druid"]="Impartasirea viziunilor Earthmother intareste direct chemarea druidica de a asculta cu atentie intelepciunea si soaptele lumii vii.",["class:Shaman"]="Cautarea lui Zarlman Two-Moons si urmarea caii viziunilor rezoneaza profund cu datoria samanica de a echilibra treburile lumesti cu vointa stramosilor.",["faction:Horde"]="Indeplinirea acestor ritualuri sacre traditionale iti dovedeste loialitatea si respectul cultural fata de batranii tauren care ajuta la indrumarea Horde.",["race:Tauren"]="Rite of Vision este o etapa culturala esentiala pentru fiecare tanar tauren, marcand trecerea ta la statutul de aparator de incredere si calator al spiritelor triburilor."},sec={{t="O piatra de hotar sacra",b="De generatii, taureni nomazi au cautat indrumarea Mamei Pamant pentru a-si calauzi poporul prin campiile din Kalimdor. Acum, reuniti intre granitele sigure din Mulgore, isi pastreaza traditiile spirituale in inima societatii. Rite of Vision este una dintre incercarile stravechi cunoscute drept Rites of the Earthmother. In timp ce incercarile anterioare pun la incercare puterea fizica si legatura cu vanatoarea a initiatului, Rite of Vision cere o calatorie interioara, indrumandu-i pe tinerii tauren si pe aliatii onorati sa intre in comuniune directa cu spiritele."},{t="Indrumarea clarvazatorului",b="Inainte de a cauta o viziune spirituala, un initiat trebuie sa fie pregatit de cineva patrunzator in intelepciunea straveche. In Bloodhoof Village, aceasta sarcina ii revine respectatului saman Zarlman Two-Moons. Incredintat de Baine Bloodhoof sa-i pregateasca pe calatori, Zarlman are privirea agera necesara pentru a-i recunoaste pe cei care urmeaza calea stramosilor si le ofera ritualurile preliminare si pregatirile sacre de care au nevoie pentru a strapunge valul lumii fizice."}},faq={{q="Ce este Rite of Vision?",a="Rite of Vision este un ritual sacru din cadrul Rites of the Earthmother. Scopul sau este sa largeasca vederea spirituala a unui aventurier, permitandu-i sa comunice cu spiritele stramosilor si sa-si dovedeasca pregatirea spirituala in fata batranilor din Thunder Bluff.",al={"misiunea Rite of Vision","ce este Rite of Vision","povestea Rite of Vision"}},{q="Cine incepe aceasta misiune?",a="Misiunea este oferita de Baine Bloodhoof, fiul marelui sef Cairne Bloodhoof. Baine vegheaza asupra asezarii Bloodhoof Village si ii indruma pe calatorii vrednici catre batranii spirituali ai satului.",al={"cine da Rite of Vision","cel care da misiunea Rite of Vision"}},{q="Cine este Zarlman Two-Moons?",a="Zarlman Two-Moons este un saman tauren cu multa experienta si liderul spiritual al Bloodhoof Village. Ii pregateste pe calatorii si initiatii care vor sa treaca prin incercari sacre precum Rite of Vision.",al={"cine este zarlman","povestea lui zarlman two moons"}},{q="De ce sunt Rites of the Earthmother importante pentru tauren?",a="Rites of the Earthmother reprezinta un ritual traditional de trecere la maturitate pentru taureni. Indeplinirea lor cu succes dovedeste capacitatea fizica, armonia spirituala si respectul neclintit fata de pamant, aducand cinstea batranilor de rang inalt.",al={"semnificatia ritualurilor Mamei Pamant","de ce au loc ritualurile Mamei Pamant"}},{q="Pot cei care nu sunt tauren sa indeplineasca Rite of Vision?",a="Da. Aliatii din Horde care calatoresc prin Mulgore si castiga increderea tribului Bloodhoof pot urma calea Earthmother, aratand respect fata de traditiile tauren in schimbul favorii batranilor.",al={"pot Orc-ii sa indeplineasca Rite of Vision","Earthmother non-tauren"}},{q="Unde se desfasoara aceasta incercare?",a="Incercarea incepe in Bloodhoof Village, o asezare tauren importanta aflata langa malul Stonebull Lake, in centrul Mulgore, la sud de Thunder Bluff.",al={"unde este Rite of Vision","locatia Rite of Vision"}}},fx={["1fa313da"]={q="De ce vrea Baine Bloodhoof sa indeplinesti Rite of Vision?",a="Baine Bloodhoof te pregateste sa pasesti pe urmele stramosilor si sa-ti dovedesti valoarea in fata poporului tauren. Pe masura ce ajungi la maturitate in Mulgore, trebuie sa implinesti sacrele Rites of the Earthmother pentru a intra in legatura cu spiritele, a invata respectul fata de pamant si, in cele din urma, a castiga respectul batranilor din Thunder Bluff. Baine te indruma catre misticul satului, Zarlman Two-Moons, pentru a incepe cum se cuvine incercarea spirituala.",al={"de ce te trimite baine in rite of vision","motivul lui baine bloodhoof in rite of vision","de ce se face rite of vision"}}},fp="14,381,23.535.0,19.443.0,27.255.0,22.205.0,25.190.0,61.255.0,44.208.0,33.154.0"}
P.entries["quest:768"] = {n="Gathering Leather",s="Gathering Leather este o cerere simpla de materiale, oferita de Veren Tallstrider pe inaltimile din Thunder Bluff. Pentru a aproviziona capitala si a-i pune la incercare pe vanatorii tineri, Veren schimba un manunchi de piei de piele usoara tabacite pe bunuri mestesugite. Cererea scoate in evidenta traditia taurenilor, adanc inradacinata, de a transforma roadele vanatorii din campii in haine si armuri esentiale.",h="Gathering Leather este o cerere simpla de materiale, oferita de Veren Tallstrider pe inaltimile din Thunder...",kw={"colectarea pielilor","prelucrarea pielii","piele usoara","mulgore","vanatoarea taurenilor","thunder bluff","veren tallstrider"},ang={["class:Hunter"]="Vanatorii care pornesc pe campiile din Mulgore se pricep in mod firesc sa urmareasca prada si sa jupoaie pieile usoare de care are nevoie Veren.",["faction:Horde"]="Furnizarea de materii prime mestesugarilor din Thunder Bluff intareste tanara capitala in timp ce isi consolideaza apararea si retelele comerciale.",["race:Tauren"]="Pentru vanatorii tauren, cinstirea fiarei cazute prin transformarea blanii sale in bunuri folositoare este o practica culturala esentiala, transmisa din generatie in generatie."},sec={{t="Sustinerea Thunder Bluff",b="In capitala nou intemeiata, pe platourile inalte din Mulgore, mestesugul si supravietuirea merg mana in mana. Veren Tallstrider prelucreaza piei pentru a face haine si armuri de protectie necesare populatiei in crestere din Thunder Bluff. In loc sa vaneze totul singur, ii incurajeaza pe tinerii aventurieri porniti spre campii sa-i aduca vanatul, transformand o simpla vanatoare intr-o indatorire civica onorabila."},{t="Calea vanatorii",b="Pentru taureni, vanarea fiarelor pe pajisti nu este un sport, ci o indeletnicire onorabila care hraneste, imbraca si adaposteste tribul. Veren Tallstrider cauta vanatori dornici sa aduca onoare clanului lor, cerandu-le in mod special piei subtiri jupuite de pe fauna locala. In schimbul a douasprezece piei bine pastrate, vanatorul primeste bunuri trainice, intarind sprijinul reciproc care uneste societatea tauren."}},faq={{q="Cine este Veren Tallstrider?",a="Veren Tallstrider este un tabacar care locuieste in Thunder Bluff. El confectioneaza haine si armuri de protectie pentru poporul tauren si face negot cu vanatorii care ii aduc piei proaspete de pe campii.",al={"Veren Tallstrider","cine ofera Gathering Leather","cel care ofera misiunea de pielarie in Thunder Bluff"}},{q="De ce are nevoie Veren Tallstrider?",a="Veren cere douasprezece bucati de piele usoara, jupuita de pe fiarele care cutreiera Mulgore si tinuturile invecinate, pentru a confectiona bunuri destinate Thunder Bluff.",al={"cerinte pentru Gathering Leather","ce sa-i aduc lui veren","materiale pentru Gathering Leather"}},{q="Unde are loc aceasta misiune?",a="Misiunea incepe si se termina cu Veren Tallstrider, pe culmea din Thunder Bluff, desi pentru a o incheia trebuie sa vanezi fiare salbatice pe pajistile de dedesubt.",al={"unde se afla Veren Tallstrider","locatia adunarii pielii"}},{q="De ce acorda taurenii atat de multa importanta vanarii fiarelor?",a="Cultura Tauren considera vanatoarea un echilibru sacru cu Earth Mother. Fiecare parte a unei bestii doborate este folosita: carnea hraneste tribul, iar oasele si pieile tabacite sunt transformate in unelte, corturi si armuri rezistente.",al={"cultura vanatorii la tauren","de ce vaneaza pentru piele","povestea pielariei la tauren"}},{q="Poate orice aventurier din Horde sa indeplineasca aceasta sarcina?",a="Da, orice calator loial Horde pe care Veren il considera dornic sa-si incerce puterile in campii il poate ajuta sa adune piei.",al={"cine poate colecta piele","colectarea pielii este doar pentru Hoarda"}},{q="Ce se intampla dupa livrarea pielii?",a="Veren verifica starea pieilor, il lauda pe vanator pentru munca depusa si ii ofera, in schimbul lor, o piesa de echipament faurita.",al={"predarea pieilor adunate","recompensa lui Veren Tallstrider"}}},fx={["1249c214"]={q="De ce vrea Veren Tallstrider Piele Usoara?",a="Veren Tallstrider este un tabacar care confectioneaza imbracaminte si armuri pentru locuitorii din Thunder Bluff. Pentru a aproviziona orasul si a-si sustine mestesugul, se bazeaza pe vanatori, care ii aduc piei de calitate din campiile din Mulgore.",al={"de ce are Veren nevoie de piele","motivul lui Veren Tallstrider","de ce are Veren nevoie de piele usoara"}},cd30155e={q="La ce se foloseste Light Leather?",a="Pielea este transformata in vesminte esentiale, armuri de protectie si bunuri folositoare pentru taurenii care locuiesc pe inaltimile meselor din Thunder Bluff, precum si in echipament confectionat la schimb pentru vanatorii calatori.",al={"la ce foloseste pielea usoara","utilizarea pielii usoare","cum foloseste Veren pielea usoara"}}},fp="17,360,24.407.0,19.436.0,25.210.0,33.153.0,33.147.0,61.219.0,45.137.0,43.128.0"}
P.entries["quest:769"] = {n="Kodo Hide Bag",s="Kodo Hide Bag este o misiune de negot oferita de Veren Tallstrider, un tabacar tauren priceput, aflat pe platourile inalte din Thunder Bluff. In schimbul unor materiale de baza pentru mestesug, el transmite tehnica traditionala a campiilor, folosita la coaserea unor desagi rezistenti de calatorie din piele groasa de animal. Pentru ucenicii tabacari din Mulgore, aceasta este un ritual initiatic timpuriu.",h="Kodo Hide Bag este o misiune de negot oferita de Veren Tallstrider, un tabacar tauren priceput, aflat pe...",kw={"ata grosiera","kodo","geanta din piele de kodo","prelucrarea pielii","piele usoara","mulgore","thunder bluff","veren tallstrider"},ang={["faction:Horde"]="Mestesugarii din Thunder Bluff furnizeaza bunurile logistice esentiale care ii mentin echipati pe vanatorii, cercetasii si razboinicii Horde din centrul Kalimdorului.",["race:Tauren"]="Pentru Shu'halo, sa invete sa confectioneze echipament de incredere din puternicii kodo este un pas esential pentru a onora darurile Earth Mother si a pastra traditiile stramosesti."},sec={{t="O lectie pe mesa",b="Pe inaltimile mestesugaresti din Thunder Bluff, Veren Tallstrider pastreaza vechea traditie nomada de a nu irosi nimic din vanat. Pentru a-i deveni ucenic, un aspirant tabacar trebuie sa-i aduca piele usoara tabacita si ata rezistenta. Dovedindu-si priceperea cu materiale de baza, ucenicii arata ca sunt gata sa faureasca bunuri vrednice de a purta echipament de supravietuire prin intinderile aspre ale Kalimdorului."},{t="Spiritul kodo-ului",b="Pentru tauren, kodo-ul simbolizeaza rezistenta, puterea si hotararea neclintita. Pielea sa groasa il apara de maracini, de vantul muscator si de ghearele fiarelor. Faureala gentilor si vesmintelor din piele de kodo nu este doar o actiune practica, ci si o expresie a respectului fata de animalul care i-a hranit si purtat pe Shu'halo de-a lungul nenumaratelor generatii petrecute pe campiile din Mulgore."}},faq={{q="Cine ofera misiunea Kodo Hide Bag?",a="Misiunea este oferita de Veren Tallstrider, instructor de prelucrare a pielii si negustor tauren din Thunder Bluff.",al={"cel care ofera misiunea","unde poti lua misiunea pentru geanta din piele de kodo","locatia lui Veren Tallstrider"}},{q="Cine poate indeplini aceasta sarcina?",a="Numai aventurierii instruiti in Leatherworking, care au atins cel putin nivelul de ucenic 10, pot primi aceasta sarcina de instruire de la Veren Tallstrider.",al={"cine poate lua aceasta misiune","cerinte pentru misiune","cerinta de profesie"}},{q="De ce materiale are nevoie Veren Tallstrider?",a="Are nevoie de patru bucati de piele usoara si patru gheme de fir grosier pentru a-si reface stocul de marfuri inainte sa-ti dezvaluie modelul.",al={"ce obiecte sunt necesare","materiale pentru geanta din piele de kodo","obiecte de predat pentru misiune"}},{q="De ce este pielea de kodo atat de importanta pentru mestesugarii tauren?",a="Kodo intruchipeaza rezistenta si forta fizica, calitati foarte pretuite de tauren. Confectionarea de echipamente trainice din pieile lor onoreaza spiritul creaturii si le ofera calatorilor unelte solide pentru traversarea campiilor.",al={"de ce piele de kodo","semnificatia kodo pentru tauren","importanta kodo"}},{q="Ce te invata Veren Tallstrider la finalizare?",a="Dupa ce primeste proviziile, Veren il invata pe mester cunostintele speciale necesare pentru a coase un Kodo Hide Bag.",al={"recompensa misiunii","ce primesc","model de geanta"}},{q="De unde pot fi obtinute materialele necesare?",a="Light Leather se obtine jupuind bestii de nivel scazut din Mulgore si din teritoriile invecinate, in timp ce Coarse Thread poate fi cumparat direct de la comerciantii de marfuri si de la croitori.",al={"de unde obtii piele usoara","de unde obtii ata groasa"}}},fx={c94273ea={q="De ce vrea Veren Tallstrider sa se faca asta?",a="Veren Tallstrider este mandru ca formeaza noua generatie de tabacari tauren. Bestiile kodo din Mulgore sunt venerate pentru puterea si rezistenta lor, iar mestesugirea unei genti traditionale din pielea lor este o deprindere de baza. Cerandu-ti sa aduni materialele necesare meseriei sale, Veren iti pune la incercare devotamentul si ingeniozitatea inainte de a-ti transmite tainele mestesugului.",al={"de ce vrea veren tallstrider piele","motivul lui veren tallstrider","de ce exista misiunea cu sacul din piele de kodo"}},["1f62e959"]={q="La ce foloseste pielea usoara?",a="Light Leather este materia prima de baza pe care Veren Tallstrider o cere in schimbul instruirii sale. Prelucrarea pieilor tabacite este esenta mestesugului taurenilor in pielarie, iar furnizarea unei piei de calitate dovedeste ca ai insusit bazele tratarii blanurilor de animale inainte de a invata sa cosi recipiente speciale, precum gentile din piele de kodo.",al={"la ce este folosita pielea usoara","de ce sa aduci piele usoara","scopul pielii usoare"}},["7d0f7d7f"]={q="La ce foloseste Firul grosier?",a="Firul aspru este un material esential pentru croitorie si prelucrarea pielii, folosit la legarea pieilor groase. Pentru a confectiona desagi rezistente, care sa tina piept campiilor din Mulgore, un mestesugar are nevoie de o sfoara trainica, ce nu se rupe sub greutate mare sau pe vreme aspra.",al={"de ce fir grosier","scopul firului grosier","la ce foloseste firul grosier"}}},fp="13,362,20.426.0,18.388.0,35.113.0,39.149.0,46.133.0,59.224.0,50.125.0,46.176.0"}
P.entries["quest:77"] = {n="A Sticky Situation",s="Gilveradin Sunchaser are ambalajul original pentru Hinterlands Honey Ripple, pe care il cauta Dran Droffers, si te va ajuta sa-l impachetezi contra unei taxe de doua sticle in plus. Sticlele se afla in lazi din jurul bazei abandonate a Horde, langa Skulk Rock.",h="Gilveradin Sunchaser are ambalajul original pentru Hinterlands Honey Ripple, pe care il cauta Dran Droffers...",kw={"dran droffers","gilveradin sunchaser","hinterlands","hinterlands honey ripple","mase gelatinoase","skulk rock","slime-uri"},sec={{t="O chestiune de ambalare",b="Dran Droffers cauta siropul, iar Gilveradin Sunchaser are ambalajul original al acestuia. Ajutorul nu e gratuit: Gilveradin vrea doua sticle in plus drept rasplata pentru efort. Trebuie sa strangi zece sticle de Hinterlands Honey Ripple si sa le aduci inapoi in tabara."},{t="Ruinele din Skulk Rock",b="Lazile se afla in jurul bazei abandonate a Horde de langa Skulk Rock. Mlastini si namoluri dezgustatoare se agata de ruine, iar zvonurile spun ca un soi de namol-maestru le conduce."}},faq={{q="Cine vrea ca Hinterlands Honey Ripple sa fie ambalata?",a="Dran Droffers este cel care cauta obiectul, iar Gilveradin Sunchaser are ambalajul original, destinat tatalui lui Malton.",al={"cine are nevoie de pachetul Ripple","pachetul Ripple al lui Dran Droffers","pentru cine este ambalajul"}},{q="Cat cere Gilveradin pentru ambalare?",a="Gilveradin cere inca doua sticle de ripple drept plata. Zece sticle trebuie recuperate din lazi.",al={"de ce 10 sticle","taxa lui gilveradin","de ce atata ripple"}},{q="Unde sunt pastrate lazile cu Hinterlands Honey Ripple?",a="Se afla in lazi raspandite in jurul bazei abandonate a Horde, de langa Skulk Rock, in Hinterlands.",al={"locatia lui ripple","unde se afla honey ripple","lazile din Skulk Rock"}},{q="Ce se afla in tabara abandonata de la Skulk Rock?",a="Mocirlele si masele gelatinoase respingatoare se agata de ruine, iar zvonurile spun ca un maestru al maselor gelatinoase le conduce.",al={"monstri din Skulk Rock","ce se afla la Skulk Rock","mocirle de la Skulk Rock"}}},fp="18,243,21.259.0,19.159.0,48.140.0,46.115.0,54.86.0,44.82.0"}
P.entries["quest:770"] = {n="The Demon Scarred Cloak",s="Demon Scarred Cloak este o piele zdrentuita, recuperata de la legendarul lup alb Ghost Howl, care rataceste prin campiile inierbate din Mulgore. Marcata de o rana veche, primita in luptele trecute cu Burning Legion, pielea dovedeste ca fiara a fost eliberata din chinuri. Aducerea ei batranilor din Bloodhoof Village incheie povestea unei legende locale tragice.",h="Demon Scarred Cloak este o piele zdrentuita, recuperata de la legendarul lup alb Ghost Howl, care rataceste...",kw={"Burning Legion","Demon Scarred Cloak","Ghost Howl","Mulgore","Skorn Whitecloud","lup alb"},ang={["class:Druid"]="Druizii vad blana brazdata de semne demonice ca pe o amintire sumbra ca pamantul si vietatile sale salbatice poarta inca rani nevindecate, ramase in urma invaziei demonice din Kalimdor.",["class:Hunter"]="Sa urmaresti un alfa singuratic si plin de cicatrici precum Ghost Howl este un ritual de trecere esential, care iti aduce laude pe masura si darul unui vanator maestru, batranul Skorn Whitecloud.",["race:Tauren"]="Pentru Shu'halo, vanatoarea lui Ghost Howl nu este un act de cruzime sau cucerire, ci un ritual solemn, menit sa elibereze o creatura chinuita de pangarirea persistenta a Burning Legion."},sec={{t="O relicva a ranilor demonice",b="Ghost Howl este un lup alb greu de zarit, cunoscut in Mulgore atat pentru ferocitatea, cat si pentru urletul sau jalnic. Cand este ucis, bestia lasa in urma o blana marcata vizibil de o coruptie demonica dezgustatoare. Aceste urme persistente dateaza din luptele disperate ale lupului impotriva demonilor invadatori ai Burning Legion, o confruntare care l-a ranit pe Ghost Howl atat in trup, cat si in spirit, mult dupa incheierea Third War."},{t="Pace pentru un spirit framantat",b="Taurenii din Mulgore pastreaza un respect profund pentru fiarele salbatice din tinutul lor natal, venerandu-le ca pe copiii Earth Mother. Inmanarea mantiei cicatrizate lui Skorn Whitecloud in Bloodhoof Village confirma moartea pradatorului chinuit. Skorn recunoaste indemanarea extraordinara necesara pentru a-l urmari si invinge pe Ghost Howl si isi exprima speranta sumbra ca, in moarte, spiritul chinuit al lupului si-a gasit in sfarsit pacea."}},faq={{q="Ce este Demon Scarred Cloak?",a="Este blana zdrentuita jupuita de pe Ghost Howl, un lup alb legendar din Mulgore. Blana poarta cicatrici vizibile lasate de energiile fel, dintr-o lupta veche impotriva Burning Legion.",al={"ce este mantia Demon Scarred Cloak","obiectul Demon Scarred Cloak","blana lui Ghost Howl"}},{q="De unde provin cicatricile demonice de pe mantie?",a="Ghost Howl si-a capatat ranile in luptele impotriva Burning Legion, cand invadatorii demonici au inaintat prin Kalimdor in timpul celui de-al Third War.",al={"de ce este ghost howl plin de cicatrice","cum a ajuns ghost howl plin de cicatrice","ghost howl si legiunea"}},{q="Cui trebuie sa duc mantia?",a="Du mantia la Skorn Whitecloud, un vanator tauren batran care locuieste in Bloodhoof Village din Mulgore.",al={"unde predau Demon Scarred Cloak","cine vrea Demon Scarred Cloak","unde predau obiectul lui Skorn Whitecloud"}},{q="De ce ii pasa lui Skorn Whitecloud de Ghost Howl?",a="Skorn Whitecloud este un vanator pensionat, care il recunoaste pe Ghost Howl drept o fiara formidabila, profund afectata de coruptia demonica. Respecta indemanarea necesara pentru a dobori o asemenea creatura si spera ca spiritul ei isi va gasi, in sfarsit, pacea.",al={"povestea lui Skorn Whitecloud","de ce vrea Skorn Ghost Howl"}},{q="Unde poate fi gasit Ghost Howl?",a="Ghost Howl este un lup alb rar care strabate campiile domoale din Mulgore si este vazut de obicei pe campurile deschise din nord sau din centru, intre Red Cloud Mesa si Thunder Bluff.",al={"unde il gasesc pe ghost howl","locatia lui ghost howl","aparitia lui ghost howl"}},{q="De ce spera taurenii ca spiritul lupului isi va gasi pacea?",a="Cultura tauren pune accentul pe armonia cu natura si venerarea spiritelor salbatice. Intrucat coruptia demonica i-a adus lui Ghost Howl chinuri fara sfarsit, infrangerea sa este privita drept o eliberare milostiva, prin intoarcerea la Earth Mother.",al={"credinta taurenilor in Ghost Howl","spiritul Ghost Howl"}}},fp="23,378,21.424.0,27.421.0,32.174.0,49.141.0,28.104.0,48.224.0,26.172.0,53.220.0"}
P.entries["quest:7701"] = {n="WANTED: Overseer Maltorius",s="Un afis cu recompense anunta ca Overseer Maltorius, un agent tradator al Thorium Brotherhood si comandant nou angajat al echipei Dark Iron Slag Pit din Cauldron, trebuie sa moara. Din ordinul lui Overseer Oilfist, capul sau trebuie adus drept dovada lui Lookout Captain Lolo Longstriker.",h="Un afis cu recompense anunta ca Overseer Maltorius, un agent tradator al Thorium Brotherhood si comandant nou...",kw={"recompensa","cazan","lolo longstriker","overseer maltorius","overseer oilfist","searing gorge","groapa de zgura","thorium brotherhood"},sec={{t="Pret pe capul unui tradator",b="Overseer Maltorius, un Dark Iron dwarf tradator, trebuie gasit in adancurile Slag Pit din Cauldron. Ordinul este sa-l ucizi, sa-i iei capul si sa-l duci inapoi la Lookout Captain Lolo Longstriker pentru recompensa oferita."}},faq={{q="Cine este Overseer Maltorius?",a="Un Dark Iron dwarf tradator. Anuntul il numeste agent rogue al Thorium Brotherhood si noul comandant angajat al echipajului Dark Iron Slag Pit din Cauldron.",al={"povestea lui maltorius","cine este maltorius","trecutul lui Overseer Maltorius"}},{q="Unde poate fi gasit Overseer Maltorius?",a="Jos, in Slag Pit, care apartine de Cauldron.",al={"locatia lui maltorius","unde se afla maltorius","cum il gasesti pe overseer maltorius"}},{q="Cine a ordonat moartea lui Overseer Maltorius?",a="Overseer Oilfist, mentionat in anunt drept cel care a dat ordinul.",al={"cine a pus recompensa","cine vrea ca Maltorius sa moara","cine a ordonat uciderea"}},{q="Cine primeste dovada mortii lui Maltorius?",a="Lookout Captain Lolo Longstriker, in Searing Gorge. Capul lui Maltorius este dovada ceruta.",al={"cui predau capul lui Maltorius","unde duc capul lui Maltorius","locatia lui Lolo Longstriker"}}},fp="26,274,20.217.0,26.162.0,38.52.0,44.71.0,40.97.0"}
P.entries["quest:7704"] = {n="Look at the Size of It!",s="Ai intrat in posesia unei perne uriase si ornamentate, care i-a apartinut candva lui Chambermaid Pillaclencher. Evonice Sootsmoker, din Searing Gorge, sigur o va dori.",h="Ai intrat in posesia unei perne uriase si ornamentate, care i-a apartinut candva lui Chambermaid...",kw={"chambermaid pillaclencher","evonice sootsmoker","priveste ce marime are","perna","searing gorge"},sec={{t="O perna pentru Evonice",b="Perna pastrata de Chambermaid Pillaclencher este acum a ta. Evonice Sootsmoker va fi cu siguranta nerabdatoare sa puna mana pe ea. Du-i-o in Searing Gorge si vezi ce-ti ofera pentru deranj."}},faq={{q="Cine vrea perna lui Chambermaid Pillaclencher?",a="Se presupune ca Evonice Sootsmoker din Searing Gorge il doreste foarte mult.",al={"cui ii duc perna","perna lui evonice sootsmoker","unde ajunge perna"}},{q="De unde provine aceasta perna?",a="I-a apartinut lui Chambermaid Pillaclencher si este urias si impodobit.",al={"cine lasa perna","cine scapa perna","perna cameristei"}},{q="Unde poate fi gasit Evonice Sootsmoker?",a="In Searing Gorge.",al={"locatia lui Evonice","unde este Evonice Sootsmoker","Evonice in Searing Gorge"}}},fp="23,156,20.196.0,45.68.0,33.69.0,38.21.0"}
P.entries["quest:771"] = {n="Rite of Vision",s="Rite of Vision este o incercare spirituala fundamentala, prin care trec tinerii tauren cand parasesc Red Cloud Mesa si patrund in Mulgore. Pentru a strapunge valul si a primi indrumarea spiritelor stramosilor, initiatii trebuie sa adune ingrediente naturale si sa prepare Water of the Seers, sub privirea atenta a lui Zarlman Two-Moons, in Bloodhoof Village.",h="Rite of Vision este o incercare spirituala fundamentala, prin care trec tinerii tauren cand parasesc Red...",kw={"ambercorn","Bloodhoof Village","Mama Pamant","Mulgore","Rite of Vision","Water of the Seers","pietre de fantana","Zarlman Two-Moons"},ang={["class:Druid"]="Druizii venereaza profund ghindele chihlimbarii si pietrele fantanilor, vazandu-le drept manifestari directe ale florei si ale apelor care dau viata si mentin echilibrul din Mulgore.",["class:Shaman"]="Shamanii vor recunoaste pregatirea apei Water of the Seers drept un ritual traditional de impamantare, care acorda spiritul pentru a percepe elementele nevazute inainte de a vorbi direct cu spiritele.",["race:Tauren"]="Pentru tauren, Rite of Vision este un moment esential al traditiei, care leaga un razboinic, vanator sau mistic aflat la inceput de drum de mostenirea spirituala a lui Earth Mother si a stramosilor."},sec={{t="Reactivii pamantului",b="Inainte de a primi vreo viziune, initiatul trebuie sa demonstreze ca intelege in profunzime darurile naturii raspandite prin Mulgore. Zarlman Two-Moons ii cere celui care cauta sa adune pietrele fantanilor, aflate langa puturile sacre de apa ale comunitatii, precum si stiuleti de ambercorn cazuti sub radacinile copacilor stravechi din Mulgore. Aceste elemente naturale nu sunt simple obiecte fizice; pentru tauren, ele adapostesc magia latenta si seva vitala a Earth Mother, gata sa fie canalizate in ritualuri."},{t="Prepararea Water of the Seers",b="Dupa ce le aduna, Zarlman imbina pietrele si porumbul de chihlimbar pentru a prepara puternicul Water of the Seers. Bauta langa flacara tribala a satului, aceasta potiune ceremoniala limpezeste mintea si cheama un indrumator eteric. Urmarirea acestei aparitii de-a lungul campiilor este adevarata incercare a ritualului, punand la incercare capacitatea initiatului de a pasi intre lumea materiala si soaptele spirituale ale tinutului."}},faq={{q="Care este scopul Rite of Vision?",a="Rite of Vision este o incercare spirituala pentru taurenii care ajung la maturitate si isi cauta drumul. Pregatind si band Water of the Seers, initiatul invata sa intre in comuniune cu spiritele si sa urmeze semnele stramosilor de-a lungul campiilor din Mulgore.",al={"ce este rite of vision","de ce sa fac rite of vision","scopul rite of vision"}},{q="Cine este Zarlman Two-Moons?",a="Zarlman Two-Moons este un saman si vazator tauren, stationat in Bloodhoof Village. El supravegheaza probele spirituale ale tinerilor aventurieri, pregateste licori ritualice precum Water of the Seers si interpreteaza semnele Earth Mother.",al={"cine este Zarlman","rolul lui Zarlman Two Moons","Zarlman, cel care da misiuni"}},{q="Unde se gasesc pietrele de fantana si ghindele chihlimbarii?",a="Pietrele fantanilor se culeg de pe pamantul din apropierea fantanilor cu apa dulce raspandite prin Mulgore. Ambercorn poate fi gasit imprastiat la baza copacilor mari si ramificati care impanzesc peisajul ierbos din jur.",al={"unde gasesc Ambercorn","locatia pietrelor fantanii","reagentii pentru Rite of Vision"}},{q="Ce se intampla dupa ce bei Water of the Seers?",a="Bautura sorbita langa focul tribului deschide vederea spirituala a celui care o bea, dezvaluindu-i un animal calauza fantomatic. Cel care cauta trebuie sa urmeze spiritul peste campii pentru a descoperi urmatoarea etapa a calatoriei sale sacre.",al={"ce se intampla dupa Rite of Vision","efectul Water of the Seers","continuarea misiunii viziunii"}},{q="De ce pretuiesc Tauren atat de mult fantanile cu apa?",a="Apa este seva vietii in Mulgore si un dar pretios al Earth Mother. Fantanile sunt centre comunitare sacre care hranesc atat pamantul, cat si turmele sale, facand ca pietrele adunate in preajma lor sa fie incarcate spiritual.",al={"fantanile taurenilor","de ce sunt fantanile sacre","apa din Mulgore"}},{q="Aceasta misiune duce la alte rituri?",a="Da. Aceasta sarcina face parte dintr-o ceremonie in mai multe etape. Dupa ce Zarlman pregateste Water of the Seers, initiatii trebuie sa o bea, sa urmareasca viziunea care li se arata si sa se infatiseze in fata conducatorilor varstnici din Mulgore.",al={"urmatoarea misiune din Rite of Vision","este Rite of Vision o serie de misiuni","seria ritualurilor taurenilor"}}},fx={["6b13f1a7"]={q="De ce vrea Zarlman Two-Moons sa se faca asta?",a="In calitate de shaman al tribului, Zarlman Two-Moons raspunde de indrumarea tinerilor aventurieri promitatori prin traditiile sacre ale taurenilor. Nu-ti poate darui pur si simplu intelepciune spirituala; trebuie sa castigi favoarea Earth Mother si a stramosilor tai, participand direct la ritual, incepand prin a aduna chiar tu elementele sacre ale pamantului.",al={"motivul lui Zarlman Two Moons","de ce te trimite Zarlman","motivul lui Zarlman pentru Rite of Vision"}},cc7474fb={q="La ce folosesc Well Stones?",a="Pietrele fantanilor sunt adunate din fantanile sacre cu apa din tot Mulgore. Imbibate cu magia naturala a celor mai pure izvoare ale Earth Mother, ele sunt unul dintre reactivii esentiali de care are nevoie Zarlman Two-Moons pentru a prepara mistica Water of the Seers.",al={"scopul pietrelor fantanilor","de ce este necesara o piatra a fantanii","utilizarea pietrei fantanii"}},["4efb8f2d"]={q="La ce foloseste Ambercorn?",a="Cazut din copacii falnici din Mulgore, Ambercorn pastreaza esenta naturala a florei tinutului. Amestecat cu pietre pentru fiert si lasat la macerat de Zarlman Two-Moons, ii confera proprietatile magice necesare prepararii Water of the Seers, care-ti daruieste viziuni stramosesti.",al={"scopul Ambercorn","la ce se foloseste Ambercorn","de ce sa obtii Ambercorn"}},["761f0189"]={q="De ce trebuie sa aduni reagentii in locul lui Zarlman Two-Moons?",a="Rite of Vision este o proba personala de dezvoltare spirituala, nu o corvoada obisnuita. Pentru a comunica cu spiritele, trebuie sa-ti demonstrezi respectul si armonia cu pamantul cautandu-i cu propriile maini binecuvantarile naturale. Daca altcineva ar aduna reactivii, scopul sacru al probei ar fi zadarnicit.",al={"de ce trebuie sa obtin ambercorn","de ce nu aduna zarlman pietrele wells","de ce eu pentru Rite of Vision"}}},fp="14,335,24.476.0,30.397.0,42.238.0,25.234.0,42.210.0,51.214.1,47.219.0,38.207.1"}
P.entries["quest:772"] = {n="Rite of Vision"}
P.entries["quest:7721"] = {n="Fuel for the Zapping",s="Pe coasta Forgotten Coast din Feralas, Zorbin Fandazzle a deschis un atelier de inginerie, impotriva oricarei judecati, iar elementalii locali sunt o pacoste. Sunt, de asemenea, o sursa ideala de energie bruta pentru perfectionarea lui Ultra-Shrinker, iar Zorbin vrea nucleele de elemental de apa.",h="Pe coasta Forgotten Coast din Feralas, Zorbin Fandazzle a deschis un atelier de inginerie, impotriva oricarei...",kw={"feralas","forgotten coast","elemental al marii","stropi de mare","ultra-shrinker","nucleu de elemental al apei","zorbin fandazzle"},sec={{t="Puterea valurilor",b="Zorbin Fandazzle blestema puterile nestavilite ale elementarismului si ii numeste daunatori pe elementali de pe coasta. Totusi, Zorbin ii considera si o sursa ideala de energie bruta pentru rafinarea Ultra-Shrinker-ului. Zorbin vrea sa-i pui la punct pe Sea Elementals si Sea Sprays de pe coasta, sa le pastrezi nucleele elementale de apa si sa i le aduci la doc."},{t="Multumirile lui Zorbin",b="Zorbin este incantat: nucleele vor permite continuarea lucrului o vreme, iar acum sunt mai putine elementale de-a lungul coastei. Zorbin adauga ca ideea de a deschide pravalie in ceea ce s-ar putea sa fie cel mai prost loc imaginabil il facuse sa planga noaptea. Zorbin isi arata recunostinta platindu-te, desi asta ii pune finantele la grea incercare."}},faq={{q="Cine cere nucleele elementale?",a="Zorbin Fandazzle, care are un atelier de inginerie pe Forgotten Coast din Feralas, langa doc.",al={"cine da fuel for the zapping","cel care ofera misiunea zorbin fandazzle","cine incepe fuel for the zapping"}},{q="De ce are nevoie Zorbin Fandazzle de nuclee de elemental al apei?",a="Zorbin considera ca elementalii din zona sunt o sursa ideala de energie bruta pentru perfectionarea Ultra-Shrinker, iar el vrea nucleele elementarilor de apa.",al={"de ce sunt necesare nucleele elementarilor de apa","la ce folosesc nucleele","combustibil pentru ultra-shrinker"}},{q="Unde sunt adunate nucleele elementale?",a="Zorbin vrea sa fie luati de la Sea Elementals si Sea Sprays care cutreiera Forgotten Coast din Feralas.",al={"unde gasesc miezuri","locatia elementarilor marini","unde sunt sea sprays"}}},fp="20,273,19.352.0,15.310.1,38.103.0,53.154.0,39.108.0"}
P.entries["quest:7722"] = {n="What the Flux?",s="Master Smith Burninate spune ca, atunci cand Maltorius a parasit clanul lor, le-a luat reteta pentru flux arzator, care valora mai mult decat un cristal arcane impecabil. Burninate vrea planurile secrete inapoi si e sigur ca se afla langa Maltorius, in adancul Slag Pit.",h="Master Smith Burninate spune ca, atunci cand Maltorius a parasit clanul lor, le-a luat reteta pentru flux...",kw={"burninate","cazan","flux incandescent","maltorius","planuri","searing gorge","groapa de zgura"},sec={{t="Reteta furata",b="Master Smith Burninate il numeste tradator pe Maltorius, care a parasit clanul cu reteta pentru flux incendiar. Burninate ar paria ca reteta a venit odata cu noua promovare a lui Maltorius in randurile Dark Iron si vrea sa i se aduca planurile secrete."},{t="In Slag Pit",b="Burninate este sigur ca planurile se afla aproape de Maltorius, in adancurile din Slag Pit. Burninate vrea sa-i aduci inapoi Secret Plans: Fiery Flux."}},faq={{q="Cine a furat reteta pentru fluxul incendiar?",a="Maltorius, pe care Master Smith Burninate il numeste tradator al clanului lor.",al={"cine a furat reteta","cine a luat planurile","ce a facut tradatorul fluxului"}},{q="Unde se afla planurile secrete?",a="Burninate crede ca se afla aproape de Maltorius, in adancurile Slag Pit din Cauldron.",al={"unde sunt planurile","locatia planurilor secrete pentru Fiery Flux","unde gasesc planurile Fiery Flux"}},{q="Cine cere recuperarea planurilor?",a="Burninate, un maestru fierar, le vrea inapoi.",al={"cine ofera ce flux","cine da misiunea What the Flux"}},{q="De ce conteaza planurile pentru Burninate?",a="Burninate spune ca reteta pentru fiery flux valoreaza mai mult decat un cristal arcane nepatat si ca era secretul clanului.",al={"de ce e important fiery flux","importanta retetei de fiery flux"}}},fp="14,241,17.224.0,17.159.0,36.69.0,27.80.0,39.53.0,37.120.0"}
P.entries["quest:7723"] = {n="Curse These Fat Fingers",s="Hansel Heavyhands, aflat in Searing Gorge, nu mai poate imparti batai ca inainte, din cauza degetelor umflate. Hansel iti cere sa te duci sa-i tavalesti pe war golemii grei in locul sau.",h="Hansel Heavyhands, aflat in Searing Gorge, nu mai poate imparti batai ca inainte, din cauza degetelor umflate.",kw={"cazan","degete groase","hansel heavyhands","golemuri de razboi grele","searing gorge","carnati de sange din thelsamar"},sec={{t="Degete ca niste carnati",b="Hansel Heavyhands spune ca aerul rarefiat din defileu face ca degetele lui Hansel sa se umfle pana ajung sa semene cu niste carnati uriasi de sange din Thelsamar. Drept urmare, Hansel nu mai poate administra bataile de altadata si are nevoie sa te ocupi tu de treburile lui in locul sau."},{t="Primul pe lista",b="Primii pe lista lui Hansel sunt masivii golemii de razboi din defileu, pe care Hansel vrea sa-i zdrobesti. Trebuie distrusi douazeci. Se plimba prin zonele din jurul Cauldron, iar tu te intorci la Hansel dupa ce ai doborat destui."}},faq={{q="Cine este Hansel Heavyhands?",a="Cineva din Searing Gorge, cu degetele umflate, nu poate lupta si iti cere sa dai tu loviturile.",al={"hansel heavyhands","cine ofera Curse These Fat Fingers","cine ofera misiunea"}},{q="De ce nu poate Hansel sa lupte personal cu golemii?",a="Hansel da vina pe clima si pe aerul rarefiat din Gorge pentru umflarea degetelor lor, pe care le aseamana cu niste carnati uriasi de sange din Thelsamar.",al={"de ce sunt degetele lui Hansel groase","povestea degetelor groase","mainile umflate ale lui Hansel"}},{q="Cu ce dusmani trebuie sa te ocupi?",a="Douazeci de golemuri de razboi greoi.",al={"cu ce dusmani ma lupt","pe cine vrea hansel mort"}},{q="Unde se afla golemii de razboi grei?",a="Cutreiera zonele din jurul Cauldron, in Searing Gorge.",al={"unde se afla golemii","locatia golemului de razboi greu"}}},fp="23,169,21.266.0,17.223.0,25.111.0,47.134.0,29.24.0,39.62.0"}
P.entries["quest:7724"] = {n="Fiery Menace!",s="Hansel Heavyhands spune ca de fiecare data cand vrea sa se relaxeze putin si sa reflecteze la viata lui, puterile care conduc lumea ii dau de lucru. Paianjenii de lava mai mari fac ravagii in Searing Gorge, iar el vrea sa omori douazeci dintre ei.",h="Hansel Heavyhands spune ca de fiecare data cand vrea sa se relaxeze putin si sa reflecteze la viata lui...",kw={"amenintare de foc","paianjeni maiestosi de lava","hansel heavyhands","pumn de ulei","searing gorge","paianjeni"},sec={{t="O alta treaba pentru Hansel",b="Hansel Heavyhands se plange ca mai-marii nu-l lasa niciodata in pace. Paianjenii mari de lava fac zarva, iar Hansel ar prefera sa-i omori tu in locul lui."},{t="Paianjenii de lava superiori",b="Oilfist spune ca paianjenii arunca foc dintr-un loc nepotrivit, ceea ce-i supara pe copii. Hansel vrea sa fie ucisi douazeci de paianjeni de lava superiori, care se gasesc pe platouri si langa lacurile de lava din Searing Gorge."}},faq={{q="Cine te trimite dupa paianjeni?",a="Hansel Heavyhands, in Searing Gorge, spera sa aiba parte de un moment de liniste, dar primeste in schimb o noua sarcina.",al={"cel care da misiunea","cine da misiunea","hansel"}},{q="De ce trebuie ucisi paianjenii?",a="Greater lava spiders fac ravagii, iar Oilfist spune ca felul in care scuipa foc ii tulbura pe copii.",al={"de ce sa ucid paianjenii","ce au facut paianjenii","problema cu paianjenii"}},{q="Cine i-a vorbit lui Hansel despre paianjeni?",a="Oilfist, care spune ca paianjenii trag foc dintr-un loc stanjenitor.",al={"cine s-a plans de paianjeni","oilfist"}},{q="Cate greater lava spiders trebuie ucise?",a="Hansel cere sa fie eliminati douazeci.",al={"cati paianjeni","numarul de paianjeni"}}},fp="13,236,22.170.0,24.214.0,32.101.0,37.104.0,34.63.0,45.38.0"}
P.entries["quest:7725"] = {n="Again With the Zapped Giants",s="Zorbin Fandazzle stie ca ai adunat deja reziduuri, dar are mereu nevoie de mai multe. Poti folosi din nou Ultra-Shrinker asupra gigantilor din Feralas, iar Zorbin te asteapta langa docurile din Forgotten Coast. De data aceasta nu te poate plati nici pe departe la fel de mult, dar promite sa raspandeasca vestea despre serviciile tale.",h="Zorbin Fandazzle stie ca ai adunat deja reziduuri, dar are mereu nevoie de mai multe.",kw={"feralas","forgotten coast","giganti","reziduuri de miniaturizare","steamwheedle cartel","ultra-shrinker","zorbin fandazzle"},sec={{t="Inca o reprezentatie pentru Ultra-Shrinker",b="Zorbin Fandazzle recunoaste ca ai adunat deja reziduuri, dar numeste asta o repetitie si spune ca intotdeauna mai e loc pentru inca. Zorbin iti cere sa electrocutezi din nou uriasii din Feralas cu Ultra-Shrinker si sa aduci zece reziduuri de miniaturizare, luate de la uriasii micsorati, la docurile din Forgotten Coast. Fiindca Zorbin nu-ti poate oferi mare lucru la schimb, iti promite sa-ti laude serviciile printre prietenii goblini, care au urechi destul de mari."},{t="Multumirile lui Zorbin",b="Zorbin e nespus de bucuros ca ai reusit din nou, desi plata e mai mica decat te-ai obisnuit. Zorbin insista ca vestea despre faptele tale marete in slujba goblinilor rasuna deja prin centrele de putere ale Steamwheedle Cartel."}},faq={{q="Cine cere mai mult reziduu?",a="Zorbin Fandazzle, care asteapta langa docurile din Forgotten Coast, in Feralas.",al={"cine da misiunea","locatia lui Zorbin","cine ofera Again With the Zapped Giants"}},{q="Ce a fost inainte de asta?",a="Urmeaza dupa Zapped Giants, prima ta serie de adunare a reziduurilor pentru Zorbin Fandazzle.",al={"conditie prealabila","misiunea anterioara","ce trebuie sa fac mai intai"}},{q="Cum se aduna reziduurile?",a="Ultra-Shrinker-ul lui Zorbin este folosit asupra oricarui tip de urias din Feralas pentru a-l micsora, iar reziduurile se gasesc pe uriasii micsorati.",al={"cum se obtine reziduu","reziduu de miniaturizare","cum sa micsorezi uriasii"}},{q="Unde se gasesc uriasii?",a="Gigantii se gasesc de-a lungul coastei vestice a Feralas.",al={"locatia uriasilor","unde sunt uriasii din feralas","uriasii din Forgotten Coast"}},{q="Va mai lua Zorbin reziduuri cu alta ocazie?",a="Zorbin spune ca poate folosi oricand mai mult reziduu, asa ca poti reveni cu inca un lot de zece.",al={"se poate repeta","pot repeta Again With the Zapped Giants","misiune repetabila cu uriasi"}}},fp="28,289,32.448.0,15.232.1,26.68.0,22.85.0,28.128.0,27.56.0,43.103.0"}
P.entries["quest:7726"] = {n="Refuel for the Zapping",s="Zorbin Fandazzle are nevoie de mai multe nuclee de elemental de apa. E greu sa-si puna pe picioare afacerea pe Forgotten Coast, asa ca plata va fi mai mica, dar Zorbin promite sa le vorbeasca tuturor celor din apropiere despre ajutorul tau si spune ca are prieteni in Cartel.",h="Zorbin Fandazzle are nevoie de mai multe nuclee de elemental de apa.",kw={"feralas","forgotten coast","elemental al marii","spuma marii","steamwheedle cartel","nucleu de elemental al apei","zorbin fandazzle"},sec={{t="Mai mult din acelasi lucru",b="Zorbin Fandazzle glumeste pe seama eroicei tale fapte de a culege gel din interiorul fiintelor elementale si se intreaba daca vei mai vrea sa faci acelasi lucru. Lasand la o parte melodrama, Zorbin chiar are nevoie de mai multe nuclee de elementali ai apei. Infiintarea pravaliei aici este o afacere disperata, asa ca are putin de oferit la schimb, dar promite sa spuna tuturor celor din jur cat l-ai ajutat si iti spune sa-l crezi, fiindca cunoaste oameni din Cartel. Vrea sase nuclee, luate de la Sea Elementals si Sea Sprays de pe Forgotten Coast, si aduse la Zorbin, langa doc."},{t="Multumirile lui Zorbin",b="Zorbin este multumit si recunoaste ca poate nu vei mai primi niciodata atat de multi bani pentru o asemenea munca. Tovarasii lui Zorbin din Steamwheedle Cartel vor afla de eforturile tale, iar daca vrei sa faci mai multe, Zorbin are in continuare nevoie de nuclee si alte lucruri asemanatoare."}},faq={{q="Cine solicita nucleele elementarilor de apa?",a="Zorbin Fandazzle, gasit langa docurile de pe Forgotten Coast din Feralas.",al={"cine ofera aceasta misiune","cine este zorbin fandazzle","unde se afla zorbin"}},{q="De unde provin nucleele elementale de apa?",a="Sunt luate de la Sea Elementals si Sea Sprays de pe Forgotten Coast din Feralas.",al={"unde cad nucleele","locatia nucleului elemental de apa","ce inamici lasa nuclee"}},{q="De ce are nevoie Zorbin Fandazzle de mai multe nuclee?",a="Zorbin spune doar ca sunt necesare mai multe nuclee de elemental de apa, in timp ce incearca sa-si deschida un magazin pe coasta.",al={"de ce vrea Zorbin nuclee","motivul lui Zorbin Fandazzle","la ce folosesc nucleele"}},{q="Ce a fost inainte de asta?",a="Urmeaza dupa Fuel for the Zapping, cand ai adunat pentru prima data nuclee elementale pentru Zorbin.",al={"misiunea anterioara","misiunea premergatoare","ce misiune trebuie facuta mai intai"}}},fp="22,235,16.548.0,15.260.1,44.70.0,45.84.0,42.117.0,22.84.0"}
P.entries["quest:7727"] = {n="Incendosaurs? Whateverosaur is More Like It",s="Hansel Heavyhands spune ca are bataturi peste bataturi si nu poate ucide nimic cu picioarele in halul asta. Scrange si Burninate i-au spus sa curete Slag Pit de incendosauri, asa ca te trimite pe tine sa omori douazeci.",h="Hansel Heavyhands spune ca are bataturi peste bataturi si nu poate ucide nimic cu picioarele in halul asta.",kw={"burninate","cazan","hansel heavyhands","incendosaur","scrange","searing gorge","slag pit"},sec={{t="Monturi peste monturi",b="Hansel Heavyhands nu este in stare sa lupte. Scrange si Burninate i-au spus sa omoare incendosaurii, pentru ca echipele expeditionare sa poata cobori in lacurile de lava din Slag Pit si sa le exploreze. Hansel iti paseaza treaba."},{t="Bazinele de lava",b="Incendosaurii ocupa bazinele de lava din adancurile Slag Pit, in Cauldron. Hansel vrea sa omori douazeci si nu vrea sa te vada inapoi pana nu termini."}},faq={{q="Cine este Hansel Heavyhands?",a="El iti da aceasta treaba in Searing Gorge. Scrange si Burninate i-au spus sa se ocupe de incendosaurs, dar nu poate din cauza monturilor.",al={"Hansel Heavyhands","cine ofera misiunea","cine ofera aceasta misiune"}},{q="De ce trebuie alungati incendosaurii?",a="Scrange si Burninate vor ca echipele expeditiei sa exploreze bazinele de lava din Slag Pit. Se spune ca Incendosaurs de acolo provoaca tot felul de probleme.",al={"de ce sa omori incendosauri","scopul incendosaurilor","de ce sa cureti groapa de zgura"}},{q="Unde pot fi gasiti incendosaurs?",a="Jos, in bazinele de lava din Slag Pit, in Cauldron.",al={"locatia incendosaurului","unde se afla groapa de zgura","unde sunt bazinele de lava"}},{q="De ce nu-i vaneaza Hansel chiar el?",a="Spune ca are bataturi peste bataturi, iar picioarele ii sunt intr-o asemenea dezordine, incat nu poate omori nimic.",al={"de ce nu vrea hansel sa lupte","picioarele lui hansel","monturile lui hansel"}}},fp="43,227,20.221.0,14.166.0,25.152.0,47.154.0,33.60.0,35.89.0"}
P.entries["quest:7728"] = {n="STOLEN: Smithing Tuyere and Lookout's Spyglass",s="Un anunt enumera doua obiecte furate: o foale Dark Iron si un binoclu de observator. Thorium Brotherhood este convins ca niste Dwarves Dark Iron lipsiti de scrupule si invidiosi din Searing Gorge le-au luat, iar cel care le gaseste trebuie sa le duca la Taskmaster Scrange pentru recompensa.",h="Un anunt enumera doua obiecte furate: o foale Dark Iron si un binoclu de observator.",kw={"Dark Iron","Scrange","Searing Gorge","fierarie","luneta","Thorium Brotherhood","tuyere"},sec={{t="Bunuri furate",b="Anuntul spune ca luneta este o unealta excelenta pentru observatori, iar suflaiul este o unealta de fierarie de neinlocuit. Tot ce se stie este ca Dark Iron dwarves le-au luat cu siguranta. Cine le gaseste trebuie sa i le inapoieze lui Taskmaster Scrange."}},faq={{q="Cine a pus anuntul?",a="Avizul vorbeste despre Thorium Brotherhood, care este convinsa ca Dark Iron dwarves au luat obiectele.",al={"cine vrea obiectele furate","cine a dat aceasta misiune","cel care da misiunea stolen smithing tuyere"}},{q="Cine a furat uneltele?",a="Thorium Brotherhood este convinsa ca au fost Dark Iron lipsiti de scrupule si invidiosi din Searing Gorge.",al={"cine a luat tuyere","cine a furat luneta","cine are obiectele furate"}},{q="Cine primeste obiectele recuperate?",a="Taskmaster Scrange in Searing Gorge.",al={"unde predau acest obiect","cine este taskmaster scrange","cine primeste luneta"}},{q="La ce folosesc obiectele furate?",a="Tuyere este o unealta de fierarie care nu poate fi inlocuita, iar luneta este o unealta valoroasa de supraveghere pentru santinele.",al={"ce este o duza de forja","de ce vrea fratia duza","la ce foloseste luneta"}}},fp="46,258,12.236.0,22.100.0,20.106.0,33.40.0,30.115.0"}
P.entries["quest:7729"] = {n="JOB OPPORTUNITY: Culling the Competition",s="Un anunt spune ca Taskmaster Scrange cauta oameni capabili sa elimine concurenta din Searing Gorge. Treaba consta in uciderea Dark Iron Taskmasters si Dark Iron Slavers pana cand hainele iti sunt destul de insangerate, apoi trebuie sa te intorci la Scrange.",h="Un anunt spune ca Taskmaster Scrange cauta oameni capabili sa elimine concurenta din Searing Gorge.",kw={"eliminarea concurentei","sclavist Dark Iron","supraveghetor Dark Iron","oportunitate de angajare","Searing Gorge","taskmaster scrange"},sec={{t="Un post vacant",b="Scrange vrea ca doritorii sa traverseze defileul si sa macelareasca Dark Iron Taskmasters si Dark Iron Slavers pe care-i intalnesc: cate cincisprezece din fiecare. Intoarce-te cand hainele iti sunt destul de insangerate. Iti vei da seama cand va fi cazul si sa nu intrebi."}},faq={{q="Cine ofera aceasta slujba?",a="Taskmaster Scrange din Searing Gorge, care vrea ajutor pentru a elimina concurenta.",al={"cine ofera aceasta misiune","cine vrea ucisi taskmasters","cine este taskmaster scrange"}},{q="Ce dusmani trebuie ucisi?",a="Cincisprezece Dark Iron Taskmasters si cincisprezece Dark Iron Slavers.",al={"ce trebuie sa omor","tinte pentru Job Opportunity","cine sunt concurentii"}},{q="Cum isi da seama Scrange ca treaba e gata?",a="Dupa starea hainelor tale. Scrange te va cantari cu ele si fara ele, ca sa se asigure.",al={"cum dovedesc ca i-am ucis","cerinta privind hainele insangerate","cum verifica scrange"}}},fp="40,242,16.243.0,25.80.0,28.60.0,39.86.0"}
P.entries["quest:773"] = {n="Rite of Wisdom",s="Rite of Wisdom este proba finala din traditionalul Rites of the Earthmother, parcurs de tinerii aventurieri din Mulgore. Dupa ce isi purifica vederea prin Rite of Vision, cei care cauta binecuvantarea calatoresc la locurile sacre de inmormantare din Red Rocks, pentru a comunica cu un Spirit Ancestral si a primi binecuvantarea celor morti.",h="Rite of Wisdom este proba finala din traditionalul Rites of the Earthmother, parcurs de tinerii aventurieri...",kw={"spirit ancestral","mulgore","stancile rosii","rite of wisdom","rites of the earthmother","seer wiserunner","thunder bluff","water of the seers"},ang={["class:Druid"]="Ritul demonstreaza echilibrul dintre lumea celor vii si ciclul etern vegheat de Earthmother, intiparindu-le tinerilor druizi datoria fata de pamant.",["class:Shaman"]="Comunicarea directa cu un Ancestral Spirit reafirma datoria fundamentala a samanilor: sa-i cinsteasca pe cei morti si sa pastreze legatura cu spiritele care vegheaza asupra Mulgore.",["race:Tauren"]="Pentru shu'halo, primirea mantiei de la strabuni, la Red Rocks, este momentul culminant al trecerii la maturitate deplina si al acceptarii de catre batranii tribului."},sec={{t="Incercarea din Red Rocks",b="Dupa ce si-au limpezit perceptia prin Rite of Vision, tinerii aparatori sunt indrumati spre est de Thunder Bluff, catre Red Rocks. Acest stravechi loc de ingropaciune adaposteste ramasitele trupesti si spiritele inca dainuind ale celor care au luptat si au murit pentru a cladi o viata pasnica in Mulgore. Pentru a trece incercarea, trebuie sa te apropii de locurile de odihna cu respectul si evlavia cuvenite, infruntand orice amenintari teritoriale cutreiera dealurile in cautarea sfatului mortilor cinstiti."},{t="Transmiterea mantiei",b="Pe culmea din Red Rocks, comuniunea cu Ancestral Spirit nu este o proba de forta martiala, ci una a pregatirii spirituale si a continuitatii. Spiritele care salasluiesc acolo fac parte din generatia ce a luptat alaturi de Cairne Bloodhoof pentru a intemeia Thunder Bluff si a apara triburile. Primind binecuvantarea lor, cel care o cere mosteneste oficial datoria solemna de a proteja orasul, dobandindu-si locul ca adult si aparator recunoscut, vrednic sa intre cu mandrie in Thunder Bluff."}},faq={{q="Care este scopul Rite of Wisdom?",a="Rite of Wisdom incheie Rites of the Earthmother, legand comuniunea vizionara a tineretii de responsabilitatile solemne ale maturitatii. Primind binecuvantarea spiritelor stramosesti, cei care o cer dovedesc ca respecta sacrificiile celor veniti inaintea lor si ca sunt gata sa apere Thunder Bluff.",al={"de ce sa faci Rite of Wisdom","ce face Rite of Wisdom","scopul Rite of Wisdom"}},{q="Cine te trimite sa indeplinesti Rite of Wisdom?",a="Seer Wiserunner, din pestera sa de la nord-vest de Bloodhoof Village, ii trimite pe initiati in aceasta incercare dupa ce au incheiat cu succes Rite of Vision si au baut din Water of the Seers.",al={"cine da Rite of Wisdom","de unde incep Rite of Wisdom"}},{q="Unde gasesti Spiritul Ancestral?",a="Spiritul Ancestral se afla la Red Rocks, un stravechi loc de inmormantare tauren, ascuns in stancariile de la est de Thunder Bluff.",al={"locatia spiritului stramosesc","unde este spiritul","unde gasesti spiritul stramosesc"}},{q="De ce este necesar mai intai Rite of Vision?",a="Numai cei care au baut din Water of the Seers si si-au curatat vederea spirituala pot percepe si primi binecuvantarea spiritelor stravechi de la Red Rocks.",al={"de ce trebuie sa faci mai intai viziunea","cerinta preliminara pentru Rite of Vision","cerinta privind apa vizionarilor"}},{q="Ce se intampla dupa finalizarea Rite of Wisdom?",a="Dupa ce si-au castigat aprobarea stramosilor, initiatii sunt indrumati sa porneasca oficial spre inaltimile din Thunder Bluff.",al={"ce urmeaza dupa Rite of Wisdom","urmatoarea misiune dupa Rite of Wisdom"}},{q="Ce creaturi ameninta tinuturile Red Rocks?",a="Cimitirul sacru de la Red Rocks a fost invadat de gnollii Palemane agresivi, care pandesc de-a lungul potecilor stancoase ce urca spre vechiul loc de inmormantare.",al={"inamici la Red Rocks","ce pazeste Red Rocks","gnoli la Red Rocks"}}},fx={["740e2883"]={q="De ce te trimite Seer Wiserunner sa parcurgi Rite of Wisdom?",a="Seer Wiserunner ii calauzeste pe tinerii tauren promitatori prin Rites of the Earthmother, stravechiul ritual. Dupa ce te-a vazut indurand viziunea oferita de Water of the Seers, te indruma spre Red Rocks pentru a primi binecuvantarea stramosilor. Pentru Wiserunner si batrani, acest ritual garanteaza ca numai cei pregatiti spiritual si recunoscuti de stramosi sunt primiti in Thunder Bluff ca aparatori ai tribului.",al={"motivul lui seer wiserunner","de ce rite of wisdom","de ce sa ma trimita la rite of wisdom"}},["8728f84f"]={q="De ce are Seer Wiserunner nevoie sa mergi tu, in loc sa mearga el insusi?",a="Rite of Wisdom este o incercare personala de trecere, nu o corvoada pe care s-o poata indeplini altcineva in locul tau. Pentru a castiga acceptarea batranilor si dreptul de a intra in Thunder Bluff, trebuie sa-l cauti personal pe Ancestral Spirit la Red Rocks si sa dovedesti limpezimea spirituala dobandita de la Water of the Seers. Indatorirea de a proteja orasul iti poate fi incredintata numai tie, in persoana.",al={"de ce eu pentru Rite of Wisdom","de ce nu pleaca seer wiserunner","de ce trebuie sa caut spiritul stramosesc"}}},fp="14,321,22.468.0,18.492.0,42.310.0,36.186.0,39.137.0,41.175.0,49.138.0,49.160.0"}
P.entries["quest:7730"] = {n="Zukk'ash Infestation",s="La Camp Mojache, Hadoken Swiftstrider are vesti despre niste creaturi asemanatoare insectelor, Zukk'ash, la sud de gnolli. Daca ii imping pe gnolli intr-o furie nestapanita, sunt o amenintare la fel de mare ca ei, poate chiar mai mare. Esti trimis in salasul lor, Writhing Deep, ca sa le reduci numarul si sa aduci inapoi douazeci de carapace.",h="La Camp Mojache, Hadoken Swiftstrider are vesti despre niste creaturi asemanatoare insectelor, Zukk'ash, la...",kw={"camp mojache","carapace","feralas","gnolli","hadoken swiftstrider","insecte","writhing deep","zukk'ash"},sec={{t="Dusmanul de la sud de Gnolls",b="Hadoken Swiftstrider crede ca dusmanul aflat la sud de gnolls este o rasa de creaturi asemanatoare insectelor. Pentru Hadoken, nu prea conteaza daca sunt capabile sa gandeasca. Daca ii imping pe gnolls intr-o furie oarba impotriva Camp Mojache, sunt la fel de periculoase ca gnolls insisi, sau chiar mai periculoase. Trebuie sa patrunzi adanc in locul unde salasluiesc, cunoscut drept Writhing Deep, si sa le imputinezi numarul. Carapacele a douazeci de Zukk'ash vor fi dovada ta, iar Hadoken vrea sa afle ce descoperi."},{t="Verdictul lui Hadoken",b="La intoarcerea ta, Hadoken este multumit. Nimic mai putin decat o invazie la scara larga nu va pune capat prezentei Zukk'ash, dar ai castigat timp pentru tabara, ca sa conceapa o strategie potrivita. Carapacele vor fi analizate, deoarece tabara trebuie sa afle totul despre aceste creaturi. Din nefericire, situatia s-a transformat intr-o problema mult mai mare decat anticipase oricine."}},faq={{q="Cine te trimite dupa Zukk'ash?",a="Hadoken Swiftstrider, la Camp Mojache din Feralas.",al={"cel care ofera misiunea","hadoken swiftstrider","cine incepe zukkash infestation"}},{q="Ce sunt Zukk'ash?",a="Hadoken crede ca sunt o rasa de creaturi asemanatoare insectelor, aflata la sud de gnolli. Lui Hadoken nu-i pasa daca sunt capabile sa gandeasca, ci doar ca ar putea sa-i impinga pe gnolli intr-o frenezie.",al={"ce sunt zukkash","insectele zukkash","gandacii din Writhing Deep"}},{q="Unde se afla Writhing Deep?",a="Acolo salasluiesc insectele Zukk'ash, la sud de gnolls.",al={"locatia Writhing Deep","unde este Writhing Deep","unde sunt insectele"}},{q="De ce vrea Hadoken carapace de Zukk'ash?",a="Hadoken vrea carapace drept dovada a muncii tale impotriva celor din Zukk'ash.",al={"de ce carapace","la ce foloseste carapacea zukkash","scopul carapacelor"}}},fp="20,317,27.474.0,17.347.1,33.49.0,22.185.0,27.60.0,41.79.0"}
P.entries["quest:7731"] = {n="Stinglasher",s="In timp ce cerceta Writhing Deep, unul dintre cercetasii lui Hadoken Swiftstrider a zarit o insecta uriasa, mult mai mare decat celelalte, ratacind prin tinutul schimonosit. A fost numita Stinglasher, iar Hadoken vrea sa fie doborata si glandele ei secretoare aduse inapoi la Camp Mojache.",h="In timp ce cerceta Writhing Deep, unul dintre cercetasii lui Hadoken Swiftstrider a zarit o insecta uriasa...",kw={"camp mojache","feralas","glande","hadoken swiftstrider","insecta","stinglasher","writhing deep","zukk'ash"},sec={{t="Un gigant printre insecte",b="Un cercetas din Writhing Deep a vazut o insecta mult mai mare decat celelalte, ratacind prin terenul contorsionat. Pare, de asemenea, sa emane o aura care o deosebeste de restul. A primit numele Stinglasher. Maruntaiele sale ar fi nepretuite pentru studiu, in timp ce Hadoken cauta o cale de a infrunta aceasta noua amenintare; de aceea, Hadoken vrea ca glandele secretoare ale creaturii sa fie taiate si aduse direct la Camp Mojache."},{t="Multumirile lui Hadoken",b="Hadoken este profund impresionat. Daca Stinglasher este intr-adevar una dintre cele mai puternice insecte, studierea bestiei se va dovedi valoroasa cu timpul, iar sarcina lui Hadoken este sa se asigure ca tabara se poate apara suficient de mult ca sa profite de asta. Primesti o recompensa in bani, impreuna cu multumirile intregii tabere."}},faq={{q="Cine te trimite dupa Stinglasher?",a="Hadoken Swiftstrider, la Camp Mojache din Feralas.",al={"cel care da misiunea","cine ofera stinglasher","Hadoken Swiftstrider"}},{q="Unde se gaseste Stinglasher?",a="Stinglasher rataceste prin terenul contorsionat din Writhing Deep.",al={"locatia lui Stinglasher","unde se afla Stinglasher","locatia Writhing Deep"}},{q="Ce il deosebeste pe Stinglasher de celelalte insecte?",a="Un cercetas a raportat o insecta de dimensiuni uriase, iar aceasta pare sa emane o aura pe care celelalte nu o au.",al={"de ce stinglasher","ce este stinglasher","aura lui stinglasher"}},{q="De ce vrea Hadoken glandele lui Stinglasher?",a="Hadoken spune ca studierea maruntaielor sale ar fi nepretuita, in timp ce se pune la punct un plan impotriva acestei noi amenintari.",al={"de ce sa colectezi glande","scopul glandelor Stinglasher"}}},fp="11,274,25.401.0,16.278.1,32.49.0,27.68.0,56.89.0,43.105.0"}
P.entries["quest:7732"] = {n="Zukk'ash Report",s="Hadoken Swiftstrider spune ca te-ai descurcat de doua ori mai bine impotriva insectelor Zukk'ash care ameninta Camp Mojache, dar pericolul nu a trecut. O ultima favoare pentru Horde: du un document care consemneaza tot ce s-a aflat despre Zukk'ash la Orgrimmar, lui Zilzibin Drumlore.",h="Hadoken Swiftstrider spune ca te-ai descurcat de doua ori mai bine impotriva insectelor Zukk'ash care...",kw={"camp mojache","trage","feralas","hadoken swiftstrider","orgrimmar","silithid","zilzibin drumlore","zukk'ash report"},sec={{t="Un document pentru Drag",b="Hadoken Swiftstrider tine un document care consemneaza tot ce a aflat tabara despre insectele Zukk'ash. Pericolul pe care il reprezinta este departe de a fi trecut, iar Hadoken iti cere sa-l duci la Orgrimmar. Acolo, in Drag, locuieste Zilzibin Drumlore, un expert in creaturi straine precum acestea, iar Hadoken spera ca informatiile adunate pana acum vor fi de folos."},{t="Verdictul expertului",b="Zilzibin astepta raportul. El numeste creaturile cu care te-ai luptat o amenintare straveche, pe care Horde continua sa aleaga sa o ignore, si spune ca Hadoken a dat dovada de intelepciune trimitand atat raportul, cat si pe tine. Zukk'ash nu sunt altceva decat creaturi numite silithid. Unii le cred o pacoste fara minte, dar Zilzibin te asigura ca sunt o amenintare mult mai grava decat orice ar putea mobiliza Alliance."}},faq={{q="Cine trimite raportul la Orgrimmar?",a="Hadoken Swiftstrider de la Camp Mojache din Feralas iti da documentul.",al={"cine ofera zukkash report","cine incepe zukkash report","cel care ofera misiunea"}},{q="Cui ii este livrat raportul?",a="Pentru Zilzibin Drumlore, care locuieste in Drag din Orgrimmar.",al={"unde trebuie dus raportul","cine primeste raportul Zukk'ash","locatia lui Drumlore"}},{q="De ce este dus documentul la Orgrimmar?",a="Zilzibin Drumlore este un expert in creaturi extraterestre precum Zukk'ash, iar Hadoken spera ca informatiile adunate de tabara vor fi folosite la ceva.",al={"de ce sa trimiti la orgrimmar","scopul raportului"}},{q="Ce a precedat aceasta livrare?",a="Urmeaza dupa ce ai luptat impotriva insectelor Zukk'ash in Zukk'ash Infestation si Stinglasher.",al={"misiuni anterioare","cerinte preliminare"}}},fp="15,267,23.347.0,20.377.1,34.71.0,32.59.0,39.142.0,31.94.0"}
P.entries["quest:7733"] = {n="Improved Quality",s="Pratt McGrubben a auzit de piei si mai bune decat cele de data trecuta. In nordul regiunii Feralas, in Rage Scar Hold, umbla o alta ceata de yeti, mai rezistenti decat cei cu care te-ai confruntat inainte. La Feathermoon Stronghold se doresc zece dintre pieile lor.",h="Pratt McGrubben a auzit de piei si mai bune decat cele de data trecuta.",kw={"feathermoon stronghold","feralas","improved quality","pratt mcgrubben","rage scar hold","thorium","piele de yeti","yetis"},sec={{t="O ceata si mai puternica de yeti",b="Dupa The Mark of Quality, Pratt McGrubben a gasit o pista catre o sursa de piei si mai buna. In nordul Feralasului, in Rage Scar Hold, traieste o alta multime de yeti, mai rezistenti decat cei pe care i-ai infruntat mai devreme. Pratt McGrubben va plati bine pentru zece piei de-ale lor, aduse inapoi la Feathermoon Stronghold pentru a incheia treaba. Daca se ridica la calitatea pieilor Feral Scar, s-ar putea dovedi la fel de rezistente ca thoriumul."},{t="Multumirile lui Pratt",b="Pieile sunt chiar mai bune decat spera. Pratt McGrubben isi da deja seama ca se vor intari mult dupa ce vor fi tabacite cum trebuie si iti inmaneaza una dintre cele mai noi creatii ale sale, drept multumire."}},faq={{q="Cine cere pieile yeti din Rage Scar?",a="Pratt McGrubben, la Feathermoon Stronghold, in Feralas.",al={"cine da improved quality","cel care da misiunea improved quality","pratt mcgrubben"}},{q="Unde traiesc yetii Rage Scar?",a="In interiorul Rage Scar Hold, in nordul Feralas.",al={"locatia yeti-lor Rage Scar","unde se afla Rage Scar Hold","de unde obtin piei Rage Scar"}},{q="Cate piei sunt necesare?",a="Pratt McGrubben vrea zece piei de yeti Rage Scar.",al={"cate blanuri de yeti","obiecte necesare pentru Improved Quality"}},{q="Ce a fost inainte de asta?",a="Urmeaza The Mark of Quality, cand te-ai ocupat de primul grup de yeti.",al={"misiune prealabila","ce misiune duce la improved quality","misiunea precedenta"}}},fp="16,238,25.430.0,14.171.1,38.54.0,34.47.0,26.47.0,22.78.0"}
P.entries["quest:7734"] = {n="Improved Quality",s="Jangdor Swiftstrider a auzit de piei si mai bune decat cele de data trecuta. In nordul regiunii Feralas, in Rage Scar Hold, umbla o alta ceata de yeti, mai rezistenti decat cei cu care te-ai confruntat inainte. La Camp Mojache se doresc zece dintre pieile lor.",h="Jangdor Swiftstrider a auzit de piei si mai bune decat cele de data trecuta.",kw={"camp mojache","feralas","improved quality","jangdor swiftstrider","rage scar hold","rage scar yeti","blanuri de yeti"},sec={{t="O ceata si mai puternica de yeti",b="Dupa The Mark of Quality, Jangdor Swiftstrider a gasit o pista catre o sursa de piei si mai buna. In nordul Feralasului, in Rage Scar Hold, traieste o alta multime de yeti, mai rezistenti decat cei pe care i-ai infruntat mai devreme. Jangdor Swiftstrider va plati bine pentru zece piei de-ale lor, aduse inapoi la Camp Mojache pentru a incheia treaba. Daca se ridica la calitatea pieilor Feral Scar, s-ar putea dovedi la fel de rezistente ca thoriumul."},{t="Multumirile lui Jangdor",b="Blanurile sunt chiar mai bune decat sperase. Jangdor Swiftstrider isi da deja seama ca vor deveni mult mai rezistente dupa ce vor fi tabacite cum trebuie si iti da una dintre cele mai recente creatii ale sale, drept multumire."}},faq={{q="Cine cere pieile yeti din Rage Scar?",a="Jangdor Swiftstrider, la Camp Mojache din Feralas.",al={"cine ofera Improved Quality","cel care da misiunea Improved Quality","jangdor swiftstrider"}},{q="Unde traiesc yetii Rage Scar?",a="In interiorul Rage Scar Hold, in nordul Feralas.",al={"locatia yeti-lor Rage Scar","unde se afla Rage Scar Hold","de unde obtin piei Rage Scar"}},{q="Cate piei sunt necesare?",a="Jangdor Swiftstrider vrea zece piei de yeti Rage Scar.",al={"cate blanuri de yeti","obiecte necesare pentru Improved Quality"}},{q="Ce a fost inainte de asta?",a="Urmeaza The Mark of Quality, cand te-ai ocupat de primul grup de yeti.",al={"misiune prealabila","ce misiune duce la improved quality","misiunea precedenta"}}},fp="16,233,25.430.0,16.176.1,38.49.0,34.47.0,26.52.0,22.78.0"}
P.entries["quest:7735"] = {n="Pristine Yeti Hide",s="Ai gasit o piele de yeti neobisnuit de groasa si rezistenta, mai tare decat oricare alta vazuta la yetii din Rage Scar. Pratt McGrubben de la Feathermoon Stronghold cauta piei de yeti, iar aceasta s-ar putea sa-l intereseze.",h="Ai gasit o piele de yeti neobisnuit de groasa si rezistenta, mai tare decat oricare alta vazuta la yetii din...",kw={"feathermoon stronghold","feralas","pratt mcgrubben","pristine yeti hide","rage scar","blana de yeti"},sec={{t="O piele iesita din comun",b="Aceasta piele este impecabila si, in mod vadit, mai groasa si mai rezistenta decat pieile luate de la yeti din Rage Scar. Pratt McGrubben, de la Feathermoon Stronghold din Feralas, vrea sa cumpere piei de yeti, asa ca merita sa i-o duci."},{t="Reactia lui Pratt",b="Pratt este uimit si se intreaba cu voce tare daca aceasta ar putea fi cea mai mare blana de yeti din toate timpurile. Pratt iti va plati pentru ea, mai mult decat se obtine de obicei pentru o singura blana, si crede ca s-ar putea face ceva deosebit din ea."}},faq={{q="Cine vrea Pristine Yeti Hide?",a="Pratt McGrubben, de la Feathermoon Stronghold din Feralas, cauta sa cumpere blanuri de yeti.",al={"cine ia Pristine Yeti Hide","unde duc blana de yeti","blana de yeti pentru Pratt McGrubben"}},{q="Ce face ca aceasta piele sa fie speciala?",a="Este neobisnuit de gros si rezistent, intrecand pana si pieile provenite de la yeti din Rage Scar.",al={"sursa pristine yeti hide","ce face blana speciala","blana yeti din feralas"}},{q="Unde se afla Pratt McGrubben?",a="La Feathermoon Stronghold, in Feralas.",al={"unde se afla pratt mcgrubben","unde sa duci Pristine Yeti Hide"}}},fp="18,230,26.223.0,16.201.1,33.87.0,29.89.0,25.37.0"}
P.entries["quest:7736"] = {n="Restoring Fiery Flux Supplies via Kingsblood",s="Dupa What the Flux?, Master Smith Burninate se ocupa de refacerea rezervei tot mai mici de flux infocat din Searing Gorge. Burninate vrea solzi de incendosaur, Kingsblood si carbune si va primi tot ce poti oferi.",h="Dupa What the Flux?, Master Smith Burninate se ocupa de refacerea rezervei tot mai mici de flux infocat din...",kw={"ardere","carbune","flux arzator","incendosaur","sange de rege","Searing Gorge","Thorium Brotherhood"},sec={{t="Fiery Flux cautat",b="Master Smith Burninate nu are timp de vorbe goale. Rezervele de flux incendiar sunt pe sfarsite, iar Burninate cere solzi de incendosaur, Kingsblood si carbune: doi solzi, patru Kingsblood si carbune. Burninate va lua tot ce poti oferi."}},faq={{q="Cine solicita aceste marfuri?",a="Master Smith Burninate din Searing Gorge, care primeste personal bunurile.",al={"cine ofera aceasta misiune","burninate fiery flux","unde o predai"}},{q="Ce materiale doreste Burninate?",a="Doua solzi de incendosaur, patru Kingsblood si niste carbune.",al={"de ce obiecte am nevoie","materiale pentru fiery flux","obiecte de predat lui burninate"}},{q="Ce a precedat aceasta cerere?",a="Pasul numit What the Flux?, pe care Burninate ti l-a dat inaintea acestuia.",al={"cerinte pentru aceasta misiune","misiunea anterioara, Fiery Flux","care este cerinta pentru flux"}},{q="De ce vrea Burninate aceste bunuri?",a="Burninate spune ca rezervele de flux aprins se imputineaza si vrea sa fie refacute.",al={"de ce flux infocata","motivul lui Burninate"}}},fp="44,214,17.224.0,25.78.0,35.55.0,30.69.0,36.78.0"}
P.entries["quest:7738"] = {n="Perfect Yeti Hide",s="Ai gasit o blana de yeti care ar putea fi perfecta: este remarcabil de groasa si rezistenta, depasind ceea ce ofera yetis din Rage Scar. La Camp Mojache, Jangdor Swiftstrider cauta blanuri de yeti.",h="Ai gasit o blana de yeti care ar putea fi perfecta: este remarcabil de groasa si rezistenta, depasind ceea ce...",kw={"camp mojache","feralas","jangdor swiftstrider","perfect yeti hide","cicatricea furiei","blana de yeti"},sec={{t="O piele demna de aratat",b="Pielea este vadit mai groasa si mai rezistenta decat cele ale yetiilor din Rage Scar. La Camp Mojache, in Feralas, Jangdor Swiftstrider vrea sa cumpere piei de yeti, asa ca merita sa o duci acolo."},{t="Verdictul lui Jangdor",b="Jangdor este incantat si spune ca este cea mai frumoasa blana de yeti pe care a vazut-o vreodata. Se cuvine sa-ti ofere o recompensa pe masura, mai mare decat plateste de obicei pentru o singura blana, si este convins ca se poate face ceva deosebit din ea."}},faq={{q="Cine este interesat de Perfect Yeti Hide?",a="Jangdor Swiftstrider, din Camp Mojache in Feralas, vrea sa cumpere piei de yeti.",al={"cine vrea pielea","cine preda Perfect Yeti Hide","blana de yeti pentru Jangdor"}},{q="De ce este considerata speciala aceasta piele?",a="Este neobisnuit de groasa si rezistenta si s-ar putea sa fie perfecta, mai buna decat pieile de la yetis din Rage Scar.",al={"de ce este perfect","ce face pielea speciala"}},{q="Unde se afla Jangdor Swiftstrider?",a="La Camp Mojache, in Feralas.",al={"unde este jangdor swiftstrider","unde sa duc Perfect Yeti Hide"}}},fp="17,187,20.194.0,17.205.1,43.78.0,36.103.0,30.27.0"}
P.entries["quest:775"] = {n="Journey into Thunder Bluff",s="Journey into Thunder Bluff este pelerinajul culminant care marcheaza sfarsitul incercarilor unui tanar erou prin Mulgore. Dupa ce a indeplinit sacrele Rites of the Earthmother sub indrumarea spiritelor, aventurierului i se acorda audienta la Marele Capetenie al taurenilor, Cairne Bloodhoof.",h="Journey into Thunder Bluff este pelerinajul culminant care marcheaza sfarsitul incercarilor unui tanar erou...",kw={"spirit ancestral","cairne bloodhoof","high rise","journey into thunder bluff","Mulgore","rites of the earthmother","Thunder Bluff"},ang={["faction:Horde"]="Faptul ca taurenii primesc cu bratele deschise orice rasa aliata care isi implineste traditiile sacre vorbeste despre respectul reciproc care tine tanara Horde unita.",["race:Tauren"]="Pentru un tanar Tauren, a sta in fata lui Cairne Bloodhoof dupa implinirea ritualurilor lui Earth Mother marcheaza hotarul definitoriu al maturitatii si onoarei tribale."},sec={{t="Un ritual de trecere incheiat",b="Inainte ca vreun calator sau razboinic in devenire sa poata spune ca si-a dovedit cu adevarat valoarea in Mulgore, trebuie sa treaca prin stravechile Rites of the Earthmother. Aceste incercari pun la incercare puterea, perspicacitatea si intelepciunea pe campiile unduitoare si la locurile stramosesti ale tinutului. Dupa ce Ancestral Spirit recunoaste indeplinirea ultimei probe, initiatul este socotit vrednic sa intre in orasul Thunder Bluff nu ca simplu vizitator, ci ca aparator de onoare al poporului tauren."},{t="Urcarea spre High Rise",b="Misiunea il calauzeste pe calator de la pamantul sacru pe unde umbla spiritele direct spre inaltimile semete din Thunder Bluff. Asezat pe platouri, orasul este un far al pacii, cioplit in piatra rosie si sustinut de poduri de franghie arcuite si lifturi uriase din lemn. Acolo, pe High Rise, High Chieftain Cairne Bloodhoof ii asteapta personal pe cei care au urmat calea stramosilor."}},faq={{q="Cine te trimite in aceasta calatorie?",a="Misiunea este incredintata de un Spirit Ancestral dupa ce inchei Rite of Wisdom, ultimul pas din traditionalele Rites of the Earthmother.",al={"cine ofera misiunea","misiunea spiritului ancestral","cel care da misiunea"}},{q="Unde il pot gasi pe Cairne Bloodhoof?",a="Cairne Bloodhoof locuieste in High Rise, platoul inalt din centrul Thunder Bluff, de unde priveste platourile rosii si campiile din jur.",al={"locatia lui Cairne","unde se afla Cairne","conducatorul din Thunder Bluff"}},{q="Care este semnificatia finalizarii acestei misiuni?",a="Aceasta marcheaza incheierea oficiala a aventurilor de inceput din Mulgore. Prezentandu-te in fata lui Cairne, dovedesti ca ai fost pe deplin recunoscut de conducerea tauren si ca esti pregatit sa-ti asumi indatoriri in intreaga Horde.",al={"de ce sa-l vizitez pe Cairne","semnificatia ritualurilor","semnificatia calatoriei la Thunder Bluff"}},{q="Doar Tauren indeplinesc aceasta calatorie?",a="Desi este un ritual de trecere profund traditional pentru tauren, orice membru al Horde care isi dovedeste devotamentul prin Rites of the Earthmother primeste aceeasi onoare si este trimis sa-l intalneasca pe High Chieftain.",al={"pot face asta orcii","cine poate face calatoria spre Thunder Bluff","rase"}},{q="Ce se intampla dupa ce vorbesti cu Cairne?",a="Cairne te intampina in caminul sau, iti recunoaste faptele si te indeamna sa te avanti in conflictele mai ample cu care se confrunta Horde in Kalimdor.",al={"urmatoarea misiune","ce urmeaza dupa cairne","dupa Journey into Thunder Bluff"}},{q="Cum ajungi la High Rise in Thunder Bluff?",a="Urca pe marile lifturi mecanice, de la campiile de jos pana la mese, apoi treci podurile de franghie si lemn care duc spre platforma centrala High Rise, unde se afla locuinta conducatorului.",al={"cum ajungi la High Rise","cum ajungi la Cairne","lifturile din Thunder Bluff"}}},fx={["74afb15b"]={q="De ce te trimite Spiritul Ancestral la Thunder Bluff?",a="Supravietuind probelor din Mulgore si intrand in comuniune cu spiritele, ti-ai dovedit intelepciunea, taria si devotamentul prin Rites of the Earthmother. Spiritul Ancestral te indruma spre Thunder Bluff, pentru ca faptele tale sa fie recunoscute de poporul tauren si de cel mai mare conducator al lor, Cairne Bloodhoof. Infatisarea inaintea Marelui Sef marcheaza primirea ta oficiala in societatea lor, ca un campion de onoare.",al={"de ce te trimite spiritul stramosesc","motivul spiritului stramosesc","de ce sa mergi la Cairne"}},c86a41a9={q="De ce trebuie sa-i duci personal vestea lui Cairne Bloodhoof?",a="Rites of the Earthmother este o incercare personala sacra. Spiritul Ancestral este un calauzitor de pe lumea cealalta, legat de locurile sfinte din Mulgore si incapabil, dar si nedornic, sa duca mesaje din lumea celor vii. Pentru ca spiritul si hotararea ta au fost puse la incercare, numai tu ai onoarea de a te infatisa inaintea marelui sef Cairne Bloodhoof.",al={"de ce eu, Cairne","de ce trebuie sa-l vizitez pe Cairne","de ce trebuie sa-l vad pe Cairne Bloodhoof"}}},fp="26,296,27.451.0,26.407.0,30.141.0,34.138.0,50.216.0,37.208.0,38.141.0,48.197.0"}
P.entries["quest:776"] = {n="Rites of the Earthmother",s="Aceasta incercare, incredintata direct de Marele Capetenie Cairne Bloodhoof, le cere eroilor in ascensiune sa vaneze marea fiara kodo Arra'chea prin campiile din Mulgore. Desi un initiat poate sa fi incheiat ritualurile traditionale de trecere, Cairne se asteapta ca poporul sau sa-si reafirme necontenit puterea, priceperea la urmarire si devotamentul fata de trib. Intoarcerea cu cornul lui Arra'chea dovedeste ca un aventurier este gata sa slujeasca intreaga Horde, dincolo de platouri.",h="Aceasta incercare, incredintata direct de Marele Capetenie Cairne Bloodhoof, le cere eroilor in ascensiune sa...",kw={"arra'chea","arrachea","bloodhoof","cairne","earthmother","corn","vanatoare","kodo","mulgore","thunder bluff"},ang={["class:Hunter"]="Urmarirea unei creaturi solitare si ratacitoare precum Arra'chea prin campiile aurii intruchipeaza stravechile filosofii ale vanatorii, transmise din generatie in generatie de urmaritorii tauren.",["faction:Horde"]="Doborarea lui Arra'chea asigura hrana esentiala, piele si materiale pentru Thunder Bluff, demonstrand mentalitatea de supravietuire colectiva care sustine Horde aflata la inceputuri.",["race:Tauren"]="Sa te infatisezi inaintea lui Cairne Bloodhoof pentru a revendica cornul Arra'chea este proba suprema de trecere pentru un tanar shu'halo, dovedind ca iscusinta ta ii onoreaza atat pe stramosi, cat si turmele din Mulgore."},sec={{t="Masura unui capetenii",b="Sosirea in Thunder Bluff marcheaza sfarsitul copilariei pentru un tauren, dar High Chieftain Cairne Bloodhoof nu-i lasa pe tinerii vanatori sa se culce pe lauri. Pentru Cairne, castigarea unui loc printre piscurile inalte este doar inceputul responsabilitatilor fata de United Tauren Tribes. In loc sa trimita initiatii impotriva unor daunatori neinsemnati, el cere dovada unei adevarate priceperi in salbaticie: urmarirea si vanarea curata a uneia dintre cele mai renumite bestii ratacitoare din Mulgore."},{t="Vanatoarea lui Arra'chea",b="Prada este Arra'chea, un kodo masiv si legendar, al carui drum in bucla strabate pajistile aurii de la nord-est de Thunder Bluff. Pentru a dobori o asemenea creatura nu e suficienta forta bruta; trebuie urmarita cu rabdare prin savana deschisa si infruntata cu respectul cuvenit unui titan al campiilor. Aducerea cornului lui Arra'chea inapoi pe culmea inalta aduce nu doar glorie personala, ci si provizii pentru oras, caci Cairne trimite numaidecat jupuitori si culegatori sa se asigure ca nimic din fiara sacra nu se iroseste."}},faq={{q="Cine ofera aceasta misiune?",a="High Chieftain Cairne Bloodhoof insusi incredinteaza aceasta sarcina de pe locul sau deasupra asezarii inalte din Thunder Bluff.",al={"cel care da misiunea","cine ofera Rites of the Earthmother","misiunea lui Cairne"}},{q="Ce este Arra'chea?",a="Arra'chea este un kodo impunator si renumit, care rataceste prin campiile din Mulgore. Cornul sau mare dovedeste iscusinta unui hunter la urmarire si lupta.",al={"cine este Arrachea","ce este Arrachea","povestea lui Arrachea"}},{q="Unde o pot gasi pe Arra'chea?",a="Arra'chea cutreiera de obicei un traseu larg, circular, la nord-est de falezele din Thunder Bluff, inconjurand incet campiile intinse si domoale in sensul acelor de ceasornic.",al={"unde este Arrachea","locatia Arrachea","traseul catre Arrachea"}},{q="De ce cere Cairne aceasta vanatoare dupa ce am indeplinit deja ritualurile anterioare?",a="In cultura tauren, dobandirea locului initial in trib nu inseamna sfarsitul indatoririlor. Cairne ii invata ca forta, modestia si iscusinta la vanatoare trebuie dovedite neincetat pentru a sustine tribul.",al={"de ce sa faci aceasta misiune","de ce sa-l ucizi pe Arrachea","scopul ritualurilor"}},{q="Ce se intampla cu trupul lui Arra'chea dupa ce i se ia cornul?",a="Respectand traditia tauren de a-si onora prada, Cairne trimite un grup sa adune carnea si pielea bestiei cazute, astfel incat vanatul sa hraneasca si sa imbrace locuitorii din Thunder Bluff.",al={"carne Arrachea","ce se intampla cu kodo","povestea hoitului"}},{q="Este aceasta aceeasi misiune ca ritualurile timpurii de initiere?",a="Nu. Desi incercarile timpurii din Camp Narache il invata pe initiat Rites of the Earthmother, aceasta incercare finala din Thunder Bluff este testul personal al lui Cairne, menita sa-ti puna la incercare valoarea de vanator.",al={"deosebirile dintre ritualurile Earthmother","care misiune cu ritualuri","ritualurile din Camp Narache"}}},fx={d7a516d7={q="La ce foloseste Horn of Arra'chea?",a="Cornul este dovada palpabila a vanatorii tale reusite. Traditia Tauren acorda o mare onoare iscusintei de a urmari si dobori bestii puternice, iar prezentarea cornului lui Arra'chea direct lui Cairne Bloodhoof, Marele Sef, dovedeste ca ai indemanarea necesara pentru a-ti hrani si a-ti proteja poporul.",al={"la ce foloseste cornul lui Arra'chea","de ce sa iei cornul lui Arra'chea","scopul cornului lui Arra'chea"}},a7e696eb={q="De ce te trimite Cairne Bloodhoof in locul garzilor orasului?",a="Aceasta vanatoare nu este o misiune de aparare sau o simpla strangere de resurse - este o proba traditionala. Chiar daca ai trecut de Rites of the Earthmother initiale pentru a ajunge la Thunder Bluff, Cairne se asteapta ca fiecare vanator al tribului sa-si dovedeasca necontenit valoarea si independenta prin fapte marete, in loc sa se culce pe laurii realizarilor trecute.",al={"de ce sa ma trimita pe mine","de ce sa nu trimita paznici dupa Arrachea","de ce are Cairne nevoie de mine"}}},fp="24,439,21.449.0,22.491.0,21.108.0,18.161.0,27.154.0,78.183.0,57.183.0,50.204.0"}
P.entries["quest:777"] = {n="This Is Going to Be Hard",s="Lucien Tosselwrench iti da roata dintata #5 pentru Lotwil Veriatus si se adaposteste, invitandu-te sa-l urmezi.",h="Lucien Tosselwrench iti da roata dintata #5 pentru Lotwil Veriatus si se adaposteste, invitandu-te sa-l...",kw={"badlands","roata dintata 5","lotwil veriatus","lucien tosselwrench","catuse","this is going to be hard"},sec={{t="La adapost",b="Lucien iti da roata dintata si spune sa o duci la Lotwil Veriatus. Lucien te va astepta la adapost si esti binevenit sa i te alaturi. Cand ajungi la Lotwil, care inca e aplecat asupra catusele, o mana ti se intinde, iar degetele se misca nerabdatoare dupa roata dintata."},{t="A face istorie",b="Lotwil ia cog-ul si spune ca este perfect, apoi iti zice sa te dai inapoi cat timp se fac pregatirile pentru a intra din nou in istorie. Lotwil isi continua lucrul cu febrilitate."}},faq={{q="Cine ii da roata dintata lui Lotwil?",a="Lucien Tosselwrench iti da roata dintata nr. 5 ca sa o duci la Lotwil Veriatus.",al={"cine ofera roata dintata","unde gasesc roata dintata 5","roata dintata lucien"}},{q="Unde merge Lucien?",a="Lucien se adaposteste dupa un obstacol si spune ca te poti alatura.",al={"de ce se ascunde lucien","acoperirea lui lucien"}},{q="Ce face Lotwil cand ii aduci roata dintata?",a="Lotwil lucreaza la un set de catuse si, fara sa ridice privirea, intinde nerabdator mana dupa roata dintata.",al={"ce face lotwil","catuse lotwil","progresul lui lotwil"}}},fp="24,106,12.254.0,14.158.1,34.65.0,21.58.0,44.105.0"}
P.entries["quest:778"] = {n="This Is Going to Be Hard",s="Lotwil Veriatus declara ca catusele sunt gata si ii cheama pe Lucien, Servo si pe tine sa depuna marturie cand va fi invocat un elemental puternic.",h="Lotwil Veriatus declara ca catusele sunt gata si ii cheama pe Lucien, Servo si pe tine sa depuna marturie...",kw={"badlands","elementar","fam'retor guardian","lotwil veriatus","lucien","servo","catuse pentru legarea elementarilor"},sec={{t="O zi istorica",b="Lotwil striga ca catusele sunt gata si ca a venit vremea, chemandu-i pe Lucien si Servo sa fie martori alaturi de tine. Lotwil prezinta catusele drept o combinatie perfecta de alchimie, inginerie si arcane si intentioneaza sa invoce un elementar puternic, intr-o zi declarata revolutionara pentru toti cei de fata."},{t="Dupa invocare",b="Rezultatul nu e cel asteptat de Lotwil, iar acesta iti cere sa aduci inapoi Shackles of Elemental Binding dupa ce va fi infrant Fam'retor Guardian. Dupa aceea, Lotwil nu stie sigur ce n-a mers bine, dar se bucura ca magia era la indemana pentru a trimite creatura inapoi pe planul din care venise."}},faq={{q="Cine este Lotwil Veriatus?",a="Lotwil Veriatus este creatorul Shackles of Elemental Binding, care imbina alchimia, ingineria si artele arcane. Lucien si Servo se afla acolo, impreuna cu Lotwil, in Badlands.",al={"cine este lotwil","lotwil veriatus"}},{q="Ce sunt Shackles of Elemental Binding?",a="Sunt catusele pe care Lotwil tocmai le-a terminat, o combinatie de alchimie, inginerie si magie arcana, menita sa fie folosita impotriva unui elemental puternic pe care Lotwil vrea sa-l invoce.",al={"ce sunt catusele","catusele legarii elementale"}},{q="Pe cine cheama Lotwil sa depuna marturie?",a="Lotwil ii cheama pe Lucien si Servo sa fie martori la invocare, impreuna cu tine.",al={"cine este lucien","cine este servo"}},{q="Ce urmeaza inaintea acestui pas?",a="Urmeaza pasul in care ai adus cog #5 la Lotwil.",al={"misiunea anterioara","ce a dus la asta"}}},fp="24,134,20.317.0,19.287.1,23.181.0,43.162.0,37.85.0,28.58.0"}
P.entries["quest:7781"] = {n="The Lord of Blackrock",s="The Lord of Blackrock este o misiune a Alliance care incepe odata cu obtinerea capului retezat al dragonului negru Nefarian in Blackwing Lair. Ducerea acestui trofeu monstruos la Highlord Bolvar Fordragon, in Stormwind Keep, vesteste caderea stapanului din Blackrock Mountain. Ea marcheaza unul dintre cele mai mari triumfuri militare pe care Alliance le-a sarbatorit in istoria recenta.",h="The Lord of Blackrock este o misiune a Alliance care incepe odata cu obtinerea capului retezat al dragonului...",kw={"blackrock mountain","blackwing lair","highlord bolvar fordragon","capul lui nefarian","lord of blackrock","nefarian","stormwind keep"},ang={["faction:Alliance"]="Pentru Alliance, prezentarea capului lui Nefarian este o mare realizare militara. Ea zadarniceste planurile dragonflight-ului impotriva tinuturilor Human.",["race:Human"]="Ca Human, stii ca Blackrock Mountain a trimis nenumarate incursiuni si uneltiri impotriva Stormwindului. Infrangerea stapanului sau aduce regatului razbunarea mult asteptata si usurare."},sec={{t="Un monument al victoriei",b="Nefarian, stapan al puilor din Black Dragonflight si conducator al Upper Blackrock Spire, ameninta de multa vreme regatele Human din jur. Infrangerea lui pune capat experimentelor si planurilor sale ticaloase. Ducand capul lui brazdat de rani de lupta inapoi in Stormwind, dovedesti ca Lord of Blackrock a fost doborat de cei mai mari eroi ai Alliance."},{t="Audienta la Stormwind Keep",b="Highlord Bolvar Fordragon conduce regatul din sala tronului din Stormwind Keep. Capul retezat al dragonului socheaza curtea regala si impune respect. Cu regatul slabit de conflictele politice interne si de amenintarile din afara, victoria ridica moralul si isi castiga un loc in istoria Alliance."}},faq={{q="Despre ce este misiunea Lord of Blackrock?",a="Ridici capul taiat al lui Nefarian din Blackwing Lair si duci trofeul la Stormwind City. Acolo i-l prezinti lui Highlord Bolvar Fordragon in numele regatului.",al={"misiunea Lord of Blackrock","misiunea cu capul lui Nefarian pentru Alianta","capul lui Nefarian in Stormwind"}},{q="Cine este Nefarian?",a="Nefarian este un mare dragon negru si fiul lui Deathwing. Domneste din Blackwing Lair, in Blackrock Mountain, comanda orcii Blackrock si desfasoara experimente sinistre pentru a crea dragonflight-ul cromatic.",al={"cine este Nefarian","Lord of Blackrock","povestea lui Nefarian"}},{q="Cine este Highlord Bolvar Fordragon?",a="Highlord Bolvar Fordragon este paladinul care conduce Stormwind ca regent in absenta regelui Varian Wrynn. Isi tine audientele in sala tronului din Stormwind Keep si vegheaza asupra tanarului print Anduin Wrynn.",al={"Bolvar Fordragon","cine este Bolvar","marele lord Bolvar"}},{q="De ce este adus acest trofeu la Stormwind Keep?",a="Domnia lui Nefarian in Blackrock Mountain ameninta regatul Stormwind si intregul continent sudic. Ducerea capului sau la conducerea militara a regatului confirma infrangerea dragonului si ofera tinutului o victorie in jurul careia sa se uneasca.",al={"de ce Stormwind","de ce sa duc capul la fortareata","de ce Bolvar"}},{q="Ce se intampla dupa ce ii dai capul lui Bolvar?",a="Highlord Bolvar Fordragon este uimit si declara ca triumful va fi consemnat in istorie. In etapa urmatoare a evenimentului, capul este expus public, pentru ca toti locuitorii din Stormwind sa-l vada.",al={"ce se intampla in continuare","Lord of Blackrock partea a 2-a","predarea capului lui Nefarian"}},{q="Predarea acestui cap afecteaza intregul oras?",a="Da. Capul lui Nefarian este dus in capitala si ridicat deasupra portilor orasului, anuntand moartea dragonului cetatenilor si soldatilor si intarind hotararea aparatorilor din Stormwind.",al={"bonus de oras","strigat de mobilizare","bonusul capului lui Nefarian"}}},fx={["150c64a2"]={q="De ce este important sa duci capul lui Nefarian la Stormwind?",a="Nefarian era dragonul negru care planuia amenintarile venite din Blackrock Spire, manipuland regatele muritorilor si alcatuind armate monstruoase chiar la portile Stormwind. Inmanarea capului sau taiat lui Highlord Bolvar Fordragon este o dovada de netagaduit ca teroarea puietului a fost zdrobita, oferindu-i Alliance o victorie uriasa, demna de sarbatorit si de etalat in fata intregului regat.",al={"de ce sa duc capul lui Nefarian la Stormwind","motivul pentru capul lui Nefarian","de ce sa predau capul lui Nefarian"}},["7e2ee731"]={q="De ce trebuie sa duci capul la Stormwind, in locul garzilor regale?",a="Tu si tovarasii tai v-ati croit drum prin Blackwing Lair si l-ati doborat chiar voi pe stapanul dragon. Ca eroii care l-au invins, aveti dreptul sa duceti trofeul macabru inapoi la Stormwind Keep, astfel incat Highlord Bolvar Fordragon sa afle vestea direct de la cei care au ucis fiara.",al={"de ce trebuie sa duc capul lui nefarian","de ce nu duc garzile regale capul lui nefarian","de ce eu trebuie sa duc trofeul lui nefarian"}}},fp="21,273,21.325.0,26.302.0,42.167.0,16.211.0,33.197.0,45.238.0,45.176.0,48.190.0"}
P.entries["quest:7782"] = {n="The Lord of Blackrock",s="La portile Stormwind, Alliance se aduna pentru a sarbatori victoria asupra celor din Blackrock. Dupa ce raportezi la Grand Admiral Jes-Tereth in Stormwind Keep, eroii merg la Valley of Heroes, unde Field Marshal Stonebridge pregateste o ceremonie publica in cinstea orasului.",h="La portile Stormwind, Alliance se aduna pentru a sarbatori victoria asupra celor din Blackrock.",kw={"Blackrock","ucigas de dragoni","Nefarian","strigat de mobilizare","Stonebridge","Stormwind","Valley of Heroes"},ang={["class:Warrior"]="Rallying Cry of the Dragonslayer le da putere luptatorilor care pleaca sa apere tinutul.",["faction:Alliance"]="Capul lui Nefarian din Valley of Heroes uneste rasele Alliance. Cetatenii din Ironforge, Darnassus si Gnomeregan vad ca fortele intunecate care napastuiesc Eastern Kingdoms pot fi invinse.",["race:Human"]="Pentru regatul Stormwind, infrangerea stapanului Blackrock inlatura o amenintare draconica grava de la granita nordica."},sec={{t="Triumful unui oras",b="Campania Alliance impotriva Blackrock clan si a puietului Black Dragonflight ajunge la finalul sau oficial. Dupa ce capul taiat al lui Nefarian este prezentat in interiorul Stormwind Keep, Highlord Bolvar Fordragon trimite eroii prin oras catre Valley of Heroes. Field Marshal Stonebridge asteapta acolo pentru a primi trofeul si a da startul sarbatorilor."},{t="Mobilizarea fortelor Alliance",b="Field Marshal Stonebridge ridica deasupra marilor arcade de la intrarea principala din Stormwind capul retezat al lui Nefarian. Imaginea se vede in tot orasul, iar Strigatul de adunare al ucigasului de dragoni ii inspira pe aparatori, demnitarii aflati in vizita si cetateni. Ei stiu ca odraslele lui Deathwing au suferit o lovitura zdrobitoare."}},faq={{q="Ce se intampla cand finalizezi aceasta misiune?",a="Field Marshal Stonebridge agata capul retezat al lui Nefarian sus, pe arcul portii de piatra din Valley of Heroes. Apoi, Rallying Cry of the Dragonslayer ii intareste pe luptatorii si gardienii aliati din tot Stormwind City.",al={"predarea misiunii pentru capul lui Nefarian","ce face Stonebridge","declansarea strigatului de mobilizare"}},{q="Cine este Field Marshal Stonebridge?",a="Field Marshal Stonebridge este un ofiter superior in armata Stormwindului, stationat in Valley of Heroes, langa intrarea in oras. Organizeaza ceremonii publice de comemorare a victoriilor militare, inclusiv expunerea capetelor dusmanilor draconici invinsi.",al={"stonebridge","field marshal stonebridge"}},{q="De ce te trimite Highlord Bolvar Fordragon aici?",a="Dupa ce primeste vestea infrangerii lui Nefarian in sala tronului, Highlord Bolvar Fordragon te trimite la portile orasului. Acolo, armata Alliance isi poate etala victoria in vazul tuturor si poate ridica moralul in intreaga capitala.",al={"Bolvar","de ce sa mergi la Valley of Heroes"}},{q="Predarea acestui obiect afecteaza intregul oras?",a="Da. Cand Stonebridge primeste trofeul, o proclamatie rasuna in Stormwind, iar Strigatul de Lupta al Ucigasului de Dragoni ajunge la toti cei aflati in hotarele orasului.",al={"bonus mondial nefarian","primeste Stormwind bonusul"}},{q="Unde se afla Valley of Heroes?",a="Valley of Heroes este marele drum de acces catre Stormwind City. De-a lungul lui se inalta statui care ii onoreaza pe eroii celui de-al Second War, cei care au trecut prin Dark Portal.",al={"locatia Valley of Heroes","unde este Stonebridge"}},{q="Cine a fost 'Lord of Blackrock'?",a="Dragonul negru Nefarian era Lord of Blackrock. Este fiul lui Deathwing si stapaneste turlele superioare din Blackrock Mountain.",al={"cine este Lord of Blackrock","identitatea lui Nefarian"}}},fx={["3a42f3f3"]={q="De ce te trimite Bolvar in loc sa mearga el insusi?",a="Tu si tovarasii tai ati fost campionii care au infruntat inaltimile din Blackwing Lair si l-au doborat pe Nefarian. In calitate de invingator, ti se cuvine onoarea de a prezenta conducerii militare din Stormwind capul retezat al dragonului si de a da startul sarbatorii din tot orasul.",al={"de ce ma trimit pe mine","de ce nu Bolvar","de ce trebuie sa duc capul"}}},fp="21,257,16.350.1,21.302.0,42.221.1,33.240.0,49.213.1,40.161.1,38.164.0,32.124.2"}
P.entries["quest:7783"] = {n="The Lord of Blackrock"}
P.entries["quest:7784"] = {n="The Lord of Blackrock"}
P.entries["quest:78"] = {n="The Legend of Stalvan",s="Aceasta treaba marcheaza un punct de cotitura in descoperirea istoriei lui Stalvan Mistmantle, trimitand anchetatorii din Elwynn Forest inapoi in orasul intunecat Darkshire. Indrumat de amintirile lui Marshal Haggard despre zilele sale de serviciu, duci o pagina de jurnal recuperata la Tavernkeep Smitts, la Scarlet Raven Tavern, pentru a identifica scrisul de mana infiorator.",h="Aceasta treaba marcheaza un punct de cotitura in descoperirea istoriei lui Stalvan Mistmantle, trimitand...",kw={"darkshire","duskwood","elwynn","jurnal","marshal haggard","mistmantle","scarlet raven tavern","stalvan","tavernkeep smitts"},ang={["faction:Alliance"]="Misiunea scoate in evidenta legaturile stranse dintre fostii aparatori ai tinutului, punand in legatura garzile pensionate din Stormwind cu paznicii comunitatilor din intregul Kingdom of Stormwind.",["race:Human"]="Aceasta etapa dezvaluie amintirile sumbre care bantuie asezarile umane si arata ca tragediile din trecutul regiunilor Elwynn si Darkshire refuza sa ramana ingropate."},sec={{t="O pista de la Marshal",b="Dupa ce a recuperat o pagina de jurnal ponosita si rupta din cufarul lui Marshal Haggard din Elwynn Forest, comandantul pensionat nu poate citi scrisul decolorat din cauza vederii tot mai slabe. Dandu-si seama ca urma duce inapoi peste rau, Haggard isi aminteste de vremea cand comanda Stormwind Guard si de serile petrecute la Scarlet Raven Tavern din Darkshire. Te indruma catre Tavernkeep Smitts, un hangiu a carui lunga cariera l-a facut pazitorul neoficial al istoriei si zvonurilor locale."},{t="Intoarcerea la Scarlet Raven",b="Dupa ce strabati din nou padurile mohorate din Duskwood, ii prezinti manuscrisul decolorat lui Smitts, aflat in spatele tejghelei. Smitts se inmoaie numaidecat cand aude numele vechiului sau cunoscut, Haggard, desi deplange sanatatea tot mai subreda a veteranului. Cand arunca o privire asupra pergamentului, firea sa relaxata se preschimba pe loc in panica: recunoaste scrisul distinctiv fara urma de indoiala, iar ancheta se apropie de adevarul inspaimantator despre nebunia lui Stalvan."}},faq={{q="De ce ma trimite Marshal Haggard inapoi la Darkshire?",a="Marshal Haggard este batran si aproape orb, asa ca nu poate examina singur pagina recuperata din jurnal. Isi aminteste ca Tavernkeep Smitts de la Scarlet Raven Tavern era un expert in traditiile si istoria locala, pe vremea cand Haggard slujea in Stormwind Guard, ceea ce il face pe Smitts persoana ideala pentru a identifica scrierea.",al={"de ce sa merg la Darkshire","Haggard si Darkshire","de ce Smitts"}},{q="Unde se afla Tavernkeep Smitts?",a="Tavernkeep Smitts serveste la barul din Scarlet Raven Tavern, aflata in partea de est a Darkshire, in Duskwood.",al={"unde este smitts","locatia lui smitts","locatia Scarlet Raven Tavern"}},{q="Ce obiect duci la Tavernkeep Smitts?",a="Aduci o pagina de jurnal decolorata, un fragment din jurnalul pierdut al lui Stalvan Mistmantle, gasit anterior ascuns in lada cu efecte personale a lui Marshal Haggard.",al={"ce obiect","pagina din jurnalul decolorata","pagina din jurnalul lui Stalvan"}},{q="Recunoaste Tavernkeep Smitts scrisul de mana?",a="Da. In clipa in care Smitts arunca o privire asupra paginii decolorate, recunoaste scrisul de mana cu o vadita neliniste, iar recunoasterea ii ofera cautarii lui Stalvan urmatoarea pista.",al={"stie smitts ce scrie","reactia lui smitts la jurnal"}},{q="De unde il cunoaste Smitts pe Marshal Haggard?",a="Smitts l-a gazduit pe Haggard cu ani in urma, cand acesta conducea patrule ale Stormwind Guard in Duskwood si trecea des pe la Scarlet Raven Tavern pentru un pahar.",al={"relatia dintre Smitts si Haggard","cum il cunoaste Smitts pe Haggard"}},{q="Ce urmeaza in cautarea lui Stalvan?",a="Du pagina de jurnal decolorata la Smitts, la Scarlet Raven Tavern, si urmeaza indiciul pe care ti-l da.",al={"ce urmeaza","urmatorul pas in cazul lui Stalvan","continua lantul de misiuni Stalvan"}}},fx={bf062962={q="De ce vrea Marshal Haggard ca acest lucru sa fie facut?",a="Marshal Haggard nu poate citi pagina de jurnal decolorata, pentru ca vederea i se inrautateste. Si-l aminteste pe Tavernkeep Smitts ca pe o veche cunostinta, priceputa la istoria locala, si iti cere sa-i duci pagina in Darkshire.",al={"de ce vrea Haggard sa se faca asta","motivul lui Marshal Haggard","de ce sa ajuti la gasirea lui Stalvan"}},c297959a={q="De ce te trimite Marshal Haggard pe tine, in loc sa mearga el insusi?",a="Haggard este un fost maresal batran si retras, care traieste izolat si isi pierde repede vederea. Drumurile prin padure sunt periculoase, iar lui ii lipsesc tineretea si rezistenta fizica necesare pentru a strabate inapoi granita pana in Duskwood. Se bazeaza pe un calator capabil ca tine sa-i faca treaba si sa-i arate pagina din jurnal vechii sale cunostinte.",al={"de ce nu poate Haggard sa mearga","de ce are Haggard nevoie de mine","de ce nu-l viziteaza Haggard pe Smitts"}}},fp="21,343,23.491.0,27.485.1,51.311.0,35.119.0,44.152.0,49.164.0,37.145.0,42.99.0"}
P.entries["quest:780"] = {n="The Battleboars",s="Battleboars este o misiune de vanatoare menita sa marcheze trecerea la maturitate, oferita de Grull Hawkwind in Camp Narache. Tinerii tauren trebuie sa rareasca mistretii feroce, antrenati pentru razboi, din Brambleblade Ravine, pentru a apara pamanturile tribului si a hrani tineretul asezarii.",h="Battleboars este o misiune de vanatoare menita sa marcheze trecerea la maturitate, oferita de Grull Hawkwind...",kw={"battleboar","brambleblade ravine","bristleback","camp narache","grull hawkwind","mulgore","quilboar","red cloud mesa"},ang={["class:Hunter"]="Infruntarea fiarelor dresate pentru cruzime de Bristlebacks ii invata pe tinerii vanatori sa deosebeasca limpede animalele salbatice de cele transformate in arme de razboi.",["profession:Cooking"]="Cererea de flancuri si boturi scoate in evidenta esenta bucatariei tauren: carnea aspra si tare poate fi intotdeauna fiarta pana devine tocana hranitoare si satioasa.",["race:Tauren"]="Aceasta sarcina intruchipeaza echilibrul tauren dintre apararea tinuturilor Earth Mother si grija ca nimic din cele dobandite in lupta sa nu se iroseasca, transformand animalele de razboi ale dusmanilor in hrana pentru puii taberei."},sec={{t="O amenintare la granita",b="La est de Red Cloud Mesa se afla Brambleblade Ravine, o rana napadita de spini, stapanita de quilboar din Bristleback. Pe masura ce tensiunile dintre Shu'halo si quilboar se transforma intr-un razboi deschis, Bristlebacks au dres vieri de lupta feroce, care sa iscodeasca hotarele taurenilor si sa terorizeze tinuturile lor traditionale de vanatoare. Lasate nesupravegheate, aceste bestii agresive ameninta nu doar cararile vanatorilor, ci si siguranta din Camp Narache."},{t="Hranirea tribului",b="Pentru tauren, vanatoarea este deopotriva o necesitate defensiva si o sursa comuna de hrana. Grull Hawkwind le cere initiatilor sa aduca boturile si coastele mistretilor de lupta ucisi. Nici macar animalele dresate de quilboar nu sunt irosite: carnea si zgarciurile lor sunt folosite la pregatirea unei tocane satioase pentru tinerii tribului, transformand o arma a quilboarilor in hrana pentru urmatoarea generatie de aparatori tauren."}},faq={{q="De ce ataca mistretii de lupta platoul?",a="Mistretii de lupta au fost crescuti si dresati in mod deliberat de quilboarii Bristleback care locuiesc in Brambleblade Ravine. Quilboarii ii folosesc ca animale de atac pentru a-i hartui pe tauren si a le incalca terenurile de vanatoare tribale din Red Cloud Mesa.",al={"agresivitatea Battleboar","de ce sunt Battleboar ostili","atacurile Battleboar"}},{q="Cine trimite jucatorii la aceasta vanatoare?",a="Grull Hawkwind, un vanator renumit si batran aflat la Camp Narache, ii indruma pe tinerii tauren prin incercarile finale ale pregatirii lor initiale.",al={"cine ofera misiunea Battleboars","cine da misiunea Battleboars","rolul lui Grull Hawkwind"}},{q="Unde se gasesc mistretii de lupta?",a="Ei ratacesc prin Brambleblade Ravine si imprejurimi, un canion accidentat aflat la est de Camp Narache, la marginea estica a Red Cloud Mesa.",al={"locatia Battleboar","unde sunt Battleboar","mistretii din Brambleblade Ravine"}},{q="Ce se intampla cu carnea adunata de la mistreti?",a="Flancurile si boturile de battleboar sunt duse inapoi la Camp Narache, unde sunt fierte incet pentru a face tocanita copiilor si batranilor asezarii, in cinstea traditiei tauren de a folosi tot ce vaneaza.",al={"la ce folosesc cotletele de Battleboar","la ce foloseste carnea de mistret","tocana de mistret"}},{q="Cum se inscrie aceasta misiune in conflictul local cu quilboarii?",a="Misiunea reprezinta o prima incursiune in razboiul deschis dintre tauren si tribul Bristleback. Rarirea animalelor lor de razboi reduce numarul fiarelor care hartuiesc terenurile de vanatoare ale taurenilor si le transmite un mesaj clar celor din Bristlebacks, din Brambleblade Ravine.",al={"razboiul dintre tauren si quilboar","conflictul cu Bristleback","istoria quilboar"}},{q="Ce misiune precede The Battleboars?",a="Este precedata de The Hunt Continues, o misiune anterioara de la Grull Hawkwind, axata pe cunoasterea terenurilor de vanatoare din Red Cloud Mesa.",al={"cerinta pentru Battleboars","misiunea anterioara Battleboars","sirul Hunt Continues"}}},fx={b70ec92c={q="De ce vrea Grull Hawkwind sa fie ucisi mistretii de lupta?",a="Mistretii de lupta au iesit din Brambleblade Ravine si au patruns chiar in vechile terenuri de vanatoare ale tribului Red Cloud. Crescuti si dresati sa fie fiorosi de quilboarii Bristleback, acestia devin tot mai agresivi si ameninta direct Camp Narache. Grull Hawkwind vrea sa le dea quilboarilor o lectie aspra, raritandu-le bestiile de razboi si transformand vanatoarea in hrana pentru tinerii tribului.",al={"de ce vrea Grull Hawkwind sa moara mistretii de lupta","motivul lui Grull Hawkwind in privinta mistretilor de lupta","de ce sa ucizi mistretii de lupta din Mulgore"}},["58a19c3f"]={q="Ce sunt mistretii de lupta?",a="Battleboars sunt fiare feroce crescute si dresate de quilboarii Bristleback din Brambleblade Ravine. Spre deosebire de pumele salbatice de munte si de alergatorii de campie bastinasi din Red Cloud Mesa, acesti mistreti sunt antrenati in mod deliberat pentru razboi si cruzime, fiind arme vii in lupta necontenita a Bristlebacks impotriva taurenilor.",al={"cine sunt Battleboars","ce sunt Battleboars","povestea Battleboars"}}},fp="15,237,22.418.0,17.402.0,43.234.0,31.147.0,32.137.0,50.191.0,57.242.0,36.132.0"}
P.entries["quest:7802"] = {n="O donatie de lana"}
P.entries["quest:7807"] = {n="A Donation of Wool",s="A Donation of Wool este o cerere de materiale organizata de Gnomeregan Exiles pentru a aduna tesaturi esentiale. Goniti din orasul lor tehnologic, gnomii exilati se bazeaza pe saizeci de bucati de panza de lana donate de aventurieri darnici din intregul tinut pentru a-si sustine comunitatea. Cei care contribuie la aceasta initiativa sunt recunoscuti oficial de comunitatea gnomilor refugiati.",h="A Donation of Wool este o cerere de materiale organizata de Gnomeregan Exiles pentru a aduna tesaturi...",kw={"colecta de materiale","donatie de lana","Gnome","Gnomeregan","exilatii din Gnomeregan","textile","tesatura de lana"},ang={["faction:Alliance"]="Furnizarea de materii prime gnomilor exilati consolideaza solidaritatea Alliance si ajuta la sustinerea unui aliat de seama, stramutat din tinuturile sale muntoase.",["profession:Tailoring"]="Croitorii care aduna sau tes panza de lana au din belsug materiale textile de care populatiile de refugiati au disperata nevoie pentru vesminte si provizii de baza.",["race:Gnome"]="Pentru gnomii exilati, strangerea lanii ajuta la aprovizionarea rudelor stramutate, care incearca sa supravietuiasca si sa recladeasca in afara Gnomeregan."},sec={{t="Nevoile unui popor stramutat",b="Dupa ce Gnomeregan a cazut in mainile invadatorilor troggs si a fost contaminat radioactiv, gnomii supravietuitori au fost alungati din metropola lor de inalta tehnologie. Traind in principal ca refugiati gazduiti de rudele lor pitice din Ironforge, Gnomeregan Exiles se confrunta cu mari dificultati logistice. Campaniile regulate de colectare a materialelor de baza, precum panza, sunt esentiale pentru a-si mentine poporul imbracat, aprovizionat si organizat in timp ce supravietuieste departe de salile stramosesti."},{t="Colecta de textile",b="Pentru a nu impovara excesiv fiecare binefacator, organizatorii campaniei cer exact saizeci de bucati de stofa de lana de la fiecare voluntar. Adunand contributii modeste din intregul regat, exilatii pot strange materialele textile necesare pentru asternuturi, bandaje si haine, fara sa puna o povara nesustenabila pe umerii unui singur furnizor. In schimb, gnomii le ofera recunoastere oficiala printre ai lor tuturor celor dispusi sa le sprijine eforturile de refacere."}},faq={{q="De ce au nevoie Gnomeregan Exiles de panza de lana?",a="Gnomeregan Exiles organizeaza o campanie de strangere a resurselor pentru a-si constitui provizii de baza de materiale textile. Alungati din orasul lor natal, membrii poporului au nevoie de materiale esentiale, precum tesatura de lana, pentru a-si sustine populatia de refugiati si operatiunile aflate in desfasurare.",al={"de ce lana","la ce foloseste lana","scopul donatiei de lana"}},{q="De cata stofa de lana este nevoie?",a="Campania de donatii cere o singura contributie de saizeci de bucati de panza de lana din partea fiecarui donator. Organizatorii estimeaza ca primirea acestei cantitati exacte de la locuitori din toate colturile tinutului le va acoperi necesarul total de provizii.",al={"cat de multa lana","cantitatea donatiei","lana necesara"}},{q="Cine organizeaza aceasta campanie de donatii?",a="Reprezentantii Gnomeregan Exiles coordoneaza colectarea textilelor, primind donatii in numele populatiei gnome stramutate, care isi gaseste acum adapost printre aliati.",al={"cine primeste donatia","cine accepta lana","destinatarul donatiei"}},{q="Poti dona stofa de lana de mai multe ori?",a="Rechizitia este limitata la o singura contributie de saizeci de bucati din partea fiecarui donator. Exilatii spun ca stocurile lor actuale necesita doar acea cantitate fixa din partea ta, intrucat se bazeaza pe un numar mai mare de contribuabili din tot tinutul pentru a-si indeplini cota.",al={"pot dona din nou","se poate repeta","mai multe donatii de lana"}},{q="Ce recunoastere ofera Gnomeregan Exiles?",a="Daca oferi saizeci de bucati de lana, Gnomeregan Exiles iti vor arata deplina recunostinta, iar tu iti vei dovedi loialitatea si sprijinul fata de poporul lor stramutat, intr-o perioada de criza.",al={"reputatia exilatilor din gnomeregan","reputatia gnomilor","recunoasterea exilatilor"}},{q="De ce sunt gnomii exilati in prezent?",a="Gnomii au fost siliti sa-si paraseasca locuinta subterana din Gnomeregan in urma unui dezastru catastrofal si a invaziei troggilor, fiind nevoiti sa depinda de tabere temporare, ajutorul aliatilor si transporturi de provizii, in timp ce traiau ca refugiati.",al={"de ce sunt gnomii in exil","unde se afla Gnomeregan","criza refugiatilor gnomi"}}},fp="18,365,26.459.0,17.448.0,45.241.0,30.243.0,38.178.0,41.252.0,48.188.0,38.229.0"}
P.entries["quest:781"] = {n="Attack on Camp Narache",s="Attack on Camp Narache este o descoperire vitala facuta in vizuina quilboar din Brambleblade Ravine. O harta patata de pamant dezvaluie ca tribul agresiv Bristleback pune la cale un asediu organizat asupra Camp Narache. Predarea acestor planuri catre Chief Hawkwind alerteaza la timp Camp Narache, care poate astfel sa ceara ajutor din Bloodhoof Village.",h="Attack on Camp Narache este o descoperire vitala facuta in vizuina quilboar din Brambleblade Ravine.",kw={"planuri de atac","Bloodhoof Village","Brambleblade Ravine","Bristleback","Camp Narache","Chief Hawkwind","harta patata de noroi","quilboar","Red Cloud Mesa"},ang={["faction:Horde"]="Pastrarea pozitiei taurenilor in Mulgore asigura Horde un punct de sprijin vital in sudul Kalimdorului central.",["race:Tauren"]="Pentru tinerii luptatori tauren care trec primele ritualuri pe mesa, interceptarea acestei harti iti dovedeste loialitatea fata de trib si iti protejeaza rudele de un macel neasteptat."},sec={{t="Un complot prin maracini",b="In timp ce cerceteaza adancul Brambleblade Ravine, tinerii aventurieri tauren descopera o harta grosolana, patata cu pamant, zaceand pe podeaua de stanca. Privita mai indeaproape, pergamentul dezvaluie marcaje tactice intentionate, facute de quilboarii Bristleback. In loc sa se multumeasca cu incaierari oportuniste, quilboarii coordoneaza un asediu de amploare, prelungit, asupra Camp Narache."},{t="Avertizarea capeteniei",b="Ducerea planurilor de atac inapoi in Camp Narache ii ofera lui Chief Hawkwind informatii esentiale. Dandu-si seama de pericolul grav care ameninta tabara relativ lipsita de aparare si tinerii ei initiati, Hawkwind se pregateste sa trimita dupa intariri in Bloodhoof Village. Harta interceptata transforma ceea ce putea fi o ambuscada catastrofala intr-o aparare pregatita."}},faq={{q="Unde sunt gasite planurile de atac ale Bristleback?",a="Planurile provin de pe o harta murdara de pamant, aflata intr-o pestera din Brambleblade Ravine, chiar sus pe o carare, la dreapta colibei lui Chief Sharptusk.",al={"locatia hartii","unde se afla harta patata de pamant","gaseste planurile"}},{q="Cine primeste planurile de atac Bristleback?",a="Planurile trebuie livrate direct lui Chief Hawkwind, in centrul taberei Camp Narache.",al={"cui sa predau","cine primeste harta","finalul misiunii"}},{q="De ce vizeaza mistretii quilboar Bristleback Camp Narache?",a="Tribul Bristleback cauta sa-i alunge pe Tauren din Red Cloud Mesa si sa-si recapete pentru cei de-un neam cu ei terenurile de vanatoare si campiile sacre din Mulgore.",al={"de ce sa ataci camp narache","motivele quilboar din mulgore","asediul bristleback"}},{q="Cum planuieste Chief Hawkwind sa contracareze asediul?",a="Datorita avertismentului timpuriu oferit de harta interceptata, Chief Hawkwind intentioneaza sa-si cheme fratii din Bloodhoof Village pentru a intari mesa si a respinge atacul.",al={"planul Hawkwind","intariri pentru Camp Narache"}},{q="Trebuie sa vorbesti cu cineva inainte sa ridici harta?",a="Nu. Misiunea incepe direct de la Dirt-stained Map, aflata pe podeaua pesterii din Brambleblade Ravine; dupa ce o ridici, aceasta se transforma in planurile de lupta.",al={"incepatorul misiunii","incepatorul misiunii Harta Patata de Pamant","cum sa incepi Attack on Camp Narache"}},{q="Ce se intampla daca Camp Narache cade?",a="Camp Narache este principalul refugiu al tinerilor razboinici tauren si locul ritualurilor de initiere; pierderea lui ar compromite securitatea Red Cloud Mesa si ar rupe legatura cu locurile de pregatire spirituala din Mulgore.",al={"miza apararii Camp Narache","de ce sa aperi Narache"}}},fp="22,330,22.393.0,21.361.0,45.143.0,42.85.0,56.152.0,50.168.0,69.149.0,35.185.0"}
P.entries["quest:7810"] = {n="Arena Master",s="Oare maiestria arenei se rezuma la atat? Short John Mithril, Pirate din spatele evenimentului Gurubashi, ar putea avea raspunsul, iar tu il vei gasi in Stranglethorn Arena.",h="Oare maiestria arenei se rezuma la atat?",kw={"arena master","gurubashi","pirat","short john mithril","stranglethorn arena","stranglethorn vale"},sec={{t="In cautarea lui Pirate",b="Orice ai obtinut la Gurubashi, se pare ca pentru a stapani arena trebuie sa faci mai mult. Short John Mithril, Pirate-ul care organizeaza concursurile de acolo, s-ar putea sa stie ce anume. Cauta-l in Stranglethorn Arena."},{t="Cuvantul lui Short John",b="Short John Mithril iti spune ca un singur obiect de podoaba nu ajunge ca sa devii campionul arenei. Acum, spune el, urmeaza adevarata incercare a vitejiei tale."}},faq={{q="Cu cine trebuie sa vorbesc?",a="Short John Mithril, Pirate-ul din spatele evenimentului Gurubashi.",al={"cu cine vorbesc","unde predau Arena Master","unde trebuie sa merg"}},{q="Unde se afla Short John Mithril?",a="In Stranglethorn Arena, la Gurubashi, in Stranglethorn Vale.",al={"locatia Gurubashi","unde este Stranglethorn Arena","locatia arenei"}},{q="Ce se sugereaza despre a fi stapanul arenei?",a="Doar ca stapanirea arenei pare sa ceara mai mult decat ai facut pana acum, iar Pirate din spatele evenimentului Gurubashi ar putea sti.",al={"cum sa devin Arena Master","sunt deja Arena Master"}}},fp="12,177,18.212.0,17.149.1,28.58.0,28.63.0,47.135.0"}
P.entries["quest:78124"] = {n="Nar'thalas Almanac",s="Nar'thalas Almanac este un manuscris savant rar, despre studiul magiei stravechi, cautat de arhivari pentru a-si imbogati colectia bibliotecii. Recuperarea volumului readuce cunostinte arcane pierdute in maini de incredere, unde cercetatorii ii pot studia invataturile uitate.",h="Nar'thalas Almanac este un manuscris savant rar, despre studiul magiei stravechi, cautat de arhivari pentru...",kw={"almanah","arcana","carte","biblioteca","lucrari magice","Nar'thalas","Narthalas","tome"},ang={["class:Mage"]="Magii inteleg imensa valoare academica a textelor recuperate despre traditiile arcanice stravechi, astfel ca orice contributie la colectia magica a bibliotecii capata o insemnatate aparte.",["faction:Alliance"]="Carturarii si curatorii care lucreaza in arhivele Alliance se bazeaza pe aventurieri intreprinzatori pentru a cauta manuscrise rare si a imbogati tezaurul de cunostinte al regatului.",["race:NightElf"]="Nar'thalas a fost candva un vechi centru de studii arcane Kaldorei, inainte ca Sundering sa sfarame lumea de odinioara; un almanah care ii poarta numele este astfel o legatura emotionanta cu istoria straveche a elfilor noptii."},sec={{t="O relicva a studiului stravechi",b="Nar'thalas Almanac este un volum rar de studii arcane, provenit din vechile traditii ale eruditiei night elf dinaintea Marii Scindari. Pentru pazitorii marilor arhive, pastrarea unui asemenea text salveaza de la uitare cunostinte vechi de secole si adauga un fragment esential de istorie colectiilor. Aventurierii care descopera aceste lucrari neglijate de multa vreme ajuta la legarea antichitatii uitate de intelegerea erudita moderna."},{t="Extinderea arhivelor",b="Arhivarii si cercetatorii cauta necontenit tratate pierdute, insemnari de teren si cronici raspandite prin Azeroth. Pastrarea Nar'thalas Almanac intr-o biblioteca special amenajata asigura protejarea, catalogarea si studierea sa, in loc sa fie lasat sa se degradeze in ruine sau sa ajunga pe maini nechibzuite. Fiecare volum recuperat le ofera invatatilor noi perspective asupra artelor arcane din epocile trecute."}},faq={{q="Ce este Nar'thalas Almanac?",a="Nar'thalas Almanac este un manuscris stravechi de studii magice, cautat de curatorii bibliotecilor pentru a le imbogati arhivele istorice. Aventurierii care recupereaza asemenea lucrari rare le incredinteaza carturarilor, pentru ca invataturile pastrate in ele sa poata fi catalogate.",al={"ce este almanacul narthalas","misiunea cu almanacul narthalas","informatii despre almanac"}},{q="Cine aduna Nar'thalas Almanac?",a="Almanahul le este prezentat carturarilor bibliotecii interesati de texte magice stravechi si arhive istorice. Acesti ingrijitori cauta activ sa-si imbogateasca cunoasterea institutionala comuna despre mostenirea arcana a lumii.",al={"cine vrea almanahul","unde ajunge almanahul","unde se preda almanahul"}},{q="La ce se refera numele Nar'thalas?",a="Nar'thalas a fost un stravechi centru Kaldorei de invatare si studiu magic, datand dinainte de Great Sundering. Textele pastrate asociate acestui nume reprezinta fragmente de magie arcana si cunostinte elfe de dinaintea Sundering-ului.",al={"ce este Narthalas","povestea Narthalas","unde se afla Narthalas"}},{q="De ce sunt adunate texte magice pentru biblioteca?",a="Numeroase documente istorice si tratate magice au fost stramutate, pierdute sau ingropate in ruinele raspandite prin Azeroth. Invatii se bazeaza pe scrierile recuperate pentru a-si largi intelegerea curentilor arcani si pentru a proteja documentele fragile de pierderea definitiva.",al={"de ce sa colectezi lucrari magice","scopul bibliotecii","de ce conteaza cartile"}},{q="Pot fi aduse la biblioteca si alte lucrari magice?",a="Carturarii primesc cu bucurie orice tratate, tomuri sau manuscrise uitate recuperate, daca acestea arunca lumina asupra teoriei arcane si a istoriei stravechi; cauta neincetat lucrari care sa le imbogateasca rafturile.",al={"mai multe carti magice","alte tomuri","mai multe texte"}},{q="Este periculos sa manuiesti Nar'thalas Almanac?",a="Almanahul este o culegere de studii, nu un artefact interzis si instabil. Este in primul rand o lucrare de referinta valoroasa pentru istoricii si practicantii care studiaza magia din trecut.",al={"este almanacul periculos","are almanacul magie neagra","este sigur de citit"}}},fp="18,251,24.420.0,22.377.0,31.251.0,41.223.0,39.219.0,54.238.0,50.182.0,46.201.0"}
P.entries["quest:78142"] = {n="Vrajiri si straluciri"}
P.entries["quest:78143"] = {n="Secrets of the Dreamers",s="Secrets of the Dreamers le cere aventurierilor sa recupereze scrieri magice rare pentru a imbogati arhivele savantilor. Predand aceste tratate descoperite, exploratorii ii ajuta pe carturarii unei biblioteci sa-si extinda colectia de cunostinte stravechi.",h="Secrets of the Dreamers le cere aventurierilor sa recupereze scrieri magice rare pentru a imbogati arhivele...",kw={"arcane","visatori","biblioteca","lucrari magice","carturari","Secrets of the Dreamers","tomuri"},ang={["class:Druid"]="Avand in vedere referirea la Visatori, scrierile legate de magia naturii si de Emerald Dream au o insemnatate profunda pentru practicantii artelor Cenarion.",["class:Mage"]="Arcanistii eruditi sunt in mod aparte potriviti sa caute tomuri rare si texte magice prin Azeroth, imbogatind arhivele institutiilor.",["faction:Alliance"]="Invatatii Aliantei, mai ales cei care se ocupa de mari colectii de documente, se bazeaza pe campioni aventurieri pentru a recupera cunostinte pierdute din locuri periculoase."},sec={{t="Recuperarea cunoasterii uitate",b="Misiunea Secrets of the Dreamers presupune recuperarea unor texte magice rare si tratate istorice din toate colturile regatului. Carturarii dedicati consemnarii misterelor arcane ale Azeroth se bazeaza pe aventurieri calatori, care sa descopere lucrari uitate si sa le aduca in siguranta in arhive. In loc sa lase cunostinte pretioase sa zaca in ruine stravechi sau colectii private, aceste eforturi de strangere asigura studierea si pastrarea traditiilor esentiale pentru generatiile viitoare."},{t="Extinderea arhivelor",b="Dupa predarea acestor tratate, arhivistii le adauga la colectiile permanente, largind intelegerea pe care o are arhiva asupra fenomenelor magice. Intr-o biblioteca precum aceasta, cercetatorii cauta neincetat manuscrise rare, despre orice, de la Emerald Dream pana la teoria arcana. Munca nu se incheie niciodata cu totul, iar invatatii primesc cu nerabdare orice alte scrieri magice descoperite pe teren."}},faq={{q="Care este scopul misiunii Secrets of the Dreamers?",a="Secrets of the Dreamers este o misiune axata pe recuperarea unor lucrari magice si cunostinte obscure pentru a imbogati o colectie savanta. Aventurierii gasesc materiale relevante in lume si le predau pentru a imbogati arhivele cercetatorilor.",al={"ce este Secrets of the Dreamers","misiunea Secrets of the Dreamers","ce trebuie sa faci in aceasta misiune"}},{q="Cine colecteaza aceste texte magice?",a="Misiunea este primita si predata unui invatat care se ocupa de colectia unei biblioteci si le cere aventurierilor calatori sa aduca opere magice.",al={"cine vrea Secrets of the Dreamers","cine ofera aceasta misiune","unde predai Secrets of the Dreamers"}},{q="Unde sunt pastrate lucrarile recuperate?",a="Scrierile recuperate sunt adaugate direct arhivelor in continua crestere ale unei biblioteci institutionale, asigurandu-se astfel ca traditia rara si descoperirile magice sunt catalogate si pastrate pentru invatatii si cercetatorii din Alliance.",al={"ce este colectia","pentru ce biblioteca este","unde merg cartile"}},{q="La ce se refera titlul prin \"Visatorii\"?",a="Denumirea Dreamers se refera, in mod traditional, la practicantii druizi aflati in armonie cu Emerald Dream sau la entitatile stravechi adormite, legate de somnul naturii. Lucrarile magice care le poarta secretele pastreaza o putere primordiala si misterioasa.",al={"cine sunt visatorii","povestea visatorilor","de ce se numesc visatori"}},{q="Poti aduce mai multe opere magice dupa ce termini misiunea?",a="Arhivistii primesc cu bucurie noi contributii. Ori de cate ori descoperi in calatoriile tale alte lucrari magice care ar putea imbogati colectia, esti incurajat sa le aduci pentru a sprijini cercetarile ulterioare.",al={"pot preda mai multe carti","se poate repeta","mai multe lucrari magice"}},{q="De ce este importanta pentru carturari adunarea acestor scrieri magice?",a="Bibliotecile si cercetatorii din Alliance cauta necontenit sa-si extinda intelegerea magiei arcane, a naturii si a misterelor obscure. Tratatele pierdute sau raspandite contin cunostinte care-i ajuta pe invatati sa descopere istoria mai profunda si misterele lumii.",al={"de ce sa adun carti magice","de ce are biblioteca nevoie de tomuri magice"}}},fp="23,228,25.462.0,22.421.0,57.238.0,33.142.0,37.199.0,47.217.0,59.220.0,63.250.0"}
P.entries["quest:7815"] = {n="Snapjaws, Mon!",s="In Hinterlands, Katoom the Angler din Revantusk Village abia isi poate tine undita in apa, fiindca snapjaw-ii de apa sarata o distrug mereu si ii fura momeala. Vrea sa omori cincisprezece dintre testoase.",h="In Hinterlands, Katoom the Angler din Revantusk Village abia isi poate tine undita in apa, fiindca snapjaw-ii...",kw={"pescar","momeala","pescuit","hinterlands","Katoom","Revantusk","Snapjaws","broaste testoase"},sec={{t="Probleme pe linie",b="Katoom te indeamna sa nu te lasi pacalit de ochii mari ai snapjaw-ilor si spune ca testoasele sunt o pacoste. Dupa cum povesteste el, nu poate pescui nici macar cinci minute fara ca una dintre ele sa-i rupa firul si sa fuga cu momeala. Iti cere, ca o favoare pentru el si pentru vecinii lui din sat, sa le starpesti pe toate; sunt cincisprezece."}},faq={{q="Cine iti cere sa vanezi testoasele?",a="Katoom the Angler, un pescar Revantusk din Hinterlands.",al={"cine da Snapjaws, Mon!","cel care da misiunea Snapjaws, Mon!","pescarul Katoom"}},{q="De ce vrea Katoom sa fie ucisi snapjawii de apa sarata?",a="Katoom spune ca ei ii rup firul unditei si-i fura momeala, asa ca nu poate pescui nici macar cinci minute in liniste.",al={"de ce sa omori snapjaws","deranjul provocat de broaste testoase","de ce sa omori broaste testoase Revantusk"}},{q="Cati snapjaw trebuie ucisi?",a="Cincisprezece broaste testoase snapjaw de apa sarata.",al={"cate broaste testoase","numar snapjaw","numar mon pentru snapjaws"}}},fp="14,199,19.333.0,33.60.0,51.109.0,35.34.0"}
P.entries["quest:7816"] = {n="Gammerita, Mon!",s="Katoom the Angler, din Revantusk Village, in Hinterlands, si-a pierdut cea mai buna momeala in favoarea lui Gammerita, conducatoarea snapjaw de apa sarata. Ti se cere s-o gasesti si s-o recuperezi.",h="Katoom the Angler, din Revantusk Village, in Hinterlands, si-a pierdut cea mai buna momeala in favoarea lui...",kw={"pescar","Gammerita","hinterlands","Katoom","momitoare","Revantusk","Snapjaw","broasca testoasa"},sec={{t="Un hot printre testoase",b="Katoom spune ca Gammerita nu este o testoasa obisnuita: ea conduce snapjaw-ii de apa sarata, iar Katoom o numeste hoata. I-a smuls cea mai buna naluca din fir si, de atunci, pestii nu mai musca asa cum o faceau inainte."},{t="Recuperarea momelii",b="Katoom vrea sa o gasesti pe Gammerita si sa recuperezi momeala din stomacul ei. Gammerita sta pe coasta, printre celelalte testoase."},{t="Sperantele lui Katoom",b="Cu momeala inapoi si mai putini snapjaws prin preajma, Katoom se asteapta ca pestele sa vina cu gramada."}},faq={{q="Cine este Katoom pescarul?",a="Un pescar din Revantusk, in Hinterlands, care iti cere sa vanezi Gammerita.",al={"cine este katoom","katoom revantusk","locatia lui katoom"}},{q="Ce este Gammerita?",a="O testoasa diferita de celelalte, care conduce snapjaw-ii de apa sarata si pe care Katoom o numeste hot.",al={"cine este gammerita","ce este gammerita","broasca testoasa gammerita"}},{q="De ce vrea Katoom sa o omoare pe Gammerita?",a="Gammerita a smuls de pe fir cea mai buna momeala a lui Katoom, iar pestii nu mai musca la fel de atunci. Katoom vrea sa-si recupereze momeala din stomacul ei.",al={"de ce sa-l ucizi pe gammerita","ce a furat gammerita","motivul lui katoom"}},{q="Unde poate fi gasita Gammerita?",a="Pe coasta, unde sta alaturi de celelalte broaste testoase saltwater snapjaw.",al={"unde se afla gammerita","locatia lui gammerita","gaseste-l pe gammerita"}}},fp="15,177,25.216.0,21.128.0,14.100.1,25.73.0,18.91.0,36.145.0,29.79.0"}
P.entries["quest:782"] = {n="Broken Alliances",s="In Kargath, Gorn vrea ca onoarea Horde sa fie restabilita dupa alianta cu Deathwing. Capetenia ogrilor Boss Tho'grun, angajata sa ajute la gasirea Sign of the Earth, s-a intors impotriva Horde si l-a pastrat pentru sine, iar tu trebuie sa-l recuperezi de la Camp Boff.",h="In Kargath, Gorn vrea ca onoarea Horde sa fie restabilita dupa alianta cu Deathwing.",kw={"badlands","blacklash","camp boff","deathwing","gorn","hematus","kargath","lethlor ravine","sign of the earth","tho'grun"},sec={{t="Mercenarii se intorc impotriva ta",b="In timpul Second War, Horde a fost de partea dragonului Deathwing. Doi dintre locotenentii acestuia, Blacklash si Hematus, au ajuns inchisi in Lethlor Ravine, departe, spre est. Gorn sustine ca acesti vechi aliati depravati trebuie redusi la tacere pentru ca onoarea Horde sa fie restaurata. Pentru a deschide inchisoarea drake-ilor, Horde avea nevoie de Sign of the Earth si a angajat mercenari ogri sub comanda lui Boss Tho'grun sa-l gaseasca. Tho'grun s-a intors impotriva lor, i-a invins si l-a pastrat pentru sine."},{t="Tabara lui Boff",b="Gorn te trimite spre sud-est de Kargath, la Camp Boff, ca sa-l ucizi pe Tho'grun si sa aduci inapoi Sign of the Earth. Gorn se va bucura sa-l vada mort pe Tho'grun si spune ca ogrii nu mai fac parte din Horde."},{t="Ce deschide semnul",b="Cu Tho'grun mort, Gorn se asteapta ca ogrii sa cada in dezordine, o mica victorie deschizand calea spre una mai mare. Cu Sign in mainile Horde, temnita dragonilor negri din Lethlor poate fi deschisa, eliberandu-i din captivitatea fara sfarsit, dar si trimitandu-i spre pieirea lor."}},faq={{q="Cine este Gorn?",a="Gorn este reprezentantul Horde din Kargath, care te trimite dupa Sign of the Earth si vrea sa restaureze onoarea Horde, reducandu-i la tacere pe fostii sai aliati degenerati.",al={"cine da Broken Alliances","gorn kargath","povestea lui gorn"}},{q="De ce il vrea Gorn mort pe Boss Tho'grun?",a="Horde i-a angajat pe Tho'grun si mercenarii sai capcani ca sa obtina Sign of the Earth. Tho'grun s-a intors impotriva lor, i-a coplesit si a pastrat obiectul.",al={"de ce sa-l ucid pe thogrun","tradarea lui thogrun","povestea sefului thogrun"}},{q="Unde se afla Camp Boff?",a="Camp Boff se afla la sud-est de Kargath.",al={"locatia taberei Boff","unde se afla Thogrun","gaseste-l pe seful Thogrun"}},{q="Ce este Semnul Pamantului?",a="Este o cheie necesara pentru a descuia inchisoarea dracilor din Lethlor Ravine.",al={"semnul pamantului","ce face semnul pamantului"}},{q="Ce dragoni sunt prizonieri in Lethlor Ravine?",a="Blacklash si Hematus, doi locotenenti ai lui Deathwing din vremea aliantei sale cu Horde in Second War.",al={"cine se afla in Lethlor Ravine","Blacklash si Hematus","locotenentii lui Deathwing"}}},fp="16,236,18.475.0,9.196.0,19.252.1,12.158.0,38.142.0,19.36.0,30.72.0,47.119.0"}
P.entries["quest:7826"] = {n="O donatie de lana"}
P.entries["quest:7828"] = {n="Stalking the Stalkers",s="Huntsman Markhor, din satul Revantusk din Hinterlands, spune ca lupii Silvermane sunt unul dintre cele mai mari pericole pentru vanatorii satului. Ti se cere sa intorci situatia in favoarea ta si sa vanezi vanatorii.",h="Huntsman Markhor, din satul Revantusk din Hinterlands, spune ca lupii Silvermane sunt unul dintre cele mai...",kw={"lupi din hinterlands","vanatorul markhor","revantusk","revantusk village","urlator silvermane","urmaritor silvermane","stalking the stalkers"},sec={{t="Lupi ascunsi",b="Markhor arata spre numerosii trolls pe care salbaticia din Hinterlands i-a rapus deja si considera ca lupii Silvermane se numara printre cele mai mari primejdii pentru vanatorii din Revantusk. Lupii asteapta ascunsi printre tufisuri si denivelarile terenului, apoi se napustesc cand le vine momentul. Markhor nu va lasa lucrurile asa si te indeamna sa gandesti ca un Silvermane si sa intorci vanatoarea impotriva vanatorilor, doborandu-i pe toti."},{t="Ce cere Markhor",b="Markhor vrea sa fie ucisi cincisprezece Silvermane Stalkers si cincisprezece Silvermane Howlers. Markhor adauga ca lupii pandesc prin salbaticia din Hinterlands."},{t="Multumirile lui Revantusk",b="Dupa ce treaba este gata, Markhor iti multumeste in numele celor din Revantusk pentru ceea ce le-ai oferit."}},faq={{q="Cine cere vanarea lupilor?",a="Huntsman Markhor, din satul Revantusk din Hinterlands.",al={"cine ofera stalking the stalkers","cel care da misiunea stalking the stalkers","misiunea lui markhor"}},{q="De ce sunt lupii Silvermane o amenintare atat de mare?",a="Markhor ii numara printre cele mai mari pericole pentru vanatorii din Revantusk: se ascund printre tufisuri si in formele terenului, apoi ataca atunci cand li se iveste ocazia, iar multi Troll au pierit deja in salbaticie.",al={"de ce ucidem lupii Silvermane","amenintarea lupilor Silvermane","de ce trebuie rariti lupii din Hinterlands"}},{q="Ce lupi trebuie rarii?",a="Cincisprezece Silvermane Stalkers si cincisprezece Silvermane Howlers.",al={"ce lupi sa omor","tinte din Stalking the Stalkers","tipuri de lupi din Hinterlands"}},{q="Unde se gasesc acesti lupi?",a="Markhor spune ca dau tarcoale prin salbaticia din Hinterlands.",al={"unde se afla lupii Silvermane","locatia vanatorului Silvermane","locatia urletului Silvermane"}}},fp="21,202,16.414.0,17.144.0,18.92.1,37.65.0,44.207.0,31.59.0,29.52.0"}
P.entries["quest:7829"] = {n="Hunt the Savages",s="Huntsman Markhor din satul Revantusk, in Hinterlands, considera ca owlbeastii salbatici sunt printre cele mai agresive creaturi din regiune si iti cere sa omori douazeci.",h="Huntsman Markhor din satul Revantusk, in Hinterlands, considera ca owlbeastii salbatici sunt printre cele mai...",kw={"hinterlands","hunt the savages","huntsman markhor","hiboare","revantusk","revantusk village","hiboara salbatica"},sec={{t="Gheare si ciocuri",b="Markhor descrie owlbeast-urile salbatice drept unele dintre cele mai indaratnice creaturi din Hinterlands si spune ca ghearele si ciocurile lor i-au costat pe cei din Revantusk multi razboinici de nadejde. Markhor vrea sa-i ucizi pe toti cei pe care ii vezi, pana cand nu mai poti suporta varsarea de sange; apoi, contributia ta va fi cantarita si judecata. Trebuie sa cada douazeci."},{t="Limpezirea mintii",b="Sfatul lui Markhor pentru vanatoare este sa-ti golesti mintea de gandurile necurate si sa te contopesti cu salbaticia. Owlbeastii se afla prin tinuturile salbatice din Hinterlands."},{t="Judecata lui Markhor",b="Dupa vanatoare, Markhor te numeste prieten demn al celor din Revantusk."}},faq={{q="Cine ofera aceasta vanatoare?",a="Huntsman Markhor, din satul Revantusk din Hinterlands.",al={"cine ofera Hunt the Savages","cine da misiunea Hunt the Savages","misiunea lui Huntsman Markhor"}},{q="De ce vrea Markhor sa fie ucisi owlbeast-ii salbatici?",a="Markhor ii numeste certareti si spune ca au rapus multi razboinici Revantusk cu ghearele si ciocurile lor.",al={"de ce sa ucid savage owlbeasts","motivul vanarii owlbeasts","de ce sa vanezi Hunt the Savages"}},{q="Unde pot fi gasite savage owlbeasts?",a="Markhor spune ca salasluiesc in tinuturile salbatice din Hinterlands.",al={"locatia owlbeast-ilor salbatici","unde sunt owlbeast-ii salbatici","owlbeast-i in Hinterlands"}},{q="Cate savage owlbeasts trebuie ucise?",a="Douazeci de owlbeasts feroce.",al={"cati owlbeast trebuie sa omor","cerinte pentru Hunt the Savages"}}},fp="16,172,15.335.0,17.143.0,18.67.1,21.65.0,50.109.0,40.49.0,40.24.0"}
P.entries["quest:783"] = {n="A Threat Within",s="Voluntarii raspund chemarii celor din Stormwind in Northshire Valley, unde apararea locala are nevoie de ajutor. La Northshire Abbey, Marshal McBride explica faptul ca fortele regatului sunt raspandite prin tinuturi indepartate, lasand garnizoanele cu prea putini oameni pentru a face fata pericolelor de acasa.",h="Voluntarii raspund chemarii celor din Stormwind in Northshire Valley, unde apararea locala are nevoie de...",kw={"o amenintare in interior","abatie","elwynn forest","marshal mcbride","northshire","recrutare","garzile din stormwind","voluntari"},ang={["faction:Alliance"]="Ca membru al Alliance, vezi cum angajamentele din tinuturi indepartate lasa chiar si meleagurile sale natale expuse problemelor din interior.",["race:Human"]="Ca aparator Human din Northshire, raspunsul la chemarea lui Marshal McBride este primul tau juramant oficial de a-ti proteja patria si Kingdom of Stormwind."},sec={{t="Un regat intins la limita",b="Northshire Valley oferea odinioara liniste pentru rugaciune, agricultura si studiu monahal. Acum este prima linie de aparare a Elwynn Forest impotriva tulburarilor din interiorul regatului. Trupele regulate din Stormwind lupta pe fronturi indepartate, lasand tinuturile centrale cu prea putini soldati. Cu putini gardieni in apropiere, Stormwind Guard trebuie sa apeleze la fiecare voluntar dispus sa ajunga la manastire."},{t="Chemarea maresalului",b="Marshal McBride conduce apararea din Northshire Valley de la Northshire Abbey, in timp ce presiunile cresc. Primejdii indepartate ameninta Alliance, iar banditii, daunatorii si lighioanele care ies din subteran profita de lipsa soldatilor din apropiere. Raspunzi chemarii de a sluji in vale, incepand cu terenurile din jurul manastirii, pe masura ce amenintarile se raspandesc prin Elwynn."}},faq={{q="Care este scopul acestei misiuni?",a="Marshal McBride cheama noii veniti in Northshire Valley sa se alature apararii. Intri in Northshire Abbey si te prezinti la el.",al={"misiunea threat within","ce este aceasta misiune","misiunea introductiva din northshire"}},{q="Cine este Marshal McBride?",a="Marshal McBride este ofiterul cu cel mai inalt grad din Stormwind Guard la Northshire Abbey. El coordoneaza apararea vaii si le incredinteaza recrutilor sarcini menite sa faca fata amenintarilor din tinuturile invecinate.",al={"marshal McBride","cine este McBride","comandantul abatiei"}},{q="De ce recruteaza Stormwind voluntari in loc sa trimita soldati regulati?",a="Fortele regulate ale Stormwind lupta in strainatate pentru a proteja Alliance. Cu garnizoanele din tinuturile centrale slabite, comandantii locali se bazeaza pe voluntari pentru a-si apara caminurile.",al={"de ce voluntari","unde sunt garzile","de ce Stormwind nu are destui oameni"}},{q="Ce amenintari afecteaza in prezent Northshire Valley?",a="Kobolds infesteaza minele si dealurile din apropiere, iar daunatorii bolnavi sau pradatori dau batai de cap podgoriilor. Banditii si proscrisii profita, de asemenea, de garnizoana slabita a vaii.",al={"amenintarile din vale","ce ataca Northshire","problemele din Northshire"}},{q="Unde duce aceasta sarcina mai departe?",a="Dupa ce ii raportezi lui Marshal McBride, esti trimis sa cureti dealurile de kobolds, sa-i ajuti pe fermierii si muncitorii locali si sa cercetezi prezenta tot mai mare a banditilor organizati.",al={"urmatoarea misiune","ce urmeaza dupa amenintarea din interior","continuarea misiunii lui McBride"}},{q="De ce este Northshire Abbey folosita ca post de comanda militar?",a="Northshire Abbey este un loc sfant de studiu si credinta, dar zidurile sale de piatra si pozitia centrala o transforma intr-o baza practica pentru vale. In timp ce autoritatea locala este pusa la incercare, Stormwind Guard si-a stabilit comandamentul in abatie.",al={"de ce sunt militari la abatie","militarii bisericii din Northshire","soldatii manastirii sfinte"}}},fx={["2039075b"]={q="De ce te trimite Deputy Willem la Marshal McBride?",a="Deputy Willem este stationat in afara Northshire Abbey pentru a-i evalua cat mai repede pe nou-venitii apti de lupta. Cu armata regatului suprasolicitata si mai multe crize apropiindu-se de granitele Northshire, are nevoie ca toti voluntarii capabili sa fie inrolati cum se cuvine. In loc sa dea el insusi misiuni, Willem te trimite direct la superiorul sau, Marshal McBride, pentru a primi instructiuni oficiale si a fi trimis acolo unde apararea vaii cedeaza cel mai mult.",al={"de ce sa vorbesc cu mcbride","motivul lui willem"}}},fp="15,247,24.347.0,18.360.0,34.131.0,23.173.0,75.173.0,54.175.0,37.171.0,62.226.0"}
P.entries["quest:7830"] = {n="Avenging the Fallen",s="Huntsman Markhor din Revantusk Village spune ca Wildhammer dreseaza gryphonii sa ucida trolli si vrea sa nimiceasca gryphonii batrani ai regiunii, Skylords. Trebuie sa ucizi un Razorbeak Skylord si sa-i aduci pana la el.",h="Huntsman Markhor din Revantusk Village spune ca Wildhammer dreseaza gryphonii sa ucida trolli si vrea sa...",kw={"razbunarea celor cazuti","gryphon","hinterlands","huntsman markhor","razorbeak skylord","revantusk village","pana de skylord","wildhammer"},sec={{t="Ucigand Skylords",b="Markhor, un vanator din Revantusk Village, in Hinterlands, este plin de amaraciune fiindca Wildhammer dreseaza gryphoni ca sa ucida Troll. Promite ca li se va face dreptate, dar mai intai vrea sa-i ataci pe cei mai batrani gryphoni din regiune, Skylords. Ucide unul si intoarce-te cu pana lui. Razorbeak Skylord este o rasa rara care tinde sa se tina departe de civilizatie, prin tinuturile salbatice din Hinterlands, iar Markhor o invinovateste pentru ca da nastere unor pui ucigasi."},{t="Pana examinata",b="Markhor cerceteaza pana si se intreaba cu voce tare cati Hunter a devorat bestia inainte de a-si gasi sfarsitul de mana ta."}},faq={{q="Cine ofera aceasta vanatoare?",a="Huntsman Markhor o ofera in Revantusk Village, in Hinterlands.",al={"cel care ofera misiunea","cine da avenging the fallen","locatia lui markhor"}},{q="De ce vrea Huntsman Markhor sa fie ucis un Skylord?",a="Markhor spune ca cei din Wildhammer dreseaza grifoni sa ucida Troll si vrea ca grifonii batrani din regiune, Skylords, sa fie starpiti. Spune ca Razorbeak Skylord este o rasa rara, ai carei pui cresc ucigasi.",al={"de ce sa-l ucid pe Razorbeak Skylord","de ce sa-l ucid pe Skylord","de ce sa vanezi gryphons"}},{q="Unde poate fi gasit un Razorbeak Skylord?",a="Markhor spune ca aceasta rasa rara traieste in tinuturile salbatice din Hinterlands.",al={"locatia lui Skylord","unde este Razorbeak Skylord","locatia penajului lui Skylord"}},{q="Ce trebuie adus inapoi lui Markhor?",a="Ucide un Razorbeak Skylord si intoarce-te la Markhor cu pana lui.",al={"de ce obiect am nevoie","obiectivul Avenging the Fallen","prada lui Skylord"}}},fp="19,229,20.422.0,18.119.1,21.67.0,47.206.0,39.67.0,37.62.0"}
P.entries["quest:7833"] = {s="Un troll Darkspear aduna donatii de lana. Saizeci de bucati de panza de lana vor ajuta la completarea colectiei cu sprijinul altora.",h="Un troll Darkspear aduna donatii de lana.",kw={"colectie","darkspear","donatie","magazine","troli","lana","panza de lana"},sec={{t="O colectie comuna",b="Trolli Darkspear colecteaza Wool Cloth, iar colectionarul poate accepta acum saizeci de piese ale tale. Magazinele lor au nevoie de acea suma de la tine; se asteapta ajutorul altora pentru a finaliza colectia."}},faq={{q="Ce se colecteaza?",a="Trolii Darkspear strang Panza de Lana.",al={"ce au nevoie","donatie de lana"}},{q="Cata panza de lana au nevoie de la mine?",a="Colectionarul iti cere saizeci de bucati de panza de lana.",al={"cata lana","60 panza"}},{q="De ce trolii aduna lana?",a="Colectia este menita sa-si completeze magazinele.",al={"de ce lana","Pentru ce"}},{q="Pot sa dau carpa acum?",a="Colectionarul poate accepta acum saizeci de bucati de panza de lana.",al={"unde dau lana","dona acum"}}},fp="18,138,19.196.0,24.47.0,41.59.0,35.50.0,25.61.0"}
P.entries["quest:7839"] = {n="Vilebranch Hooligans",s="Smith Slagtree, din Revantusk Village, spune ca Vilebranch troll-ii au invadat satul si i-au furat uneltele. Are unelte de rezerva, dar setul furat a fost un dar de la un gnome cu inima buna, care i-a salvat viata cand era un orc tanar, si vrea sa-l recupereze.",h="Smith Slagtree, din Revantusk Village, spune ca Vilebranch troll-ii au invadat satul si i-au furat uneltele.",kw={"agol'watha","hinterlands","markhor","revantusk village","shaol'watha","skulk rock","uneltele pierdute ale lui slagtree","smith slagtree","vilebranch"},sec={{t="Un dar de la un Gnome",b="Trollii Vilebranch au invadat Revantusk Village si au furat uneltele lui Smith Slagtree. Are unelte de rezerva, dar setul furat era un dar de la un gnome cu inima buna, care i-a salvat viata pe cand era un orc tanar. Iti spune ca uneltele inseamna totul pentru el si te roaga sa le recuperezi."},{t="Unde au fost vazute uneltele",b="Slagtree spune ca Markhor a raportat ca a vazut uneltele langa templele din Agol'watha si Shaol'watha, in nord-estul regiunii Hinterlands. Adauga ca ar trebui sa verifici si Skulk Rock si te avertizeaza ca trollii Vilebranch din regiune sunt nemilosi si criminali."}},faq={{q="De ce sunt uneltele furate atat de importante pentru Smith Slagtree?",a="Setul a fost un dar de la un Gnome cu inima buna, care i-a salvat viata lui Slagtree cand era un Orc tanar. Are unelte de rezerva, dar spune ca acestea inseamna totul pentru el.",al={"de ce ii pasa lui slagtree de uneltele sale","povestea uneltelor pierdute ale lui slagtree","de ce sunt uneltele lui slagtree speciale"}},{q="Cine a furat uneltele din Revantusk Village?",a="Trolls Vilebranch au invadat satul si au furat uneltele lui Smith Slagtree.",al={"cine a luat uneltele","cine a furat uneltele lui slagtrees"}},{q="Unde au fost duse uneltele lipsa?",a="Markhor i-a vazut langa templele din Agol'watha si Shaol'watha, in nord-estul Hinterlands. Slagtree spune, de asemenea, sa verifici Skulk Rock.",al={"unde sunt uneltele lui Slagtree","unde gasesc uneltele","locatia uneltelor lui Slagtree"}},{q="Cine a raportat ca a vazut uneltele dupa raid?",a="Markhor este cel care i-a adus lui Slagtree vestea despre locul unde au fost vazute uneltele.",al={"cine a vazut uneltele","cine a raportat furtul uneltelor"}}},fp="20,243,19.273.0,25.258.0,58.157.0,43.71.0,35.141.0,45.74.0"}
P.entries["quest:784"] = {n="Vanquish the Betrayers"}
P.entries["quest:7840"] = {n="Lard Lost His Lunch",s="Lard, din satul Revantusk din Hinterlands, este flamand si speriat. Un Vilebranch l-a lovit in timpul unui picnic privat, iar Lard a fugit fara pranz. Ti se cere sa-l aduci de pe o insula din nord.",h="Lard, din satul Revantusk din Hinterlands, este flamand si speriat.",kw={"hinterlands","insula","untura","pranz","picnic","satul revantusk","vilebranch"},sec={{t="Un picnic intrerupt",b="Lard facea un picnic intr-un loc secret cand un Vilebranch, urat si rautacios dupa cum il descrie Lard, l-a lovit cu o bata mare. Lard a fugit spre Revantusk si a lasat pranzul in urma. Acum ii este foame si se teme sa se intoarca."},{t="Insula din nord",b="Locul de picnic se afla pe o insula spre nord. Lard spera ca vei merge acolo, vei gasi pranzul si il vei aduce inapoi, avand grija la trollii Vilebranch."},{t="Multumirile lui Lard",b="Pranzul se dovedeste a fi o halca uriasa de carne. Lard o infuleca, iti multumeste si iti promite un cos special de picnic pentru ajutorul dat."}},faq={{q="Cine este Lard?",a="Un locuitor din Revantusk, in Hinterlands, flamand si speriat dupa ce un Vilebranch l-a lovit pe Lard cu o bata mare.",al={"lard hinterlands","cine este lard","lard revantusk"}},{q="Unde si-a pierdut Lard pranzul?",a="Intr-un loc de picnic ascuns, pe o insula din nord.",al={"unde este pranzul lui lard","locul de picnic al lui lard","locul secret al lui lard"}},{q="De ce si-a lasat Lard mancarea in urma?",a="Un Vilebranch l-a lovit pe Lard cu un bat mare in timpul picnicului, iar Lard a fugit inapoi la Revantusk fara pranz.",al={"de ce a fugit Lard","cine l-a atacat pe Lard"}},{q="La ce ar trebui sa fii atent pe insula?",a="Lard ii identifica pe Vilebranch Trolls drept pericolul de pe insula.",al={"Vilebranch pe insula","pericolele de pe insula Lards"}}},fp="19,213,20.211.0,20.153.0,13.136.1,12.114.0,30.50.0,35.107.0,44.61.0"}
P.entries["quest:7841"] = {n="Message to the Wildhammer",s="In Revantusk Village, in Hinterlands, Otho Moji'ko spune ca Wildhammer incheie intelegeri cu dusmanii troll-ilor, iar de data aceasta partenerii lor sunt high elves. Otho vrea sa fie trimis un mesaj catre Dwarves din Wildhammer, scris cu sangele high elves din Highvale, la Quel'Danil Lodge.",h="In Revantusk Village, in Hinterlands, Otho Moji'ko spune ca Wildhammer incheie intelegeri cu dusmanii...",kw={"highvale","hinterlands","message to the wildhammer","otho mojiko","quel'danil lodge","revantusk village","wildhammer"},sec={{t="Un mesaj scris cu sange",b="Wildhammer isi faureste noi aliante cu dusmanii trollilor, iar de data aceasta partenerii lor sunt high elves. Otho Moji'ko scuipa la gandul acesta. Le datoram dwarf-ilor un mesaj scris in sangele noilor lor prieteni: macelareste fiecare Highvale high elf pe care-l intalnesti si lasa trupurile drept avertisment. Alergatorii, cercetasii, tragatorii si rangerii Highvale se aduna la Quel'Danil Lodge, in nord-vestul Hinterlands."},{t="Vesti de la Revantusk Village",b="La intoarcerea ta, Otho declara ca Revantusk forjeaza si noi aliante si iti lauda munca."}},faq={{q="Cine ofera aceasta misiune?",a="Otho Moji'ko, care se afla in Revantusk Village.",al={"cine da message to the wildhammer","misiunea lui otho mojiko"}},{q="Unde se afla Highvale high elves?",a="Se aduna la Quel'Danil Lodge, in nord-vestul Hinterlands.",al={"locatia hanului quel danil","unde sunt highvale elves","unde gasesc cercetasi highvale"}},{q="De ce vrea Otho Moji'ko ca high elves sa fie atacati?",a="Otho spune ca cei din Wildhammer fac intelegeri cu dusmanii Troll, iar acum colaboreaza cu High Elf. Otho vrea sa le trimiti celor din Wildhammer un mesaj scris cu sangele High Elf.",al={"de ce sa ataci Quel'Danil","de ce sa omori High Elf in Hinterlands"}},{q="Care Highvale elves vrea Otho sa fie macelariti?",a="Highvale Outrunners, Scouts, Marksmen si Rangers de la Quel'Danil Lodge.",al={"care highvale elves","marcator highvale","ranger highvale"}}},fp="25,280,18.421.0,25.107.1,22.46.0,42.63.0,51.208.0,48.70.0"}
P.entries["quest:7842"] = {n="Another Message to the Wildhammer",s="Dupa primul mesaj, Otho Moji'ko din Revantusk Village spune ca Wildhammer si gryphonii lor sunt la fel de apropiati ca un troll si un tovaras. Dezgustator, dar lucrul acesta poate fi folosit impotriva lor. Otho vrea sa omori gryphonii din Hinterlands pentru penele lor.",h="Dupa primul mesaj, Otho Moji'ko din Revantusk Village spune ca Wildhammer si gryphonii lor sunt la fel de...",kw={"gryphon","Hinterlands","pana lunga si eleganta","otho moji'ko","revantusk village","wildhammer"},sec={{t="Un mesaj din pene",b="Dupa Highvale high elves, Otho Moji'ko mai are un mesaj de transmis. Se spune ca Wildhammer si grifonii lor sunt la fel de apropiati ca un troll si perechea sa, lucru care i se pare dezgustator lui Otho, dar si folositor. Ucide grifonii pe care-i intalnesti prin Hinterlands si aduna-le Penele Lungi si Elegante. Grifonii traiesc, dupa cum se stie, in toate regiunile de acolo. Din pene, Otho va alcatui mesajul final."},{t="Placerea lui Otho",b="Otho se asteapta ca ultimul mesaj sa-i sperie pe Wildhammer si sa-i faca sa renunte sau, dimpotriva, sa-i infurie foarte, foarte tare. Otho e incantat ca a mai ramas doar un pas pana cand Wildhammer vor intelege ca trollii nu pot fi infruntati fara urmari."}},faq={{q="Cine ofera aceasta misiune?",a="Otho Moji'ko, care se afla in Revantusk Village.",al={"cine da Another Message to the Wildhammer","cel care ofera misiunea Another Message","otho mojiko"}},{q="De ce vrea Otho Moji'ko pene de gryphon?",a="Otho spune ca Wildhammer si gryphonii lor sunt la fel de apropiati precum un Troll si perechea sa, si vrea sa foloseasca acest lucru impotriva lor. Penele vor fi incluse in mesajul final.",al={"de ce pene de grifon","de ce sa ucizi grifoni in hinterlands"}},{q="Unde pot fi gasiti gryphonii?",a="Se stie ca Gryphons traiesc in fiecare regiune din Hinterlands.",al={"locatiile gryphon din hinterlands","unde se afla gryphonii din hinterlands"}},{q="Ce a precedat acest mesaj?",a="Urmeaza dupa Message to the Wildhammer, in care Otho a pus Highvale high elves sa fie macelariti, ca avertisment pentru Dwarves.",al={"ce urmeaza inainte de Another Message to the Wildhammer","lantul Message to the Wildhammer"}}},fp="33,244,21.388.0,15.199.1,21.46.0,44.160.0,28.62.0,30.116.0"}
P.entries["quest:7843"] = {n="The Final Message to the Wildhammer",s="Otho Moji'ko iti da o sulita imbibata in sange si legata cu pene de gryphon. Trebuie sa o duci la Aerie Peak, in vestul Hinterlands, si sa o infigi in pamant langa fantana din inima orasului.",h="Otho Moji'ko iti da o sulita imbibata in sange si legata cu pene de gryphon.",kw={"aerie peak","pene de gryphon","hinterlands","otho moji'ko","revantusk village","sulita","wildhammer"},sec={{t="O sulita pentru Aerie Peak",b="Dupa Another Message to the Wildhammer, Otho Moji'ko iti da mesajul final: o sulita imbibata cu sange si legata cu pene de grifon. Du-o la Aerie Peak si infige-o chiar in centrul orasului, langa fantana, ca sa le arati piticilor ca trollii vorbesc serios. Otho spera sa te intorci teafar si te avertizeaza in legatura cu piticii Wildhammer furiosi si cu membrii turbulenti ai Alliance."},{t="Speranta lui Otho",b="Otho si-ar fi dorit sa vada fetele lui dwarves si se intreaba cu voce tare daca isi impacheteaza lucrurile si pleaca din oras. Otho iti promite mult mojo pentru treaba."}},faq={{q="Cine te trimite sa infigi sulita?",a="Otho Moji'ko, care se afla in Revantusk Village.",al={"cel care da misiunea","cine da misiunea","otho mojiko"}},{q="Unde trebuie infipta sulita?",a="Langa fantana din inima lui Aerie Peak, in vestul Hinterlands.",al={"locatia sulitei","unde sa asez sulita","fantana din Aerie Peak"}},{q="Din ce este alcatuit mesajul final?",a="O sulita imbibata in sange si impodobita cu pene de grifon.",al={"ce este sulita","sulita cu pene de gryphon","obiectul final message"}},{q="Ce a precedat aceasta in lantul de misiuni?",a="Urmeaza dupa Another Message to the Wildhammer, in care Otho a cerut pene de gryphon pentru a alcatui acest ultim mesaj.",al={"misiunea precedenta","cerinte preliminare","lantul de mesaje Wildhammer"}}},fp="35,215,22.361.0,11.167.1,33.46.0,32.75.0,34.56.0,35.115.0"}
P.entries["quest:7844"] = {n="Cannibalistic Cousins",s="Mystic Yayo'jin din Revantusk Village ii numeste pe trollii Vilebranch niste degenerati care ii prada pe alti trolli si humanoizi. Cum Zul'jin nu este acolo sa-i nimiceasca, iti cere sa le distrugi unitatile Scalpers si Soothsayers de langa templele din nord-nord-est.",h="Mystic Yayo'jin din Revantusk Village ii numeste pe trollii Vilebranch niste degenerati care ii prada pe alti...",kw={"agol'watha","cannibalistic cousins","misticul yayo'jin","revantusk village","jupuitor","shaol'watha","profet","vilebranch","zul'jin"},sec={{t="Trei triburi, un singur tinut",b="In Hinterlands traiesc trei triburi de troll, iar Mystic Yayo'jin spune ca, in afara faptului ca sunt troll si locuiesc pe acelasi meleag, au putine lucruri in comun. Ea ii descrie pe Vilebranch, pe buna dreptate numiti astfel, drept o adunatura depravata care vaneaza alti troll si umanoizi. Zul'jin i-ar fi nimicit fara efort, dar Zul'jin nu este aici, iar Revantusk trebuie sa se descurce singuri."},{t="Unde se aduna Vilebranch",b="Yayo'jin iti cere sa-i distrugi pe Vilebranch Scalpers si Soothsayers, care pot fi gasiti in jurul templelor Shaol'watha si Agol'watha, in nordul si nord-estul regiunii Hinterlands."},{t="Laudele lui Yayo'jin",b="La intoarcere, Yayo'jin declara ca nici Zul'jin n-ar fi putut face mai bine."}},faq={{q="Cine ofera aceasta misiune?",a="Mystic Yayo'jin, care se afla in Revantusk Village.",al={"cel care da misiunea cannibalistic cousins","cine ofera cannibalistic cousins","mystic yayojin"}},{q="De ce vrea Yayo'jin ca Vilebranch sa fie distrusi?",a="Ea ii numeste pe Vilebranch o sleahta depradata, care se napusteste asupra altor trolli si umanoizi, si spune ca tie iti revine sa distrugi mizeria din regiune.",al={"de ce se lupta revantusk cu vilebranch","canibalismul vilebranch","conflictul dintre revantusk si vilebranch"}},{q="Unde pot fi gasiti trollii Vilebranch?",a="In jurul templelor Shaol'watha si Agol'watha, in nordul-nord-estul tinutului Hinterlands.",al={"locatia shaolwatha","locatia agolwatha","unde sunt ghicitorii vilebranch"}},{q="Care dintre Vilebranch vrea Yayo'jin sa fie eliminat?",a="Vilebranch Scalpers si Vilebranch Soothsayers.",al={"tinte pentru Cannibalistic Cousins","pe cine ucid pentru Cannibalistic Cousins"}},{q="Unde este Zul'jin?",a="Nu, deocamdata nu in Hinterlands. Yayo'jin spune ca, daca Zul'jin ar fi acolo, i-ar nimici cu usurinta pe Vilebranch, dar el nu este, asa ca Revantusk sunt nevoiti sa se descurce singuri.",al={"este zuljin aici","unde este zuljin in Hinterlands","situatia lui zul'jin"}}},fp="21,258,22.361.0,27.176.0,17.79.1,22.49.0,48.137.0,41.86.0,46.47.0,17.180.0"}
P.entries["quest:7845"] = {n="Kidnapped Elder Torntusk!",s="Primal Torntusk din Revantusk Village spune ca salbaticii Vilebranch i-au rapit perechea, Elder Torntusk, intr-un raid indraznet, in toiul noptii. Spionii spun ca este in viata si tinut prizonier in varful Jintha'alor, iar ea iti cere sa-l salvezi.",h="Primal Torntusk din Revantusk Village spune ca salbaticii Vilebranch i-au rapit perechea, Elder Torntusk...",kw={"elder torntusk","hakkar","hexx","hinterlands","jintha'alor","primal torntusk","revantusk","torntusk","vilebranch"},sec={{t="Un raid nocturn",b="Salbaticii Vilebranch au atacat Revantusk Village la miezul noptii si l-au rapit pe Elder Torntusk, perechea lui Primal Torntusk. Spionii ei spun ca e inca in viata, prizonier in varful Jintha'alor, capitala Vilebranch din sudul Hinterlands. Primal Torntusk se teme ca satul n-ar putea indura sa-l piarda."},{t="Zeul Blood fara chip",b="Se spune ca Vile Priestess Hexx il pregateste pe prizonier pentru sacrificiul adus lui Hakkar, zeul sangeros fara chip."},{t="Dupa ce ajungi la el",b="Cand ajungi la Elder, ti se spune sa te grabesti, fiindca paznicii trebuie sa fi aflat deja de sosirea ta."}},faq={{q="Cine l-a luat pe Elder Torntusk?",a="Vilebranch savages l-au rapit intr-un indraznet raid de la miezul noptii asupra Revantusk Village.",al={"cine l-a rapit pe elder torntusk","cine l-a luat pe torntusk","rapitorii lui torntusk"}},{q="Unde este tinut captiv Elder Torntusk?",a="Spionii ei spun ca este prizonier in varful Jintha'alor, capitala celor din Vilebranch, in sudul Hinterlands.",al={"locatia lui Elder Torntusk","unde este Elder Torntusk","unde este captivul Torntusk"}},{q="Ce soarta il asteapta pe Elder Torntusk in varful Jintha'alor?",a="Se spune ca Vile Priestess Hexx il pregateste pentru sacrificiul adus lui Hakkar, zeul sangeros fara chip.",al={"de ce a fost capturat Torntusk","ce vor Vilebranch de la Torntusk","sacrificiul lui Hexx pentru Torntusk"}},{q="Cine este Primal Torntusk?",a="Primal Torntusk este perechea lui Elder Torntusk si iti cere sa-l salvezi.",al={"cine este primal torntusk","perechea lui primal torntusk"}}},fp="25,211,15.283.0,22.101.0,18.100.1,24.73.0,35.103.0,49.93.0,23.76.0"}
P.entries["quest:7846"] = {n="Recover the Key!",s="Elder Torntusk este tinut in lanturi la Jintha'alor. Spune ca Hitah'ya the Keeper are cheia catusei sale si se afla in pestera din apropiere, bine pazita, si iti cere s-o ucizi si sa aduci cheia inapoi.",h="Elder Torntusk este tinut in lanturi la Jintha'alor.",kw={"elder torntusk","hinterlands","hitah'ya the keeper","jintha'alor","recupereaza cheia","revantusk","cheia catusei"},sec={{t="Pestera paznicului",b="Dupa Kidnapped Elder Torntusk!, il gasesti pe Elder Torntusk legat in lanturi, la Jintha'alor. Hitah'ya the Keeper detine cheia catuselor si se afla in pestera din apropiere, bine pazita. Elder Torntusk iti cere s-o ucizi si sa iei cheia, ca sa-i poti desface lanturile; numai atunci se va putea intoarce acasa."},{t="Multumirile lui Elder Torntusk",b="Cu cheia in mana, Elder Torntusk se ridica in picioare. Iti multumeste si spune ca revantusk vor afla despre faptele tale."}},faq={{q="Cine detine cheia catuselui lui Elder Torntusk?",a="Hitah'ya the Keeper detine cheia. Elder Torntusk spune ca se afla in pestera din apropiere si ca este bine pazita.",al={"cine are cheia","hitahya the keeper","unde se afla cheia catusei"}},{q="Unde este tinut captiv Elder Torntusk?",a="Elder Torntusk este tinut captiv in Jintha'alor.",al={"unde este elder torntusk","locatia lui torntusk","torntusk din jintha'alor"}},{q="De ce are Elder Torntusk nevoie de cheie?",a="Cheia desface catusele care-l tin legat. Abia atunci, spune el, va fi liber sa se intoarca acasa.",al={"de ce cheia de catuse","la ce foloseste cheia"}}},fp="16,194,17.293.0,23.114.1,47.101.0,29.38.0,37.95.0"}
P.entries["quest:7847"] = {n="Return to Primal Torntusk",s="Elder Torntusk iti cere sa te intorci la perechea sa, Primal Torntusk, in Revantusk Village, si sa-i spui ca vine acasa.",h="Elder Torntusk iti cere sa te intorci la perechea sa, Primal Torntusk, in Revantusk Village, si sa-i spui ca...",kw={"elder torntusk","Hinterlands","jintha'alor","primal torntusk","revantusk","revantusk village"},sec={{t="Vesti pentru perechea lui",b="Elder Torntusk este eliberat din legaturi si iti cere sa te intorci la Revantusk Village. Acolo trebuie sa-i spui perechii sale, Primal Torntusk, ca vine acasa."},{t="Satul este recunoscator",b="Primal Torntusk spune ca ai fost de mare ajutor pentru Revantusk si ca satul iti datoreaza o recunostinta profunda."}},faq={{q="Cine te trimite in aceasta calatorie?",a="Elder Torntusk iti cere sa-i duci perechii sale vestea ca a fost salvat.",al={"cine incepe return to primal torntusk","cel care da misiunea elder torntusk"}},{q="Unde se afla Primal Torntusk?",a="Primal Torntusk se afla in Revantusk Village, in Hinterlands.",al={"unde este primal torntusk","locatia primal torntusk","unde predau return to primal torntusk"}},{q="Ce ar trebui sa-i spun lui Primal Torntusk?",a="Faptul ca Elder Torntusk se intoarce acasa.",al={"ce sa-i spui lui Primal Torntusk","mesaj pentru Torntusk"}},{q="Ce a precedat aceasta calatorie?",a="Urmeaza dupa Recover the Key!, dupa efortul anterior, inceput cu Kidnapped Elder Torntusk!",al={"misiunea anterioara","lantul de misiuni primal torntusk"}}},fp="25,121,17.160.0,23.112.1,30.68.0,33.59.0,43.35.0,30.93.0"}
P.entries["quest:7849"] = {n="Separation Anxiety",s="Huntsman Markhor din Revantusk Village si-a pierdut fratele geaman, Malkhor, rapit de Vilebranch in acelasi raid in care a fost rapita si perechea lui Torntusk. Malkhor a avut parte de un sfarsit rapid si brutal, iar ramasitele lui au fost date de mancare mazgelor si lupilor Vilebranch. Markhor spune ca viata fratelui sau nu mai poate fi salvata, dar sufletul lui inca poate fi izbavit, si iti cere sa recuperezi ramasitele.",h="Huntsman Markhor din Revantusk Village si-a pierdut fratele geaman, Malkhor, rapit de Vilebranch in acelasi...",kw={"oase","hinterlands","jintha'alor","malkhor","markhor","revantusk","craniu","vilebranch","yayo'jin"},sec={{t="Pierderea unui geaman",b="Markhor spune ca multi din sat si-au pierdut oamenii dragi in salbaticie, iar pierderea lui este Malkhor, geamanul sau. Vilebranch l-au luat pe Malkhor in timpul raidului in care au luat perechea lui Torntusk. Malkhor nu era menit sa traiasca, iar rapitorii lui i-au curmat viata cu repeziciune si cruzime."},{t="Unde zac ramasitele",b="Vilebranch au dat ramasitele lui Malkhor mazgelor si lupilor lor. O groapa de gunoi plina de mazge si o vizuina de lupi se afla amandoua langa varful templului din Jintha'alor. Oasele lui zac in mijlocul unei gropi cu mal, aproape de nivelul superior, iar craniul se afla chiar la nivelul cel mai de sus. Markhor vrea sa duca ramasitele la Yayo'jin, care le va pregati pentru o inmormantare cum se cuvine."}},faq={{q="Cine a fost Huntsman Malkhor?",a="Malkhor era fratele geaman al vanatorului Markhor. Vilebranch l-au luat in timpul raidului in care au rapit-o si pe perechea lui Torntusk, apoi l-au omorat rapid si cu cruzime.",al={"cine este malkhor","fratele lui markhor","povestea lui malkhor"}},{q="Unde au fost duse ramasitele lui Malkhor?",a="Vilebranch i-au dat ramasitele sale de mancare slugilor si lupilor lor. Craniul lui se afla pe terasa superioara din Jintha'alor, iar oasele zac intr-o groapa de namol de langa acea terasa.",al={"unde sunt oasele","unde este craniul lui malkhor","ramasitele din jintha'alor"}},{q="Cine il va pregati pe Malkhor pentru inmormantare?",a="Markhor spune ca va duce ramasitele la Yayo'jin, care le va pregati pentru o inmormantare cum se cuvine.",al={"inmormantare pentru malkhor","cine este yayojin","yayo'jin"}},{q="De ce are nevoie Markhor ca oasele sa fie returnate?",a="Markhor nu-i mai poate salva viata fratelui sau, dar spune ca sufletul acestuia mai poate fi salvat. Pentru asta, vrea sa-i recuperezi ramasitele.",al={"de ce sa recuperezi ramasitele","salveaza sufletul lui malkhor","salvarea sufletului sau"}}},fp="18,361,13.263.0,21.369.0,25.159.0,35.158.0,36.93.0,41.141.0"}
P.entries["quest:7850"] = {n="Dark Vessels",s="Primal Torntusk din Revantusk Village spune ca Vilebranch lupta cu o ferocitate supranaturala, rodul vrajilor magice josnice ale lui Vile Priestess Hexx. Prin Jintha'alor se afla vase intunecate cu sange pangarit, din care radiaza o magie respingatoare, proprie zeului fara chip al sangelui. Torntusk iti cere sa le furi si sa i le aduci, pentru ca pangarirea sa poata fi inlaturata.",h="Primal Torntusk din Revantusk Village spune ca Vilebranch lupta cu o ferocitate supranaturala, rodul vrajilor...",kw={"zeul sangelui","vase intunecate","jintha'alor","primal torntusk","revantusk village","sange corupt","vile priestess hexx","vilebranch"},sec={{t="Furia Vilebranch",b="Oriunde ai merge in Jintha'alor, vei gasi vase cu sange intinat. Ele radiaza puterea intunecata a zeului sangelui fara chip, care ii intareste pe Vilebranch si ii impinge spre nebunie. Torntusk crede ca, daca vasele ar fi luate si intinarea indepartata, influenta zeului sangelui asupra lor ar slabi."},{t="Dupa intoarcerea vaselor",b="Odata ce ai vasele asupra ta, energia intunecata care ii constrange pe cei din Vilebranch se risipeste, dar numai pentru o vreme. Torntusk iti aminteste sa ramai mereu vigilent fata de rau, fiindca o preoteasa cazuta este in curand inlocuita de alta."}},faq={{q="Cine da misiunea Dark Vessels?",a="Primal Torntusk ti-l da in Revantusk Village, in Hinterlands.",al={"cine da dark vessels","cel care ofera misiunea dark vessels"}},{q="Unde se afla vasele contaminate?",a="Vase intunecate cu sange corupt pot fi gasite pretutindeni in Jintha'alor, in Hinterlands.",al={"unde sunt dark vessels","locatia vessels of tainted blood","gaseste sangele corupt"}},{q="De ce sunt atat de feroce troll-ii Vilebranch?",a="Primal Torntusk da vina pe impletiturile magice spurcate ale Vile Priestess Hexx. Vasele cu sange intinat poarta si puterea zeului sangeros fara chip, care ii intareste pe Vilebranch si ii impinge spre nebunie.",al={"de ce sunt vilebranch nebuni","nebunia vilebranch","ferocitatea vilebranch"}},{q="Ce planuieste Primal Torntusk sa faca cu vasele?",a="Torntusk planuieste sa le curete de intinare, pentru a slabi stransoarea Dumnezeului sangelui fara chip asupra clanului Vilebranch.",al={"de ce sa colectezi vasele","ce se intampla cu vasele de sange"}}},fp="12,353,19.303.0,24.210.1,33.66.0,38.85.0,43.203.0,54.113.0"}
P.entries["quest:786"] = {n="Thwarting Kolkar Aggression"}
P.entries["quest:7861"] = {n="Wanted: Vile Priestess Hexx and Her Minions",s="Primal Torntusk a poruncit ca Vile Priestess Hexx si slugile ei sa fie aduse in fata justitiei, iar pe oricine o ucide pe preoteasa si pe garda ei de elita Aman'zasi il asteapta un premiu maret. Ii vei gasi in varful Jintha'alor, in Hinterlands.",h="Primal Torntusk a poruncit ca Vile Priestess Hexx si slugile ei sa fie aduse in fata justitiei, iar pe...",kw={"Aman'zasi","Hexx","Hinterlands","Jintha'Alor","Primal Torntusk","satul Revantusk","Vile Priestess Hexx","Vilebranch"},sec={{t="O lovitura la Jintha'alor",b="Primal Torntusk a dat ordin ca Vile Priestess Hexx si slujitorii ei sa fie adusi in fata justitiei. Tintele sunt preoteasa insasi si gardienii Aman'zasi, elita ei. Se afla in varful Jintha'alor, in Hinterlands. Dupa ce sunt ucisi, te intorci cu raportul la Torntusk, in Revantusk Village."}},faq={{q="Cine a pus recompensa pe Vile Priestess Hexx?",a="Chemarea la arme a fost lansata la ordinul lui Primal Torntusk, iar celui care o ucide pe preoteasa si pe garda ei i se ofera un premiu mare.",al={"cine il vrea mort pe hexx","cine a oferit recompensa","cine da misiunea Priestess Hexx"}},{q="Unde pot fi gasite Vile Priestess Hexx si garzile ei?",a="Se gasesc in varful Jintha'alor, in Hinterlands.",al={"unde este hexx","locatia Vile Priestess Hexx","locatia garzilor amanzasi"}},{q="Cine trebuie ucis pentru a indeplini contractul de vanatoare?",a="Preoteasa Hexx insasi, impreuna cu garda sa de elita Aman'zasi a Vilebranch.",al={"obiectivele recompensei lui hexx","pe cine sa omori pentru hexx"}},{q="Unde se preda recompensa?",a="Raporteaza-te la Primal Torntusk din Revantusk Village dupa ce preoteasa si garda ei sunt ucise.",al={"unde predau recompensa pentru Hexx","locatia lui Primal Torntusk"}}},fp="43,226,23.300.0,46.131.0,54.51.0,40.83.0,30.90.0"}
P.entries["quest:7862"] = {n="Job Opening: Guard Captain of Revantusk Village",s="Guard Captain Malkhor a disparut, iar garda din Revantusk are nevoie de un nou capitan. Oricine doreste postul trebuie sa-i nimiceasca pe Vilebranch Berserkers, Shadow Hunters, Blood Drinkers si Soul Eaters, apoi sa duca o cerere la Primal Torntusk, in Hinterlands.",h="Guard Captain Malkhor a disparut, iar garda din Revantusk are nevoie de un nou capitan.",kw={"berserker","blood drinker","capitan al garzii","malkhor","revantusk","vanator al umbrelor","devorator de suflete","torntusk","vilebranch"},sec={{t="Un post vacant",b="Un apel la arme anunta ca Guard Captain Malkhor a fost pierdut, asa ca Revantusk a ramas din nou fara capitan al garzii. Oricine vrea sa o conduca este invitat sa indeplineasca sarcinile din anunt si apoi sa-i trimita o cerere lui Primal Torntusk."},{t="Dovedirea valorii",b="Un candidat trebuie sa extermine patru tipuri de Vilebranch: Berserkers, Shadow Hunters, Blood Drinkers si Soul Eaters. Dupa ce termina, trebuie sa se intoarca la Primal Torntusk din Revantusk Village."}},faq={{q="De ce este vacant postul de capitan al garzii?",a="Guard Captain Malkhor a disparut, iar anuntul spune ca functia de capitan al Revantusk este din nou vacanta.",al={"de ce este deschisa functia de capitan al garzii","ce s-a intamplat cu Malkhor","cine a fost capitanul anterior"}},{q="Cine primeste cererea dupa ce dusmanii sunt ucisi?",a="Cererile se trimit lui Primal Torntusk, in Revantusk Village.",al={"cui predau asta","unde depun cererea","cine evalueaza candidatii"}},{q="Ce dusmani trebuie invinsi pentru a fi acceptat?",a="Candidatii trebuie sa extermine Vilebranch Berserkers, Shadow Hunters, Blood Drinkers si Soul Eaters.",al={"pe care Vilebranch sa-l ucid","tinte pentru Job Opening","pe cine sa ucid pentru capitanul garzii"}}},fp="47,255,13.235.0,13.183.0,42.95.0,56.57.0,42.98.0"}
P.entries["quest:787"] = {n="The New Horde"}
P.entries["quest:789"] = {n="Sting of the Scorpid",s="Sting of the Scorpid este o prima incercare pe care Gornek le-o incredinteaza recrutilor Horde de la Den, in Valley of Trials. Novicii trebuie sa vaneze lucratori scorpid veninosi la nord-vest de tabara si sa aduca inapoi zece cozi, pentru a-si dovedi pregatirea de lupta. Sarcina ii invata sa supravietuiasca pericolelor de pe campul de lupta si sa nu subestimeze nici cei mai mici adversari.",h="Sting of the Scorpid este o prima incercare pe care Gornek le-o incredinteaza recrutilor Horde de la Den, in...",kw={"antidot","Durotar","Gornek","scorpida","lucrator scorpida","Sting of the Scorpid","The Den","Valley of Trials","venin"},ang={["class:Warrior"]="Gornek trateaza vanatoarea scorpizilor ca pe o lectie fundamentala de hotarare martiala, amintindu-le razboinicilor ca loviturile decisive strapung carapacele rezistente si ca aroganta fata de dusmani mai mici aduce infrangerea.",["race:Orc"]="Pentru orcii tineri care ajung la varsta maturitatii in Valley of Trials, vanarea scorpizilor veninosi este o proba esentiala de rezistenta si vigilenta pe campul de lupta, supravegheata de Gornek.",["race:Troll"]="Trollii Darkspear care se antreneaza alaturi de Horde in Valley of Trials trebuie sa-si dovedeasca si iscusinta impotriva scorpizilor locali inainte de a se aventura mai adanc in Durotar."},sec={{t="Incercarea intepatorului",b="In canionul parjolit de soare din Valley of Trials, Gornek ii pune la incercare pe recruti novici ai Horde, trimitandu-i impotriva faunei locale. Scorpidii veninosi care cutreiera pamantul arid de la nord-vest de Den i-au umilit deopotriva pe razboinicii incercati si pe initiatii neindemanatici. Pentru a-si dovedi priceperea in lupta, tinerii campioni trebuie sa se aventureze printre stanci, sa ucida lucratori scorpid si sa se intoarca cu zece cozi taiate, ca dovada a iscusintei lor."},{t="Venin si vigilenta",b="Desi sunt mortali, acesti pradatori veninosi ofera totodata singura salvare initiatilor raniti. The Den pastreaza rezerve de antidot preparat direct din venin de scorpid extras, pentru a-i trata pe novicii doborati. Dincolo de supravietuirea in fata veninului, Gornek subliniaza un adevar tactic fundamental: in haosul luptei, aroganta este fatala, iar chiar si cel mai neinsemnat dusman poarta suficient venin ucigator ca sa doboare un razboinic puternic."}},faq={{q="Cine ofera misiunea Sting of the Scorpid?",a="Gornek, maestrul de arme care supravegheaza pregatirea incepatorilor de la Den, din Valley of Trials, le incredinteaza aceasta incercare tinerilor razboinici si aventurieri.",al={"cine ofera Sting of the Scorpid","cel care ofera misiunea cu scorpizi","misiunea lui Gornek"}},{q="Unde se afla scorpizii?",a="Lucratorii scorpid traiesc in numar mare chiar la nord-vest de Den, in Valley of Trials, cutreierand terenul arid al canionului rosu.",al={"unde gasesti scorpidi","locatia scorpizilor","scorpizi in Valley of Trials"}},{q="Ce ii cere Gornek sa aduci de la vanatoare?",a="Gornek cere zece cozi de lucrator scorpid drept dovada concreta ca un recrut s-a infruntat cu fiarele veninoase si a iesit victorios din lupta.",al={"ce lasa scorpizii","obiect de misiune de la scorpid","cozi de scorpid"}},{q="Cum se prepara antidotul pentru veninul de scorpid?",a="Antidotul pentru intepaturile scorpizilor este preparat direct din veninul extras din acul acestor creaturi. The Den pastreaza provizii suficiente pentru a-i trata pe novicii care isi subestimeaza prada.",al={"leac pentru veninul de scorpid","istoricul antidotului","cum se prepara antidotul pentru scorpid"}},{q="Ce lectie vrea Gornek sa invete recrutii?",a="Gornek foloseste vanatoarea pentru a-i invata pe luptatorii incepatori ca orice adversar, mare sau mic, poate fi letal. Increderea exagerata intr-o lupta cu creaturi aparent neinsemnate se poate dovedi rapid fatala.",al={"lectia lui Gornek","de ce sa vanezi scorpizi","scopul incercarii scorpizilor"}},{q="Ofera Gornek si alte lectii dupa aceasta vanatoare?",a="Dupa ce predai cozile, Gornek declara ca nu mai are nimic sa te invete la Den, trimitandu-te mai departe prin Durotar pentru a-ti continua slujirea Horde.",al={"ce urmeaza dupa Sting of the Scorpid","urmatoarea misiune a lui Gornek","il mai invata Gornek ceva"}}},fp="20,352,20.421.0,19.399.0,33.141.0,31.130.0,39.136.0,46.187.0,47.192.0,51.159.0"}
P.entries["quest:79"] = {n="The Legend of Stalvan",s="Aceasta misiune marcheaza clipa in care zvonurile disparate despre Stalvan Mistmantle devin dovezi incontestabile ale unei crime brutale. Tavernkeep Smitts iti da pagini de jurnal noroioase, ascunse de multa vreme, si-l indruma pe investigator direct la comandanta Night Watch, Althea Ebonlocke.",h="Aceasta misiune marcheaza clipa in care zvonurile disparate despre Stalvan Mistmantle devin dovezi...",kw={"Darkshire","Duskwood","Ebonlocke","investigatie","Mistmantle","jurnal murdar","Night Watch","Smitts","Stalvan"},ang={["class:Paladin"]="A scoate la lumina crime ingropate de mult implineste chemarea unui paladin si cere sa se faca dreptate pentru vietile nevinovate luate cu violenta in umbra Duskwood.",["class:Rogue"]="Reconstituirea scrisului de mana din mostre gasite prin taverne si cufere prafuite reflecta munca de detectiv rabdatoare, adesea necesara pentru a da de urma unei prazi greu de gasit.",["faction:Alliance"]="Ancheta arata ca teritoriile sudice trebuie sa se bizuie pe eroi ratacitori ai Alliance pentru a infaptui dreptatea, in lipsa totala a sprijinului oficial din partea Stormwind."},sec={{t="O descoperire la Darkshire",b="Vreme de ani intregi, soarta cumplita a unei familii de nobili aflati in vizita a ramas o tragedie nerezolvata in Duskwood. Tavernkeep Smitts si Marshal Haggard, pe atunci conducator al Stormwind Guard, au anchetat initial locul masacrului si au descoperit cateva pagini rupte, pline de noroi, dintr-un jurnal. Fara mostre de scris sau documente care sa le confirme, notitele au ramas neelucidate si nu au putut sa-l incrimineze oficial pe pustnicul despre care se zvonea ca traia in salbaticie. Dovezile adunate din Elwynn, Westfall si Duskwood leaga in cele din urma scrisul de Stalvan Mistmantle, transformand barfa din oras intr-un caz de crima rezolvat fara urma de indoiala."},{t="A duce problema la garda",b="Darkshire traieste sub asediul constant al strigoilor, al fiarelor salbatice si al unor orori si mai cumplite, care pandesc in bezna padurii. Comandantul Althea Ebonlocke are prea putina rabdare pentru povesti inflorite sau banuieli nefondate, cand supravietuirea orasului ei atarna de un fir de ata. Predarea acestor pagini pline de noroi face legatura dintre istoria rece si justitia militara imediata. Pusa in fata dovezilor concrete ale unui masacru petrecut pe pamantul din Duskwood, Night Watch este in cele din urma nevoita sa-l recunoasca pe Stalvan Mistmantle nu doar ca pe un pustnic excentric sau o poveste cu fantome, ci ca pe un fugar periculos care trebuie sa-si primeasca pedeapsa."}},faq={{q="Ce dovezi avea Tavernkeep Smitts de la bun inceput?",a="Cu ani in urma, Smitts i s-a alaturat lui Haggard pentru a investiga masacrarea unor nobili aflati in vizita. Au recuperat de la fata locului pagini rupte si pline de noroi dintr-un jurnal, dar nu aveau mostre de scris de comparat pentru a dovedi ca Stalvan Mistmantle era autorul... pana acum.",al={"paginile jurnalului lui smitts","paginile ude ale jurnalului","ce a gasit smitts"}},{q="De ce nu i-a raportat Smitts mai devreme acest lucru comandantului Ebonlocke?",a="Fara dovezi care sa lege scrisul de pe paginile pline de noroi de tutorele retras, Smitts si Haggard aveau doar fragmente de dovezi circumstantiale. Daca i-ar fi prezentat comandantului Ebonlocke zvonuri neconfirmate, acesta le-ar fi respins, considerandu-le o risipa inutila a timpului deja limitat al Night Watch.",al={"de ce sa astepti atat","de ce sa pastrezi paginile secrete","de ce nu i-a spus Smitts garzii"}},{q="Cine este Commander Althea Ebonlocke?",a="Commander Althea Ebonlocke este conducatoarea Night Watch, militia oraseneasca greu incercata, insarcinata cu paza Darkshire si patrularea drumurilor din Duskwood impotriva strigoilor si a pradatorilor padurii.",al={"cine este ebonlocke","rolul lui althea ebonlocke","comandantul din darkshire"}},{q="Ce masacru a avut loc in Duskwood?",a="Cu cativa ani in urma, o familie nobiliara in vizita a fost macelarita in Duskwood. Desi zvonurile il indicau pe fostul lor tutore, Stalvan Mistmantle, anchetatorilor locali le-au lipsit la inceput dovezile incontestabile necesare pentru a-l acuza.",al={"ce masacru","macelarirea nobililor","cine a fost ucis"}},{q="Unde se incadreaza acest pas in cadrul anchetei generale?",a="Aceasta etapa reprezinta trecerea de la ancheta privata la justitia oficiala. Dupa ce scotocesti registre, dosare scolare si lazi de familie in trei tinuturi, predai dovezile adunate autoritatilor locale, care vor sanctiona luarea de masuri impotriva lui Stalvan.",al={"etapa din sirul de misiuni Stalvan","cat de departe sunt","este aceasta ultima misiune"}},{q="De ce Night Watch este atat de reticenta sa investigheze crimele vechi?",a="Darkshire se confrunta zilnic cu pericolul disparitiei, din cauza monstruozitatilor ratacitoare, a haitelor de worgen si a paianjenilor. Comandantul Ebonlocke trebuie sa-si concentreze toti strajerii disponibili asupra supravietuirii, asa ca are nevoie de dovezi incontestabile inainte sa aloce personal investigarii unor cazuri vechi.",al={"de ce este Ebonlocke ocupat","prioritatile apararii din Darkshire","prioritatile Night Watch"}}},fx={["3928db26"]={q="De ce vrea Tavernkeep Smitts sa vorbesti cu Commander Ebonlocke?",a="Smitts a urmarit in tacere legenda lui Stalvan ani la rand, inca de cand nobilii aflati in vizita au fost macelariti in afara Darkshire. Cand el si Haggard au cercetat pe atunci locul macabru, au gasit pagini noroioase dintr-un jurnal, dar nu aveau mostre de scris de mana cu care sa le lege de pustnicul din padure. Acum ca investigatia ta a scos la iveala mostre care dovedesc ca Stalvan le-a scris, Smitts are, in sfarsit, dovezi incontestabile despre identitatea ucigasului. Vrea sa dezvalui adevarul numaidecat, pentru ca aparatorii orasului sa-l poata infrunta oficial pe criminal.",al={"de ce te trimite Smitts la Ebonlocke","motivul lui Tavernkeep Smitts","de ce sa-i spuna lui Ebonlocke acum"}},["225fd2ad"]={q="De ce te trimite Smitts pe tine in loc sa raporteze el insusi acest lucru?",a="Smitts tine barul de la Scarlet Raven Tavern si a pastrat doar cateva fragmente razlete din macelul initial. Tu ai fost cel care a urmarit cu adevarat pista prin Elwynn, Westfall si Duskwood, recuperand scrisorile si jurnalele care leaga scrisul de mana de Stalvan. Fiindca ai descoperit indiciile esentiale care leaga toate piesele enigmei, comandantul Ebonlocke trebuie sa auda intreaga poveste direct de la anchetatorul care a dovedit-o.",al={"de ce nu vorbeste Smitts cu Ebonlocke","de ce sa-i duc raportul lui Stalvan","de ce trebuie sa-i raportez lui Ebonlocke"}}},fp="21,266,27.595.0,22.573.1,51.232.0,61.273.0,34.199.0,37.217.0,56.266.0,62.245.0"}
P.entries["quest:79007"] = {n="... and that note you found",s="'... and that note you found' incepe langa jarul pe cale sa se stinga al unei tabere parasite de curand, presarata cu provizii. Printre cenusa se afla o foaie de pergament arsa si basicata, pe care este scrisa o ghicitoare despre gasirea unui 'tinut geaman'. Neexistand alte indicii, bucata carbonizata este singurul indiciu despre orice a fost lasat in urma.",h="'...",kw={"si biletelul pe care l-ai gasit","bilet patat","bilet carbonizat","jar","foc recent","provizii imprastiate","twin land"},sec={{t="Jaratic in salbaticie",b="Langa stralucirea pe cale sa se stinga a unui foc de tabara recent si provizii imprastiate zace o bucata de hartie deteriorata si plina de basici. Oricine s-a oprit aici a plecat de curand, lasand in urma doar jarul care se raceste si un fragment de pergament care a scapat la limita de flacari. Scena sugereaza graba sau o intrerupere brusca, cu proviziile lasate in voia stihiilor."},{t="O ghicitoare criptica",b="Fragmentul de pergament ramas poarta o singura porunca enigmatica: 'Nu tot ce arde se pierde. Gaseste taramul geaman, gaseste locul.' Fara semnatura, coordonate sau alte indicii care sa fi supravietuit incendiului, fragmentul carbonizat este singurul reper pentru oricine da peste el."}},faq={{q="Ce scrie pe biletul gasit in tabara?",a="Biletul parlit si acoperit de basica contine un mesaj enigmatic: 'Nu tot ce arde se pierde. Gaseste tinutul geaman, gaseste locul.' Este singurul indiciu ramas in tabara abandonata.",al={"ce scrie pe nota","textul notei","nota cu basici"}},{q="Cine a lasat biletul?",a="Autorul ramane necunoscut. Biletul a fost gasit printre provizii imprastiate, langa jarul pe cale sa se stinga al unui foc de tabara recent. Asta sugereaza ca persoana care l-a scris sau l-a avut asupra sa a plecat de curand ori a fost nevoita sa fuga in graba.",al={"de unde a venit biletul","cine a scris biletul","cine a facut focul"}},{q="La ce se refera expresia 'taramul geaman'?",a="Nota vorbeste in mod criptic despre un 'taram geaman', indrumandu-l pe cititor sa caute un loc identic sau in oglinda. Fragmentul carbonizat nu ofera nicio alta explicatie, lasand semnificatia sa o enigma pe care calatorii trebuie s-o dezlege.",al={"ce este twin land","indiciu despre twin land"}},{q="Cum urmaresti indiciile de pe bilet?",a="Fara ca harta sa indice o destinatie clara, ramasitele carbonizate ale biletului sunt singurul tau indiciu. Pentru a-i urma ghicitoarea, trebuie sa cauti un tinut sau un loc care sa aminteasca de descrierea ei criptica.",al={"ce sa faci cu biletul","unde duce aceasta misiune"}},{q="De ce a fost parasita tabara?",a="Locul prezinta semne de plecare sau tulburare brusca, cu provizii imprastiate langa jarul care se stinge. In afara de fragmentul de hartie ars si supravietuitor, nu a mai ramas niciun alt echipament de identificare sau indiciu.",al={"cine a abandonat proviziile","provizii imprastiate, tabara"}},{q="Mai exista alte indicii langa foc?",a="Nu au mai ramas scrieri sau insemne intacte langa focul de tabara. Flacarile au distrus aproape totul, lasand drept unica dovada o bucata de hartie parlita, ramasita a celui care s-a odihnit acolo.",al={"dezvaluie focul si altceva","indicii de la tabara"}}},fp="27,318,18.339.0,16.289.0,45.187.0,25.212.0,35.221.0,40.196.0,31.206.0,38.190.0"}
P.entries["quest:79008"] = {n="... and that note you found",s="In Westfall, langa un foc de tabara pe cale sa se stinga, se afla o nota parlita. Mesajul ei scurt indica un loc numit tinutul geaman.",h="In Westfall, langa un foc de tabara pe cale sa se stinga, se afla o nota parlita.",kw={"nota cu basici","foc de tabara","nota carbonizata","jaratic","nota","tinut geaman","westfall"},ang={["class:Rogue"]="Ca rogue, stii sa descifrezi indicii criptice lasate in tabere ascunse; astfel de lucruri le vin firesc celor care traiesc din soapte, secrete si mesaje tainuite.",["faction:Alliance"]="Ca aventurier al Alliance care incearca sa restabileasca ordinea in Westfall, te confrunti cu o alta enigma la frontiera regatului: o tabara neidentificata si un cifru misterios."},sec={{t="Un foc pe cale sa se stinga",b="Prin campurile abandonate si campiile batute de vant din Westfall, calatorii gasesc tabere parasite de vagabonzi, proscrisi si ratacitori ajunsi la disperare. Aceasta tabara mica ar fi putut fi parasita in graba sau in taina; proviziile zac abandonate, iar jarul inca mai mocneste. Printre ramasitele imprastiate se afla o fasie de pergament parlit."},{t="Mesajul enigmatic",b="Biletul cu urme de arsura poarta doua propozitii scurte: “Nu tot ce arde se pierde. Gaseste tinutul geaman, gaseste locul.” Cuvintele te indeparteaza de Westfall, dar nu ofera o directie clara. Ce loc are un nume, o geografie sau o soarta asemanatoare cu acest tinut?"}},faq={{q="Ce scrie pe bilet?",a="Pe biletul cu bule de aer scrie: Nu tot ce arde este pierdut. Gaseste tara geamana, gaseste locul acela. Este singurul indiciu de la locul de campare abandonat.",al={"textul biletului","ce scrie pe bilet","cuvintele de pe biletul cu basici"}},{q="Unde se gaseste acest bilet?",a="Biletul zace printre ramasitele unui foc si proviziile imprastiate in salbaticia din Westfall.",al={"locatia biletului","unde este biletul","locatia focului de tabara"}},{q="Cine a lasat focul de tabara?",a="Nimeni nu stie cine a parasit tabara. Cel care a aprins focul a plecat de curand, lasand in urma provizii imprastiate si mesajul parjolit printre taciuni.",al={"cine a lasat biletul","proprietarul focului de tabara","autorul biletului"}},{q="La ce se refera expresia 'taramul geaman'?",a="Tara geamana face referire la o alta regiune legata de locul in care a fost gasita biletul, dar mesajul carbonizat nu ofera nicio explicatie suplimentara.",al={"intelesul tinutului geaman","ce este tinutul geaman","unde este tinutul geaman"}},{q="De ce a fost arsa nota?",a="Biletul a fost parlit si innegrit de jar. Poate ca cineva a incercat sa-l distruga in graba sau l-a lasat acolo din neglijenta, pe masura ce flacarile se stingeau.",al={"de ce a fost arsa","a incercat cineva sa arda biletul","biletul carbonizat"}},{q="Are legatura cu Defias Brotherhood?",a="Westfall este napadit de Defias Brotherhood si de ocupanti fara adapost, dar mesajul criptic sugereaza ceva mai obscur decat comunicatiile obisnuite ale banditilor.",al={"nota defias","este defias","brotherhood focul de tabara"}}},fp="27,124,12.304.0,19.241.0,23.142.0,25.97.0,22.142.0,35.146.0,24.143.0,44.163.0"}
P.entries["quest:79091"] = {n="Archmage Antonidas: The Unabridged Autobiography",s="Aceasta misiune presupune recuperarea memoriilor personale complete ale Archmage Antonidas, veneratul conducator raposat al Kirin Tor. Pastrata initial in arhivele grandioase din Ironforge, aceasta carte rara ofera informatii de nepretuit despre istoria Dalaranului si studiile arcane de nivel inalt.",h="Aceasta misiune presupune recuperarea memoriilor personale complete ale Archmage Antonidas, veneratul...",kw={"antonidas","arcane","archmage antonidas","autobiografie","dalaran","hall of explorers","ironforge","kirin tor","biblioteca","mage"},ang={["class:Mage"]="Archmage Antonidas a fost unul dintre cei mai mari conducatori ai lui Kirin Tor si un model de eruditie arcana. Studierea vietii si a scrierilor sale personale ofera cunostinte esentiale oricui practica artele arcane.",["faction:Alliance"]="Antonidas a fost un stalp al Alliance of Lordaeron impotriva Orcish Horde si a Scourge, ceea ce face din memoriile sale personale o pretioasa marturie istorica pe intregul teritoriu al Alliance.",["race:Dwarf"]="Tomul provine din marea biblioteca a Hall of Explorers din Ironforge, desi savantii care il primesc par sa nu fie preocupati ca ii lipsesc pe arhivistii pitici de un volum atat de rar.",["race:Human"]="Antonidas a fost un archmage human venerat, care a condus Kirin Tor si Dalaran in Second War si in Third War, ceea ce face din autobiografia sa integrala o piesa pretioasa a istoriei human."},sec={{t="Cuvintele marelui mag",b="Archmage Antonidas a fost una dintre cele mai stralucite minti din Azeroth si, timp de decenii, liderul venerat al Kirin Tor si conducatorul Dalaran. Autobiografia sa integrala povesteste ascensiunea lui prin ierarhia Violet Citadel, stapanirea artelor arcane si felul in care a condus in vremurile tulburi ale Second War si Third War. Pentru invatatii si practicantii magiei, amintirile directe ale lui Antonidas ofera o privire fara egal asupra mecanismelor interne ale Dalaran si asupra artelor arcane."},{t="Din Marea Biblioteca din Ironforge",b="Inainte de a ajunge la noua sa casa, acest manuscris rar se afla in marea biblioteca din Ironforge, pastrat alaturi de relicve antice ale titanilor si de istorii despre Dwarf in Hall of Explorers. Dwarf detin colectii vaste de texte adunate din ruine si regate straine de-a lungul Azerothului, ceea ce face din arhivele lor o comoara de literatura rara. Totusi, invatatii arcanisti din alte parti sunt nerabdatori sa puna mana pe astfel de lucrari pentru propriile colectii, convinsi ca arhivarii ocupati din randul Dwarf nu vor observa niciodata lipsa unui singur volum."}},faq={{q="Cine a fost Archmage Antonidas?",a="Archmage Antonidas a fost vreme indelungata conducatorul Kirin Tor si carmuitorul orasului-stat magic Dalaran. Maestru legendar al artelor arcane, a fost un consilier important al Alliance of Lordaeron in timpul Second War si l-a avertizat pe regele Terenas in legatura cu ciuma, inainte sa cada aparand Dalaran in timpul Third War.",al={"cine a fost antonidas","istoria arhimagului antonidas","trecutul lui antonidas"}},{q="Ce este autobiografia integrala?",a="Este autobiografia completa si neprescurtata scrisa chiar de Archmage Antonidas, in care isi descrie viata, studiile si conducerea din Dalaran. Avand in vedere ca era conducatorul Kirin Tor, scrierile sale personale constituie o marturie istorica si magica de nepretuit.",al={"ce este aceasta carte","autobiografia integrala","tomul lui antonidas"}},{q="De unde provine aceasta carte?",a="Volumul a fost obtinut de la biblioteca din Ironforge, aflata in Hall of Explorers, in fortareata piticilor. Exploratorii si arhivistii pitici aduna adesea texte istorice si magice din toate tinuturile continentelor estice.",al={"de unde provine cartea","a venit de aici, din ironforge?","carte din biblioteca ironforge"}},{q="De ce este cautata aceasta carte?",a="Invatatii si bibliotecarii cauta neincetat texte magice puternice sau cu insemnatate istorica, pentru a-si imbogati arhivele si a pastra cunoasterea arcane, indeosebi lucrari scrise de magi legendari, care altfel s-ar putea pierde sau ascunde in colectii straine.",al={"de ce colectam carti magice","cine vrea cartea lui Antonidas","de ce are biblioteca nevoie de asta"}},{q="Ce i s-a intamplat lui Archmage Antonidas?",a="Arhimagul Antonidas a pierit in timpul Third War, cand printul cazut Arthas Menethil si Scourge au invadat Dalaran. Antonidas a ridicat o bariera magica puternica pentru a apara orasul si secretele sale, dar Arthas a strapuns apararea si l-a doborat, punand mana pe Book of Medivh.",al={"a murit antonidas","cum a murit antonidas","ce s-a intamplat cu antonidas"}},{q="Va observa biblioteca din Ironforge ca lipseste cartea?",a="Destinatarul inlatura cu nonsalanta orice ingrijorare ca piticii ar putea observa lipsa cartii si isi spune ca arhivele vaste din Ironforge sunt atat de cuprinzatoare, incat disparitia unui singur volum va trece probabil neobservata.",al={"va simti Ironforge lipsa cartii","furtul din biblioteca Ironforge"}}},fp="48,290,28.497.0,35.523.0,27.321.0,37.277.0,30.229.0,36.240.0,36.282.0,51.204.0"}
P.entries["quest:79092"] = {n="Archmage Theocritus' Research Journal",s="Archmage Theocritus' Research Journal este un volum de magie arcana care documenteaza cercetarile maestrului mag din Tower of Azora. Inmanat carturarilor din Library-ul Ironforge, jurnalul imbogateste marea arhiva a piticilor cu cunostinte magice pretioase.",h="Archmage Theocritus' Research Journal este un volum de magie arcana care documenteaza cercetarile maestrului...",kw={"cunostinte arcane","archmage theocritus","ironforge","biblioteca din ironforge","jurnal de cercetare","theocritus","tower of azora"},ang={["class:Mage"]="Cercetatorii arcani pretuiesc notitele recuperate de la personalitati marcante precum Archmage Theocritus, ale carui cercetari ajuta la protejarea tratatelor magice istorice din arhivele Ironforge.",["faction:Alliance"]="Asigurarea unor texte si jurnale rare imbogateste marele tezaur de cunostinte pastrat in inima Ironforge, spre folosul tuturor carturarilor Alliance."},sec={{t="Notele de teren ale unui maestru",b="Archmage Theocritus este cunoscut in toata Alliance drept un vrajitor respectat, stationat in Tower of Azora, in tinuturile estice din Elwynn Forest. In decursul anilor de studiu solitar, Theocritus a cercetat artefacte neobisnuite, anomalii ale liniilor ley si amenintari magice din apropiere, consemnandu-si descoperirile in jurnale amanuntite. Recuperarea unui astfel de volum este o ocazie rara de a studia observatiile personale ale unui arhimag cu rang inalt din Kirin Tor."},{t="Extinderea arhivelor din Ironforge",b="Explorers' League si ingrijitorii bibliotecii din Ironforge pastreaza una dintre cele mai mari colectii de arhiva de pe continent. Predand Archmage Theocritus' Research Journal in grija lor, aventurierii se asigura ca invataturile sale arcane sunt pastrate si catalogate in siguranta, alaturi de volumele istorice din Khaz Modan. Bibliotecarii primesc cu bratele deschise orice noi descoperiri magice care le pot largi intelepciunea colectiva."}},faq={{q="Ce este Archmage Theocritus' Research Journal?",a="Este un jurnal de cercetare academica al mage-ului Archmage Theocritus, predat la Library din Ironforge pentru a pastra cunostintele arcane si a imbogati arhivele.",al={"predare jurnal Theocritus","ce este jurnalul lui Theocritus"}},{q="Cine este Archmage Theocritus?",a="Archmage Theocritus este un mag human renumit, care locuieste in Tower of Azora din Elwynn Forest si studiaza tulburari si artefacte magice stravechi.",al={"cine este Theocritus","povestea arhimagului Theocritus"}},{q="Unde este dus acest jurnal?",a="Jurnalul este dus arhivarilor din Library, in Ironforge, care aduna documente rare si manuscrise magice pentru colectia lor.",al={"unde predau jurnalul lui theocritus","cine doreste jurnalul lui theocritus"}},{q="De ce vrea biblioteca acest jurnal?",a="Invatatii din Library din Ironforge cauta sa pastreze cunostintele arcane si sa studieze tratate rare ale maestrilor vrajitori, pentru a-si imbogati arhivele istorice.",al={"de ce sa colectezi jurnale magice","scopul jurnalului lui Theocritus"}},{q="Se pot aduce si alte lucrari magice la biblioteca?",a="Da, curatorii ii incurajeaza pe aventurieri sa continue sa caute prin lume lucrari magice pierdute si texte istorice care sa le imbogateasca colectia arhivistica.",al={"mai multe jurnale de predat","mai sunt si alte carti pentru biblioteca"}},{q="Ce fel de cercetari sunt cuprinse in jurnal?",a="Jurnalul contine notite si observatii adunate de Archmage Theocritus in timpul cercetarilor sale indelungate asupra fenomenelor magice si cunostintelor arcane.",al={"ce contine jurnalul lui Theocritus","continutul jurnalului lui Theocritus"}}},fp="37,255,22.448.0,32.432.0,46.166.0,27.149.0,30.146.0,39.157.0,51.154.0,50.151.0"}
P.entries["quest:79093"] = {n="Rumi of Gnomeregan: The Collected Works",s="Rumi of Gnomeregan: The Collected Works presupune recuperarea si predarea unui volum compilat de scrieri gnomice, pentru a imbogati colectia unei biblioteci. Predand aceste texte rare, aventurierii ii ajuta pe carturari sa protejeze cunostinte istorice si magice valoroase, ca sa nu se piarda.",h="Rumi of Gnomeregan: The Collected Works presupune recuperarea si predarea unui volum compilat de scrieri...",kw={"opere adunate","istorie Gnomeregan","scrieri gnomice","biblioteca","opere magice","Rumi of Gnomeregan"},ang={["class:Mage"]="Invatatii arcanelor pretuiesc scrierile rare si neobisnuite recuperate din toate colturile Azerothului, mai ales lucrarile care sporesc intelegerea colectiva a teoriei si istoriei magiei.",["faction:Alliance"]="Carturarii si curatorii Alliance cauta neincetat sa recupereze si sa protejeze literatura si textele magice valoroase, spre folosul cunostintelor comune ale Alliance.",["race:Gnome"]="Pentru gnomii care cauta sa-si pastreze cultura si contributiile intelectuale dupa caderea Gnomereganului, arhivarea in siguranta a scrierilor adunate ale unor ganditori precum Rumi este o chestiune esentiala de patrimoniu."},sec={{t="Pastrarea gandirii gnomice",b="Rumi of Gnomeregan: The Collected Works reprezinta un efort de pastrare a literaturii gnomilor si a realizarilor lor intelectuale de seama. Dupa pierderea devastatoare a Gnomereganului in fata infestarii cu trogg-i, o mare parte din patrimoniul scris al gnomilor a fost imprastiata, ingropata sau amenintata cu distrugerea. Carturarii si arhivistii care lucreaza in biblioteci si centre de invatatura cauta in mod activ manuscrisele, tratatele si scrierile compilate care au supravietuit, pentru ca intelepciunea si inventivitatea ganditorilor gnomi sa nu se piarda in negura timpului."},{t="Recuperarea arhivelor",b="Cand aventurierii descopera aceste volume adunate in teren si le duc la arhive, curatorii le includ cu entuziasm in colectiile lor tot mai mari. Arhivistii privesc fiecare manuscris recuperat drept o extindere a intelegerii colective si ii incurajeaza pe calatori sa aduca orice alte texte magice sau istorice pe care le gasesc. Datorita acestor contributii, cunoasterea ramane la indemana invatatilor, magilor si istoricilor care se straduiesc sa ocroteasca mostenirea carturareasca a Azeroth."}},faq={{q="Ce este Rumi of Gnomeregan: The Collected Works?",a="Rumi of Gnomeregan: The Collected Works este o sarcina care presupune recuperarea si donarea unei colectii importante de scrieri gnomice. Un aventurier duce aceste materiale literare unui invatat care imbogateste colectia unei biblioteci, pentru ca informatiile valoroase sa fie pastrate si studiate.",al={"misiunea Rumi of Gnomeregan","ce este Rumi of Gnomeregan","cine este Rumi"}},{q="Unde sunt duse aceste opere culese?",a="Operele adunate sunt predate unui curator sau carturar care intretine colectia unei biblioteci. Destinatarii cauta scrieri importante si tratate magice pentru a-si imbogati arhivele.",al={"unde predau Rumi Works","cine primeste cartile rumi","unde predau colectia rumi"}},{q="De ce isi doreste biblioteca aceste opere adunate?",a="Invatatii si arhivistii aduna in mod activ texte rare, tratate istorice si manuscrise magice din intreaga lume pentru a asigura pastrarea cunoasterii esentiale, mai ales a scrierilor provenite din Gnomeregan.",al={"de ce sa aduni cartile Rumi","scopul cartilor Rumi of Gnomeregan","de ce vrea biblioteca Rumi"}},{q="Cine este Rumi din Gnomeregan?",a="Rumi din Gnomeregan este un autor intelectual sau magic ale carui scrieri adunate sunt cautate de arhivari. Cum Gnomeregan a fost in mare parte cucerit, colectiile de gandire si cunoastere gnomica ramase in viata reprezinta marturii pretioase ale traditiilor lor erudite.",al={"cine a fost rumi of gnomeregan","povestea lui rumi","autorul rumi"}},{q="Pot fi aduse si alte carti la biblioteca dupa aceasta?",a="Da, arhivistii primesc cu placere descoperiri suplimentare. Custodii ii incurajeaza pe aventurieri sa caute in continuare tratate magice rare sau importante si lucrari istorice care pot fi adaugate colectiei.",al={"mai sunt carti de gasit","pot aduce mai multe texte","mai multe lucrari magice pentru biblioteca"}},{q="Cine poate indeplini aceasta sarcina?",a="Misiunea este indeplinita de aventurieri Alliance care ii ajuta pe eruditi sa protejeze literatura istorica si arcane. Oricine recupereaza aceste texte valoroase le poate prezenta arhivelor, pentru a sprijini cercetarea academica.",al={"cerinte pentru misiunea Rumi","cine poate preda Rumi Works","Rumi doar pentru Alliance"}}},fp="39,281,26.517.0,17.482.0,48.284.0,42.186.0,48.216.0,26.252.0,52.202.0,27.216.0"}
P.entries["quest:79095"] = {n="The Apothecary's Metaphysical Primer",s="Apothecary's Metaphysical Primer este un text magic de specialitate, cautat de curatorii care doresc sa imbogateasca arhivele stiintifice. Predarea lui ajuta la pastrarea teoriilor rare despre alchimie si magie arcana pentru cercetatori si vrajitori.",h="Apothecary's Metaphysical Primer este un text magic de specialitate, cautat de curatorii care doresc sa...",kw={"alchimie","alchimist","Undercity","biblioteca","lucrari magice","manual metafizic","tom"},ang={["class:Mage"]="Cei care practica artele arcane pretuiesc lucrarile introductive metafizice pentru revelatiile profunde despre teoria magiei, interactiunile alchimice si legile fundamentale ale vrajitoriei.",["faction:Horde"]="Invatatii si aventurierii Horde il ajuta pe Owen Thadd in Undercity, recuperand tratate rare pentru a imbogati colectiile arcane ale bibliotecii."},sec={{t="O achizitie pentru un carturar",b="Apothecary's Metaphysical Primer este un text savant despre principii ezoterice si magice. Custodienii care vor sa-si imbogateasca arhivele primesc cu placere astfel de tratate si adauga direct volumul in colectia de referinta magica pe care o folosesc."},{t="Extinderea arhivelor",b="Pastrarea tratatelor de specialitate este esentiala pentru biblioteci precum colectia lui Owen Thadd din Undercity. Predand lucrari introductive rare despre teoria arcana si alchimica, exploratorii contribuie la pastrarea in siguranta a cunostintelor metafizice rare si la accesibilitatea lor pentru cercetatori, in loc ca acestea sa se piarda in salbaticie."}},faq={{q="Ce este Apothecary's Metaphysical Primer?",a="Apothecary's Metaphysical Primer este un text savant rar, cautat de curatori pentru a-si imbogati colectia de literatura magica si a-si aprofunda intelegerea stiintelor metafizice.",al={"ce este apothecaries metaphysical primer","misiunea metaphysical primer","ce este cartea aceasta"}},{q="Cine trebuie sa primeasca acest manual?",a="Volumul este dus la Owen Thadd in Undercity, care cauta lucrari magice si tratate arcane pentru a pastra cunostintele in folosul cercetatorilor si al celor care manuiesc magia.",al={"cine vrea aceasta carte","unde predau abecedarul","cine ia abecedarul"}},{q="De ce colecteaza biblioteca lucrari de acest fel?",a="Bibliotecile si arhivele aduna lucrari metafizice si magice pentru a-si extinde sistematic colectia de cunostinte, ajutandu-i pe invatati, alchimisti si arcanisti sa studieze principiile magiei arcane.",al={"de ce vrea biblioteca primerul","scopul colectarii primerului","de ce sa adun carti magice"}},{q="Poti aduce mai multe opere magice la biblioteca?",a="Invatatii insarcinati cu catalogarea literaturii magice primesc cu interes orice descoperiri arcane si academice ulterioare pe care le gasesti si care le-ar putea imbogati arhivele.",al={"mai sunt si alte carti de predat","pot aduce si alte carti","mai multe carti de biblioteca"}},{q="Ce fel de cunostinte despre legende contine un tratat metafizic?",a="In studiul magiei, metafizica se ocupa de natura fundamentala a energiilor magice, de fortele nevazute care guverneaza realitatea si de felul in care reactivii fizici interactioneaza cu energiile arcane.",al={"ce inseamna metaphysical in WotLK Classic","lore despre metafizica in WoW","ce este metafizica apotecarilor"}},{q="Cine a scris Apothecary's Metaphysical Primer?",a="Apotecarul care a scris lucrarea nu este numit in registre, dar apotecarii si invatatii alcatuiesc adesea indrumare care rezuma alchimia practica, amestecurile de plante si formulele mistice.",al={"cine a scris manualul farmacistului","autorul manualului farmacistului","cine este farmacistul"}}},fp="36,212,23.268.0,22.307.0,45.186.0,40.154.0,45.185.0,48.154.0,56.182.0,47.198.0"}
P.entries["quest:79096"] = {n="Ataeric: On Arcane Curiosities",s="Ataeric: On Arcane Curiosities presupune livrarea unor scrieri magice recuperate, pentru a imbogati colectia unei arhive de studiu. Adunand texte si tratate rare de pe teren, cercetatorii cauta sa-si aprofundeze intelegerea studiilor arcane si sa pastreze cunoasterea mistica.",h="Ataeric: On Arcane Curiosities presupune livrarea unor scrieri magice recuperate, pentru a imbogati colectia...",kw={"arcane","curiozitati arcane","ataeric","biblioteca","lucrari magice","savanti"},ang={["class:Mage"]="Magii au un interes innascut pentru cercetarea arcana, asa ca aportul lor la bibliotecile savante si recuperarea tratatelor magice sunt direct relevante pentru meseria lor.",["race:Dwarf"]="Invatatii pitici si Explorers' League pretuiesc foarte mult adunarea documentelor scrise, a artefactelor si a cunostintelor ezoterice."},sec={{t="Conservarea cunoasterii arcane",b="Invatatii si arhivistii din tot Azerothul se bazeaza pe aventurieri ratacitori pentru a recupera tomuri rare si tratate uitate din locuri periculoase. In aceasta sarcina, un cercetator cauta scrieri magice pentru a largi intelegerea unei institutii asupra artelor arcane. Fiecare volum recuperat ajuta la reconstituirea unor practici mistice care altfel ar putea ramane risipite sau pierdute."},{t="O arhiva in extindere",b="Dupa ce primeste curiozitatile, curatorul le adauga direct in depozitul arhivei. In loc sa considere colectarea incheiata, biblioteca continua sa primeasca orice alte scrieri magice descoperite prin lume, asigurandu-se ca fondul sau creste odata cu cercetarea."}},faq={{q="Care este scopul acestei misiuni?",a="Ataeric: On Arcane Curiosities presupune predarea unui text erudit sau magic unui colectionar care doreste sa imbogateasca fondul unei biblioteci cu cunostinte ezoterice.",al={"ce misiune este aceasta","misiunea lui Ataeric","predarea obiectelor pentru Arcane Curiosities"}},{q="Cine aduna aceste scrieri arcane?",a="Ataeric este autorul tratatului. Acesta este predat unui cercetator sau curator care aduna lucrari magice si volume rare pentru a imbogati arhiva unei biblioteci.",al={"cine vrea asta","cine primeste cartea","cine este Ataeric"}},{q="Care biblioteca beneficiaza de pe urma acestor curiozitati?",a="Textul este cautat pentru a imbogati o colectie academica, contribuind la biblioteca savanta care il gazduieste.",al={"ce biblioteca este aceasta","unde trebuie duse aceste carti"}},{q="Mai sunt si alte lucrari magice de adunat?",a="Invatatul ii incurajeaza in mod special pe aventurieri sa aduca orice alte lucrari magice descoperite in calatorii, pentru a-si imbogati necontenit cunostintele.",al={"pot preda mai multe","lucrari magice repetabile","mai multe carti pentru biblioteca"}},{q="De ce cauta biblioteca obiecte arcane neobisnuite?",a="Invatatii cauta neincetat tratate rare pentru a intelege mai bine subtilitatile arcanului si a pastra cunostinte istorice si mistice.",al={"ce studiaza biblioteca","de ce sa colectionezi carti arcane"}},{q="De ce este importanta recuperarea operelor arcane?",a="Textele arcane contin adesea cunostinte instabile sau obscure, asa ca e de preferat sa fie pastrate in siguranta si studiate intr-o biblioteca dedicata, nu lasate sa se piarda pe camp.",al={"este periculos","riscurile magiei arcane"}}},fp="30,271,27.371.0,20.321.0,34.164.0,35.154.0,46.110.0,40.169.0,45.136.0,41.165.0"}
P.entries["quest:79097"] = {n="Baxtan: On Destructive Magics",s="Baxtan: On Destructive Magics este o misiune de predare a unei lucrari savante, in care un aventurier ii duce unui carturar de la biblioteca tratatul lui Baxtan despre vrajile distructive. Recuperarea unor astfel de lucrari ii ajuta pe arhivistii bibliotecii sa-si aprofundeze intelegerea energiilor arcane instabile.",h="Baxtan: On Destructive Magics este o misiune de predare a unei lucrari savante, in care un aventurier ii duce...",kw={"arcana","baxtan","carte","magii distructive","biblioteca","magie","tom"},ang={["class:Mage"]="Tratatul savant despre magia distructiva ii intereseaza firesc pe Mage, care studiaza echilibrul dintre puterea arcana si fortele distructive.",["class:Warlock"]="Cei care patrund in puteri instabile sau interzise inteleg interesul academic al invatatilor pentru studierea magiei arcane distructive.",["faction:Alliance"]="Imbogatirea cunostintelor pastrate in bibliotecile Alliance consolideaza temelia academica a intregii Alliance."},sec={{t="Un tom al artelor nimicitoare",b="Aceasta misiune reprezinta efortul continuu al carturarilor de a cataloga si pastra cunostintele arcane. Cand aventurierii descopera texte despre natura nestatornica a magiilor distructive, inmanarea lor unor cercetatori de incredere asigura intelegerea puterii si primejdiei acestor arte, in loc sa le lase sa se piarda."},{t="Selectarea cunostintelor din Library",b="Biblioteca este un depozit de istorie, stiinta si cunoastere arcana. Carturarul care o supravegheaza se ocupa de achizitionarea volumelor rare si ii primeste pe calatorii care recupereaza tratate uitate din colturi periculoase ale lumii, pentru a imbogati cunostintele colective ale bibliotecii."}},faq={{q="Ce este misiunea 'Baxtan: On Destructive Magics'?",a="Aceasta misiune presupune livrarea tratatului lui Baxtan despre magiile distructive unui carturar dintr-o biblioteca, contribuind astfel la colectia de lucrari magice.",al={"ce este misiunea lui Baxtan despre magiile distructive","ce este aceasta misiune","misiunea lui Baxtan"}},{q="Cine este Baxtan?",a="Baxtan este autorul tratatului On Destructive Magics. Savantii care il primesc sunt cei care aduna volume importante si tratate magice pentru biblioteca.",al={"cine este baxtan","baxtan npc","unde se afla baxtan"}},{q="Ce fel de carti cauta Baxtan?",a="Carturarul bibliotecii cauta lucrari savante si magice care sa imbogateasca colectia si primeste cu interes orice tratat suplimentar despre magie descoperit in lume.",al={"ce fel de carti vrea Baxtan","colectia de carti a lui Baxtan","mai multe carti pentru Baxtan"}},{q="Unde ajunge pana la urma aceasta cunoastere magica?",a="Textele adunate sunt aduse in colectia bibliotecii care le primeste, pastrand pentru studiu cunostinte despre artele arcane si periculoase.",al={"unde se duce cartea","care biblioteca","colectia bibliotecii din Ironforge"}},{q="De ce colecteaza biblioteca lucrari despre magia distructiva?",a="Invatatii catalogheaza magiile distructive pentru a intelege mai bine pericolele, mecanismele teoretice si manifestarile energiilor arcane puternice.",al={"de ce sa studiezi magia distructiva","povestea magiei distructive"}},{q="Poti aduce mai multe opere magice la Baxtan?",a="Da. Carturarul ii invita pe aventurieri sa-i aduca orice alte lucrari magice descopera, ceea ce indica un efort continuu de a aduna cunostinte.",al={"mai sunt misiuni pentru baxtan","pot preda mai multe carti"}}},fp="29,263,22.297.0,27.261.0,50.141.0,14.166.0,42.158.0,41.150.0,56.138.0,43.141.0"}
P.entries["quest:791"] = {n="Carry Your Weight"}
P.entries["quest:79192"] = {n="Stepping Stones"}
P.entries["quest:792"] = {n="Vile Familiars"}
P.entries["quest:79236"] = {n="Cherry for Your Thoughts?",s="In Booty Bay, un mercenar pe nume Tokal cauta o bautura in schimbul adevarului despre atacurile recente asupra avanposturilor Human si Dwarf. Desi zvonurile dau vina pe Horde, Tokal sustine ca grupul sau actiona in baza unui contract privat de mercenariat.",h="In Booty Bay, un mercenar pe nume Tokal cauta o bautura in schimbul adevarului despre atacurile recente...",kw={"booty bay","cherry for your thoughts","bautura cherry grog","maresal","mercenar","jefuire","contract privat","tokal"},ang={["faction:Alliance"]="Membrii Alliance vor fi interesati sa afle ca jefuitorii care atacau taberele omenesti si pitice nu actionau sub autoritatea Horde, ci fusesera angajati de un patron privat.",["faction:Horde"]="Aventurierii din Horde pot gasi o confirmare a dreptatii lor in marturisirea lui Tokal, care lamureste ca atacurile asupra taberelor Alliance au fost contracte private de mercenariat, nu acte oficiale de agresiune ale Horde."},sec={{t="Soaptele din Booty Bay",b="In portul animat din Booty Bay, un individ pe nume Tokal se tine deoparte, fiind totodata atent la oamenii legii. O serie de raiduri agresive au devastat recent tabere de oameni si pitici, alimentand zvonurile ca Horde ar fi orchestrat atacurile. Cand il abordeaza calatori care in mod clar nu lucreaza pentru maresalul anchetator, Tokal se grabeste sa conteste naratiunea raspandita, oferind in schimbul unei bauturi o alta versiune a evenimentelor."},{t="Mercenari particulari",b="Tokal recunoaste fara ezitare ca a participat la jefuirea avanposturilor omenesti si piticesti, dar neaga cu hotarare ca raidurile ar fi fost in numele Horde. In schimb, sustine ca banda ei lucra pe baza unui contract privat pentru o terta parte care nu a fost dezvaluita. Inainte sa povesteasca pe larg cine a finantat operatiunea si de ce, insista sa i se aduca un Cherry Grog racoritor."}},faq={{q="Cine este Tokal?",a="Tokal este un agent sau mercenar care si-a gasit refugiul in portul piratilor Booty Bay. Fiind cercetata in legatura cu raidurile recente asupra asezarilor oamenilor si piticilor, ea se ofera sa spuna intreaga poveste despre cine a angajat-o oricui e dispus sa-i cumpere un Cherry Grog.",al={"cine este Tokal","Tokal din Booty Bay","cel care da misiunea cu Cherry Grog"}},{q="De ce vrea Tokal un Cherry Grog?",a="Tokal ezita sa vorbeasca despre detaliile sensibile ale contractelor sale din trecut cat timp e treaza. Daca-i cumperi o Cherry Grog, i se dezleaga limba si-ti spune cine a finantat pe ascuns raidurile impotriva taberelor Alliance.",al={"de ce sa cumperi rachiu de cirese","rachiu de cirese Tokal","ce vrea Tokal"}},{q="A fost Horde responsabila pentru jefuirea taberelor oamenilor si piticilor?",a="Potrivit lui Tokal, raidurile asupra taberelor oamenilor si piticilor nu au fost ordonate de Horde. Desi zvonurile sustineau ca Horde era responsabila, ea insista ca grupul ei lucra in baza unui contract privat de mercenariat.",al={"cine l-a angajat pe tokal","au atacat hoarda taberele aliantei","s-a aflat hoarda in spatele raidurilor"}},{q="De ce este Tokal ingrijorat de un maresal?",a="Tokal se teme ca o urmareste un maresal care ancheteaza jefuirea asezarilor oamenilor si piticilor. Are grija sa se asigure ca nimeni care se apropie de ea in Booty Bay nu este un agent trimis sa o aduca in fata justitiei.",al={"cine este maresalul","se ascunde Tokal de maresal","maresalul il cauta pe Tokal"}},{q="De unde iei Cherry Grog pentru Tokal?",a="Cherry Grog este o bautura care poate fi cumparata de la hangiii si barmanii din Booty Bay. Sa-i duci o cana din aceasta bautura lui Tokal ii satisface cererea si o face sa-si dezvaluie povestea.",al={"de unde iei Cherry Grog","locatia lui Cherry Grog","bautura din Booty Bay"}},{q="De ce sta Tokal in Booty Bay?",a="Booty Bay functioneaza ca un port neutru al corsarilor, in afara jurisdictiei stricte atat a Alliance, cat si a Horde. Pentru un mercenar care se ascunde dupa ce a jefuit tabere ale oamenilor si ale Dwarves, este o ascunzatoare ideala.",al={"de ce se afla Tokal in Booty Bay","ascunzatoarea lui Tokal"}}},fp="25,253,25.465.0,19.385.1,13.261.0,34.209.0,68.211.0,37.204.0,39.194.0,34.217.0"}
P.entries["quest:793"] = {n="Broken Alliances",s="Gorn te trimite in Lethlor Ravine, in estul indepartat al Badlands, unde drakes negri Blacklash si Hematus sunt legati de Seal of the Earth. Aceasta misiune urmeaza dupa prima Broken Alliances.",h="Gorn te trimite in Lethlor Ravine, in estul indepartat al Badlands, unde drakes negri Blacklash si Hematus...",kw={"black dragonflight","blacklash","orci blackrock","gorn","hematus","lethlor ravine","sigiliul pamantului","semnul pamantului"},sec={{t="Trei pietre runice",b="Trei pietre runice tin inchisa Pecetea Pamantului. Fiecare se afla intr-un stalp din Lethlor Ravine: Diamant, Opal si Ametist. Semnul Pamantului, pe care ti-l da Gorn, scoate pietrele si deschide pecetea. Nenumarati drakes isi au salasul in ravina, iar Blacklash si Hematus sunt redutabili. Gorn ii vrea pe amandoi morti, iar legaturile lor inapoi."},{t="Ce crede Gorn despre asta",b="Gorn spune ca zborul dragonilor negri este inca aliat cu orcii Blackrock renegati si ca atat dragonii, cat si orcii trebuie tinuti in frau sau alungati. Dupa ce Blacklash si Hematus vor fi morti, Horde isi va putea indrepta privirea spre vest, catre Blackrock Spire."}},faq={{q="Cine ofera aceasta misiune?",a="Gorn o da ca pas urmator dupa primul Broken Alliances.",al={"cine da broken alliances","locatia lui gorn","cine ofera broken alliances"}},{q="Unde se afla Lethlor Ravine?",a="Calatoreste pana la capatul estic al Badlands. Nenumarati drakes isi au salasul in ravina.",al={"locatia Lethlor Ravine","cum ajungi la Lethlor Ravine","unde se afla Lethlor Ravine"}},{q="Cum ii eliberezi pe Blacklash si Hematus?",a="Sign of the Earth scoate cate o piatra runica din fiecare dintre cei trei stalpi. Asezate in Seal of the Earth, pietrele ii elibereaza pe ambii dragoni.",al={"cum il invoc pe Blacklash","seal of the earth","stalpii de diamant, opal si ametist"}},{q="Ce trebuie adus inapoi la Gorn?",a="Legaturile lui Blacklash, lanturile lui Hematus si Sign of the Earth, dupa ce ambii drakes sunt morti.",al={"obiecte de predat pentru Broken Alliances","ce vrea Gorn inapoi","legaturile lui Blacklash"}}},fp="16,183,16.352.0,21.238.1,21.65.0,32.94.0,38.136.0,34.102.0"}
P.entries["quest:794"] = {n="Burning Blade Medallion"}
P.entries["quest:79974"] = {n="Wet Job",s="Wet Job este o misiune care te trimite sa descoperi o rezerva de urgenta ascunsa sus pe coasta unui munte. Pregatita pentru o retragere grabita si tainuita langa o stanca pitoreasca, provizia recuperata este protejata de ingeniozitatea mestesugului dwarf.",h="Wet Job este o misiune care te trimite sa descoperi o rezerva de urgenta ascunsa sus pe coasta unui munte.",kw={"inginerie piticeasca","Cuibul vulturilor","geanta mesagerului","coasta muntelui","pergament","rezerva ascunsa","provizii","Wet Job"},ang={["class:Rogue"]="Ideea de a ascunde rezerve de urgenta pentru o fuga grabita le vine firesc celor care traiesc in umbra.",["profession:Engineering"]="Ascunzatoarea demonstreaza ingeniozitatea inginereasca a piticilor, fiind o rezerva sigura pentru urgente, ascunsa pe un teren accidentat.",["race:Dwarf"]="Maiestria dwarven este laudata in timpul recuperarii depozitului, subliniind calitatea trainica a lucraturii lor montane."},sec={{t="O rezerva de urgenta",b="Cine lucreaza in conditii primejdioase stie sa nu porneasca niciodata la drum fara un plan de rezerva. Wet Job presupune gasirea unui depozit de rezerva ascuns in tinuturi muntoase accidentate. Pastrata pentru situatii de urgenta, cand o retragere rapida ar putea deveni necesara, aceasta rezerva asteapta sa fie recuperata daca lucrurile merg prost."},{t="Cuibul vulturului",b="Indiciile duc direct spre un loc pitoresc de observatie montan, descris poetic ca fiind sculptat de cascadele timpului. Sus, pe fata stancoasa, se afla ceea ce este numit cuibul vulturului. Acolo, partial ingropata in pamant, se gaseste o geanta de mesager uzata, ale carei provizii si pergamente sunt protejate de intemperii datorita mestesugului piticilor."}},faq={{q="Despre ce este misiunea Wet Job?",a="Wet Job este o misiune care presupune recuperarea unei rezerve de urgenta ascunse in teren. Cel care a pregatit-o a avut grija sa puna deoparte provizii, in caz ca ar fi trebuit sa fuga pe neasteptate.",al={"ce este wet job","misiunea wet job","ce fel de misiune este wet job"}},{q="Cine a lasat proviziile de rezerva?",a="Ascunzatoarea a fost pregatita de cineva care a pus deoparte rezerve de urgenta, in caz ca ar fi trebuit sa fuga in graba. Recuperarea scoate la iveala o geanta de mesager, langa care se afla pergamente si provizii confectionate cu o inginerie pitica remarcabila.",al={"cine a lasat proviziile ascunse","ale cui sunt proviziile","cine a ascuns rezerva"}},{q="Unde este ascunzatoarea?",a="Indiciul trimite spre un versant montan pitoresc, descris ca fiind cioplit de cascadele timpului, si ii indruma pe cei care cauta catre un cuib de vultur, sus pe peretele stancos, unde o geanta de mesager iese din pamant.",al={"unde este ascunzatoarea","locatia Wet Job","locatia cuibului vulturilor"}},{q="Ce se gaseste in geanta mesagerului?",a="Gasirea sacului de curier ingropat dezvaluie provizii esentiale si un pergament ascuns, protejat de maiestria deosebit de rezistenta a dwarfilor.",al={"ce se afla in ascunzatoare","obiecte din Wet Job","ce gasesti"}},{q="De ce se numeste sarcina Wet Job?",a="Desi titlul sugereaza adesea operatiuni de teren clandestine sau dezordonate, aici face trimitere directa la reperele montane, incadrate de ceata, cascadele timpului si pamantul umed care ascunde geanta.",al={"de ce se numeste wet job","semnificatia numelui wet job"}},{q="Ce legatura are ingineria piticilor cu asta?",a="La descoperirea si deschiderea ascunzatorii, constructia si fiabilitatea depozitului sunt laudate ca o minune a ingineriei piticesti, menita sa reziste ingroparii in aer liber.",al={"legatura cu ingineria piticilor","este lucru de pitici"}}},fp="7,246,18.303.0,16.356.0,32.206.0,27.218.0,26.221.0,35.155.0,31.186.0,36.165.0"}
P.entries["quest:79975"] = {n="Eagle's Fist",s="Eagle's Fist se invarte in jurul unei scrisori criptice, descoperite intr-o trusa de unelte, intr-un loc inalt, invaluit in ceata. Biletul dezvaluie ca un strajer singuratic pazea o baricada roasa de vreme, din loialitate fata de Old Kingdoms si Eagle and Fist. Desi focul de tabara fusese alimentat de curand, paznicul plecase in graba.",h="Eagle's Fist se invarte in jurul unei scrisori criptice, descoperite intr-o trusa de unelte, intr-un loc...",kw={"baricada","foc de tabara","eagle's fist","scrisoare impaturita","post de observatie","vechi regate","planor cu parasuta","trusa de unelte"},ang={["profession:Engineering"]="Biletul cercetasului evidentiaza locul drept punct de lansare ideal pentru un planor cu parasuta, atragand atentia inginerilor pasionati de cercetarea aeriana si zborul mecanic."},sec={{t="Un loc de panda ascuns",b="Ascunsa intr-o trusa de scule modesta, intr-un loc cu o priveliste minunata, se afla o scrisoare impaturita cu grija. Autorul reflecteaza asupra pozitiei dominante a inaltimii, remarcand ca de acolo poti da ordine sau poti plana cu un planor cu parasuta peste tinut. Umezit de stropii de apa purtati de ceata, avanpostul singuratic ofera o priveliste incredibila asupra unor tinuturi incarcate de istorie."},{t="Loialitate fata de vechile regate",b="Autorul biletului isi marturiseste devotamentul profund si statornic fata de 'the Eagle and Fist', observand ca slujirea cum se cuvine a acestei cauze impune pastrarea unei distante cumpatate. Desi recunoaste ca baricada locala s-a degradat - la fel ca Old Kingdoms, pe care candva le ferea de primejdii -, veghetorul neclintit jura ca nu va parasi cu adevarat postul."},{t="O plecare grabita",b="Cine a fost de serviciu in acest punct de observatie a plecat in graba. Cei care descopera avanpostul vor gasi un foc de tabara alimentat de curand cu lemne proaspete, dar santinela a disparut fara urma, lasand in urma doar uneltele, taciunii aprinsi si scrisoarea misterioasa."}},faq={{q="Ce este Eagle's Fist?",a="Eagle's Fist este o intalnire in jurul unei truse de scule ascunse, care contine o scrisoare impaturita cu grija, intr-un loc pitoresc si cetos, cu vedere spre o baricada veche. Acolo se afla tabara unui cercetas misterios care a fugit de curand.",al={"ce este Eagle's Fist","misiunea Eagle's Fist","ce este aceasta misiune"}},{q="Cine a scris scrisoarea gasita in lada cu unelte?",a="Autorul este un cercetas sau santinela neidentificata, devotata vechilor regate si unei entitati ori aliante cunoscute drept Vulturul si Pumnul. Vegheaza singur langa baricada darapanata.",al={"cine a scris biletul","cine a lasat scrisoarea","autorul scrisorii din cutia de unelte"}},{q="La ce se refera 'vulturul si pumnul'?",a="Scrisoarea vorbeste despre loialitatea fata de 'Vultur si Pumn', care trebuie pastrata de la distanta pentru a fi cel mai utila. Desi organizatia ramane invaluita in mister, ea are legatura cu apararea ramasitelor Vechilor Regate.",al={"ce inseamna vulturul si pumnul","semnificatia vulturului si pumnului","cine este Vulturul si Pumnul"}},{q="De ce este abandonata tabara?",a="Cercetasul a plecat in graba, lasand in urma un foc de tabara caruia tocmai i se adaugase lemn proaspat. Locul in care se afla ramane necunoscut, desi amplasamentul a fost laudat ca fiind ideal pentru lansarea unui planor cu parasuta.",al={"unde s-a dus cercetasul","de ce au plecat","cine a hranit focul de tabara"}},{q="Ce baricada este aparata?",a="Autorul deplange faptul ca baricada a vazut vremuri mai bune, comparandu-i starea uzata cu vechile regate cazute ale omenirii pe care le-a aparat odinioara, dar jura ca nu va renunta niciodata sa o pazeasca.",al={"ce baricada","care vechi regate","povestea baricadei"}},{q="Ce fel de post de observatie este acesta?",a="De pe culme se deschid privelisti panoramice uimitoare, iar aerul este racorit de stropii de apa, ceea ce sugereaza o stanca inalta sau un punct de belvedere langa o cascada uriasa ori un rau involburat.",al={"unde se afla","de ce tasneste apa","locatia lui eagles fist"}}},fp="12,314,14.373.0,27.351.0,17.260.1,21.224.0,42.189.0,40.196.0,30.194.0,33.186.0,34.159.0"}
P.entries["quest:79976"] = {n="This Must Be The Place",s="This Must Be The Place marcheaza locul unei tabere abandonate de curand, al carei ocupant a disparut cu doar cateva clipe in urma. Un bilet rupt, lasat in urma, dezvaluie ca autorul misterios si-a dus munca in subteran, ca sa nu ajunga pe maini nepotrivite.",h="This Must Be The Place marcheaza locul unei tabere abandonate de curand, al carei ocupant a disparut cu doar...",kw={"tabara parasita","rucsac cu echipament","ascunzatoare","sac de dormit","this must be the place","bilet rupt","subteran"},sec={{t="O plecare grabita",b="Un calator necunoscut a plecat recent in graba din acest loc izolat, strangandu-si tabara. Nu a ramas decat un sac de dormit derulat sub picioare si prins insuficient, o prelata groasa infasurata in jurul unor echipamente felurite si o bucatica de hartie rupta, suficient de mare pentru un mesaj de ramas-bun scris in graba. Oricine campa aici a disparut cu cateva clipe inainte ca cineva sa-l poata ajunge din urma."},{t="In adancuri",b="Mesajul lasat in urma dezvaluie ca autorul a hotarat sa-si duca din nou lucrarea in subteran, pentru a se asigura ca nu ajunge pe maini gresite. Ramane neclar daca biletul reprezinta un ramas-bun definitiv sau un indiciu subtil catre urmatorul refugiu secret al cercetatorului, lasandu-si echipamentul abandonat in urma, pentru oricine a dat peste acel loc."}},faq={{q="Cine a scris nota rupta?",a="Nota nu dezvaluie identitatea autorului. Scriitorul explica doar ca a hotarat sa-si continue munca in subteran, pentru a nu ajunge pe maini gresite, lasand in urma un loc de tabara parasit si echipament.",al={"cine a scris biletul","autorul biletului","cine a lasat mesajul"}},{q="Ce lucrare este dusa in subteran?",a="Natura exacta a lucrarii autorului ramane necunoscuta. Acesta mentioneaza ca s-a intors in subteran doar pentru a-si pastra cercetarile sau creatiile in siguranta fata de adversari nespecificati, care le-ar putea folosi gresit.",al={"ce munca subterana","de ce sa lucrezi sub pamant","ce munca"}},{q="Unde a plecat ocupantul taberei?",a="Cine ocupa locul si-a strans lucrurile in graba si a plecat pe furis cu doar cateva clipe inainte sa soseasca cineva. Destinatia nu este cunoscuta, dar biletul lasa sa se inteleaga ca s-ar fi mutat in alta ascunzatoare retrasa.",al={"i-am ratat","unde s-au dus","unde se afla autorul"}},{q="Ce a fost lasat in urma la tabara?",a="Calatorul a lasat in urma un sac de dormit prins necorespunzator, desfacut pe pamant, o panza groasa rulata peste diverse echipamente si un rucsac abandonat, plin cu tot felul de lucruri.",al={"ce a ramas in urma","provizii in tabara","ce era in rucsac"}},{q="Este acesta un indiciu care duce la o alta ascunzatoare?",a="Bucata rupta de hartie nu lamureste daca acestea sunt cuvinte de ramas-bun sau o urma lasata intentionat pentru a-l conduce pe cititor spre urmatorul adapost subteran al autorului.",al={"mai exista o ascunzatoare","urmatoarea tabara","mai multe indicii"}},{q="Cine sunt 'mainile nepotrivite' mentionate in nota?",a="Nota nu precizeaza cine sunt 'mainile gresite'. Autorul se temea in mod evident ca va fi urmarit sau ca i se vor fura lucrurile, asa ca s-a retras in graba, inainte ca eforturile sale sa fie compromise.",al={"cine sunt cei cu mainile nepotrivite","sensul expresiei maini nepotrivite","cine il urmareste pe autor"}}},fp="22,241,17.385.0,20.363.1,24.233.0,37.193.0,37.204.0,37.187.0,42.157.0,48.168.0"}
P.entries["quest:79980"] = {n="Scramble",s="Scramble este o vanatoare de comori ascunsa, care ii trimite pe aventurieri sa urmeze coordonatele de-a lungul unei stanci abrupte. Calauziti de biletul unui scotocitor, calatorii dezgroapa o geanta de curier ingropata, care contine provizii de supravietuire si un pergament murdar.",h="Scramble este o vanatoare de comori ascunsa, care ii trimite pe aventurieri sa urmeze coordonatele de-a...",kw={"ascunzatoare","versantul stancos","geanta mesagerului","pergament","harababura","rezerva","provizii"},sec={{t="Poteca spre nord",b="Un mesaj enigmatic indruma orice calator suficient de istet pentru a-l gasi catre o rezerva ascunsa de provizii. Autorul lasa incurajari informale alaturi de indicatii precise: mergi o suta de pasi drept spre nord, de-a lungul unei stanci periculoase, pentru a descoperi provizii lasate acolo ca sa ajute un calator sa-si continue drumul."},{t="Descoperirea gentii mesagerului",b="Urmarea instructiunilor de-a lungul fetei abrupte a stancii dezvaluie o geanta de mesager ingropata. Scoasa din pamant, geanta contine provizii practice de supravietuire si inca un pergament murdar, impaturit inauntru, sugerand ca aceasta scurta coborare face parte dintr-o pista mai ampla."}},faq={{q="Ce este misiunea Scramble?",a="Scramble este o misiune de cautare a urmelor, care indruma un aventurier spre o rezerva ascunsa pentru supravietuire. Un bilet scris le cere celor care o gasesc sa mearga spre nord, pe o stanca primejdioasa, pentru a recupera proviziile ingropate.",al={"misiunea Scramble","ce este Scramble","ascunzatoarea Scramble"}},{q="Unde se afla ascunzatoarea secreta?",a="Conform instructiunilor, ascunzatoarea este ingropata la aproximativ o suta de pasi spre nord, jos, pe o stanca abrupta. E nevoie sa pasesti cu grija ca sa ajungi la ea fara sa te rostogolesti pe versantul stancos.",al={"unde este ascunzatoarea","cum gasesc ascunzatoarea","locatia ascunzatorii"}},{q="Cine a lasat biletul si proviziile ascunse?",a="Identitatea exacta a autorului nu este mentionata. Scriitorul a lasat insemnari informale si practice, menite sa ajute un explorator sa-si gaseasca proviziile de urgenta, confirmand ca ascunzatoarea a ramas neatinsa.",al={"cine a scris biletul mazgalit","cine a lasat ascunzatoarea","autorul mazgalelilor"}},{q="Ce se afla in ascunzatoarea ingropata?",a="Dezgroparea ascunzatorii dezvaluie o geanta de mesager ingropata, care contine provizii de supravietuire si un pergament murdar printre echipamente.",al={"recompensele din Scramble","ce contine ascunzatoarea din Scramble","continutul gentii"}},{q="Ce este pergamentul murdar gasit printre provizii?",a="Pergamentul murdar este indesat in geanta mesagerului ingropata, alaturi de provizii; este descoperit cand geanta este scoasa din pamant.",al={"pergament murdar amestecat","ce scrie pe pergament","notita amestecata"}},{q="Ce pericole implica ajungerea la ascunzatoare?",a="Principalul pericol este coborarea abrupta de-a lungul stancii spre nord, unde un pas gresit poate duce la glezne rupte sau la caderi grave.",al={"escaladare periculoasa","escaladare pe stanci","escaladare pe coasta stancii"}}},fp="8,230,19.287.0,28.257.1,27.196.0,34.200.0,32.193.0,32.125.0,52.139.0,48.143.0"}
P.entries["quest:8"] = {n="A Rogue's Deal",s="O favoare aparent banala pentru Calvin Montague in Deathknell trimite un calator pe drumul catre Gallows' End Tavern din Brill. Sarcina presupune sa duca un mesaj misterios, fara destinatar, la Innkeeper Renee, sub pretextul unei livrari obisnuite.",h="O favoare aparent banala pentru Calvin Montague in Deathknell trimite un calator pe drumul catre Gallows' End...",kw={"brill","calvin montague","deathknell","gallows end","innkeeper renee","scrisoare anonima","rogue","tirisfal glades"},ang={["class:Rogue"]="Treaba de curier in interes personal a lui Calvin Montague ofera o privire asupra intelegerilor neoficiale care au loc in jurul Deathknell si Brill.",["faction:Horde"]="Livrarea duce direct la Brill, unde aliatii nou-sositi descopera centrul regional al administratiei Forsaken si un loc de ragaz in Tirisfal.",["race:Undead"]="Pentru Forsaken ridicati recent din morti, aceasta treaba marcheaza prima lor calatorie departe de siguranta cimitirului din Deathknell, spre centrul aglomerat din Brill."},sec={{t="Un curier prietenos",b="Lenevind printre mormintele solemne si capelele in ruina din Deathknell, Calvin Montague se da drept un luptator epuizat de prea multi zombi Scourge si paianjeni taratori. Sustinand ca are nevoie doar de o mana de ajutor ca sa duca un mesaj la Brill, le incredinteaza aventurierilor aflati in trecere o scrisoare nemarcata. Atitudinea lui degajata si promisiunea unei rasplate generoase fac ca sarcina sa para o favoare inofensiva, menita sa-i indrume pe Forsaken abia treziti spre orasul principal al regiunii."},{t="Gallows' End Tavern",b="Drumul duce spre est, printre copacii napastuiti din Tirisfal Glades, trecand pe langa Cold Hearth Manor pana la asezarea Brill. In spatele tejghelei tavernelor locale, Innkeeper Renee ii intampina initial pe nou-veniti cu o fire nelinistitor de vesela, rasfatandu-si clientii cu atentia sa. Totusi, dupa ce primeste scrisoarea lui Montague, ospitalitatea i se naruie pe loc. Renuntand la amabilitatile prefacute, se preface ca a primit vesti de la o mama draga, apoi il cearta pe curier ca s-a amestecat si ii cere sa cumpere ceva sau sa plece. Intoarcerea la Calvin aduce apoi o alta surpriza: in loc sa achite pe cale pasnica plata promisa, acesta il provoaca pe curier la duel."}},faq={{q="Cine este Calvin Montague?",a="Calvin Montague este un rogue din Deathknell care le cere calatorilor proaspat treziti sa duca o scrisoare la Innkeeper Renee, in Brill. O prezinta drept o favoare simpla si promite sa plateasca bine.",al={"Calvin Montague","cine da A Rogue's Deal","cel care da misiunea"}},{q="Ce se afla in Nondescript Letter?",a="Continutul exact al scrisorii nu este consemnat. Calvin ii da curierului un mesaj fara insemne, pe care sa-l duca la Innkeeper Renee din Brill.",al={"continutul scrisorii fara insemne","ce se afla in scrisoare","scrisoarea lui calvin"}},{q="De ce se poarta atat de ciudat Innkeeper Renee?",a="Renee tine hanul din Brill si insista ca purtarea ei de corespondenta sa ramana privata. Raspunsul ei la livrare poate fi aflat ducandu-i scrisoarea lui Montague.",al={"atitudinea lui innkeeper renee","de ce e renee falsa","scuza cu mama lui renee"}},{q="Chiar plateste Calvin Montague pentru livrare?",a="Montague promite sa plateasca bine pentru livrare. Renee iti ofera mancare sau apa cand primeste scrisoarea; dupa aceea, intoarce-te la Calvin pentru a continua negocierile legate de plata promisa.",al={"m-a inselat Calvin","unde-mi sunt banii","recompensa de la Montague"}},{q="Unde se afla Brill?",a="Brill se afla la nord-est de Deathknell. Calatorii urmeaza drumul principal spre est, iesind din valea de inceput, o iau la dreapta dupa Cold Hearth Manor si trec un pod acoperit pentru a ajunge in asezare.",al={"cum ajungi la Brill","drumul spre Brill","indicatii catre Brill"}},{q="Ce se intampla dupa ce scrisoarea ii este data lui Renee?",a="Urmeaza o alta misiune, intitulata 'A Rogue's Deal'. Intoarce-te la Calvin Montague in Deathknell pentru a-ti continua intelegerile cu el.",al={"urmatoarea misiune","continuarea misiunii A Rogue's Deal","ce sa fac dupa Renee"}}},fx={df83fdd9={q="De ce vrea Calvin Montague ca scrisoarea sa fie livrata?",a="Calvin Montague sustine ca s-a luptat cu mai mult decat ii revenea de drept cu zombi si paianjeni fara minte prin Deathknell si ca are nevoie doar de cineva care sa-i faca un comision. In loc sa urce el insusi drumul pana la Brill, se ofera sa te plateasca generos pentru a-i duce scrisoarea sigilata si fara insemne direct lui Innkeeper Renee.",al={"motivul lui Calvin Montague","de ce sa trimit o scrisoare lui Renee","de ce vrea Calvin sa se faca asta"}}},fp="14,250,18.483.0,23.691.1,23.180.0,38.130.0,40.160.0,51.182.0,23.181.0,46.130.1"}
P.entries["quest:80"] = {n="The Legend of Stalvan",s="Acest pas esential in ancheta asupra lui Stalvan Mistmantle aduce dovezile stranse in fata autoritatilor din Darkshire. Cu o pagina patata de sange dintr-un jurnal in mana, comandantul Althea Ebonlocke il trimite pe anchetator la Clerk Daltry, pentru autentificarea scrisului o data pentru totdeauna.",h="Acest pas esential in ancheta asupra lui Stalvan Mistmantle aduce dovezile stranse in fata autoritatilor din...",kw={"Althea Ebonlocke","pagina de jurnal patata de sange","functionar daltry","Darkshire","Duskwood","legenda lui Stalvan","Night Watch","Stalvan Mistmantle"},ang={["faction:Alliance"]="Ancheta scoate in evidenta eforturile oraselor de frontiera precum Darkshire de a mentine legea, ordinea si registrele civile, in ciuda asediului celor undead si al fiarelor din umbra.",["race:Human"]="Pentru oamenii din regatele sudice, aceasta misiune priveste tragediile interconectate care leaga nobilimea din Stormwind, colonistii din Duskwood si conacele risipite din Elwynn."},sec={{t="Strangerea latului",b="Urmand sirul paginilor de jurnal recuperate din Duskwood si din teritoriile umane invecinate, Night Watch detine in sfarsit ceea ce pare a fi o dovada zdrobitoare impotriva enigmaticului indrumator, Stalvan Mistmantle. Comandantul Althea Ebonlocke a banuit de ceva vreme ca barbatul ascunde ceva, insa o condamnare oficiala necesita certitudine absoluta. O singura pagina patata de sange nu este de ajuns pentru a pronunta sentinta pana cand nu se dovedeste fara urma de indoiala ca insemnarile macabre sunt scrise chiar de mana lui Stalvan."},{t="Ochiul functionarului",b="Pentru a transforma banuiala in certitudine, Night Watch se bazeaza pe arhivarul orasului Darkshire, Clerk Daltry. Dupa ce a supravegheat ani intregi registrele orasului, Daltry a examinat nenumarate evidente si semnaturi, devenind o autoritate in identificarea scrisului de mana. Compararea noii pagini de jurnal cu semnaturile istorice ale lui Stalvan din registrele orasului ofera corespondenta finala, de necontestat, necesara pentru a-i confirma decaderea intunecata si vinovatia."}},faq={{q="De ce are Commander Ebonlocke nevoie de confirmarea lui Clerk Daltry?",a="Comandantul Althea Ebonlocke vrea sa se asigure ca vinovatia lui Stalvan este dovedita fara urma de indoiala inainte de a lua masuri definitive. Clerk Daltry tine registrele orasului Darkshire si are multa experienta in examinarea semnaturilor, ceea ce il face persoana ideala pentru a verifica daca pagina insangerata corespunde scrisului de mana al lui Stalvan din registrele orasului.",al={"de ce Daltry","de ce sa verifici scrisul de mana","scopul functionarului Daltry"}},{q="Unde se incadreaza acest pas in povestea Legend of Stalvan?",a="Acesta este al unsprezecelea capitol al anchetei indelungate. Are loc imediat dupa recuperarea paginii patate de sange din jurnal si reprezinta ultima verificare a dovezilor inainte ca Night Watch sa ia masuri hotarate impotriva lui Stalvan.",al={"in ce etapa sunt","cat de departe sunt in lantul de misiuni","ordinea misiunilor din lantul lui Stalvan"}},{q="Unde se afla Clerk Daltry in Darkshire?",a="Clerk Daltry poate fi gasit in primarie, in Darkshire, unde gestioneaza registrele locale si evidentele proprietatilor comunitatii.",al={"locatia lui Daltry","unde este functionarul Daltry","gaseste-l pe Daltry"}},{q="Ce dovezi a adus investigatorul la Darkshire?",a="Investigatorul are asupra sa o pagina patata de sange din jurnal, recuperata in timpul cautarilor aflate in desfasurare pentru a afla unde se gaseste Stalvan. Scrierea descrie gandurile si intamplarile sale sumbre, dar trebuie verificata comparand scrisul de mana cu documentele oficiale.",al={"care sunt dovezile","ce pagina este aceasta","istoria paginii patate de sange"}},{q="Confirma Clerk Daltry ca scrisul de mana este al lui Stalvan?",a="Da. Comparand pagina patata de sange cu semnaturile din registrul orasului, Daltry confirma ca scrisul se potriveste, oferindu-i lui Ebonlocke certitudinea dorita inainte de a lua masuri definitive.",al={"se potriveste scrisul de mana","este stalvan","a scris stalvan acest lucru"}},{q="De ce este Night Watch atat de precauta cand vine vorba sa-l acuze pe Stalvan?",a="Chiar si in padurea tulburata si izolata din Duskwood, Night Watch se straduieste sa mentina ordinea si respectarea legii. Acuzarea unui fost invatat de crime ingrozitoare necesita dovezi concrete si verificabile, nu simple zvonuri sau supozitii.",al={"de ce sunt necesare dovezi","de ce sa nu-l omoram pur si simplu pe stalvan","suspiciunile lui ebonlocke"}}},fx={["5aad2c8f"]={q="De ce te pune Commander Althea Ebonlocke sa duci pagina la Clerk Daltry?",a="Comandanta Ebonlocke raspunde de apararea regiunii Duskwood si a orasului Darkshire, supraveghind perimetrul asezarii in timp ce tu te-ai ocupat de investigatia pe teren legata de Stalvan Mistmantle. Pentru ca i-ai adus direct ei pagina patata de sange din jurnal, cel mai rapid este sa o duci la Clerk Daltry, la primarie, ca sa verifice scrisul, in timp ce ea ramane de serviciu.",al={"de ce eu, Ebonlocke","de ce nu vorbeste Ebonlocke cu Daltry","de ce ma trimite la Daltry"}}},fp="21,281,15.511.0,15.474.1,62.349.0,62.242.0,43.125.0,54.237.0,55.190.1,58.219.0"}
