P.entries["quest:815"] = {n="Break a Few Eggs",s="Break a Few Eggs este o treaba prin care ajuti un bucatar coplesit, care trebuie sa tina pasul cu pregatirea nesfarsita a mancarii. Ingredientele proaspete si fragile trebuie adunate fara a le sparge, ca bucataria sa functioneze si mancarea sa fie gata la timp.",h="Break a Few Eggs este o treaba prin care ajuti un bucatar coplesit, care trebuie sa tina pasul cu pregatirea...",kw={"break a few eggs","mic dejun","bucatar","gatit","oua","bucatarie","mese"},ang={["profession:Cooking"]="Orice bucatar care munceste cunoaste presiunea neincetata de a-i hrani pe toti. Sa aduci ingrediente fragile fara sa le zdrobesti este jumatate din lupta in orice bucatarie."},sec={{t="Mese nesfarsite",b="Sa hranesti o multime este o sarcina istovitoare, care nu se termina niciodata. Intre micul dejun, pranz si cina, abia daca ramane timp sa te indepartezi de cuptor, daramite sa iesi din bucatarie ca sa cauti provizii crude. In Break a Few Eggs, un bucatar coplesit apeleaza la aventurierii aflati in trecere, rugandu-i sa aduca oua proaspete inainte ca urmatoarea tura de servire sa ramana in urma."},{t="Recunostinta unui bucatar",b="Transportarea oualor necesita o atingere delicata, pe care forta bruta nu o poate inlocui. Bucatarul poate avea vorbe aspre si putine laude de oferit, dar ingredientele intacte vorbesc de la sine. De indata ce ouale sunt livrate in siguranta si fara sa se sparga, bucatarul nu pierde vremea: il trimite pe culegator la drum si se intoarce direct la treaba, langa foc."}},faq={{q="Ce este misiunea Break a Few Eggs?",a="Break a Few Eggs este o sarcina culinara in care un aventurier ajuta un bucatar ocupat, coplesit de cererea neincetata de mancare. Sarcina presupune livrarea oualor intregi, pentru ca pregatirea bucatelor sa nu ramana in urma.",al={"misiunea Break a Few Eggs","ce este Break a Few Eggs","misiunea cu oua"}},{q="Cine este bucatarul din Break a Few Eggs?",a="Bucatarul este Cook Torka din Razor Hill, Durotar, care pregateste mancare fara oprire. Desi este direct si grabit, Torka se bazeaza pe oameni priceputi care sa-i aduca oua de Taillasher din Echo Isles fara sa le sparga inainte de masa.",al={"cine da Break a Few Eggs","bucatarul misiunii cu oua","cine gateste"}},{q="De ce are nevoie bucatarul de oua?",a="Bucatarul are nevoie de ele pentru pregatirea continua a meselor, fie ca e vorba de micul dejun, pranz sau cina. Hranirea oamenilor este o corvoada fara sfarsit, iar ouale proaspete sunt un ingredient esential care trebuie adus imediat la vatra.",al={"de ce oua","la ce folosesc ouale","de ce sunt necesare ouale"}},{q="De ce spune bucatarul sa nu fii neindemanatic?",a="Ouale sunt fragile si se pot strica usor in timpul transportului. Bucatarul tine in mod explicit sa lucreze cu cineva care nu e neindemanatic, caci cojile crapate si galbenusurile pierdute compromit ingredientele necesare pregatirii meselor.",al={"de ce trebuie sa ai grija cu ouale","nu sparge ouale","de ce sa nu fii neindemanatic"}},{q="La ce se refera titlul Break a Few Eggs?",a="Numele face trimitere la proverbul cunoscut potrivit caruia nu poti face o omleta fara sa spargi cateva oua, potrivindu-se unei sarcini axate pe strangerea unor ingrediente fragile pentru o bucatarie ocupata.",al={"sensul expresiei Break a Few Eggs","sensul expresiei","de ce se numeste Break a Few Eggs"}},{q="De ce se grabeste atat de tare bucatarul?",a="Bucatarul este complet ocupat sa tina pasul cu mesele neintrerupte de la micul dejun, pranz si cina. Cu atata mancare de gatit, bucatarul are putina rabdare pentru palavrageala si vrea pur si simplu sa se intoarca la vatra.",al={"atitudinea bucatarului","de ce este bucatarul nepoliticos","bucatar morocanos"}}},fp="16,216,13.344.0,18.311.0,35.225.0,36.235.0,28.203.0,46.178.0,46.187.0,29.219.0"}
