P.entries["quest:82"] = {n="Noxious Lair Investigation",s="Senior Surveyor Fizzledowser vrea sa afle cine este inamicul. Insectele au secat baltile care se aflau acolo unde se inalta acum Noxious Lair si se cunosc putine alte lucruri despre ele. Ti se cere sa iei cinci parti de insecte de la Centipaar din barlog si sa le duci la Alchemist Pestlezugg in Gadgetzan.",h="Senior Surveyor Fizzledowser vrea sa afle cine este inamicul.",kw={"centipaar","fizzledowser","gadgetzan","insecte","noxious lair","pestlezugg","tanaris"},sec={{t="Piese din vizuina",b="Dupa Gadgetzan Water Survey, Senior Surveyor Fizzledowser se ocupa de rapoartele despre insecte. Se stie putin, in afara de faptul ca acestea dreneaza baltile care se aflau odinioara acolo unde este acum Noxious Lair. Fizzledowser vrea mai intai sa afle cine este dusmanul si iti cere sa intri in barlog, sa iei cinci parti de la Centipaar gasiti acolo si sa le duci inapoi la Gadgetzan, la alchimistul Pestlezugg, pentru a fi examinate."},{t="Ce gaseste Pestlezugg",b="Pestlezugg incepe imediat sa lucreze la componente si spune fara intarziere ca nu seamana cu nicio forma de insecta vazuta pana acum, de parca o forta din afara ar controla insectele. Apoi Pestlezugg te trimite inapoi la Fizzledowser: are nevoie urgent de ajutorul tau, iar problema ar putea avea legatura cu mai multe insecte din Tanaris."}},faq={{q="De ce vrea Senior Surveyor Fizzledowser parti de insecte?",a="Gandacii seaca ochiurile de apa care se aflau odinioara acolo unde este acum Noxious Lair si se stiu putine alte lucruri despre ei. Partile provenite de la Centipaar ar trebui sa-l ajute pe Pestlezugg sa-si dea seama ce sunt.",al={"de ce sa aduni parti de insecte","parti de insecte pentru fizzledowser","scopul noxious lair"}},{q="Unde pot fi gasiti Centipaar?",a="Centipaar se afla in Noxious Lair, unde inainte se aduna apa.",al={"unde se afla Noxious Lair","locatia Centipaar","unde gasesti Centipaar"}},{q="Cine primeste partile de insecte in Gadgetzan?",a="Alchemist Pestlezugg din Gadgetzan, caruia trebuie sa i le duci pentru examinare.",al={"cui sa predau","locatia lui Pestlezugg","cine vrea partile de insecta"}},{q="Ce urmeaza inaintea acestui pas?",a="Urmeaza dupa Gadgetzan Water Survey.",al={"misiunea anterioara","misiune prealabila","ce duce la aceasta"}}},fp="26,308,19.413.0,21.291.1,56.189.0,30.68.0,43.58.0,28.38.0"}
