P.entries["quest:8273"] = {n="Oran's Gratitude",s="Dupa Rin'ji's Secret, lantul inceput cu Rin'ji is Trapped! se incheie cu Oran Snakewrithe, caruia ii aduci o tablite.",h="Dupa Rin'ji's Secret, lantul inceput cu Rin'ji is Trapped!",kw={"doamna intunecata","hinterlands","oran snakewrithe","stancile overlook","rin'ji","placuta"},sec={{t="O tablite pentru Oran",b="Rin'ji is Trapped! a inceput acest lant, iar Rin'ji's Secret a fost etapa de dinaintea acesteia. Oran Snakewrithe este cel care primeste tablitea pe care o porti."},{t="Raspunsul lui Oran",b="Oran intreaba unde a fost gasita tablitea, iar tu ii povestesti despre o mica insula pustie, la Overlook Cliffs. Oran gaseste acest lucru foarte interesant, pune cu grija tablitea deoparte si spune ca Dark Lady va fi foarte incantata de descoperire."}},faq={{q="Cine este Oran Snakewrithe?",a="Oran Snakewrithe este cel care incheie lantul inceput cu Rin'ji is Trapped! si continuat prin Rin'ji's Secret.",al={"oran","cine este oran","povestea lui oran snakewrithe"}},{q="Ce urmeaza inainte de aceasta parte a lantului?",a="Inaintea ei vine Rin'ji's Secret, iar inainte de aceasta, Rin'ji is Trapped!.",al={"misiunea precedenta","conditie prealabila pentru Oran's Gratitude","cum incep Oran's Gratitude"}}},fp="16,137,17.154.0,13.233.1,24.120.0,36.68.0"}
