P.entries["quest:847"] = {n="Guile of the Raptor",s="Dupa ce globul lui Tor'gan i-a dat lui Gor'mul esenta raptorului, puterea pe care a simtit-o il face sa se intrebe despre magia shamanilor. Te trimite sa-i spui lui Tor'gan ca, deocamdata, s-a lasat convins si va asculta.",h="Dupa ce globul lui Tor'gan i-a dat lui Gor'mul esenta raptorului, puterea pe care a simtit-o il face sa se...",kw={"arathi highlands","gor'mul","viclenia raptorului","hammerfall","shaman","tor'gan"},sec={{t="Un Warrior convins",b="Gor'mul se intreaba cu voce tare daca puterea care ii strabate trupul este puterea shamanilor pe care Tor'gan a incercat sa i-o arate. O gaseste interesanta. Iti cere sa-i spui lui Tor'gan ca s-a lasat convins, deocamdata, si ca va asculta ce are de spus Tor'gan."},{t="Raspunsul lui Tor'gan",b="Tor'gan spune ca va vorbi cu Gor'mul dupa ce vraja isi va pierde efectul. Iti multumeste ca l-ai ajutat sa-l readuci pe Gor'mul printre cei vii si se asteapta ca si Gor'mul sa-ti fie recunoscator."}},faq={{q="Cine te trimite sa vorbesti cu Tor'gan?",a="Gor'mul o face. Dupa ce simte puterea globului, iti cere sa-i spui lui Tor'gan ca s-a lasat convins, cel putin deocamdata.",al={"cine incepe Guile of the Raptor 3","cine ofera aceasta misiune","de unde incepe"}},{q="De ce se razgandeste Gor'mul in privinta lui Tor'gan?",a="Se intreaba daca puterea pe care a simtit-o este puterea shamanilor pe care Tor'gan a incercat sa i-o arate si i se pare interesanta. Deocamdata este convins si il va asculta pe Tor'gan.",al={"de ce s-a razgandit gormul","magia shaman a lui gormul","s-a lasat convins gormul"}},{q="Ce a fost inainte de acest pas?",a="Urmeaza pasului anterior, cand i-ai dus globul lui Tor'gan lui Gor'mul.",al={"misiunea anterioara","conditia prealabila pentru Guile of the Raptor"}}},fp="19,205,19.254.0,15.180.1,36.125.0,47.182.0,27.74.0"}
P.entries["quest:848"] = {n="Fungal Spores"}
P.entries["quest:849"] = {n="Revenge of Gann"}
P.entries["quest:85"] = {n="Lost Necklace",s="In sudul regiunii Elwynn, Bernice Stonefield isi cauta colierul disparut. Il banuieste pe Billy Maclure, fiul cel tanar al familiei vecine, si iti cere sa-l cauti peste drum.",h="In sudul regiunii Elwynn, Bernice Stonefield isi cauta colierul disparut.",kw={"Bernice","Billy","Elwynn","ferma","Maclure","colier","Stonefield","vii"},ang={["faction:Alliance"]="Ca novice al Alliance in Elwynn Forest, ai parte de viata de la frontiera locala rezolvand o disputa marunta dintre familiile certarete Stonefield si Maclure.",["race:Human"]="Ca human, vezi ca vrajba din Kingdom of Stormwind nu vine doar de la haiducii Defias si cetele de gnolli. Vechile dusmanii dintre vecinii de la tara sunt si ele adanc inradacinate."},sec={{t="O acuzatie intre vecini",b="Familiile Stonefield si Maclure locuiesc pe terenuri invecinate, in sudul Elwynn Forest, dar nu prea se au la inima. Cand \"Auntie\" Bernice Stonefield descopera ca i-a disparut colierul drag, da vina pe cel mai tanar membru al familiei Maclure. Convinsa ca Billy Maclure s-a furiat pe ferma ei si l-a luat, vaduva amara iti cere sa treci drumul spre podgorii, sa-l gasesti pe baiat si sa-i ceri sa-l inapoieze."},{t="Un baiat cu pofta de mancare",b="La via vecina, Billy Maclure neaga ca ar fi luat colierul si insista ca nu este hot. Cu un zambet complice, lasa sa se inteleaga ca poate stie ce s-a ales de el. Mai intai, vrea ca cineva sa-i potoleasca foamea cu o placinta proaspata cu carne de porc."}},faq={{q="Cine este Auntie Bernice Stonefield?",a="Auntie Bernice Stonefield este o vaduva in varsta care locuieste la Stonefield Farm, in sudul Elwynn Forest. Nu are incredere in familia Maclure din vecini, mai ales in fiul lor cel mic, Billy, care face numai pozne.",al={"cine este auntie bernice","bernice stonefield","cine ofera misiunea colierului pierdut"}},{q="A furat cu adevarat Billy Maclure colierul?",a="Billy Maclure neaga cu incapatanare ca ar fi furat colierul. Da de inteles ca stie cine l-a luat, dar nu va spune ce stie pana nu-l hraneste cineva.",al={"este Billy un hot","a furat Billy acel lucru","a luat Billy colierul"}},{q="Unde il pot gasi pe Billy Maclure?",a="Il poti gasi pe Billy Maclure printre vita-de-vie de la Maclure Vineyards, chiar la est, dincolo de drum, fata de Stonefield Farm.",al={"locatia lui Billy Maclure","unde este Billy","gaseste-l pe Billy Maclure"}},{q="De ce nu se suporta Stonefields si Maclures?",a="Familiile Stonefield si Maclure, care locuiesc una langa alta, sunt prinse de ani intregi intr-o vrajba rurala amara. Proprietatile, mandria si vechile ranchiune personale intretin tensiunile, asa ca fiecare tabara se asteapta la ce e mai rau din partea celeilalte.",al={"cearta dintre familii","cearta dintre Stonefield si Maclure","de ce se urasc"}},{q="Ce se intampla dupa ce vorbesti cu Billy Maclure?",a="Billy spune ca ii este prea foame ca sa-si aminteasca unde a ajuns colierul. Te trimite inapoi la Auntie Bernice ca sa-i coaca o placinta cu porc, in schimbul informatiei.",al={"ce urmeaza","dupa colierul pierdut","urmatoarea misiune"}},{q="Unde are loc aceasta misiune?",a="Calatoresti prin sudul Elwynn Forest, intre Stonefield Farm si Maclure Vineyards, aflata in apropiere.",al={"zona misiunii","unde se afla colierul pierdut"}}},fx={b7900c48={q="De ce vrea Auntie Bernice colierul inapoi?",a="Auntie Bernice este o vaduva in varsta, iar colierul este un bun personal la care tine foarte mult. Pierderea lui o tulbura si o face sa banuiasca imediat familia rivala de alaturi, mai exact pe tanarul Billy Maclure, ca l-a furat. Recuperarea bijuteriei de familie i-ar reda linistea si ar incalzi inima unei vaduve batrane.",al={"de ce vrea bernice colierul","motivul colierului lui bernice","importanta colierului din stonefield"}},["27b02d6f"]={q="De ce nu o confrunta Auntie Bernice personal pe Billy Maclure?",a="Dusmania apriga dintre Stonefields si Maclures face aproape imposibil ca oricare dintre parti sa vorbeasca civilizat fara sa izbucneasca o incaierare. Bernice nu poate pur si simplu sa mearga pana la Maclure Vineyards, iar garzile din Stormwind sunt prea ocupate sa se ocupe de gnolli si banditii Defias ca sa arbitreze certurile marunte dintre fermierii vecini. Un aventurier aflat in trecere poate fi un mediator neutru, care sa-l intrebe direct pe baiat.",al={"de ce are Bernice nevoie de mine","de ce sa trimita un aventurier la Billy","de ce sa nu intrebe garzile din Stormwind"}}},fp="13,184,23.386.0,22.232.1,33.196.0,46.144.1,31.117.0,55.206.0,44.156.1,33.101.0"}
P.entries["quest:850"] = {n="Kolkar Leaders",s="Kolkar Leaders da startul unei campanii conduse de orcul Regthar Deathgate, menita sa zdrobeasca sefii de razboi centauri aflati in plina ascensiune in Barrens. Nomazii Kolkar i-au hartuit pe tauren de generatii intregi, dar noii conducatori isi organizeaza cetele dezbinate intr-o veritabila amenintare militara. Regthar le cere campionilor din Horde sa-l doboare pe Barak Kodobane la Forgotten Pools, inainte ca influenta acestuia sa se raspandeasca.",h="Kolkar Leaders da startul unei campanii conduse de orcul Regthar Deathgate, menita sa zdrobeasca sefii de...",kw={"Barak","Barrens","centaur","Crossroads","Deathgate","Forgotten Pools","Kod obane","Kolkar","Regthar"},ang={["faction:Horde"]="Raspantiile din Barrens sunt artera vitala care leaga Mulgore, Durotar si avanposturile Horde aflate mai departe. Inlaturarea conducerii Kolkar protejeaza caravanele fragile de aprovizionare de ambuscade devastatoare.",["race:Orc"]="Thrall a fagaduit ca Horde ii va apara pe tauren, iar veterani incercati precum Regthar Deathgate iau in serios acest juramant de sange, considerandu-i pe centaurii belicosi o amenintare strategica imediata la adresa suveranitatii orcilor in Barrens.",["race:Tauren"]="Pentru tauren, uciderea comandantilor Kolkar este o chestiune de supravietuire si razbunare. Timp de decenii, clanurile Centaur au macelarit triburi si i-au alungat pe shu'halo de pe pasunile stramosesti, inainte ca Horde sa-si stabileasca un cap de pod in Kalimdor."},sec={{t="O amenintare in crestere in Tinuturile Aride",b="Vreme de nenumarati ani, centaurii cu trup de cal au terorizat Kalimdor, aducand poporul nomad tauren aproape de disparitie, pana cand Horde-ul lui Thrall a sosit si a schimbat cursul razboiului. In Barrens, puternicul trib Kolkar rataceste de obicei in cete razlete si dezbinate de jefuitori. Insa, de curand, capetenii agresive au inceput sa uneasca cetele disparate, transformand simplele grupuri de atac in forte militare unite, capabile sa infrunte avanposturile fortificate ale Horde."},{t="Decapitarea bestiei",b="Stationat intr-o tabara la vest de Crossroads, razboinicul orc Regthar Deathgate si-a dat seama ca Kolkar se bizuie prea mult pe fanfaronada si forta bruta pentru a-si pastra unitatea. Fara comandanti puternici, jefuitorii lor ajung sa se lupte intre ei. Pentru a le opri inaintarea, Regthar le cere aventurierilor Horde sa taie capul hidrei, incepand cu Barak Kodobane, un conducator ambitios care si-a stabilit tabara langa apele verzi din Forgotten Pools."},{t="Primul dintre multi",b="Uciderea lui Barak Kodobane da o lovitura puternica taberelor nordice ale Kolkar, insa Regthar stie ca Barak este doar avangarda unei miscari mai ample. Eliminarea lui marcheaza prima salva a unei campanii concertate de distrugere a inaltului comandament Kolkar, deschizand calea pentru vanarea celorlalti capetenii, Verog the Dervish si Hezrul Bloodmark, in Barrens."}},faq={{q="Cine este Barak Kodobane?",a="Barak Kodobane este un conducator feroce al centaurilor Kolkar, care a adunat jefuitori in jurul Forgotten Pools, la nord de Crossroads. Cunoscut pentru istetimea si cruzimea sa, s-a dovedit mult mai periculos decat jefuitorii nomazi obisnuiti, organizand clanuri disparate intr-o forta ofensiva impotriva Horde.",al={"Barak","cine este Barak","povestea lui Barak Kodobane"}},{q="Unde il pot gasi pe Barak Kodobane?",a="Barak Kodobane isi mentine tabara la Forgotten Pools, o oaza luxurianta aflata la nord de Crossroads, in centrul regiunii Barrens. De obicei, este inconjurat de garzi Kolkar loiale.",al={"locatia lui barak","unde este barak","barak din Forgotten Pools"}},{q="Cine este Regthar Deathgate?",a="Regthar Deathgate este un veteran orc aflat intr-o tabara cu un mic buncar, chiar la vest de Crossroads. El monitorizeaza deplasarile centaurilor in Barrens si coordoneaza lovituri preventive pentru a proteja asezarile Horde de raidurile organizate.",al={"regthar","cine le da liderilor kolkar","istorie regthar deathgate"}},{q="De ce reprezinta Kolkar o asemenea problema pentru Horde?",a="Membrii rasei centaur au purtat vreme de generatii un razboi nemilos, aproape genocidar, impotriva tauren. Ca membri cu drepturi depline ai Horde, tauren se bazeaza pe aliatii lor pentru a-si proteja stravechile terenuri de vanatoare si rutele comerciale din Barrens de expansiunea continua a centaurilor.",al={"de ce ne luptam cu Kolkar","amenintarea Kolkar","rivalitatea dintre centauri si Horde"}},{q="Ce se intampla dupa ce Barak este ucis?",a="Infrangerea lui Barak Kodobane dezvaluie ca alti capetenii aduna forte in alte locuri din Barrens. Regthar te trimite imediat sa-l asasinezi pe Verog the Dervish la Stagnant Oasis, apoi pe Hezrul Bloodmark la Lushwater Oasis, iar in final sa respingi un atac direct al Kolkar.",al={"urmatoarea misiune dupa Barak","continuarea povestii cu liderii Kolkar","ce urmeaza"}},{q="De ce se aduna Kolkar in jurul oazelor?",a="Apa si pamantul fertil sunt comori pretioase in clima arida din Barrens. Punand stapanire pe izvoare naturale precum Forgotten Pools, Kolkar isi asigura rezerve esentiale de apa si le refuza calatorilor si vanatorilor tauren locuri strategice de odihna.",al={"de ce sunt centaurii la oaze","apa kolkar","centaurii din Forgotten Pools"}}},fx={["55ee765d"]={q="De ce vrea Regthar Deathgate ca liderii Kolkar sa fie ucisi?",a="Triburile Centaur i-au hartuit pe tauren timp de generatii, insa cei din Kolkar, in Barrens, sunt de obicei dezbinati si dezorganizati. Recent, capetenii carismatice au inceput sa adune cetele razlete intr-o amenintare unita la adresa asezarilor din Horde. Regthar stie ca, daca acesti comandanti in ascensiune sunt lasati sa se organizeze, pozitia Horde in Barrens s-ar putea prabusi. Eliminarea unor figuri precum Barak Kodobane loveste in fruntea rascoalei inainte ca aceasta sa copleseasca apararea regionala.",al={"de ce sa omori conducatorii Kolkar","motivul lui Regthar Deathgate","de ce vrea Regthar ca acest lucru sa fie facut"}},["4347847a"]={q="La ce foloseste capul lui Barak?",a="Regthar cere dovezi incontestabile ca acel comandant al centaurilor a fost doborat. La frontiera aspra din Barrens, zvonurile si simplele afirmatii nu sunt suficiente pentru a garanta siguranta. Aducerea capului taiat al lui Barak dovedeste ca banda de razboinici Kolkar, tabarata langa Forgotten Pools, si-a pierdut cu adevarat conducatorul si capacitatea de a coordona alte atacuri.",al={"de ce capul lui Barak","scopul capului lui Barak","ce fac cu capul lui Barak"}}},fp="14,401,31.466.0,22.446.0,17.360.1,22.286.0,32.176.0,25.231.0,48.268.0,35.299.1,42.250.0"}
P.entries["quest:851"] = {n="Verog the Dervish"}
P.entries["quest:852"] = {n="Hezrul Bloodmark"}
P.entries["quest:853"] = {n="Apothecary Zamah",s="Aceasta insarcinare trimite un aventurier intr-o goana din tinutul arid Barrens pana la Thunder Bluff, purtand o emulsie fungica volatila, obtinuta prin prelucrare. Apothecary Helbrim are nevoie ca amestecul puternic sa-i fie livrat rapid colegului sau, Apothecary Zamah, ascuns in adancurile intunecate de sub Spirit Rise.",h="Aceasta insarcinare trimite un aventurier intr-o goana din tinutul arid Barrens pana la Thunder Bluff...",kw={"apothecary helbrim","apothecary zamah","spori fungici","pools of vision","spori prelucrati","royal apothecary society","spirit rise","the barrens","thunder bluff"},ang={["faction:Horde"]="Comunicarea rapida intre avanposturile din Barrens si platoul inalt din Thunder Bluff mentine conectate lanturile de aprovizionare regionale.",["race:Tauren"]="In timp ce isi intampina noii aliati, taurenii traditionalisti privesc adesea cu neincredere potiunile ciudate si bolborositoare pe care Forsaken le prepara in adancurile sacre ale Pools of Vision.",["race:Undead"]="Transportarea muncii lui Helbrim la Zamah consolideaza reteaua clandestina de cercetare pe care Royal Apothecary Society o mentine de-a lungul frontierei prafuite din centrul Kalimdor."},sec={{t="O incarcatura fragila",b="Dupa ce studiaza ciupercile neobisnuite care infloresc prin oazele din Barrens, Apothecary Helbrim fierbe o portie pana o transforma intr-o emulsie delicata. Licoarea instabila se degradeaza rapid dupa preparare. Neavand timp sa calatoreasca el insusi pana in Mulgore, Helbrim incredinteaza flaconul unui curier de incredere, care trebuie sa urce pantele inainte ca solutia sa-si piarda eficacitatea chimica."},{t="Sub privirile samanilor",b="Apothecary Zamah isi tine laboratorul departe de campiile deschise din Mulgore, ascuns in Pools of Vision. Aceasta pestera subterana se afla adanc sub inaltimile sacre din Spirit Rise, unde locuieste alaturi de magi si preoti Forsaken. Aici, sub podeaua sanctuarului taurenilor, Royal Apothecary Society isi desfasoara discret cercetarile, folosind materii prime adunate de pe tot continentul."}},faq={{q="De ce exista o limita de timp pentru aceasta livrare?",a="Emulsia fungica preparata de Helbrim este instabila din punct de vedere chimic. Daca este lasata prea mult timp la aer sau netratata, compusii se descompun si isi pierd potenta, facand amestecul inutil pentru munca lui Zamah.",al={"de ce este cronometrat","cronometrul misiunii","cronometrul sporilor prelucrati"}},{q="Unde o pot gasi pe Apothecary Zamah?",a="Apothecary Zamah se afla in interiorul Pools of Vision, in Thunder Bluff. Intrarea in pestera este oarecum ascunsa pe Spirit Rise si coboara sub corturile samanilor.",al={"unde este Zamah","locatia lui Zamah","gaseste-l pe Zamah"}},{q="Cine este Apothecary Helbrim?",a="Apothecary Helbrim este un alchimist care reprezinta Royal Apothecary Society si este stationat la Crossroads, in Barrens. El analizeaza flora si fauna locala pentru a afla cum ar putea organismele autohtone din Kalimdor sa le fie de folos celor Forsaken.",al={"cine este Helbrim","Helbrim la rascruce"}},{q="Ce face Royal Apothecary Society in Thunder Bluff?",a="Ca aliati in cadrul Horde, Forsaken trimit reprezentanti precum Zamah in Thunder Bluff. Lucrand discret in Pools of Vision, aflate in subteran, ei analizeaza exemplarele adunate din intreaga Kalimdor si mentin legaturi de aprovizionare cu alte avanposturi.",al={"de ce sunt forsaken in thunder bluff","alchimistii din pools of vision"}},{q="La ce se foloseau initial sporii fungici?",a="Sporii cresc in jurul oazelor luxuriante din Barrens, dezvoltandu-se nefiresc in desert. Helbrim i-a prelucrat pentru a le studia caracteristicile biologice si utilizarile alchimice, apoi i-a predat lui Zamah.",al={"de ce sporii","la ce folosesc ciupercile din barrens"}},{q="Ce se intampla daca expira timpul?",a="Daca timpul expira, emulsia se degradeaza si se strica. Trebuie sa te intorci la Apothecary Helbrim din Crossroads pentru a lua un lot proaspat, pe care sa-l duci la Thunder Bluff.",al={"cronometru ratat","sporii au expirat"}}},fx={f0da41d1={q="De ce vrea Apothecary Helbrim ca sporii prelucrati sa fie livrati atat de repede?",a="Apothecary Helbrim a prelucrat cu succes sporii fungici ciudati, culesi din Barrens, transformandu-i intr-o emulsie instabila. Amestecul se degradeaza rapid, iar doar asociata sa, Apothecary Zamah, dispune de reactivii si instalatiile specializate din Pools of Vision, necesare pentru a-l stabiliza, resigila si analiza in mod corespunzator, inainte sa-si piarda puterea pentru totdeauna.",al={"de ce sa trimiti spori la Zamah","motivul lui Helbrim","de ce vrea Helbrim sa fie livrat acest lucru"}}},fp="16,277,15.372.0,30.400.0,43.195.0,34.185.0,26.219.0,60.243.0,48.214.0,35.165.0"}
P.entries["quest:854"] = {n="Journey to the Crossroads"}
P.entries["quest:855"] = {n="Centaur Bracers"}
P.entries["quest:8551"] = {n="The Captain's Chest",s="Captain Hecklebury Smotts naviga odinioara intre Booty Bay si Ratchet, in Kalimdor, pana cand uriasii marini i-au distrus corabia, i-au ucis echipajul si l-au trimis pe Smotts spre Booty Bay intr-o barca de salvare. Uriasul Gorlash i-a luat Captain's Chest, iar Smotts vrea sa-l recupereze.",h="Captain Hecklebury Smotts naviga odinioara intre Booty Bay si Ratchet, in Kalimdor, pana cand uriasii marini...",kw={"Booty Bay","Gorlash","Ratchet","gigant marin","Smotts","tabachera","Stranglethorn"},sec={{t="Un capitan ruinat",b="Smotts spune ca voiajele spre Ratchet, in Kalimdor, i-au cladit o cariera de succes si o reputatie frumoasa. Gigantii marini au pus capat tuturor acestora: au distrus corabia, au ucis echipajul si l-au trimis pe Smotts spre Booty Bay intr-o barca de salvare."},{t="Cufarul furat",b="Uriasul Gorlash a luat Captain's Chest al lui Smotts, spunand ca il vrea drept tabachera. Cufarul era preferatul lui Smotts si avea un compartiment secret unde erau pastrate cele mai mari comori. Smotts a auzit ca Gorlash cutreiera tarmul de la est de Booty Bay."},{t="Multumirile lui Smotts",b="Smotts e in culmea fericirii ca si-a primit cufarul inapoi; furia i s-a mai potolit, dar razbunarea nu e inca desavarsita."}},faq={{q="Cine este Captain Hecklebury Smotts?",a="Smotts este capitan de corabie in Booty Bay, unde candva naviga intre acest loc si Ratchet, in Kalimdor, pana cand uriasii marini i-au zdrobit corabia si i-au ucis echipajul.",al={"captain smotts","cine este smotts","hecklebury smotts"}},{q="Cine a luat cufarul?",a="Gorlash, unul dintre uriasii marini, l-a luat si a spus ca il voia drept tabachera.",al={"cine a furat cufarul","cine are cufarul lui smotts","gorlash"}},{q="Unde poate fi gasit Gorlash?",a="La est de Booty Bay, de-a lungul tarmului. Acolo a auzit Smotts ca se plimba uriasul.",al={"unde se afla gorlash","locatia lui gorlash","gaseste-l pe gorlash"}},{q="De ce vrea Smotts cufarul inapoi?",a="Era cufarul preferat al lui Smotts, iar compartimentul ascuns pastra cele mai pretioase comori.",al={"ce se afla in cufar","de ce vrea smotts cufarul"}}},fp="19,258,16.217.0,16.247.0,14.124.1,33.147.0,19.76.0,27.83.0,36.86.0"}
P.entries["quest:8552"] = {n="The Monogrammed Sash",s="O esarfa eleganta, cu initiale brodate, sugereaza ca undeva in Stranglethorn Vale exista un proprietar de drept. Gasirea marinarului care a pierdut-o duce la The Captain's Cutlass.",h="O esarfa eleganta, cu initiale brodate, sugereaza ca undeva in Stranglethorn Vale exista un proprietar de...",kw={"hecklebury smotts","hs","mok'rash","monogrammed sash","sea giant","stranglethorn vale"},sec={{t="O haina insemnata",b="Aceasta esarfa eleganta poarta literele 'HS' brodate de-a lungul tivului. Cel care a pierdut-o poate fi identificat doar dupa aceste doua litere."},{t="Legatura cu Smotts",b="Returnarea vesmantului catre Captain Hecklebury Smotts confirma ca ii apartine. Recuperarea lui dezvaluie ca gigantul marin Mok'rash a fost ucis, spre usurarea capitanului, dupa ce matahala a contribuit de mai multe ori la distrugerea corabiilor si a echipajului sau."}},faq={{q="Ce litere sunt cusute pe esarfa?",a="Tivul esarfei fine este brodat cu initialele 'HS'.",al={"ce initiale sunt pe esarfa","initialele de pe Monogrammed Sash","literele de pe esarfa"}},{q="Unde duce mai departe?",a="Dupa ce braul este inapoiat proprietarului, urmatorul pas este The Captain's Cutlass.",al={"ce misiune urmeaza dupa Monogrammed Sash","urmatoarea misiune dupa Monogrammed Sash","pasul urmator"}}},fp="20,167,16.121.0,21.259.1,40.63.0,26.79.0"}
P.entries["quest:8553"] = {n="The Captain's Cutlass",s="Captain Hecklebury Smotts a cumparat o a doua nava, numita Smotts' Revenge, pentru a-i vana pe uriasii marini care i-au luat prima corabie, dar a suferit o noua infrangere. Uriasii au sfaramat nava si au ucis echipajul, iar unul dintre ei, Negolash, a furat sabia de abordaj a capitanului. Smotts te indruma sa-l consulti pe fostul bucatar de pe nava sa, Sprogger, pentru a da de urma colosului.",h="Captain Hecklebury Smotts a cumparat o a doua nava, numita Smotts' Revenge, pentru a-i vana pe uriasii marini...",kw={"sabie de abordaj","hecklebury smotts","negolash","uriasi marini","razbunarea lui smotts","sprogger","stranglethorn"},sec={{t="O a doua calamitate",b="Dupa pierderea primei sale nave, Captain Hecklebury Smotts a procurat o a doua ambarcatiune, numita Smotts' Revenge, si a strans un echipaj nou si provizii pentru a se razbuna pe uriasii marini. Expeditia s-a incheiat dezastruos, cand uriasii au sfaramat nava si au ucis echipajul, lasandu-l din nou pe Smotts in deriva, intr-o barca de salvare. In timpul atacului, uriasul Negolash a luat spada de abordaj a capitanului."},{t="Consultandu-l pe bucatar",b="Hotarat sa-si recupereze lama furata, Smotts se bazeaza pe bucatarul sau. Sprogger, care a slujit la bordul navei Smotts' Revenge, a supravietuit atacului si te poate ajuta sa-l gasesti pe Negolash."}},faq={{q="Ce nava a pierdut Captain Hecklebury Smotts in acest atac?",a="Smotts a cumparat si echipat o corabie numita Smotts' Revenge pentru a vana uriasii care i-au distrus prima nava, dar uriasii au distrus-o si pe aceasta.",al={"cum se numea a doua corabie","a doua corabie a lui Smotts","ce corabie a fost zdrobita"}},{q="Cine a furat spada de abordaj a capitanului?",a="Negolash, unul dintre uriasii marini care au zdrobit Smotts' Revenge si au ucis echipajul, a luat arma.",al={"cine are cutlass","care urias a luat cutlass","cine a luat cutlass-ul lui Smotts"}},{q="Cine este Sprogger?",a="Sprogger a lucrat ca bucatar la bordul navei Smotts' Revenge si a supravietuit atacului care a distrus-o. Captain Smotts ii indruma pe calatori spre el pentru a-i ajuta sa-l gaseasca pe Negolash.",al={"cine este sprogger","rolul lui sprogger","cine era bucatarul"}},{q="Unde se incadreaza aceasta etapa in vanatoarea uriasilor marini?",a="Aceasta etapa urmeaza dupa The Monogrammed Sash si duce direct la Facing Negolash.",al={"ce misiune vine inaintea acesteia","care este urmatoarea misiune","lantul de misiuni cu cutlass"}}},fp="21,351,17.388.0,19.165.0,60.149.0,32.98.0,16.168.0,58.77.0"}
P.entries["quest:8555"] = {n="The Charge of the Dragonflights",s="Anachronos, din zborul dragonilor de bronz, te intalneste in Tanaris pentru a incheia prima parte a misiunii Scepter of the Shifting Sands. Acest lant de misiuni este calea spre deschiderea portilor Ahn'Qiraj.",h="Anachronos, din zborul dragonilor de bronz, te intalneste in Tanaris pentru a incheia prima parte a misiunii...",kw={"anachronos","azuregos","eranikus","gates of ahn'qiraj","scepter of the shifting sands","tanaris","vaelastrasz"},sec={{t="Sfarsitul inceputului",b="Aceasta intalnire incheie prima etapa din Scepter of the Shifting Sands, lantul de misiuni care duce spre deschiderea portilor din Ahn'Qiraj. Anachronos este cel care incheie aceasta prima parte alaturi de tine."},{t="Cei trei observatori",b="Anachronos numeste trei dragoni, Eranikus, Vaelastrasz si Azuregos, care au avut roluri importante ca pazitori ai lumii. Potrivit lui Anachronos, fiecare dintre acesti gardieni a cazut victima unei tragedii, fie din cauza agentilor Old Gods, fie prin tradarea celor care-i numeau prieteni. Anachronos recunoaste ca poarta o parte din vina, din naivitate, si spune ca toate acestea au starnit neincredere fata de muritori. Ti se spune sa-i cauti pe cei trei si sa te pregatesti pentru ce e mai rau."}},faq={{q="Cine este Anachronos?",a="Anachronos este un dragon din zborul dragonilor de bronz, intalnit aici, in Tanaris.",al={"cine este anachronos","anachronos tanaris","dragon de bronz"}},{q="Ce este Scepter of the Shifting Sands?",a="Este lantul lung de misiuni care duce la deschiderea Portilor Ahn'Qiraj. Aceasta intalnire incheie prima parte.",al={"lantul sceptrelor","sceptrul nisipurilor schimbatoare","lantul misiunilor Gates of Ahn'Qiraj"}}},fp="31,186,24.198.0,18.466.1,18.71.0,42.108.0"}
P.entries["quest:8569"] = {n="Past Efforts in Warsong Gulch",s="In Warsong Gulch, soldatii lupta pentru Ashenvale, iar comandantii le onoreaza sacrificiile. Ofiterii din capitala accepta Ribbon of Sacrifice ca semn al unei slujiri neclintite, chiar si atunci cand luptele nu aduc o victorie limpede.",h="In Warsong Gulch, soldatii lupta pentru Ashenvale, iar comandantii le onoreaza sacrificiile.",kw={"ashenvale","general de brigada","orgrimmar","eforturi anterioare","ribbon of sacrifice","stormwind","warbringer","warsong gulch"},ang={["class:Warrior"]="Ca warrior, cunosti lupta corp la corp brutala din defileu. Disciplina inseamna sa lupti cu inversunare chiar si cand victoria atarna in balanta.",["faction:Alliance"]="Ca soldat din Alliance, oferirea unei panglici unui general de brigada iti reafirma juramantul de a apara padurile stravechi si de a-ti sprijini aliatii Night Elf impotriva agresiunii Warsong.",["faction:Horde"]="Ca membru al Horde, sa-i prezinti un jeton unui Warbringer confirma ca sangele varsat pentru asigurarea lemnului si supravietuirii in Ashenvale nu a fost irosit."},sec={{t="In cinstea celor cazuti si a celor viteji",b="Silverwing Sentinels si Warsong Outriders se infrunta in lupte crancene de-a lungul granitei sudice din Ashenvale. Multe batalii se incheie fara un invingator clar. Stormwind, Orgrimmar si alte capitale ii onoreaza pe cei care isi mentin pozitia in ciuda sanselor potrivnice. Ribbon of Sacrifice marcheaza luptatorii care s-au jertfit in aceasta confruntare."},{t="Efortul de razboi de acasa",b="Departe de front, generalii de brigada ai Alliance si Warbringerii Horde isi supravegheaza fortele. Recrutorii trimit noi luptatori in Warsong Gulch, in timp ce sferturmastii si tacticienii tin socoteala veteranilor intorsi din campanii grele. Cinstindu-le curajul in impas sau infrangere, conducatorii lor ii ajuta pe soldati sa ramana hotarati sa apere Ashenvale."}},faq={{q="Care este scopul acestei citatii?",a="Distinctia onoreaza luptatorii care au dat totul in Warsong Gulch. Comandantii capitalei accepta Ribbon of Sacrifice pentru a le recunoaste perseverenta si a mentine moralul.",al={"de ce eforturile din trecut","scopul eforturilor din trecut","ce inseamna eforturile din trecut"}},{q="Cine primeste aceste jetoane de sacrificiu?",a="Brigadier Generals din Alliance si Warbringers din Horde accepta aceste insemne in marile orase, inclusiv in Stormwind si Orgrimmar.",al={"cine preia Past Efforts","unde predau Past Efforts","cine este generalul de brigada"}},{q="De ce armata rasplateste eforturile care nu au dus la victorie?",a="Comandantii stiu ca luptele din padurile Ashenvale fac multe victime. Cinstirea devotamentului soldatilor arata ca sacrificiul lor conteaza chiar si atunci cand nu inving.",al={"de ce recompensa cu panglica sacrificiului","de ce recompensa pentru pierdere","sensul efortului eroic"}},{q="Unde se desfasoara conflictul din Warsong Gulch?",a="Warsong Gulch se intinde de-a lungul granitei sudice a Ashenvale. Warsong Outriders aduna lemne acolo, in timp ce Silverwing Sentinels li se opun.",al={"unde este warsong gulch","locatia warsong gulch","ce este warsong gulch"}},{q="Pot participa atat membri ai Alliance, cat si ai Horde?",a="Da. Ambele factiuni ii onoreaza pe soldatii intorsi acasa prin intermediul conducatorilor lor militari din capitalele respective.",al={"aceasta misiune este pentru ambele factiuni","eforturile Hoardei sau Aliantei din trecut","poate Hoarda sa predea aceasta misiune"}},{q="Ce reprezinta Ribbon of Sacrifice?",a="The Ribbon of Sacrifice ii onoreaza pe luptatorii care au indurat confruntari aprige in Warsong Gulch si au ramas gata sa lupte pentru poporul lor.",al={"povestea Ribbon of Sacrifice","ce este Ribbon of Sacrifice","panglica sacrificiului"}}},fp="29,209,35.318.0,22.335.0,41.172.0,38.119.0,66.167.0,52.141.0,58.104.0,44.131.0"}
P.entries["quest:857"] = {n="The Tear of the Moons"}
P.entries["quest:8576"] = {n="Translating the Ledger",s="Ii duci registrul lui Azuregos lui Narain Soothfancy, care trebuie sa descifreze ce scrie in el. Este un pas pe drumul spre deschiderea Portilor din Ahn'Qiraj.",h="Ii duci registrul lui Azuregos lui Narain Soothfancy, care trebuie sa descifreze ce scrie in el.",kw={"arcanite buoy","Azuregos","draconic","registru","Narain Soothfancy","Tanaris"},sec={{t="Registrul ajunge la Narain",b="Ii duci registrul lui Azuregos lui Narain Soothfancy. Cineva trebuie sa descifreze ce a scris Azuregos, iar sarcina ii revine lui Narain."},{t="Ce parere are Narain despre asta",b="Narain afla ca Azuregos te-a pus sa construiesti o geamandura din arcanit si ca registrul contine schema. Narain considera ciudat faptul ca Azuregos a scris-o in Draconic, pe care Narain nu il poate citi. Pentru a o face sa functioneze, Narain va avea nevoie de ochelarii de clarvazator, de o gaina de cinci sute de livre si de al doilea volum din Draconic for Dummies, in orice ordine."}},faq={{q="Al cui este registrul?",a="Este registrul lui Azuregos. Trebuie sa i-l duci lui Narain Soothfancy.",al={"registrul cui","registrul lui Azuregos","cine a scris registrul"}},{q="Cine citeste registrul?",a="Narain Soothfancy, care trebuie sa afle ce a scris Azuregos in el.",al={"cine traduce registrul","narain soothfancy","unde duc registrul"}}},fp="22,154,26.125.0,23.345.1,19.70.0,21.65.0"}
P.entries["quest:8577"] = {n="Stewvul, Ex-B.F.F.",s="Dupa Translating the Ledger, Narain Soothfancy spune ca nimic nu poate fi tradus fara ochelarii de clarviziune. Fostul lui cel mai bun prieten pe vecie, Stewvul, i-a furat, iar tu trebuie sa-l gasesti pe Stewvul si sa-i iei inapoi.",h="Dupa Translating the Ledger, Narain Soothfancy spune ca nimic nu poate fi tradus fara ochelarii de...",kw={"greymane wall","lada discreta","registru","narain soothfancy","ochelari de clarvazator","silverpine","stewvul","tanaris"},sec={{t="Ochelarii furati",b="Narain Soothfancy are nevoie de ochelarii de clarviziune inainte sa traduca ceva. Stewvul i-a furat cu ceva vreme in urma. Fostul sau prieten pe veci i-a frant inima in cinci locuri, apoi l-a abandonat aici."},{t="Unde sa cauti",b="Cu ajutorul unei bile de cristal de incredere, Narain a restrans locurile unde s-ar putea afla Stewvul la doua. Unul este Greymane Wall, in Silverpine. Celalalt este o lume de dincolo de un portal. Tu trebuie sa-l gasesti pe Stewvul si sa recuperezi ochelarii."},{t="Ce spune Stewvul",b="Stewvul nu-si poate crede ochilor ca Narain i-a gasit. Stewvul nu se va intoarce si s-a saturat sa fie prieten doar uneori si sclav in restul timpului."}},faq={{q="De ce are nevoie Narain de ochelarii de clarviziune?",a="Narain spune ca nimic nu poate fi tradus fara ele.",al={"de ce sunt necesari ochelarii","scopul ochelarilor lui narain","la ce folosesc ochelarii de clarviziune"}},{q="Cine este Stewvul?",a="Stewvul este fostul cel mai bun prieten pe viata al lui Narain Soothfancy. Stewvul a furat ochelarii de clarviziune, i-a frant inima lui Narain in cinci locuri, apoi l-a abandonat aici.",al={"cine este Stewvul","povestea lui Stewvul","prietenul lui Narain"}},{q="Unde crede Narain ca se afla Stewvul?",a="Globul de cristal al lui Narain reduce posibilitatile la doua locuri: Greymane Wall din Silverpine sau o lume indepartata, dincolo de un portal.",al={"unde se afla stewvul","locatiile lui stewvul","greymane wall"}},{q="Ce urmeaza inaintea acestui lucru?",a="Translating the Ledger, misiunea in care ai dus registrul lui Azuregos la Narain.",al={"misiunea anterioara","conditie prealabila","ce duce la asta"}}},fp="18,209,18.228.0,13.238.0,17.151.1,41.51.0,15.157.0,35.107.0,23.70.0"}
P.entries["quest:858"] = {n="Ignition"}
P.entries["quest:8584"] = {n="Never Ask Me About My Business",s="Narain Soothfancy are un plan pe care refuza sa-l explice, iar acesta cere o gaina de cinci sute de livre. Te indrepti spre Gadgetzan ca sa vorbesti cu Dirge Quikcleave, care te poate ajuta sa gasesti o pasare potrivita.",h="Narain Soothfancy are un plan pe care refuza sa-l explice, iar acesta cere o gaina de cinci sute de livre.",kw={"gaina de 500 de livre","gaina neagra a mortii","Dirge Quikcleave","Gadgetzan","Narain Soothfancy","Tanaris"},sec={{t="Planificare si aprovizionare",b="Narain Soothfancy nu mai vrea intrebari despre afacerea lui, care se ocupa cu lucruri pe care n-ai putea spera vreodata sa le intelegi. Planificarea ii revine lui, iar adunatul lucrurilor tie. Asa cum a spus mai devreme, planul are nevoie de o gaina de cinci sute de livre, iar Dirge Quikcleave, de la hanul din Gadgetzan, iti poate indica una."},{t="Raspunsul lui Dirge",b="Dirge Quikcleave se scarpina in cap. Spune ca nu se mai gaseste o gaina de greutatea aceea, desi odinioara stia de una, Black Chicken of Death, iar nimeni dintre cei care au vazut acea pasare n-a trait ca sa povesteasca. Apoi spune ca are o idee care v-ar putea prinde bine amandurora."}},faq={{q="De ce are nevoie Narain Soothfancy de o gaina de cinci sute de livre?",a="Narain nu spune. Afacerea lui implica lucruri pe care nu le-ai putea intelege, precum un muzzledorf psihotronic, iar planificarea si-o lasa in seama lui, in timp ce pe tine te pune sa aduci cele necesare.",al={"de ce o gaina de 500 de livre","afacerea cu gaini a lui Narain","de ce vrea Narain o gaina"}},{q="Cu cine trebuie sa vorbesti in Gadgetzan?",a="Narain te trimite la Dirge Quikcleave, care se afla in hanul din Gadgetzan si care te va indruma sa gasesti o gaina potrivita.",al={"unde sa merg","pe cine sa vizitez in Gadgetzan","unde se afla Dirge Quikcleave"}},{q="Ce misiune preceda aceasta?",a="Mai intai trebuie sa termini Translating the Ledger. Dupa aceea, Narain Soothfancy aduce vorba despre gaina.",al={"misiune premergatoare","ce misiune vine prima","pasul anterior"}},{q="Unde se afla Narain Soothfancy?",a="Narain Soothfancy se afla in Tanaris.",al={"unde este Narain","locatia lui Narain","locatia lui Narain Soothfancy in Tanaris"}}},fp="30,208,21.297.0,14.263.1,61.173.0,40.115.0,29.98.0,35.32.0"}
P.entries["quest:8586"] = {n="Dirge's Kickin' Chimaerok Chops",s="Dirge Quikcleave din Gadgetzan si-a terminat reteta. Inca are nevoie de douazeci de combustibil pentru rachete Goblin si douazeci de sare Deeprock de la tine si le vrea repede, ca sa nu se strice carnea pe care i-ai adus-o.",h="Dirge Quikcleave din Gadgetzan si-a terminat reteta.",kw={"chimaerok","cotlete","deeprock salt","dirge","gadgetzan","narain","quikcleave","combustibil pentru rachete"},sec={{t="De ce mai are nevoie Dirge",b="Dirge Quikcleave se ocupa personal de mirodenii, iar carnea pe care i-ai adus-o completeaza restul preparatului. Ii mai lipsesc doar combustibil pentru rachete si sare deeprock, cate douazeci din fiecare. Cu toate acestea in mana, puiul va fi gata sa se intoarca la Narain Soothfancy. Dirge te indeamna sa nu zabovesti, fiindca nu vrea ca acea carne sa se strice."}},faq={{q="Cine cere aceste provizii?",a="Dirge Quikcleave din Gadgetzan ti le cere pentru a-si termina reteta.",al={"cine incepe aceasta misiune","cine ofera dirge's kickin chimaerok chops","misiunea lui dirge quikcleave"}},{q="De ce ingrediente are nevoie Dirge Quikcleave?",a="Dirge vrea douazeci de Goblin Rocket Fuel si douazeci de Deeprock Salt. Condimentele sunt treaba lui, iar carnea pe care i-ai dat-o acopera restul.",al={"de ce obiecte am nevoie","ingrediente pentru cotletele lui Dirge","obiecte necesare pentru cotletele lui Dirge"}},{q="Pentru cine este preparatul final?",a="Dirge spune ca, dupa ce ii aduci ce ti-a cerut, pasarea va putea fi dusa inapoi la Narain Soothfancy.",al={"cine mananca friptura","cine primeste puiul","pentru cine este mancarea"}},{q="Ce urmeaza dupa ce livrezi aceste ingrediente?",a="Return to Narain este urmatorul pas.",al={"urmatoarea misiune","ce fac dupa Dirge Chops","ce urmeaza dupa aceasta misiune"}}},fp="31,209,22.332.0,28.66.0,44.134.0,38.112.0,46.34.0"}
P.entries["quest:8587"] = {n="Return to Narain"}
P.entries["quest:8597"] = {n="Draconic for Dummies",s="Narain Soothfancy isi aminteste de o carte pe care a ascuns-o intr-un loc sigur. Ca sa ajungi la ea, cauti girocopterul sau prabusit de pe Land's End Beach, apoi inoti de acolo spre sud, pana la o insula din South Seas. Aceasta continua misiunea Translating the Ledger.",h="Narain Soothfancy isi aminteste de o carte pe care a ascuns-o intr-un loc sigur.",kw={"draconic for dummies","pamant proaspat sapat","girocopter","land's end beach","narain soothfancy","south seas","tanaris"},sec={{t="O carte ascunsa",b="Narain Soothfancy spune ca volumul se va dovedi cu siguranta util si ca l-a ascuns intr-un loc unde nimeni nu ar putea spera sa-l gaseasca. A avut nevoie de un girocopter ca sa ajunga acolo prima data si l-a prabusit pe plaja la intoarcere. Spune ca accidentul i-a dat puterile sale psihice super-gnomesti. Epava se afla undeva de-a lungul Land's End Beach, iar de acolo trebuie sa inoti spre sud. Narain este sigur ca vei recunoaste locul dintr-o privire. Insula unde este ingropat volumul se afla in largul South Seas."},{t="Pe insula",b="Pe insula gasesti o movilita de pamant, iar cartea a disparut. In locul ei se afla un bilet deasupra movilei."}},faq={{q="Cine te trimite sa gasesti aceasta carte?",a="Narain Soothfancy te trimite dupa carte dupa ce termini Translating the Ledger pentru el.",al={"cine ofera Draconic for Dummies","cine da startul misiunii lui Narain","cine ofera aceasta misiune"}},{q="Unde s-a prabusit Narain cu girocopterul?",a="Narain spune ca l-a prabusit pe o plaja in timp ce se intorcea dupa ce ascunsese cartea. Epava se afla undeva pe Land's End Beach.",al={"unde este girocopterul","locatia girocopterului prabusit","locul prabusirii de pe plaja Lands End"}},{q="Unde ar trebui ascunsa cartea?",a="Narain Soothfancy spune ca este ingropat pe o insula din South Seas. Inoti spre sud, pornind de la epava de pe Land's End Beach, iar el spune ca locul va fi limpede cand il vei vedea.",al={"locatia cartii","unde se afla insula","unde sa inot"}},{q="Cum si-a dobandit Narain puterile psihice?",a="Narain spune ca prabusirea girocopterului pe plaja i-a dat puterile sale psihice.",al={"puterile psihice ale lui narain","cum a devenit narain medium"}}},fp="20,225,18.474.0,13.107.1,32.98.0,38.129.0,40.176.0,38.74.0"}
P.entries["quest:8598"] = {n="rAnS0m",s="In locul unde ar trebui sa fie ingropata cartea lui Narain Soothfancy, a fost lasat un bilet de rascumparare. Duci scrisoarea inapoi la Narain Soothfancy, in Tanaris. Aceasta misiune urmeaza dupa Draconic for Dummies.",h="In locul unde ar trebui sa fie ingropata cartea lui Narain Soothfancy, a fost lasat un bilet de rascumparare.",kw={"draconic for dummies","pamant proaspat sapat","narain soothfancy","rascumparare","scrisoare de rascumparare","tanaris"},sec={{t="Un bilet facut din bucati",b="Biletul e alcatuit din multe tipuri diferite de litere, lipite pe pergament. Ii spune lui Narain, numindu-l gnome, ca pretioasa lui carte se afla in mainile celor care au scris biletul si ca o va revedea doar daca face intocmai ce i se spune. Instructiuni detaliate umplu trei pagini si se incheie cu cererea de a aduce banii si de a veni singur. Duceti scrisoarea la Narain Soothfancy, in Tanaris."},{t="Raspunsul lui Narain",b="Narain Soothfancy te intreaba ce s-a intamplat, apoi citeste scrisoarea si i se inroseste fata. Este indignat ca cineva i-ar fura cartea si jura ca le va arata vinovatilor ce inseamna sa te pui cu un gnom psihic."}},faq={{q="Ce cere biletul de rascumparare?",a="Autorii sustin ca au cartea lui Narain, iar el o va revedea numai daca face exact ce i se cere. Instructiunile se intind pe trei pagini si se incheie cu o cerere de bani si cu porunca sa vina singur. Biletul nu spune cine l-a scris.",al={"ce spune biletul","textul scrisorii de rascumparare","cine a luat cartea"}},{q="Unde duce urmatorul pas?",a="Dupa ce ii duci scrisoarea lui Narain Soothfancy din Tanaris, lantul continua cu Decoy!",al={"ce urmeaza dupa ransom","continuarea lui ransom","urmatoarea misiune dupa ransom"}},{q="Ce s-a intamplat inainte de gasirea biletului de rascumparare?",a="Draconic for Dummies vine inaintea acesteia: cautarea cartii ingropate a lui Narain, care se incheie la pamantul proaspat sapat.",al={"misiunea precedenta","conditie prealabila pentru rascumparare"}}},fp="6,202,21.366.0,15.215.1,34.230.0,31.86.0,41.108.0"}
P.entries["quest:8599"] = {n="Love Song for Narain",s="Meridith the Mermaiden are un mesaj pentru Narain Soothfancy, gnome-ul pe care l-a salvat candva din ramasitele unei masini zburatoare prabusite. Te roaga sa-i duci scrisoarea de dragoste in Tanaris. Te poti ocupa de asta in timp ce cauti cartea lui Narain, Draconic for Dummies.",h="Meridith the Mermaiden are un mesaj pentru Narain Soothfancy, gnome-ul pe care l-a salvat candva din...",kw={"masina zburatoare","scrisoare de dragoste","meridith","mermaiden","narain soothfancy","tanaris","epava"},sec={{t="Un mesaj pentru tarm",b="Meridith the Mermaiden primeste rareori vizitatori. Ultimul a fost gnome-ul pe care l-a salvat din epava unei masini zburatoare prabusite, iar ea priveste in gol o clipa, pierduta in amintiri. Te intreaba daca il cunosti pe Narain Soothfancy, fiindca trebuie sa-i spuna ce simte si e sigura ca e vorba de iubire. Te roaga fierbinte sa-i duci un mesaj si promite ca-ti va ramane vesnic indatorata."},{t="Raspunsul lui Narain",b="Narain Soothfancy remarca faptul ca mirosi a peste. Cand afla ce scrie in scrisoare, se foieste si protesteaza ca ea este un peste, iar el un gnome, asa ca relatia lor n-ar putea functiona niciodata."}},faq={{q="Cine este Meridith?",a="Meridith este o sirena care primeste rareori musafiri. Ultimul a fost gnome-ul pe care l-a salvat dintr-o masinarie zburatoare prabusita, Narain Soothfancy.",al={"cine este Meridith","Meridith sirena","povestea sirenei"}},{q="Cum o cunoaste Meridith pe Narain Soothfancy?",a="Ea l-a salvat din ramasitele masinii sale zburatoare prabusite si crede ca este indragostita de el.",al={"cum l-a cunoscut meridith pe narain","relatia dintre narain si meridith","prabusirea avionului lui narain"}},{q="Ce este scrisoarea de dragoste?",a="Este mesajul lui Meridith catre Narain Soothfancy, in care ii spune ce simte. Vrea sa i-l duci in Tanaris.",al={"scrisoarea de dragoste a lui Meridith","scrisoare de dragoste pentru Narain","ce contine mesajul"}},{q="Ce a precedat aceasta cerere?",a="Draconic for Dummies vine inaintea acesteia. Meridith le face cererea celor care sunt deja in cautarea cartii ingropate a lui Narain.",al={"misiune anterioara","cerinta prealabila pentru Love Song for Narain"}}},fp="20,264,23.383.0,15.176.1,16.133.0,41.106.0,24.115.0,30.112.0"}
P.entries["quest:86"] = {n="Pie for Billy",s="Disparitia colierului lui Auntie Bernice Stonefield l-a facut pe Billy Maclure sa se tocmeasca pentru o placinta cu burta de porc. Familiile Stonefield si Maclure se dusmanesc de generatii, iar Billy va spune cine are colierul doar dupa ce isi primeste placinta.",h="Disparitia colierului lui Auntie Bernice Stonefield l-a facut pe Billy Maclure sa se tocmeasca pentru o...",kw={"Bernice Stonefield","Billy Maclure","Elwynn Forest","colier pierdut","vii Maclure","placinta cu burta de porc","ferma Stonefield","carne frageda de mistret"},ang={["profession:Cooking"]="Auntie Bernice spune ca friptura de mistret poate fi tare si fada, dar condimentele potrivite si fierberea lenta o transforma intr-o umplutura savuroasa, exceptionala, pentru placinte.",["race:Human"]="Ca Human, vezi rivalitatile incapatanate si inchistate dintre fermierii din Elwynn, chiar la sud de portile Stormwind."},sec={{t="Mita unui baiat",b="Billy Maclure nu-si cere iertare cand este intrebat despre colierul disparut al lui Auntie Bernice Stonefield. Nu-l va inapoia si nici nu va spune cine il are pana cand nu primeste o placinta cu burta de porc proaspat coapta. Stie ca Bernice este cea mai buna bucatareasa din vale si vrea sa se bucure de tocmeala."},{t="Coptul cu sange rau",b="Maclures si Stonefields si-au aruncat insulte, s-au luat la bataie si s-au acuzat reciproc printre culturile lor de dovleci, generatie dupa generatie. Bernice e furioasa la gandul ca ar trebui sa hraneasca baiatul despre care crede ca a furat bijuteriile familiei sale, si totusi accepta sa coaca. Aduni carne frageda de la mistretii salbatici care cutreiera pasunile din apropiere, iar ea isi lasa mandria deoparte pentru a-si recupera colierul pretios."}},faq={{q="De ce vrea Billy o placinta inainte sa vorbeasca?",a="Billy Maclure stie unde se afla colierul lui Auntie Bernice si foloseste aceasta informatie ca sa negocieze pentru mancare. Nu va spune cine il are pana cand nu primeste una dintre placintele cu burta de porc ale lui Bernice.",al={"de ce vrea billy placinta","placinta mita a lui billy","placinta cu burta de porc a lui billy"}},{q="De ce accepta Auntie Bernice sa gateasca pentru un hot?",a="Auntie Bernice este furioasa pe baiatul despre care crede ca i-a furat colierul, dar nu vede alta cale de a-l recupera. Se invoieste sa coaca dupa ce ii aduci carne de mistret, punandu-si recuperarea bunului mai presus de mandrie.",al={"de ce coace Bernice","de ce face Bernice placinta Stonefield","copturi Stonefield pentru Maclure"}},{q="De unde provine carnea pentru placinta?",a="Carnea provine de la mistreti salbatici care scurma prin pajisti si de-a lungul marginilor fermelor Stonefield si Maclure din Elwynn Forest.",al={"unde gasesc carne","sursa de carne frageda de mistret"}},{q="Care este istoria dintre Stonefields si Maclures?",a="Familiile Stonefield si Maclure sunt fermieri vecini, prinsi intr-o rivalitate amara de ani intregi. Se suspecteaza reciproc de furt, vandalism si certuri de rea-credinta de-a lungul hotarelor proprietatilor lor.",al={"cearta Stonefield Maclure","rivalitate intre ferme","Maclure contra Stonefield"}},{q="A furat Billy intr-adevar colierul?",a="Auntie Bernice il acuza direct pe Billy. El evita sa marturiseasca deschis, dar stie limpede unde a ajuns colierul si foloseste aceasta informatie ca sa negocieze pentru mancare.",al={"a furat Billy colierul","cine a luat colierul","Billy, hotul de coliere"}},{q="Ce se intampla dupa ce Bernice primeste carnea?",a="Cand ii aduci carnea frageda de mistret, Auntie Bernice iti coace o placinta cu burta de porc pe care sa i-o duci lui Billy. Speranta ei este ca el va dezvalui apoi cine i-a luat colierul.",al={"urmatorul pas dupa placinta","ce urmeaza dupa Pie for Billy"}}},fp="13,233,13.265.0,24.371.0,41.174.0,50.214.0,42.128.0,57.207.0,38.162.0,41.156.0"}
P.entries["quest:860"] = {n="Sergra Darkthorn",s="Dupa ce si-au dovedit abilitatile de baza de urmarire si pandire pe colinele domoale din Mulgore, tinerii tauren sunt indrumati spre salbaticia arida din Barrens. Melor Stonehoof ii trimite pe vanatorii aspiranti la nord de granita, sa se prezinte la Sergra Darkthorn in Crossroads. Aceasta calatorie marcheaza trecerea oficiala a vanatorului de la probele locale la ierarhia pradatorilor, mult mai exigenta, din intinsele campii ale Kalimdorului.",h="Dupa ce si-au dovedit abilitatile de baza de urmarire si pandire pe colinele domoale din Mulgore, tinerii...",kw={"rascruce","calea vanatorului","melor stonehoof","mulgore","plainstrider","sergra darkthorn","the barrens","thunder bluff"},ang={["class:Hunter"]="Aceasta calatorie marcheaza trecerea de la urmarirea vanatului local la stapanirea pradatorilor agresivi si a conditiilor aspre din savanele interioare ale Kalimdorului.",["faction:Horde"]="Crossroads este inima logistica pulsanda a tinerei Horde, reunind rezistenta orcish, viclenia Darkspear si traditia Tauren sub privirea veteranilor precum Sergra.",["race:Tauren"]="Pentru taurenii crescuti pe pasunile inverzite din Mulgore, a se prezenta la Sergra marcheaza prima lor expeditie importanta dincolo de granitele stramosesti, in slujba solicitanta a intregii Horde."},sec={{t="Parasirea dealurilor sacre",b="Pentru un vanator tauren novice, indeplinirea primelor ritualuri din Mulgore este doar inceputul. Vaile luxuriante ale patriei stramosesti sunt protejate si familiare, iar vietatile de acolo pun la incercare rabdarea, nu doar capacitatea de supravietuire. Melor Stonehoof isi da seama cand spiritul unui vanator s-a maturizat suficient pentru a avea nevoie de incercari mai dure. Isi indeamna elevii sa-si impacheteze echipamentul, sa paraseasca siguranta din Bloodhoof Village si sa se aventureze spre est, peste trecatoarea montana, in tinuturile aride si parjolite ale Barrens."},{t="Drumul spre Crossroads",b="Poteca prin canioanele de piatra rosie duce drept in savana intinsa, parjolita de soare, unde Horde tanara isi revendica tinuturile. La intersectia rutelor comerciale centrale din Kalimdor se afla Crossroads, o asezare fortificata, plina de orci, troli si tauren. Acolo te asteapta Sergra Darkthorn, un saman orc cu experienta, vestit pentru standardele sale necrutatoare. Ea ii indruma pe toti cei suficient de indrazneti sa urmareasca fauna feroce din Barrens, promitand sa le transforme avantul nestapanit in disciplina calita a supravietuirii in salbaticie."}},faq={{q="Cine da aceasta misiune si unde il gasesc?",a="Misiunea este oferita de Melor Stonehoof, un mentor tauren al vanatorilor care locuieste in Hunter Rise, in Thunder Bluff.",al={"cine ii da misiunea lui Sergra Darkthorn","locatia lui Melor Stonehoof","unde sa incep"}},{q="Unde se afla Sergra Darkthorn?",a="Sergra Darkthorn este stationata la Crossroads, in centrul regiunii Barrens, stand langa latura estica a asezarii, in apropierea turnurilor de veghe si a tarcurilor.",al={"locatia lui Sergra Darkthorn","unde se afla Sergra","gaseste-o pe Sergra"}},{q="Cum ajung din Mulgore la Crossroads?",a="Paraseste Thunder Bluff indreptandu-te spre sud, treci de Bloodhoof Village, apoi urmeaza drumul estic care iese din Mulgore prin trecatoarea canionului si duce in Barrens. Dupa ce treci de poarta de la granita, urmeaza spre est drumul principal de pamant pana la bifurcatie, apoi mergi spre nord pana ajungi la Crossroads.",al={"indicatii catre Crossroads","din Mulgore in Barrens","cum ajung la Crossroads din Thunder Bluff"}},{q="Care este scopul acestei misiuni?",a="Este o misiune de orientare care ii indruma pe jucatorii ce si-au inceput calatoria in Mulgore spre urmatorul centru important de avansare, Crossroads din Barrens, unde pot incepe siruri de misiuni locale de vanatoare.",al={"de ce sa faci aceasta misiune","scopul Sergra Darkthorn","este aceasta o misiune introductiva"}},{q="Primesc aceasta misiune orcii si trolii?",a="Orcii si trolii primesc in Durotar o misiune introductiva echivalenta, numita 'Conscript of the Horde', care ii trimite din Razor Hill in Barrens. Totusi, dupa ce ajung acolo, o pot intalni in continuare pe Sergra si pot accepta misiuni de la ea.",al={"varianta orcilor","varianta trolilor","misiunea de indrumare din Durotar"}},{q="Ce ii invata Sergra Darkthorn pe vanatori?",a="Sergra ii pune la incercare pe vanatorii nou-veniti in fata faunei bastinase din Barrens, incepand cu plainstriders si prowlers. Ea ii invata ca adevarata maiestrie cere rezistenta, respect fata de pamant si tarie sufleteasca, nu forta bruta.",al={"rolul Sergrei","ce face Sergra","vanatoarea Sergrei"}}},fx={["94d282e7"]={q="De ce te trimite Melor Stonehoof la Sergra Darkthorn?",a="Melor Stonehoof isi da seama ca ai depasit terenurile blande de vanatoare din Mulgore. Pentru a urma cu adevarat calea vanatorului si a-ti pune spiritul la incercare, trebuie sa te masori cu fiarele feroce si neinfricate din Barrens. Melor te trimite la Sergra Darkthorn, la Crossroads, fiindca ea are experienta indelungata necesara pentru a-ti indruma pregatirea prin acele campii aspre, dogorite de soare.",al={"de ce sa o trimita la sergra","motivul lui melor stonehoof","de ce sa mergi la crossroads"}},bb525daf={q="De ce te alege Melor pentru aceasta calatorie?",a="Aceasta calatorie nu este o corvoada sau o treaba pentru garzile din Thunder Bluff; este un rit de initiere esential pentru un vanator aspirant. Melor nu poate parcurge drumul in locul tau. Ai dovedit ca ai dedicarea si spiritul necesare pentru a-ti continua pregatirea, iar numai calatorind de unul singur prin tinuturile salbatice din Barrens iti poti cali instinctele si deveni un maestru al vanatorii.",al={"de ce eu, Melor","de ce ma trimite Melor"}}},fp="16,405,24.484.0,26.510.0,46.110.0,34.154.0,44.263.0,34.198.0,34.217.0,41.232.0"}
P.entries["quest:8606"] = {n="Decoy!",s="Narain Soothfancy are un plan pentru rascumparare: un sac cu pietre in loc de bani, iar tu in locul lui. Ii duci deghizarea la locul de predare stabilit de rapitorii de carti in Winterspring. Asta urmeaza scrisorii de rascumparare.",h="Narain Soothfancy are un plan pentru rascumparare: un sac cu pietre in loc de bani, iar tu in locul lui.",kw={"rapitorii de carti","momeala","Narain Soothfancy","numarul doi","rascumparare","winterspring"},sec={{t="Planul lui Narain",b="In biletul de rascumparare scria ca Narain trebuia sa faca personal livrarea, iar el intentioneaza s-o faca, intr-un fel. Umple un sac cu pietre, te masoara din priviri si hotaraste ca te vei descurca. Trusa lui speciala contine un turban, o roba si sacul, iar tu o duci la locul de predare indicat de rapitorii de carti din Winterspring. Cand rapitorii apar dupa marfa, Narain vrea sa-i lichidezi, ca lectie despre ce se intampla cand te pui cu el."},{t="Verdictul lui Narain",b="Cand te intorci, Narain recunoaste ca el si tu poate ca i-ati subestimat pe acesti hoti de carti."}},faq={{q="De ce vrea Narain sa porti o deghizare?",a="In biletul de rascumparare scria ca Narain trebuia sa faca personal livrarea. Planul lui este sa te trimita in locul sau, cu turbanul si roba din trusa lui speciala.",al={"de ce sa porti turbanul","de ce sa te deghizezi","de ce sa te imbraci ca narain"}},{q="Unde are loc predarea?",a="La locul predarii din Winterspring, stabilit de hotii de carti, unde trebuie lasat sacul cu pietre.",al={"unde se afla obiectul","unde duc sacul","locatia punctului de predare"}},{q="Ce se afla in geanta cu rascumpararea?",a="Narain umple sacul cu pietre, nu cu bani.",al={"ce se afla in sac","este aur adevarat","ce a impachetat narain"}},{q="Ce a precedat aceasta misiune?",a="Scrisoarea de rascumparare a venit mai devreme, biletul care cerea bani pentru cartea furata a lui Narain si pe care i-ati dus-o inapoi.",al={"misiune prealabila","misiunea precedenta","ce a dus la aceasta"}}},fp="6,222,15.422.0,16.89.1,44.146.0,35.106.0,30.51.0,28.110.0"}
P.entries["quest:861"] = {n="The Hunter's Way",s="Hunter's Way este un rit de trecere oferit vanatorilor de urme in devenire din Mulgore de catre batranul Skorn Whitecloud. Pentru a-si dovedi iscusinta in formare si respectul fata de salbaticie, drumetii trebuie sa doboare pradatorii sireti ai campiilor si sa-i duca ghearele lui Melor Stonehoof, pe Hunter Rise, in varful lui Thunder Bluff.",h="Hunter's Way este un rit de trecere oferit vanatorilor de urme in devenire din Mulgore de catre batranul...",kw={"pradator al campiilor","gheare de pradator al campiilor","hunter rise","melor stonehoof","mulgore","skorn whitecloud","calea Hunter-ului","thunder bluff"},ang={["class:Hunter"]="Incercarea pune la test direct principiile fundamentale ale salbaticiei: urmarirea unui pradator de ambuscada inainte sa loveasca primul si citirea semnelor subtile ale pajistilor.",["faction:Horde"]="Acest rit le ofera calatorilor aliati ai Horde ocazia sa inteleaga respectul taurenilor fata de natura si sa le castige increderea pe inaltimile din Thunder Bluff.",["race:Tauren"]="Pentru tinerii tauren, oferirea ghearelor de prowler catre Hunter Rise este un ritual esential de trecere, care ii leaga de generatiile de stramosi ce au vanat pe aceleasi campii intinse."},sec={{t="O traditie a campiilor",b="Pentru tauren, vanatoarea nu este nici simplu sport, nici doar un mijloc de subzistenta; este considerata una dintre cele mai mari onoruri ale poporului lor. Ea cere rabdare, intelegerea echilibrului Earth Mother si respect fata de fiarele care umbla prin campiile domoale. Batranul Skorn Whitecloud, care se odihneste in Mulgore dupa zeci de ani de urmarit prada prin Kalimdor, recunoaste aceasta neliniste in aventurierii tineri. In loc sa-i lase sa rataceasca fara tinta, le canalizeaza ambitia intr-o proba traditionala de maturitate si disciplina."},{t="Pradatorii pajistilor",b="Pentru a dovedi ca instinctele lor de urmaritori sunt autentice, candidatii trebuie sa doboare pradatorii de campie din Mulgore. Aceste feline mari sunt rapide, furise si viclene, vanand prin ambuscada si contopindu-se cu usurinta in iarba inalta a campiilor. Adunarea a patru seturi de gheare dovedeste ca un drumet incepator poate zari pradatorul inainte sa devina prada, intorcand propria ferocitate a vanatorului impotriva lui."},{t="Ajungerea la Hunter Rise",b="Dupa ce strange trofeele, initiatul urca pe turnurile si podurile inalte de lemn care duc spre Thunder Bluff. Acolo, in Hunter Rise, Melor Stonehoof primeste ghearele. Maestru urmaritor, care pretuieste intelepciunea straveche a lui Skorn Whitecloud, Stonehoof accepta ofranda drept dovada ca initiatul are spiritul potrivit pentru a fi indrumat mai departe pe cararile pradatorii din Kalimdor."}},faq={{q="Cine ofera sarcina de a urma Hunter's Way?",a="Misiunea este oferita de Skorn Whitecloud, un tauren venerabil, calator al campiilor, care se odihneste in Mulgore si ii indruma pe tinerii aventurieri dornici sa stapaneasca salbaticia.",al={"cel care ofera misiunea","cine ofera misiunea","skorn whitecloud"}},{q="Unde duc ghearele pradatorului de campie?",a="Du ghearele la Melor Stonehoof, care locuieste in Hunter Rise, in capitala taurenilor, Thunder Bluff.",al={"unde se afla Melor Stonehoof","locatia predarii misiunii","Hunter Rise"}},{q="De ce au fost alese ghearele pandarilor de campie drept ofranda?",a="Pradatorii de campie sunt vanatori de varf sireti si periculosi, care traiesc in pajistile din Mulgore. Urmarirea si infrangerea lor dovedesc ca un initiat are privirea agera, rabdarea si disciplina de lupta necesare pentru vanatoare avansata.",al={"de ce pradatori de campie","povestea ghearelor de pradator","ce sunt pradatorii"}},{q="Este aceasta misiune rezervata exclusiv clasei Hunter?",a="Nu. In ciuda numelui sau, Skorn Whitecloud le ofera aceasta proba a hotararii oricaror aventurieri tineri din Horde care dau dovada de dorinta de a calatori si de a invata traditiile campiilor.",al={"doar pentru Hunter?","pot participa si alte clase","este pentru Hunter?"}},{q="Unde duce calatoria vanatorului dupa ce vorbeste cu Melor?",a="Dupa ce Melor Stonehoof iti recunoaste talentul in devenire, incepe sa te indrume catre tinuturile mai aspre din Barrens, trimitandu-te in cele din urma la cercetasi cu experienta, precum Sergra Darkthorn.",al={"ce urmeaza","urmatoarea misiune","unde sa mergi dupa Melor"}},{q="Ce importanta are vanatoarea in cultura taurenilor?",a="In credinta taurenilor, vanatoarea se numara printre cele mai inalte onoruri. Ea presupune sa traiesti in armonie directa cu creatia pe care a zamislit-o Earth Mother, sa iei doar ceea ce iti este necesar si sa arati un respect profund fata de prada care le sustine triburile.",al={"lore despre vanatoarea Tauren","onoarea vanatorii Tauren","de ce este vanatoarea importanta pentru Tauren"}}},fx={["1c4e016d"]={q="De ce vrea Skorn Whitecloud ca acest lucru sa fie facut?",a="Skorn Whitecloud este un vanator batran, care si-a incheiat propriile rataciri, dar inca arde de pasiune. Vazand ca esti nerabdator si doresti sa explorezi, vrea sa-ti indrume ambitia spre traditiile onorabile ale vanatorii. Punandu-ti la incercare capacitatea si trimitandu-te la Melor Stonehoof, in Hunter's Rise, Skorn se asigura ca mostenirea sacra a vanatorii taurenilor este transmisa unei noi generatii pline de fagaduinta.",al={"de ce da Skorn aceasta misiune","motivul lui Skorn Whitecloud","de ce sa ma trimita la Melor"}},["837cf763"]={q="La ce foloseste Flatland Prowler Claw?",a="Ghearele sunt o dovada incontestabila a priceperii tale de urmarire, a sireteniei si a hotararii martiale. Pradatorii de campie sunt vanatori feroce si greu de prins din campiile lui Mulgore. Sa-i prezinti lui Melor Stonehoof patru dintre ghearele lor dovedeste ca ai rabdarea necesara pentru a vana prazi primejdioase si puterea de a le rapune, aratandu-le maestrilor de pe Hunter's Rise ca esti vrednic de instruire suplimentara.",al={"scopul ghearelor de prowler de campie","de ce sa strang gheare","tribut din gheare de prowler"}},d784e285={q="Ce sunt pradatorii de campie si unde pot fi gasiti?",a="Pradatorii de campie sunt feline mari de prada, native pajistilor deschise din Mulgore. Ratacesc prin campii in cautarea prazii, bazandu-se pe siretenie, viteza si gheare ca briciul pentru a-si dobori tinta. Datorita vicleniei si fortei lor naturale, sunt considerate o prada ideala pentru a pune la incercare daca un vanator aspirant a deprins abilitatile de baza necesare pentru a urmari si dobori fiare salbatice.",al={"pradatori de campie","pradatori din Mulgore","ce sunt pradatorii"}},["3cad1e98"]={q="De ce te trimite Skorn Whitecloud in loc sa vaneze el prowlerii?",a="Skorn vaneaza prin Mulgore de multi ani, dar trupul i-a imbatranit, chiar daca spiritul ii ramane ager. Mai important, sarcina nu este o simpla treaba de adunat provizii pentru tabara - este un ritual de trecere pentru tine. Skorn iti recunoaste dorinta tinereasca de a hoinari si iti pune hotararea la incercare, pentru ca tu sa dovedesti ca meriti indrumarea lui Melor Stonehoof.",al={"de ce nu vaneaza Skorn","de ce eu, Skorn Whitecloud","de ce trebuie sa iau ghearele"}}},fp="16,291,25.509.0,30.399.0,20.391.0,45.165.0,43.105.0,53.238.0,50.170.0,61.211.1,54.224.0"}
P.entries["quest:862"] = {n="Dig Rat Stew"}
P.entries["quest:863"] = {n="The Escape"}
P.entries["quest:8642"] = {n="Silvervein the Elder"}
P.entries["quest:8646"] = {n="Hammershout the Elder",s="In timpul Lunar Festival, Hammershout the Elder apare in Park, in Stormwind. Calatorii cinstesc rasele stravechi si primesc de la el un simbol ceremonial.",h="In timpul Lunar Festival, Hammershout the Elder apare in Park, in Stormwind.",kw={"stramos","elder hammershout","parcul","hammershout","Lunar Festival","olden races","Stormwind"},ang={["faction:Alliance"]="Cand vizitezi Park din Stormwind, Hammershout the Elder isi aminteste de veneratie, pace si de trecutul ancestral impartasit de lume.",["faction:Horde"]="Pentru a ajunge la Hammershout the Elder, trebuie sa intri in Stormwind si sa te indrepti spre Park, o calatorie indrazneata pentru un pelerin din Horde.",["race:Human"]="In Park-ul din Stormwind, Hammershout the Elder iti aminteste sa respecti istoria Azeroth, care incepe cu mult inaintea regatului modern al human."},sec={{t="Cinstirea sangelui stravechi",b="In timpul Lunar Festival, spirite strabune venerate apar prin Azeroth, oferindu-le intelepciune si binecuvantari calatorilor care le aduc omagii. Elder Hammershout apare in cartierul Park din Stormwind. Prezenta sa aproape de inima civilizatiei Human aminteste de rasele stravechi care au umblat pe pamant inainte ca regatele de astazi sa se ridice."},{t="Insemne ale veneratiei stramosesti",b="Hammershout the Elder nu cere nicio incercare sau juramant, ci doar recunoasterea trecutului. Se simte usurat si recunoscator cand oamenii inca cinstesc vechile rase. In schimb, le ofera calatorilor un simbol ceremonial, semn al legaturii dintre cei vii si spiritele celor care au fost inaintea lor."}},faq={{q="Cine este Elder Hammershout?",a="Hammershout the Elder este un spirit ancestral care apare in timpul Lunar Festival. El intruchipeaza neamurile stravechi ale Azerothului si le ofera binecuvantari si simboluri celor care il cinstesc in Stormwind.",al={"Hammershout","cine este Hammershout","identitatea Elder Hammershout"}},{q="Unde poate fi gasit Elder Hammershout?",a="Hammershout the Elder apare in cartierul Park din Stormwind in timpul Lunar Festival.",al={"locatia lui Hammershout","unde se afla Hammershout","Hammershout din Elwynn"}},{q="De ce mentioneaza Elder Hammershout 'rasele de odinioara'?",a="Cuvintele sale reflecta celebrarea antichitatii si venerarea stramosilor din cadrul Lunar Festival. Festivalul cinsteste popoarele si traditiile stravechi care au modelat Azeroth inainte de aparitia asezarilor moderne.",al={"sensul raselor stravechi","ce inseamna Hammershout"}},{q="Ce simbol ofera Elder Hammershout?",a="Hammershout the Elder ofera un Coin of Ancestry, un jeton ceremonial daruit de spiritele Lunar Festival calatorilor care ii cauta pe batrani si le aduc omagiul cuvenit.",al={"recompensa lui Hammershout","jetonul Hammershout","ce ofera el"}},{q="Pot aventurierii din Horde sa vorbeasca cu Elder Hammershout?",a="Da. Drumetii Horde pot vorbi cu Hammershout the Elder, desi trebuie sa fie prevazatori in Stormwind, capitala Alliance.",al={"poate Horde sa vorbeasca cu Hammershout","Hammershout Horde"}},{q="Este aceasta intalnire legata de o sarbatoare activa?",a="Hammershout the Elder apare in timpul Lunar Festival anual, oferind binecuvantari inainte de a se retrage in taramul spiritelor.",al={"este hammershout mereu acolo","batranul din lunar festival"}}},fp="21,148,22.323.0,29.269.0,25.193.0,37.85.0,53.192.0,40.160.0,51.127.0,44.122.0"}
P.entries["quest:8648"] = {n="Darkcore the Elder",s="Darkcore the Elder este o misiune sezoniera din timpul Lunar Festival, desfasurata in Undercity. Calatorii ii aduc omagiu batranului Elder Darkcore, unul dintre spiritele stravechi cinstite prin Azeroth, si primesc in schimb un Coin of Ancestry.",h="Darkcore the Elder este o misiune sezoniera din timpul Lunar Festival, desfasurata in Undercity.",kw={"stramos","moneda stramosilor","darkcore the elder","elder darkcore","batrani","lunar festival","undercity"},ang={["faction:Horde"]="Elder Darkcore le permite membrilor Horde sa participe la ritualurile Lunar Festival de pe intregul continent, chiar in siguranta unei capitale aliate.",["race:Undead"]="Pentru Forsaken care strabat ruinele fostului lor regat, Elder Darkcore ofera o amintire tulburatoare a vremurilor de demult, dinaintea Scourge si a caderii Lordaeron."},sec={{t="Un spirit in Undercity",b="In timpul Lunar Festival, spiritele stramosilor antici ai elfilor noptii si ai celor pamanteni apar pe toate continentele pentru a-si impartasi intelepciunea si binecuvantarile. Elder Darkcore locuieste in salile umbrite din Undercity, fiind martor al lumii moderne si pastrand vie amintirea pentru cei care cauta originile lumii."},{t="Cinstirea stramosilor",b="A te apropia de Elder Darkcore respecta un obicei stravechi, menit sa arate respect fata de mortii venerabili si pazitorii eterni ai Azeroth. In semn de recunoastere pentru acest pelerinaj, spiritul le daruieste calatorilor un Coin of Ancestry, drept simbol al bunavointei si al amintirii nepieritoare."}},faq={{q="Care este scopul vizitei la Elder Darkcore?",a="Vizitarea lui Elder Darkcore in timpul Lunar Festival le permite aventurierilor sa aduca omagiu popoarelor stravechi din Azeroth. O discutie cu el incheie misiunea si aduce o Coin of Ancestry.",al={"scopul lui elder darkcore","de ce sa-l vizitezi pe darkcore","scopul misiunii darkcore"}},{q="Unde poate fi gasit Elder Darkcore?",a="Elder Darkcore se manifesta in sala tronului in ruina din Lordaeron, deasupra capitalei Forsaken, Undercity.",al={"locatia lui Elder Darkcore","unde se afla Elder Darkcore","locul lui Darkcore in Undercity"}},{q="Ce este Lunar Festival?",a="Lunar Festival este o perioada anuala de comemorare si reinnoire, tinuta in tot Azeroth, care celebreaza victoria asupra Burning Legion si aduce omagiu strabunilor care au calauzit rasele muritoare.",al={"povestea Lunar Festival","de ce apar batranii","cine sunt batranii"}},{q="Ce reprezinta batranii?",a="Elders sunt spirite stravechi, de obicei legate de night elves sau de vechile culturi ale pamantului, care se arata in timpul Lunar Festival pentru a-i binecuvanta pe cei care isi amintesc faptele lor si duc mai departe invataturile din vechime.",al={"cine sunt batranii","istoria batranilor de la Lunar Festival","spirite ancestrale"}},{q="Pot aventurierii din Alliance sa vorbeasca cu Elder Darkcore?",a="Elder Darkcore ii va saluta pe toti calatorii care reusesc sa ajunga la el, desi jucatorii Alliance trebuie sa infrunte capitala Forsaken, puternic aparata, pentru a face acest lucru.",al={"alliance darkcore","poate alliance sa obtina darkcore","elder darkcore alliance"}},{q="Ce este Coin of Ancestry?",a="O Coin of Ancestry este un jeton festiv oferit de batrani in timpul Lunar Festival, simbolizand veneratia pentru trecut si putand fi schimbat pe tinute festive si suveniruri de sezon.",al={"ce sunt monedele stramosilor","la ce foloseste moneda stramosilor","moneda Lunar Festival"}}},fp="18,238,25.321.0,22.257.0,47.185.0,34.109.0,27.202.0,29.211.0,49.147.0,27.173.0"}
P.entries["quest:8649"] = {n="Stormbrow the Elder",s="Langa Goldshire, Stormbrow the Elder asteapta langa apa in timpul Lunar Festival. Calatorii onoreaza traditiile stravechi si rasele de odinioara din Azeroth, primind in schimb un simbol de amintire.",h="Langa Goldshire, Stormbrow the Elder asteapta langa apa in timpul Lunar Festival.",kw={"stramos","Elder Stormbrow","Elwynn Forest","forja","Goldshire","Lunar Festival","jeton"},ang={["faction:Alliance"]="Ca calator din partea Alliance, aflat in trecere prin Goldshire, il poti gasi pe Stormbrow the Elder in inima Elwynn Forest, printre cele mai accesibile spirite ancestrale pentru tinerii aventurieri.",["race:Human"]="Ca Human care traieste in Elwynn, il poti privi pe Stormbrow the Elder ca pe o amintire a istoriei stravechi de dincolo de zidurile Stormwindului si de razboaiele recente."},sec={{t="Un spirit in Goldshire",b="In spatele fierariei din Goldshire se afla un iaz linistit, unde isi face aparitia Stormbrow the Elder. Garzi, mestesugari si calatori obositi trec prin oras in drum spre padure. Sub bolta din Elwynn Forest, spiritul venerat ii intampina pe toti cei care vin sa cinsteasca istoria indelungata a tinutului."},{t="Omagiu adus raselor stravechi",b="In timpul Lunar Festival, spiritele marilor stramosi se intorc sa umble printre cei vii. Stormbrow the Elder ii lauda pe calatorii care isi amintesc de cei de dinaintea lor. Pentru ca au cinstit intelepciunea si mostenirea popoarelor stravechi, el le daruieste o binecuvantare si o moneda comemorativa a sarbatorii."}},faq={{q="Unde il pot gasi pe Elder Stormbrow?",a="Il poti gasi pe Stormbrow the Elder langa iazul din spatele fierariei din Goldshire, in Elwynn Forest.",al={"locatia lui Stormbrow","unde se afla Elder Stormbrow","batrana din Goldshire"}},{q="Cine este Elder Stormbrow?",a="Stormbrow the Elder este un spirit ancestral care apare in timpul Lunar Festival si ii reprezinta pe veneratii batrani ai raselor stravechi din Azeroth.",al={"cine este stormbrow","povestea lui stormbrow","identitatea lui elder stormbrow"}},{q="Care este scopul vizitei la Elder Stormbrow?",a="Calatorii il viziteaza pe Stormbrow the Elder pentru a-i cinsti pe stramosii din vechime in timpul festivalului. El le adreseaza salutari si le ofera in schimb un semn de apreciere.",al={"de ce sa-l vizitez pe Stormbrow","misiunea Elder Stormbrow","scopul lui Stormbrow the Elder"}},{q="Pot jucatorii Horde sa vorbeasca cu Elder Stormbrow?",a="Batranii Lunar Festival ii onoreaza pe toti cei care ii cauta pasnic, dar Goldshire este un teritoriu Alliance puternic pazit, asa ca o vizita este primejdioasa pentru calatorii Horde.",al={"Horde la Stormbrow","poate Horde sa viziteze Stormbrow"}},{q="Ce simbol ofera batranul?",a="Stormbrow the Elder iti ofera un Coin of Ancestry, un simbol traditional al respectului si al amintirii, impartasit de batranii din intreaga sarbatoare.",al={"recompensa stormbrow","ce jeton","moneda lunara stormbrow"}},{q="De ce pomeneste Stormbrow 'rasele de odinioara'?",a="Stormbrow ii lauda pe calatori pentru ca isi amintesc ca civilizatiile de astazi locuiesc pe meleaguri modelate de popoare stravechi si de traditii dainuitoare, cu mult inainte de aparitia regatelor moderne.",al={"intelesul raselor stravechi","de ce rase stravechi","dialogul lui Stormbrow"}}},fp="19,198,21.289.0,24.280.0,33.115.0,23.140.0,48.142.0,43.157.0,32.135.0,45.169.0"}
P.entries["quest:865"] = {n="Raptor Horns"}
P.entries["quest:8652"] = {n="Graveborn the Elder",s="Graveborn the Elder este o intalnire din cadrul Lunar Festival, aflata langa orasul Brill din Tirisfal Glades. In timpul sarbatorii, calatorii il cauta pe Elder Graveborn printre crangurile napadite de blestem, pentru a-i cinsti pe stramosii stravechi ai Azeroth. A-i aduce omagii acestui spirit iti castiga binecuvantarea sa si un simbol al sarbatorii.",h="Graveborn the Elder este o intalnire din cadrul Lunar Festival, aflata langa orasul Brill din Tirisfal Glades.",kw={"Brill","moneda stramosilor","Elder Graveborn","Graveborn","Lunar Festival","Tirisfal Glades"},ang={["class:Druid"]="Druid-ii venereaza batranii din Lunar Festival ca pe niste punti de legatura cu lumea straveche de dinaintea Sundering, fara sa tina seama de granitele fractiunilor tulburate in care traiesc.",["faction:Alliance"]="Aventurierii Alliance care il cauta pe Elder Graveborn trebuie sa inainteze cu grija prin Tirisfal Glades, caci Brill este un refugiu Forsaken puternic fortificat.",["race:Undead"]="Pentru Forsaken care traiesc in Brill, sosirea spiritelor stravechi ale stramosilor le aminteste cu tarie de istoria mai indepartata a Azerothului, dincolo de tragediile recente provocate de Scourge."},sec={{t="O veghe fantomatica in Brill",b="Desi Forsaken locuiesc printre conace in ruina si cimitire din Tirisfal Glades, Lunar Festival le ofera o legatura neasteptata cu vremurile stravechi. Elder Graveborn apare ca un batran spectral, postat chiar in afara Brill. Chiar si intr-un tinut sfasiat de Scourge si recucerit de mortii-vii, el ii intampina pe pelerinii care se opresc sa cinsteasca vechile traditii."},{t="Omagiu adus raselor stravechi",b="Lunar Festival este perioada in care marile spirite ale epocilor de mult apuse se intorc pentru a oferi intelepciune si a-si exprima recunostinta. Cand calatorii se apropie de Elder Graveborn, acesta spune cat de incurajator este faptul ca locuitorii din Tirisfal continua sa le aduca omagiu stramosilor, in ciuda decaderii actuale a tinutului, si le daruieste un Coin of Ancestry celor care il saluta."}},faq={{q="Unde se afla Elder Graveborn?",a="Elder Graveborn se gaseste langa asezarea Brill din Tirisfal Glades, stand in tacere langa drumul de la marginea orasului.",al={"locatia lui Elder Graveborn","unde se afla Graveborn","coordonatele lui Graveborn"}},{q="Ce se intampla cand vorbesti cu Elder Graveborn?",a="Dupa ce il saluti, Elder Graveborn te felicita pentru ca ai onorat popoarele stravechi din Azeroth si iti ofera un Coin of Ancestry in cadrul sarbatorilor Lunar Festival.",al={"recompensa lui Graveborn","Graveborn la Lunar Festival","ce iti da"}},{q="De ce se afla un batran stravechi in Tirisfal Glades?",a="In timpul Lunar Festival, spiritele stramosilor stravechi se manifesta in tot Azeroth, de la padurile kaldorei pana la tinuturile sfasiate de razboi si molima. Elder Graveborn vegheaza asupra regiunilor nordice din Lordaeron, pentru a se asigura ca istoria sa nu este cu totul eclipsata de moarte.",al={"de ce este el in Tirisfal","povestea lui Graveborn","cine este Elder Graveborn"}},{q="Pot jucatorii Alliance sa-l viziteze pe Elder Graveborn?",a="Elder Graveborn este un spirit al intelepciunii, neutru, si le vorbeste atat membrilor Alliance, cat si celor din Horde. Totusi, fiindca se afla chiar in afara orasului Forsaken Brill, aventurierii Alliance trebuie sa se fereasca de garzile locale.",al={"poate alliance sa vorbeasca cu graveborn","alliance graveborn the elder","graveborn ostil"}},{q="La ce foloseste Coin of Ancestry?",a="Coins of Ancestry adunate de la batrani precum Graveborn pot fi schimbate in Moonglade, in timpul Lunar Festival, pe vesminte festive, retete de artificii si alte suveniruri de sarbatoare.",al={"la ce foloseste moneda stramosilor","la ce folosesc monedele lunare"}},{q="Este Elder Graveborn unul dintre Forsaken?",a="Nu. In ciuda numelui si a infatisarii sale fantomatice de langa Brill, Elder Graveborn este unul dintre spiritele stravechi sarbatorite in timpul Lunar Festival si face parte din lunga descendenta a batranilor din Azeroth, nu dintre Forsaken ai Sylvanas.",al={"Este Graveborn Forsaken","este Elder Graveborn Forsaken"}}},fp="19,307,24.352.0,24.344.0,33.126.0,47.165.0,52.270.0,43.233.0,38.176.0,39.218.0"}
P.entries["quest:8653"] = {n="Goldwell the Elder"}
P.entries["quest:86585"] = {n="Banner of the Fallen",s="Banner of the Fallen spune povestea sumbra a lui Mountaineer Ylva, o pitica neinfricata care s-a aventurat pe teritoriul troggilor pentru a da de urma camarazilor disparuti. Dupa ce a cazut in lupta, iar stindardul ei din Ironforge a fost calcat in picioare, ridicarea steagului inca o data il scoate la iveala pe ucigasul ei, care va raspunde in fata justitiei.",h="Banner of the Fallen spune povestea sumbra a lui Mountaineer Ylva, o pitica neinfricata care s-a aventurat pe...",kw={"stindardul celor cazuti","captain rugelfuss","despicatoarea de capete","stindardul din ironforge","mountaineer ylva","troggs","ylva"},ang={["faction:Alliance"]="Stindardul Ironforge reprezinta loialitatea piticilor si sfidarea lor pe teritoriul troggilor. Recuperarea lui ii onoreaza pe soldatii cazuti care tin linia pentru Alliance.",["race:Dwarf"]="Ylva, cataratoare de munte, a murit aparand onoarea Ironforge-ului si cautandu-si rudele disparute. Recuperarea stindardului ei calcat in picioare si razbunarea mortii sale lovesc in inima mandriei si datoriei piticesti."},sec={{t="Stindardul calcat in picioare",b="Un stindard al Ironforge, calcat in picioare, marcheaza locul in care un cercetas al Alliance si-a gasit sfarsitul intr-un mod brutal. Munteanul Ylva s-a aventurat pe un teritoriu impanzit de trogg, hotarata sa-si gaseasca tovarasii disparuti in timpul patrulei, purtand steagul orasului drept semn de sfidare. Hotararea sa a fost curmata cand un trogg puternic a lovit-o cu atata forta, incat i-a spulberat apararea, lasand mandrul stindard prabusit in tarana."},{t="Razbunare pentru Ylva",b="Troggul vinovat, un bataus cunoscut drept Headsplitter, a recunoscut stindardul si amenintarea pe care o reprezenta. Ridicarea steagului cazut este o provocare deschisa, care-l atrage pe monstru inapoi la vedere, ca sa-si apere prada. Dupa ce-l doboara pe Headsplitter, steagul zdrentuit poate fi dus inapoi la Captain Rugelfuss, care se va asigura ca arma Ylvei este transmisa mai departe, iar stindardul este curatat si pastrat ca monument al tenacitatii piticilor."}},faq={{q="Cine era alpinistul cazut?",a="Pitic-ul cazut este Mountaineer Ylva, o soldata independenta care a patruns pe teritoriul troggilor in cautarea camarazilor munteni care nu s-au mai intors din patrula. Inarmata cu un stindard din Ironforge, a vrut sa dovedeasca hotararea piticilor in fata troggilor, inainte sa fie doborata.",al={"cine era alpinistul","povestea lui Ylva","cine a murit cu stindardul"}},{q="Despre ce este misiunea Banner of the Fallen?",a="Banner of the Fallen presupune descoperirea trupului alpinistei Ylva si a stindardului din Ironforge pe care il purta, calcat in picioare. Ridicand din nou stindardul, un aventurier il atrage pe ucigasul ei, troggul Headsplitter, pentru a-i razbuna moartea, inainte de a returna stindardul catre Captain Rugelfuss.",al={"ce este banner of the fallen","ce se intampla in banner of the fallen","misiunea banner din ironforge"}},{q="Cine l-a ucis pe Mountaineer Ylva?",a="Ylva a fost ucisa de un trogg cunoscut drept Headsplitter, probabil cu o ghioaga grea si tepoasa, care i-a dat lovitura fatala in craniu si i-a smuls coiful. Ridicarea stindardului Ironforge provoaca intoarcerea creaturii.",al={"cine a ucis-o pe Ylva","care trogg l-a ucis pe alpinist","trogg Headsplitter"}},{q="Cine este Captain Rugelfuss?",a="Captain Rugelfuss este ofiterul pitic care supravegheaza operatiunile cercetasilor montani si primeste stindardul recuperat. El recunoaste curajul si spiritul independent al lui Ylva si promite sa curete stindardul si sa-l expuna in onoarea ei.",al={"cine este Rugelfuss","unde predau stindardul","stindardul lui Captain Rugelfuss"}},{q="De ce a mers Mountaineer Ylva singura pe teritoriul troggilor?",a="Ylva a plecat singura sa cerceteze disparitia mai multor alpinisti care nu se intorsesera dintr-o patrula prin tinutul troggilor. Cunoscuta pentru independenta ei neclintita, a purtat stindardul pentru a arata ca Ironforge nu se va pleca niciodata in fata troggilor.",al={"de ce a intrat Ylva pe teritoriul troggilor","de ce era Ylva singura","patrula disparuta a Ylvei"}},{q="Cum este atras troggul Headsplitter afara?",a="Headsplitter isi aminteste stindardul Ironforge de cand l-a doborat pe Mountaineer Ylva. Plantarea si ridicarea din nou a steagului calcat in picioare il provoaca pe trogg sa se intoarca pentru a termina ce a inceput.",al={"cum il invoci pe Headsplitter","cheama-l pe Headsplitter","ridicarea stindardului"}}},fp="20,277,21.410.0,18.425.1,31.280.0,45.287.0,28.213.0,25.221.0,55.260.0,40.195.0"}
P.entries["quest:86614"] = {n="Silver of the Waves",s="Silver of the Waves presupune recuperarea unei agrafe de par din argint, patata si gravata cu initiale, gasita printre resturi de pescuit aruncate. Inapoierea obiectului pierdut proprietarului ii ofera acestuia un ragaz binevenit de la treburile zilnice si ii reda o amintire pretioasa, pe care o credea pierduta in valuri.",h="Silver of the Waves presupune recuperarea unei agrafe de par din argint, patata si gravata cu initiale...",kw={"treburi","resturi de pescuit","agrafa","K.D.","monograma","suvenir de argint","Silver of the Waves"},sec={{t="O amintire printre epave",b="Scormonind prin resturi aruncate si rebuturi de pescuit - printre carlige ruginite si bobine de sarma rupte - un calator atent ar putea descoperi ceva mult mai delicat: o agrafa de par ornamentata, din argint, purtand monograma 'K.D.' Desi umezeala si vremea au patat-o putin, maiestria lucraturii se vede in continuare sub coroziune."},{t="Redarea stralucirii",b="Cautarea proprietarului duce la un localnic harnic, prins in iuresul treburilor zilnice. Usurarea este imediata cand vede mostenirea de familie returnata; desi se credea ca a fost pierduta pentru totdeauna in ape, piesa de argint nu are nevoie decat de putina lustruire pentru a-si recapata luciul de odinioara, iar cel care a gasit-o primeste multumiri din inima."}},faq={{q="Ce este Silver of the Waves?",a="Silver of the Waves este o sarcina care incepe cand un aventurier scotoceste printre maruntisurile de pescuit si resturile aruncate. Printre carligele ruginite si firele incalcite se afla o agrafa argintie de par, patinata si gravata cu initiale, ceea ce da start cautarii pentru a-i inapoia amintirea personala proprietarului de drept.",al={"Silver of the Waves","ce este Silver of the Waves","misiunea cu agrafa de par"}},{q="A cui agrafa de par este gasita printre daramaturi?",a="Agrafa este gravata cu initialele 'K.D.' Desi ramasitele nu dezvaluie imediat numele complet al proprietarului, cineva ocupat cu treburile zilnice recunoaste pe loc obiectul cand ii este inapoiat, recunoscator ca si-a recuperat un accesoriu pierdut, pe care il credea disparut pentru totdeauna.",al={"monograma kd","al cui este ac de par","cine este kd"}},{q="Unde s-a pierdut agrafa de par?",a="Agrafa de par a fost gasita printre diverse resturi, alaturi de unelte obisnuite de pescuit, inclusiv mulinete de sarma rupte si carlige ruginite. Se pare ca a fost pierduta langa apa sau luata de valuri impreuna cu deseurile de pescuit, inainte sa fie recuperata.",al={"unde a fost gasita agrafa de par","locatia agrafei de par"}},{q="In ce stare este agrafa de par?",a="Desi este usor corodata de apa si intemperii, agrafa de par din argint ramane ornamentata si intacta. Proprietarul spune ca, dupa putin efort si o lustruire, piesa de argint va straluci din nou fara greutate.",al={"starea agrafei argintii","este rupta agrafa de par"}},{q="Cum incepe aceasta misiune?",a="Sarcina incepe cand inspectezi o gramada de resturi aruncate de la pescuit. Gasirea agrafei de par monogramate, printre mulinetele si carligele distruse, iti da obiectivul de a afla cine ar fi putut s-o piarda.",al={"cine da misiunea","cum incepi Silver of the Waves"}},{q="De ce este importanta returnarea acului de par?",a="Inapoierea unui suvenir personal pierdut in maree sau pe tarm este un simplu gest de bunavointa. Usurat ca si-a recuperat un accesoriu pe care il credea pierdut pentru totdeauna, proprietarul isi lasa cu bucurie treburile deoparte pentru a-l rasplati pe cel care l-a gasit.",al={"recompensa agrafei de par","de ce sa returnez agrafa de par"}}},fp="19,287,25.334.0,19.316.0,28.288.0,39.261.0,29.236.0,35.239.0,26.215.0,43.231.0"}
P.entries["quest:86667"] = {n="Snowbound",s="Snowbound este o misiune locala de livrare din Loch Modan, indeplinita in numele lui Grenhild, care studiaza elementalii din regiune. Fostul sau mentor, Norric Lochthane, a cerut un borcan cu zapada netopita, adunata din South Gate Pass, pentru ritualurile sale samanice. Livrarea acestui reactiv rece dezvaluie legatura personala trainica si dorul tacut dintre un saman ajuns la batranete si fosta sa eleva.",h="Snowbound este o misiune locala de livrare din Loch Modan, indeplinita in numele lui Grenhild, care studiaza...",kw={"grenhild","borcan cu zapada","loch modan","elementar minor","norric lochthane","ritualuri samanice","acoperit de zapada","south gate pass","loch-ul"},ang={["class:Shaman"]="Faptul ca Norric Lochthane se bazeaza pe curieri elementali neinsemnati si reactivi inghetati scoate in evidenta traditiile samanice locale si studiul elementelor practicate in Khaz Modan.",["race:Dwarf"]="Schimbul dintre Norric Lochthane si Grenhild ofera o fereastra catre ucenicia piticilor si studiul elementelor in jurul varfurilor si tarmurilor din Loch Modan."},sec={{t="O cerere neobisnuita",b="In timp ce cerceta elementalii locali din Loch Modan, Grenhild a primit un curier neasteptat: un elemental minor trimis de fostul ei mentor, Norric Lochthane. Norric ii trimisese vorba ca avea nevoie urgenta de zapada proaspata, netopita, pentru ritualurile sale samanice. In loc sa puna la indoiala metodele excentrice ale fostului sau profesor, Grenhild a cautat un aventurier care sa aduca zapada, ca sa se poata concentra asupra studiilor elementale. Pentru indeplinirea sarcinii, trebuia adunata zapada din South Gate Pass, unde curentii inghetati pastreaza troienele tot anul, si inchisa ermetic intr-un borcan de ceramica lucrat special, conceput sa o fereasca de caldura vaii."},{t="Invatator si discipol",b="Norric Lochthane locuieste intr-o casuta linistita de pe coasta nord-vestica a lacului Loch, practicandu-si artele samanice departe de asezarile forfotitoare. Cand borcanul cu zapada ii este livrat la usa, Norric se bucura vizibil sa primeasca reactivul rece pentru cercetarile sale mistice, dar reactia lui sugereaza un motiv mai profund pentru aceasta sarcina. Se plange deschis ca Grenhild nu a facut drumul pentru a-l vizita personal. Cererea nu era doar o chestiune de reactivi magici, ci speranta tacuta a unui mentor imbatranit de a relua legatura cu o fosta eleva, care si-a urmat de atunci propriul drum."}},faq={{q="Cine este Norric Lochthane?",a="Norric Lochthane este un Shaman cu experienta, care locuieste intr-o casuta de-a lungul coastei de nord-vest a lacului din Loch Modan. A fost candva profesorul lui Grenhild si isi continua practicile shamanice in particular. Stapaneste suficient de bine magia elementala pentru a folosi elementali minori ca mesageri prin tinuturile salbatice.",al={"povestea lui Norric Lochthane","cine este Norric","Norric din Loch Modan"}},{q="Cine este Grenhild?",a="Grenhild este o cercetatoare a elementelor stationata in Loch Modan. A studiat magia sub indrumarea lui Norric Lochthane si ii respecta maiestria, dar si-a dedicat propriile eforturi cercetarii comportamentului elementarilor din zona, pe teren, asa ca ii ramane putin timp pentru calatorii.",al={"cine este grenhild","grenhild din Loch Modan","mentorul lui grenhild"}},{q="De ce are Norric nevoie de un borcan cu zapada?",a="Norric a cerut zapada anume pentru lucrarile sale samanice si cercetarile mistice. Totusi, spera si ca cererea sa o va face pe fosta lui eleva, Grenhild, sa-l viziteze acasa.",al={"de ce vrea Norric zapada","zapada pentru ritualuri samanice","la ce foloseste borcanul cu zapada"}},{q="De unde se aduna zapada pentru aceasta misiune?",a="Zapada este adunata in apropierea intrarii tunelului de la South Gate Pass, sus, in muntii dintre Dun Morogh si Loch Modan. Datorita altitudinii si frigului, zapada ramane acolo tot anul, astfel ca poate fi indesata intr-un borcan ceramic izolat.",al={"unde gasesti zapada","locatia zapezii din South Gate Pass","cum obtii un borcan cu zapada"}},{q="De ce nu a putut Grenhild sa livreze ea insasi zapada?",a="Grenhild observa si studiaza in mod activ elementarii locali din Loch Modan. Deoarece cercetarea ei de teren necesita atentie continua, nu-si poate parasi postul pentru a merge pana la South Gate Pass si apoi la resedinta lui Norric, de pe malul lacului.",al={"de ce nu poate grenhild sa plece","de ce are grenhild nevoie de ajutor","grenhild e ocupata"}},{q="Cum i-a trimis Norric cererea lui Grenhild?",a="In loc sa foloseasca un curier dwarf obisnuit sau serviciile postale, Norric a invocat si a trimis un elemental minor sa-i duca mesajul lui Grenhild. Acest curier neobisnuit arata cat de familiar ii sunt artele elementale si practicile shamanice.",al={"curierul lui Norric","mesager elemental","cum a luat legatura Norric cu Grenhild"}}},fp="9,375,18.657.0,17.590.0,24.306.0,16.261.0,35.230.0,42.265.0,47.250.0,44.228.0"}
P.entries["quest:867"] = {n="Harpy Raiders"}
P.entries["quest:8670"] = {n="Runetotem the Elder"}
P.entries["quest:8673"] = {n="Bloodhoof the Elder",s="Bloodhoof the Elder este o intalnire cu unul dintre venerabilii spirite ancestrale care se arata in timpul Lunar Festival. Aflat chiar in afara Bloodhoof Village, in Mulgore, acest spirit cinstit recunoaste respectul aratat de calatorii ratacitori si le ofera in schimb un simbol ancestral.",h="Bloodhoof the Elder este o intalnire cu unul dintre venerabilii spirite ancestrale care se arata in timpul...",kw={"stramos","Bloodhoof Village","moneda stramosilor","Elder Bloodhoof","Lunar Festival","Mulgore"},ang={["class:Druid"]="Druizii au o mare stima pentru spiritele Lunar Festival si iau legatura cu batranii pentru a-si intari legatura fireasca cu pamantul si stelele.",["class:Shaman"]="Pentru un saman, conversatia cu stramosi intrupati precum Elder Bloodhoof reafirma legatura vie dintre lumea muritorilor si spiritele stramosesti.",["faction:Alliance"]="Pentru a ajunge la Elder Bloodhoof, trebuie sa patrunzi in inima tinutului Mulgore, intr-o indrazneata calatorie prin campiile ostile ale Horde.",["race:Tauren"]="A-l saluta pe Elder Bloodhoof este o datorie sacra pe meleagurile natale, cinstind mostenirea tribului care i-a ajutat pe Tauren sa-si gaseasca adapostul pasnic din Mulgore."},sec={{t="O vizita din partea stramosilor",b="In timpul sarbatorii Lunar Festival, spiritele marilor eroi si ale batranilor din veacuri apuse se intorc in Azeroth. Invaluit intr-o stralucire cereasca, Elder Bloodhoof apare chiar la nord de Bloodhoof Village, langa pod. Apropierea de acesti stramosi venerati este un gest de cinstire a sacrificiilor din trecut, iar in schimb Elder Bloodhoof ofera cuvinte de incurajare si un Coin of Ancestry sacru."},{t="Mostenirea Bloodhoof",b="Aflat pe pamanturile stramosesti din Mulgore, Elder Bloodhoof este o punte intre triburile taurenilor in viata si amintirea inaintasilor lor. Pentru tauren, cinstirea mortilor este un pilon al vietii spirituale, intarind armonia dintre Earth Mother, stramosi si cei care strabat acum campiile."}},faq={{q="Unde il pot gasi pe Elder Bloodhoof?",a="Elder Bloodhoof sta luminat de o raza de lumina cereasca chiar in afara satului Bloodhoof Village din Mulgore, langa pod.",al={"locatia lui Elder Bloodhoof","unde este Elder Bloodhoof","locul unde se afla Elder Bloodhoof"}},{q="Care este scopul cautarii lui Elder Bloodhoof?",a="In timpul Lunar Festival, calatorii il cauta pe Elder Bloodhoof pentru a le aduce omagiu stramosilor. Drept recunoastere a acestui gest, spiritul ii rasplateste cu un Coin of Ancestry si cu intelepciuni despre spiritele invecinate, precum Elder Proudhorn.",al={"de ce sa vorbesc cu elder bloodhoof","scopul batranului bloodhoof","ce ofera elder bloodhoof"}},{q="De ce straluceste o raza de lumina asupra lui?",a="Raza de lumina marcheaza prezenta spiritului, o aparitie strabuna intrupata in timpul Lunar Festival, simbolizand o legatura sacra cu cerul si cu spiritele trecutului.",al={"de ce straluceste elder bloodhoof","lumina de pe elder bloodhoof"}},{q="Pot personajele din Alliance sa-i aduca un omagiu lui Elder Bloodhoof?",a="Stramosii din Lunar Festival ii cinstesc pe toti muritorii care dau dovada de respect, indiferent de factiune. Totusi, calatorii Alliance trebuie sa fie prudenti, deoarece Elder Bloodhoof se afla chiar la marginea teritoriului Horde.",al={"poate Alianta sa faca aceasta misiune","este Elder Bloodhoof doar pentru Horde"}},{q="Cine este Elder Proudhorn, cel despre care vorbeste acest batran?",a="Elder Proudhorn este un alt spirit stramosesc care cinsteste festivalul, aflat in Thunder Bluff. Elder Bloodhoof iti poate spune unde sa-l cauti.",al={"batranul Wheathoof","cine este Wheathoof"}},{q="Ce reprezinta Coins of Ancestry?",a="Monedele Stramosilor sunt semne ale bunavointei spiritelor cinstite din Azeroth. Ele dovedesc ca un calator a aratat respect fata de trecut, iar participantii la festival le schimba pe tinute de sarbatoare, scheme si marfuri festive.",al={"ce sunt monedele stramosilor","jetoane pentru lunar festival"}}},fp="19,285,26.394.0,20.316.0,33.123.0,51.245.0,49.185.0,54.211.0,48.155.0,40.234.0"}
P.entries["quest:8675"] = {n="Skychaser the Elder",s="In timpul Lunar Festival, Skychaser the Elder apare in varful Sentinel Tower din Westfall. Calatorii urca pentru a-i aduce omagiu si, in schimb, a primi binecuvantarea ei.",h="In timpul Lunar Festival, Skychaser the Elder apare in varful Sentinel Tower din Westfall.",kw={"moneda stramosilor","elder skychaser","lunar festival","sentinel hill","sentinel tower","skychaser","westfall"},ang={["class:Druid"]="Ca druid, onorezi Lunar Festival si spiritele stramosilor. Skychaser leaga traditiile stravechi de un profund respect fata de natura.",["faction:Alliance"]="Ca calator Alliance, o gasesti pe Elder Skychaser in baza People's Militia din Sentinel Hill. Ii poti aduce cu usurinta omagiu in timp ce strabati Westfall.",["faction:Horde"]="Ca un calator Horde, te confrunti cu garzile ostile Alliance si cu cercetasii militiei de la Sentinel Hill. Pentru a ajunge la Elder Skychaser, ai nevoie de furisare, viteza sau forta bruta."},sec={{t="Un far in praf",b="Sentinel Hill rezista raidurilor Defias si culegatorilor ratacitori din tinuturile cu tufisuri salbatice si tulburate ale Westfall. In timpul Lunar Festival, un spirit ancestral pe nume Elder Skychaser apare pe platforma deschisa din varful Sentinel Tower. De deasupra prafului si a vantului, ea vegheaza asupra soldatilor istoviti si a colonistilor asediati de dedesubt. Oricine poate urca in turn si ii poate aduce omagiu."},{t="Cinstirea stramosilor",b="In tot Azeroth, Lunar Festival cinsteste intelepciunea, mostenirea si faptele spiritelor stravechi care au umblat pe pamant inaintea luptelor de astazi. Cand te apropii, Elder Skychaser recunoaste scanteia vietii din tine. Iti primeste omagiul si-ti da un jeton al favorii sale, o legatura intre cei vii si mortii onorati."}},faq={{q="Unde il pot gasi pe Elder Skychaser?",a="Elder Skychaser te asteapta in varful Sentinel Tower, la Sentinel Hill, in Westfall. Urca scarile in spirala ale turnului pana la crenelurile platformei superioare de observatie.",al={"locatia lui skychaser","unde se afla elder skychaser","skychaser in westfall"}},{q="De ce sta Elder Skychaser in varful Sentinel Tower?",a="In timpul Lunar Festival, spiritele stramosilor apar in locuri importante si simbolice din Azeroth. Inaltimile Sentinel Tower domina bazinul Westfall, unde batranul poate privi calatorii care infrunta tinutul de frontiera.",al={"de ce se afla el in Sentinel Tower","turnul skychaser"}},{q="Care este scopul acestei misiuni?",a="Ii onorezi pe stramosii venerabili in timpul Lunar Festival, cautandu-l pe Elder Skychaser. Respectul tau iti aduce un Coin of Ancestry si o binecuvantare care celebreaza spiritul tau viu.",al={"recompensa misiunii skychaser","de ce sa-l onorezi pe elder skychaser"}},{q="Pot jucatorii din Horde sa-i aduca omagiu lui Elder Skychaser?",a="Elder Skychaser ii primeste pe toti pelerinii, dar Sentinel Hill este un avanpost al Alliance puternic aparat. Pentru Adventurers ai Horde, sa ajunga la ea este primejdios.",al={"poate horde sa-l viziteze pe skychaser","este skychaser ostil fata de horde"}},{q="Participa Elder Skychaser la apararea Sentinel Hill?",a="Nu. Batranii din Lunar Festival sunt manifestari spirituale dedicate traditiei si amintirii. Elder Skychaser nu ia parte la incaierarile People's Militia impotriva Defias Brotherhood.",al={"lupta Skychaser cu Defias","face Skychaser parte din People's Militia"}},{q="Ce spune Skychaser cand o saluti?",a="Elder Skychaser spune ca spiritul tau arde cu puterea vietii. Iti accepta omagiul si iti ofera in schimb un simbol ancestral.",al={"replicile lui skychaser","ce spune batranul"}}},fp="19,152,20.364.0,22.322.0,33.134.0,57.207.0,34.169.0,40.144.0,65.195.0,43.123.0"}
P.entries["quest:8677"] = {n="Darkhorn the Elder"}
P.entries["quest:86776"] = {n="Ingredients for the Forge",s="Ingredients for the Forge este o sarcina locala din Thelsamar, in care mesterul pitic Morhan Coppertongue cere lingouri de bronz pentru a-si reface stocul atelierului. Cum asezarea rurala nu are accesul facil la comert de care se bucura Ironforge, se bazeaza pe calatori pentru aprovizionarea forjei cu metalele esentiale necesare uneltelor si obiectelor de uz zilnic.",h="Ingredients for the Forge este o sarcina locala din Thelsamar, in care mesterul pitic Morhan Coppertongue...",kw={"fierar","lingouri de bronz","forja","ingredients for the forge","loch modan","morhan coppertongue","thelsamar"},ang={["profession:Blacksmithing"]="Morhan Coppertongue se bazeaza pe fierari si metalurgisti pentru a aproviziona Thelsamar cu unelte de uz zilnic, de la ceainice si oale de gatit pana la unelte de camp.",["profession:Mining"]="Minerii care pot topi cupru si cositor pentru a obtine lingouri de bronz furnizeaza materiile prime necesare mentinerii in functiune a atelierelor rurale din Loch Modan.",["race:Dwarf"]="Chiar si asezari pitice mici, precum Thelsamar, depind mult de o fierarie functionala, asa ca lipsurile de metal sunt o grija constanta pentru comunitate."},sec={{t="Probleme cu proviziile in Thelsamar",b="Viata in Thelsamar se desfasoara intr-un ritm mai linistit decat in Great Forge of Ironforge, insa departarea de capitala aduce cu sine dificultati logistice. Fierarul local Morhan Coppertongue se straduieste sa le furnizeze locuitorilor echipamente, oale si unelte esentiale, dar se confrunta adesea cu lipsa unor metale brute, precum bronzul. Fara transporturi regulate din oras, mestesugarii locali depind de calatorii si prospectori aflati in trecere pentru a-si mentine nicovalele in lucru."},{t="Mentinerea focurilor aprinse",b="Obtinerea bronzului topit rezolva problema imediata de mestesugarit a lui Morhan, permitandu-i sa refaca stocurile de bunuri casnice si practice ale orasului. Chiar si asa, fieraria rurala se confrunta in continuare cu dificultati de aprovizionare, in special cu lipsa unei rute comerciale sigure care sa aduca regulat combustibili precum carbunele in Loch Modan."}},faq={{q="Cine ofera Ingredients for the Forge?",a="Misiunea este oferita de Morhan Coppertongue, un mestesugar pitic care lucreaza la forja din orasul Thelsamar, in Loch Modan.",al={"cine ofera ingredients for the forge","misiunea lui morhan coppertongue","misiunea fierarului din thelsamar"}},{q="De ce materiale are nevoie Morhan Coppertongue?",a="Morhan Coppertongue are nevoie de lingouri de bronz pentru a-si mentine atelierul in functiune si a putea confectiona obiecte esentiale pentru locuitori, precum oale, ceainice si unelte.",al={"de ce are nevoie morhan","materiale pentru Ingredients for the Forge","ce lingouri sunt necesare pentru forja din thelsamar"}},{q="De ce a ramas Thelsamar fara metal?",a="Desi Thelsamar este o asezare primitoare, nu are facilitatile industriale vaste si fluxul comercial constant din Ironforge, ceea ce ii lasa pe mestesugarii locali vulnerabili la lipsa materiilor prime.",al={"de ce nu are Thelsamar bronz","de ce nu are Thelsamar metal"}},{q="Ce faureste Morhan din bronz?",a="Morhan foloseste bronzul mai ales pentru a confectiona obiecte practice, de uz casnic si de lucru, printre care vase de gatit, ceainice, oale si diverse unelte pentru localnici.",al={"la ce se foloseste bronzul in Thelsamar","ce confectioneaza Morhan"}},{q="Ce alte provizii ii este greu sa obtina forjei?",a="Pe langa lingourile de metal, Morhan spune ca are nevoie de un negustor care sa aduca regulat carbune in oras, deoarece combustibilul este esential pentru a mentine focurile forjei aprinse.",al={"de ce combustibil are nevoie morhan","problema carbunelui din Thelsamar"}},{q="Unde se finalizeaza aceasta misiune?",a="Misiunea are loc in Thelsamar, principala asezare piticeasca din dealurile Loch Modan, chiar la est de Dun Morogh.",al={"unde se desfasoara ingredients for the forge","locatia ingredients for the forge"}}},fp="25,343,27.453.0,25.298.0,37.125.0,45.162.0,38.182.0,39.152.0,51.150.0,30.127.0"}
P.entries["quest:8678"] = {n="Proudhorn the Elder",s="Proudhorn the Elder este un spirit ancestral tauren, cinstit in timpul Lunar Festival pe inaltimile din Thunder Bluff. Sa-l vizitezi este un gest de profunda veneratie, prin care recunosti intelepciunea stramosilor ce vegheaza asupra Mulgore si Horde.",h="Proudhorn the Elder este un spirit ancestral tauren, cinstit in timpul Lunar Festival pe inaltimile din...",kw={"stramos","moneda stramosilor","batran","Lunar Festival","Mulgore","spirit","Thunder Bluff","Proudhorn"},ang={["class:Shaman"]="Pentru un Shaman, comuniunea cu un batran ancestral este un ritual profund, o legatura cu lumea spiritelor, care dainuie.",["faction:Horde"]="Aflat in inima puterii taurenilor, acest batran ii primeste pe toti aliatii Horde care urca in Thunder Bluff pentru a-i aduce omagiu.",["race:Tauren"]="A-i aduce omagiu lui Elder Proudhorn este o intoarcere sacra acasa pentru campionii tauren, care le reafirma legatura eterna cu spiritele ce vegheaza asupra Mulgore."},sec={{t="Un spirit din Mulgore",b="Cocoatat sus, pe platourile batute de vant din Thunder Bluff, Proudhorn the Elder se manifesta ca prezenta strabunilor in timpul Lunar Festival. Cultura tauren pretuieste nespus glasurile stramosilor, crezand ca spiritele conducatorilor si inteleptilor de odinioara zabovesc in lume pentru a-i indruma si intari pe cei vii."},{t="Omagiu si binecuvantare stramoseasca",b="Calatorii care urca pe inaltimi pentru a-i aduce omagii lui Elder Proudhorn sunt intampinati nu ca niste straini, ci ca flacari vitale ale vietii. In schimbul omagiului calatorului, batranul ii daruieste o Coin of Ancestry, simbol al legaturii dintre trecutul dainuitor si campionii vii care lupta pentru viitorul lumii."}},faq={{q="Cine este Proudhorn the Elder?",a="Este un spirit ancestral tauren venerat, care se manifesta deasupra orasului Thunder Bluff in timpul Lunar Festival, pentru a primi omagiul campionilor din toate colturile Azerothului.",al={"wheathoof","elder wheathoof","cine este wheathoof"}},{q="Unde il pot gasi pe Proudhorn the Elder?",a="Elder Proudhorn locuieste in capitala taurenilor, Thunder Bluff, pe vastele platouri centrale de unde domina campiile din Mulgore.",al={"unde se afla Elder Wheathoof","locatia lui Wheathoof","batrana din Thunder Bluff"}},{q="Care este scopul vizitei la el?",a="Vizitandu-l pe Elder Proudhorn, jucatorii pot onora spiritele trecutului in timpul Lunar Festival si pot primi binecuvantarea lui si un Coin of Ancestry.",al={"de ce sa vizitezi wheathoof","misiune wheathoof","batran de lunar festival"}},{q="Pot jucatorii din Alliance sa-l viziteze pe Elder Proudhorn?",a="Desi spiritul isi va darui binecuvantarea oricarui calator respectuos, intrarea in Thunder Bluff ca aventurier Alliance este extrem de primejdioasa din cauza strajerilor vigilenti ai orasului si a aparatorilor Horde.",al={"poate Alliance sa vorbeasca cu Wheathoof","batrana din Thunder Bluff pentru Alliance"}},{q="Ce este Coin of Ancestry?",a="Este un simbol ceremonial daruit de spiritele stravechi in timpul Lunar Festival, simbolizand respectul si comuniunea dintre cei vii si stramosi.",al={"moneda stramosilor","moneda Lunar Festival"}},{q="Cum isi privesc taureni batranii?",a="Tauren isi venereaza stramosii ca paznici si invatatori, a caror prezenta spirituala ramane impletita cu pamantul si care le ofera indrumare neincetata celor aflati in comuniune cu Earth Mother.",al={"cultul stramosilor Tauren","povestile despre batranii Tauren"}}},fp="19,240,19.318.0,29.314.0,27.157.0,37.136.0,36.156.0,43.195.0,27.154.0,36.176.0"}
P.entries["quest:86784"] = {n="Sticks and Bones",s="Sticks and Bones este o sarcina locala oferita de Deathguard Bartholomew in Tirisfal Glades. El trimite calatorii sa adune crengi uscate din padurea pustiita si sa le duca la Eleanor Shackleton, o supravietuitoare cu multa experienta, aflata intr-o tabara din dealurile vestice.",h="Sticks and Bones este o sarcina locala oferita de Deathguard Bartholomew in Tirisfal Glades.",kw={"cos de colectare","deathguard bartholomew","creanga uscata","eleanor shackleton","lemne de foc","sticks and bones","supravietuire","tirisfal glades"},ang={["faction:Horde"]="Taberele izolate precum cea a lui Eleanor le ofera tinerilor aventurieri ai Horde opriri primitoare in timp ce strabat Tirisfal Glades.",["race:Undead"]="Chiar si in padurile pustiite din Lordaeron, calatori Forsaken precum Eleanor Shackleton trebuie sa-si adapteze vechile deprinderi de supravietuire la noua lor existenta."},sec={{t="Un gest prietenos",b="Desi Deathguards din Tirisfal Glades sunt de obicei ocupati pana peste cap cu patrulele militare si cu paza impotriva Scourge sau a cruciatilor Scarlet, Deathguard Bartholomew isi face timp sa aiba grija de o cunostinta. Stiind ca Eleanor Shackleton isi petrece viata de dupa moarte in mijlocul intemperiilor, el ii indeamna pe aventurierii care trec pe acolo sa-i adune crengi uscate pentru focul de tabara."},{t="Viata in salbaticie",b="Eleanor Shackleton se mandreste ca a supravietuit singura in salbaticia bolnava din Tirisfal. Desi sunt strigoi, Forsaken simt in continuare frigul umed si muscator care se revarsa peste mlastinile nordice. Filosofia lui Eleanor in privinta lemnelor este simpla: ori de cate ori crezi ca ai strans destule, mai strange de cinci ori pe atat. Recunoscatoare pentru lemnele in plus, il lasa pe curier sa pastreze cosul lui Bartholomew si ii imparte caldura focului sau."}},faq={{q="Cine da misiunea Sticks and Bones?",a="Deathguard Bartholomew din Tirisfal Glades le da aceasta sarcina aventurierilor aflati in trecere, cerandu-le sa-si ajute asociata, Eleanor Shackleton.",al={"cine ofera Sticks and Bones","cine da misiunea Sticks and Bones"}},{q="Unde si-a asezat tabara Eleanor Shackleton?",a="Eleanor Shackleton isi tine o tabara mica in dealurile din vestul Tirisfal Glades, supravietuind stihiilor departe de asezari.",al={"locatia lui Eleanor Shackleton","unde este Eleanor","unde predau Sticks and Bones"}},{q="De ce au Forsaken nevoie de lemne de foc daca sunt undead?",a="Desi Forsaken nu ingheata pana la moarte precum cei vii, ei simt totusi umezeala persistenta si frigul patrunzator al tinuturilor salbatice din Tirisfal. Un foc de tabara le ofera alinare, le incalzeste incheieturile intepenite si face tabara locuibila in salbaticie.",al={"le este frig celor Undead","de ce lemne de foc pentru Undead","frigul celor Forsaken"}},{q="Ce sfat da Eleanor despre strangerea lemnelor?",a="Potrivit lui Deathguard Bartholomew, regula de aur a supravietuirii pentru Eleanor este: 'Cand crezi ca ai destule lemne de foc, aduna de cinci ori mai multe.'",al={"regula lui eleanor privind lemnele de foc","sfatul lui eleanor"}},{q="Ce obiect folosesti pentru a strange ramurile?",a="Deathguard Bartholomew iti da un cos de colectare in care sa duci cele sase ramuri uscate gasite prin luminisuri; Eleanor te lasa sa-l pastrezi dupa ce inchei livrarea.",al={"cos pentru ramura uscata","cum aduni ramuri"}},{q="Duce aceasta misiune la o pregatire suplimentara pentru supravietuire?",a="Eleanor te intampina in tabara ei si iti impartaseste sfaturi despre calatoriile prin salbaticie ca aventurier, oferindu-ti un punct de contact prietenos in tinuturile salbatice din Tirisfal.",al={"continuarea Sticks and Bones","ce face Eleanor in continuare"}}},fx={e518ee9d={q="De ce vrea Deathguard Bartholomew sa duci lemne de foc la Eleanor?",a="Deathguard Bartholomew o vegheaza pe colega sa, Eleanor Shackleton, o supravietuitoare incercata care infrunta dealurile periculoase din vest. Amintindu-si indemnul ei personal de a-si face mereu provizii generoase de lemne de foc, iti sugereaza sa-i duci combustibil in plus, atat pentru a-i sprijini straja, cat si pentru a face cunostinta cu o calatoare incercata, care te poate invata sa supravietuiesti in salbaticie.",al={"de ce sa o ajut pe eleanor","motivul lui bartholomew","de ce Sticks and Bones"}},["8ea276ef"]={q="La ce folosesc ramurile uscate?",a="Crengile uscate sunt combustibil esential pentru focul de tabara al lui Eleanor Shackleton, aprins in salbaticie. Desi mortii umblatori nu au nevoie sa respire, Eleanor se bazeaza pe focul cald pentru a se feri de frigul patrunzator al noptilor din Tirisfal, cand campeaza singura printre dealuri.",al={"la ce foloseste ramura uscata","pentru ce e ramura uscata","lemne de foc pentru Eleanor"}},faf72368={q="De ce iti cere Bartholomew tie sa aduni lemne, in loc sa le stranga chiar el?",a="Ca Deathguard stationat in Tirisfal Glades, indatorirea principala a lui Bartholomew este sa stea de veghe si sa pazeasca drumurile. Nu-si poate parasi postul ca sa caute combustibil, asa ca un calator independent ca tine este curierul ideal pentru a duce lemne de foc la tabara salbatica a lui Eleanor.",al={"de ce eu pentru sticks and bones","de ce are bartholomew nevoie de mine","de ce nu se ocupa bartholomew de asta"}}},fp="16,247,18.361.0,17.436.0,38.135.0,35.140.0,53.241.0,51.138.0,45.164.0,50.154.0"}
